export const DRIVE_CASES = [{"id":"puem-r1-cc-r1-15-01","number":1,"title":"Profesionalismo médico, ética y consentimiento informado · caso 1","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"Paciente de 60 años, programado para colectomía por cáncer, que tras la explicación dice \"no quiero operarme, prefiero irme a mi casa\". Está lúcido, entiende los riesgos y no hay coacción.","questions":[{"id":"puem-r1-cc-r1-15-01-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Respetar su negativa informada, documentarla, explicarle las consecuencias y el seguimiento, y ofrecerle alternativas y cuidados paliativos si aplica.","Pedirle a la familia que lo convenza.","Darle de alta sin documentar.","Operarlo de todas formas; es por su bien."],"answer_index":0,"correct_text":"Respetar su negativa informada, documentarla, explicarle las consecuencias y el seguimiento, y ofrecerle alternativas y cuidados paliativos si aplica.","explanation":"un paciente capaz que rechaza el tratamiento tras información adecuada ejerce su autonomía; la negativa informada se respeta y se documenta, con explicación de consecuencias y alternativas. D es incorrecta: operar contra su voluntad viola la autonomía. B es incorrecta: la familia no decide por un paciente capaz. C es incorrecta: hay que documentar la negativa y el plan.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-15-02","number":2,"title":"Profesionalismo médico, ética y consentimiento informado · caso 2","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"Familiar pide al R1: \"No le digan a mi papá que tiene cáncer, se va a deprimir\". El paciente pregunta directamente: \"Doctor, ¿qué tengo?\"","questions":[{"id":"puem-r1-cc-r1-15-02-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Mentirle al paciente como pide la familia.","Decirle la verdad con empatía y lenguaje claro, respetando su derecho a saber; hablar con la familia sobre cómo acompañarlo, sin mentir.","No decirle nada y evadir la pregunta.","Decirle solo a la familia."],"answer_index":1,"correct_text":"Decirle la verdad con empatía y lenguaje claro, respetando su derecho a saber; hablar con la familia sobre cómo acompañarlo, sin mentir.","explanation":"el paciente tiene derecho a la información sobre su salud; mentir viola la autonomía y la confianza, y la familia no puede imponer el ocultamiento. A es incorrecta: mentir es antiético. C es incorrecta: evadir no respeta su derecho. D es incorrecta: la información es del paciente, no solo de la familia.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-15-03","number":3,"title":"Profesionalismo médico, ética y consentimiento informado · caso 3","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"Paciente de 16 años, inconsciente tras trauma, sin familiar presente, con hemorragia que requiere cirugía urgente.","questions":[{"id":"puem-r1-cc-r1-15-03-q1","ordinal":1,"stem":"¿Quién consiente?","options":["Pedir consentimiento a la enfermera.","Nadie; no se puede operar sin consentimiento.","Se opera por urgencia (consentimiento presunto / estado de necesidad) y se documenta; se busca al familiar/tutor en paralelo.","Esperar a que llegue la familia aunque se desangre."],"answer_index":2,"correct_text":"Se opera por urgencia (consentimiento presunto / estado de necesidad) y se documenta; se busca al familiar/tutor en paralelo.","explanation":"en urgencia con paciente incapaz y sin representante, se actúa por estado de necesidad/consentimiento presunto para salvar la vida, documentando la situación y buscando al tutor. B es incorrecta: no operar en urgencia por falta de firma es dejar morir. D es incorrecta: esperar pone en riesgo la vida. A es incorrecta: la enfermera no es la representante legal.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-15-04","number":4,"title":"Profesionalismo médico, ética y consentimiento informado · caso 4","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"El R1 se da cuenta de que administró un fármaco equivocado (sin daño grave al paciente).","questions":[{"id":"puem-r1-cc-r1-15-04-q1","ordinal":1,"stem":"¿Cuál es la conducta profesional?","options":["Culpar a la enfermera.","Borrar la nota.","No decir nada; no pasó nada grave.","Informar al adscrito y al paciente (según el caso), documentar, vigilar al paciente y participar en el análisis del sistema para evitar que se repita."],"answer_index":3,"correct_text":"Informar al adscrito y al paciente (según el caso), documentar, vigilar al paciente y participar en el análisis del sistema para evitar que se repita.","explanation":"el manejo del error es reconocerlo, informar, documentar y analizar el sistema; ocultarlo impide aprender y pone en riesgo a otros pacientes. C es incorrecta: ocultar un error es antiético. A es incorrecta: buscar culpables no corrige el sistema. B es incorrecta: borrar la nota es falsificar el expediente.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-15-05","number":5,"title":"Profesionalismo médico, ética y consentimiento informado · caso 5","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"Paciente que pide un antibiótico \"por si acaso\" para una cirugía limpia sin indicación, y se enoja si no se lo dan.","questions":[{"id":"puem-r1-cc-r1-15-05-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Explicarle por qué no está indicado (resistencia, efectos adversos, sin beneficio), con empatía y sin ceder a la presión.","Dárselo por vía oral en dosis baja.","Decirle que el adscrito no quiso.","Dárselo para que no se enoje."],"answer_index":0,"correct_text":"Explicarle por qué no está indicado (resistencia, efectos adversos, sin beneficio), con empatía y sin ceder a la presión.","explanation":"prescribir sin indicación por presión del paciente viola la beneficencia y la no maleficencia (resistencia, efectos adversos); hay que explicar con empatía. D es incorrecta: ceder a la presión no es buen cuidado. B es incorrecta: la dosis baja no lo hace correcto. C es incorrecta: evadir la responsabilidad no es profesional.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-15-06","number":6,"title":"Profesionalismo médico, ética y consentimiento informado · caso 6","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"El R1 publica en redes sociales una foto del quirófano con el paciente (sin nombre) \"para presumir el caso\".","questions":[{"id":"puem-r1-cc-r1-15-06-q1","ordinal":1,"stem":"¿Qué está mal?","options":["Nada; no puso el nombre.","Viola la confidencialidad y el consentimiento: el paciente es identificable por el contexto y no consintió la publicación; no se publican casos en redes sin consentimiento explícito y anonimización real.","Solo está mal si el paciente se entera.","Está bien si es con fines educativos."],"answer_index":1,"correct_text":"Viola la confidencialidad y el consentimiento: el paciente es identificable por el contexto y no consintió la publicación; no se publican casos en redes sin consentimiento explícito y anonimización real.","explanation":"la confidencialidad incluye no publicar imágenes ni detalles que puedan identificar al paciente sin su consentimiento explícito; \"sin nombre\" no es anonimización suficiente. A es incorrecta: la ausencia de nombre no basta. C es incorrecta: está mal aunque no se entere. D es incorrecta: el fin educativo no justifica publicar sin consentimiento.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-15-07","number":7,"title":"Profesionalismo médico, ética y consentimiento informado · caso 7","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"El adscrito indica un tratamiento y la coordinadora indica lo contrario; el R1 está entre dos órdenes.","questions":[{"id":"puem-r1-cc-r1-15-07-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["No hacer nada.","Obedecer al de mayor jerarquía sin preguntar.","Comunicar el conflicto con respeto a ambos, pedir clarificación, documentar y priorizar la seguridad del paciente; si hay riesgo, escalar por la vía institucional.","Hacer lo que le parezca al R1 sin avisar."],"answer_index":2,"correct_text":"Comunicar el conflicto con respeto a ambos, pedir clarificación, documentar y priorizar la seguridad del paciente; si hay riesgo, escalar por la vía institucional.","explanation":"ante órdenes contradictorias, la conducta profesional es comunicar el conflicto, pedir clarificación y priorizar la seguridad del paciente, documentando; la obediencia ciega no es profesionalismo. B es incorrecta: la jerarquía no sustituye el juicio ni la seguridad. D es incorrecta: actuar sin avisar es inseguro. A es incorrecta: no hacer nada abandona al paciente.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-15-08","number":8,"title":"Profesionalismo médico, ética y consentimiento informado · caso 8","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"Paciente que no entiende la explicación del consentimiento (lenguaje técnico, prisa) y firma sin comprender.","questions":[{"id":"puem-r1-cc-r1-15-08-q1","ordinal":1,"stem":"¿El consentimiento es válido?","options":["Sí, si el familiar firmó también.","No importa; la cirugía es necesaria.","Sí; firmó.","No; el consentimiento requiere comprensión, no solo firma. Hay que explicar con lenguaje claro, verificar que lo repita con sus palabras y dar tiempo."],"answer_index":3,"correct_text":"No; el consentimiento requiere comprensión, no solo firma. Hay que explicar con lenguaje claro, verificar que lo repita con sus palabras y dar tiempo.","explanation":"el consentimiento informado es un proceso con información, comprensión, voluntariedad y capacidad; una firma sin comprensión no es consentimiento válido. C es incorrecta: la firma no es el consentimiento. A es incorrecta: la firma del familiar no sustituye la comprensión del paciente capaz. B es incorrecta: la necesidad no sustituye el consentimiento.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-15-09","number":9,"title":"Profesionalismo médico, ética y consentimiento informado · caso 9","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"El R1 lleva 36 h sin dormir, con guardia y quirófano, y nota que está cometiendo errores de concentración.","questions":[{"id":"puem-r1-cc-r1-15-09-q1","ordinal":1,"stem":"¿Cuál es la conducta profesional?","options":["Reconocer la fatiga como riesgo para el paciente, pedir ayuda/supervisión, priorizar la seguridad y descansar cuando sea posible; la fatiga deteriora el juicio.","Tomar café y seguir igual.","Pedir que otro haga su trabajo sin avisar.","Seguir sin decir nada; es parte de la residencia."],"answer_index":0,"correct_text":"Reconocer la fatiga como riesgo para el paciente, pedir ayuda/supervisión, priorizar la seguridad y descansar cuando sea posible; la fatiga deteriora el juicio.","explanation":"la fatiga es un factor de riesgo para el paciente; reconocerla, pedir ayuda y priorizar la seguridad es profesionalismo, no debilidad. D es incorrecta: normalizar la fatiga pone en riesgo al paciente. B es incorrecta: el café no restaura el juicio. C es incorrecta: hay que comunicarlo por la vía adecuada, no abandonar el trabajo sin avisar.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-15-10","number":10,"title":"Profesionalismo médico, ética y consentimiento informado · caso 10","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R1","context":"Paciente con cáncer terminal, con dolor, que pide \"que no me hagan nada más, solo que no me duela\".","questions":[{"id":"puem-r1-cc-r1-15-10-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["No hablar del pronóstico.","Seguir con tratamientos curativos aunque no los quiera.","Respetar sus voluntades, priorizar el control del dolor y el confort (cuidados paliativos), con comunicación empática y acompañamiento a la familia.","Darle de alta sin plan."],"answer_index":2,"correct_text":"Respetar sus voluntades, priorizar el control del dolor y el confort (cuidados paliativos), con comunicación empática y acompañamiento a la familia.","explanation":"respetar las voluntades del paciente terminal y priorizar el confort y el control del dolor es beneficencia y respeto a la autonomía; los cuidados paliativos son tratamiento activo, no abandono. B es incorrecta: imponer tratamiento contra su voluntad viola la autonomía. D es incorrecta: requiere un plan de cuidados paliativos y seguimiento. A es incorrecta: hablar del pronóstico con empatía es parte del cuidado.\n\n*Fin del archivo 04. Total: 150 casos (10 por tema × 15 temas).*","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-01","number":11,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 1","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"R4 jefe de guardia: el R1 duda de una indicación del adscrito y no se atreve a hablar.","questions":[{"id":"puem-r1-cc-r4-12-01-q1","ordinal":1,"stem":"¿Qué haces como líder?","options":["Crear espacio para la alerta (comunicación cerrada, briefing) y escalar la duda con respeto y datos","Regañar al R1 por dudar","Decidir solo sin escuchar","Ignorarlo, el adscrito manda"],"answer_index":0,"correct_text":"Crear espacio para la alerta (comunicación cerrada, briefing) y escalar la duda con respeto y datos","explanation":"El liderazgo seguro fomenta que el equipo alerte (Reason, cultura justa); silenciar dudas genera error. Escalar con datos y respeto protege al paciente y al equipo.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-02","number":12,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 2","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"Quirófano: falta un instrumento y el equipo discute.","questions":[{"id":"puem-r1-cc-r4-12-02-q1","ordinal":1,"stem":"¿Conducta del jefe?","options":["Culpar a enfermería en voz alta","Time-out, verificación de la lista OMS, comunicación cerrada y resolución sin culpar","Cancelar sin avisar al paciente","Operar sin el instrumento"],"answer_index":1,"correct_text":"Time-out, verificación de la lista OMS, comunicación cerrada y resolución sin culpar","explanation":"La lista OMS y la comunicación cerrada previenen error; culpar rompe el equipo. Operar sin lo necesario es inseguro.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-03","number":13,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 3","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"Paciente rechaza la cirugía propuesta pese a explicarle riesgos.","questions":[{"id":"puem-r1-cc-r4-12-03-q1","ordinal":1,"stem":"¿Conducta ética?","options":["Obligar a firmar","Operar de todos modos por su bien","Respetar la autonomía: reexplicar, documentar rechazo informado y ofrecer alternativas","Dar de alta sin documentar"],"answer_index":2,"correct_text":"Respetar la autonomía: reexplicar, documentar rechazo informado y ofrecer alternativas","explanation":"La autonomía manda: el rechazo informado se respeta y documenta, con alternativas. Operar contra la voluntad viola autonomía y es agresión.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-04","number":14,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 4","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"M&M: un residente cometió un error que causó daño.","questions":[{"id":"puem-r1-cc-r4-12-04-q1","ordinal":1,"stem":"¿Enfoque correcto?","options":["Ocultar el caso","Castigar sin analizar","Culpar públicamente al residente","Análisis de causa raíz, sistema y cadena de fallos, con plan de mejora y aprendizaje"],"answer_index":3,"correct_text":"Análisis de causa raíz, sistema y cadena de fallos, con plan de mejora y aprendizaje","explanation":"M&M es aprendizaje sistémico (Reason), no juicio. Culpar u ocultar impide prevenir el siguiente error.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-05","number":15,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 5","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"R4 debe delegar una colecistectomía a un R2.","questions":[{"id":"puem-r1-cc-r4-12-05-q1","ordinal":1,"stem":"¿Criterio?","options":["Delegar según competencia demostrada (N1-N4) con supervisión proporcional al riesgo y disponibilidad","No delegar nunca","Delegar la más difícil al menos experto","Delegar siempre sin supervisar"],"answer_index":0,"correct_text":"Delegar según competencia demostrada (N1-N4) con supervisión proporcional al riesgo y disponibilidad","explanation":"La delegación es por competencia y riesgo, con supervisión proporcional (APROC/EPA). Delegar sin supervisar o no delegar nunca frenan formación y seguridad.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-06","number":16,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 6","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"Investigación: quieres estudiar si un protocolo reduce fugas.","questions":[{"id":"puem-r1-cc-r4-12-06-q1","ordinal":1,"stem":"¿Primer paso metodológico?","options":["Operar y luego escribir","Pregunta PICO, diseño, comité de ética y registro antes de reclutar","Inventar datos","Publicar sin revisión"],"answer_index":1,"correct_text":"Pregunta PICO, diseño, comité de ética y registro antes de reclutar","explanation":"La investigación exige PICO, diseño, ética y registro previos. Operar sin protocolo no es investigación y publicar sin revisión es mala práctica.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-07","number":17,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 7","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"Pase de guardia incompleto: se pierde un pendiente de antibiótico.","questions":[{"id":"puem-r1-cc-r4-12-07-q1","ordinal":1,"stem":"¿Solución sistémica?","options":["Confiar en la memoria","Regañar al que entregó","Pase estructurado (SBAR), lista escrita y verificación de pendientes","No hacer pase"],"answer_index":2,"correct_text":"Pase estructurado (SBAR), lista escrita y verificación de pendientes","explanation":"El pase estructurado con verificación evita pérdidas; la memoria y el regaño no son sistema. Lo que no se entrega, se pierde.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-08","number":18,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 8","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"Residente con burnout, errores crecientes.","questions":[{"id":"puem-r1-cc-r4-12-08-q1","ordinal":1,"stem":"¿Acción del jefe?","options":["Exigir más guardias","Burlarse","Ignorarlo, es parte de la residencia","Detectar, hablar en privado, redistribuir carga, derivar apoyo y proteger al paciente"],"answer_index":3,"correct_text":"Detectar, hablar en privado, redistribuir carga, derivar apoyo y proteger al paciente","explanation":"El burnout es riesgo para el paciente y el residente: se aborda con apoyo, redistribución y derivación. Ignorarlo perpetúa error y daño.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-09","number":19,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 9","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"Consentimiento: paciente no entiende los riesgos por barrera de idioma.","questions":[{"id":"puem-r1-cc-r4-12-09-q1","ordinal":1,"stem":"¿Conducta?","options":["Intérprete, explicación clara, tiempo para preguntas y documentación real del consentimiento","Operar sin consentimiento","Pedir a un familiar que firme por él sin explicar","Hacer firmar igual"],"answer_index":0,"correct_text":"Intérprete, explicación clara, tiempo para preguntas y documentación real del consentimiento","explanation":"El consentimiento exige comprensión: intérprete y explicación clara. Firmar sin entender no es consentimiento informado.","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r4-12-10","number":20,"title":"Liderazgo quirúrgico, gestión, ética, investigación y enseñanza · caso 10","topic":"Profesionalismo médico","topicId":"ap-r1-profesionalismo","nivel":"R4","context":"Quirófano con recursos limitados (IMSS): dos urgencias simultáneas, un quirófano.","questions":[{"id":"puem-r1-cc-r4-12-10-q1","ordinal":1,"stem":"¿Decisión del jefe?","options":["Decidir por preferencia personal","No decidir","El que llegó primero, sin valorar","Priorizar por gravedad/urgencia y recurso, comunicar al equipo y documentar la decisión"],"answer_index":2,"correct_text":"El que llegó primero, sin valorar","explanation":"La gestión prioriza por gravedad y recurso, con comunicación y documentación. El orden de llegada sin triaje y la preferencia personal son injustos e inseguros.\n\n*Fin del archivo 04. Total de casos: 120 (10 por tema × 12 temas).*","topic":"Profesionalismo médico"}]},{"id":"puem-r1-cc-r1-09-01","number":21,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 1","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"Durante una colecistectomía laparoscópica, el cirujano no logra ver con claridad el triángulo hepatocístico por inflamación y adherencias.","questions":[{"id":"puem-r1-cc-r1-09-01-q1","ordinal":1,"stem":"¿Cuál es la conducta segura?","options":["Cortar el conducto que parece el cístico.","Dar más antibiótico y seguir.","Seguir disecando a ciegas para terminar rápido.","Detenerse, pedir ayuda, intentar la visión crítica de seguridad; si no se logra, convertir a abierto o hacer colecistectomía subtotal según el caso."],"answer_index":3,"correct_text":"Detenerse, pedir ayuda, intentar la visión crítica de seguridad; si no se logra, convertir a abierto o hacer colecistectomía subtotal según el caso.","explanation":"la visión crítica de seguridad es la barrera contra la lesión de la vía biliar; si no se logra, la conducta segura es pedir ayuda, convertir o hacer una colecistectomía subtotal, no disecar a ciegas. C es incorrecta: disecar a ciegas es la causa clásica de lesión biliar. A es incorrecta: cortar sin identificar es el error que se quiere evitar. B es incorrecta: el antibiótico no aclara la anatomía.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-09-02","number":22,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 2","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"Paciente con neumoperitoneo a 20 mmHg durante laparoscopia, con hipotensión y dificultad ventilatoria.","questions":[{"id":"puem-r1-cc-r1-09-02-q1","ordinal":1,"stem":"¿Cuál es la causa probable y la acción?","options":["Reacción alérgica; dar adrenalina.","Neumotórax; descomprimir el tórax.","Presión de neumoperitoneo excesiva (disminuye el retorno venoso y la ventilación); bajar la presión a ~12-15 mmHg y avisar al anestesiólogo.","Hemorragia; transfundir."],"answer_index":2,"correct_text":"Presión de neumoperitoneo excesiva (disminuye el retorno venoso y la ventilación); bajar la presión a ~12-15 mmHg y avisar al anestesiólogo.","explanation":"la presión alta de neumoperitoneo comprime la vena cava (↓ retorno venoso) y eleva el diafragma (dificultad ventilatoria); bajar la presión es la medida inmediata. B es incorrecta: no hay datos de neumotórax. D es incorrecta: no hay datos de hemorragia. A es incorrecta: no hay datos de alergia.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-09-03","number":23,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 3","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"En la entrada laparoscópica con aguja de Veress, hay salida de sangre por la aguja y caída de la presión.","questions":[{"id":"puem-r1-cc-r1-09-03-q1","ordinal":1,"stem":"¿Cuál es la sospecha?","options":["Lesión intestinal.","Lesión vascular mayor en la entrada; avisar de inmediato, no retirar la aguja a ciegas sin control y preparar conversión.","Embolia por CO₂.","Que es normal."],"answer_index":1,"correct_text":"Lesión vascular mayor en la entrada; avisar de inmediato, no retirar la aguja a ciegas sin control y preparar conversión.","explanation":"la sangre por la aguja de Veress con hipotensión es lesión vascular mayor en la entrada; es una emergencia que exige control inmediato y conversión, no retirar la aguja sin tener control. A es incorrecta: la lesión intestinal da contenido entérico, no sangre con hipotensión inmediata. C es incorrecta: la embolia por CO₂ da hipotensión e hipoxemia, pero no sangre por la aguja. D es incorrecta: no es normal.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-09-04","number":24,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 4","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"El R1 hace un nudo que se desliza y se afloja al soltarlo.","questions":[{"id":"puem-r1-cc-r1-09-04-q1","ordinal":1,"stem":"¿Qué hizo mal?","options":["Hizo un \"nudo de abuela\" (las lazadas en el mismo sentido) en lugar de nudos cuadrados y planos alternados.","Usó monofilamento.","Anudó demasiado fuerte.","Usó sutura absorbible."],"answer_index":0,"correct_text":"Hizo un \"nudo de abuela\" (las lazadas en el mismo sentido) en lugar de nudos cuadrados y planos alternados.","explanation":"el nudo de abuela (lazadas en el mismo sentido) se desliza; el nudo cuadrado alterna el sentido de las lazadas y queda plano y seguro. D es incorrecta: la sutura absorbible no es la causa. B es incorrecta: el monofilamento puede ser más deslizante, pero la técnica del nudo es el factor principal. C es incorrecta: anudar fuerte no corrige un nudo mal hecho.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-09-05","number":25,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 5","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"Durante una cirugía, el conteo de gasas no cuadra al cerrar.","questions":[{"id":"puem-r1-cc-r1-09-05-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Anotar \"conteo incompleto\" y cerrar.","Culpar a la enfermera.","Cerrar y buscar la gasa después.","No cerrar; buscar en el campo, revisar al paciente (imagen si es necesario) y resolver el conteo antes de cerrar."],"answer_index":3,"correct_text":"No cerrar; buscar en el campo, revisar al paciente (imagen si es necesario) y resolver el conteo antes de cerrar.","explanation":"un conteo incompleto es una señal de cuerpo extraño retenido: no se cierra hasta resolverlo (búsqueda en campo, radiografía si es necesario). C es incorrecta: cerrar con una gasa dentro es un evento adverso evitable. A es incorrecta: anotarlo no lo resuelve. B es incorrecta: el conteo es responsabilidad del equipo.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-09-06","number":26,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 6","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"Paciente con quemadura por electrocauterio en la zona de la placa de retorno.","questions":[{"id":"puem-r1-cc-r1-09-06-q1","ordinal":1,"stem":"¿Cuál es la causa más probable?","options":["Que la cirugía duró poco.","Que el paciente es diabético.","Mala colocación o contacto incompleto de la placa de retorno (aumenta la densidad de corriente en un punto).","Que se usó bipolar."],"answer_index":2,"correct_text":"Mala colocación o contacto incompleto de la placa de retorno (aumenta la densidad de corriente en un punto).","explanation":"la quemadura en la placa de retorno ocurre por contacto incompleto o mala colocación, que concentra la corriente en un área pequeña. B es incorrecta: la diabetes no es la causa. D es incorrecta: el bipolar no usa placa de retorno de la misma forma. A es incorrecta: la duración corta no es la causa.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-09-07","number":27,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 7","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"En una anastomosis intestinal, el cirujano nota que un extremo está pálido y sin sangrado al cortar.","questions":[{"id":"puem-r1-cc-r1-09-07-q1","ordinal":1,"stem":"¿Qué debe hacer?","options":["Anastomosar igual; el color no importa.","Resecar hasta tejido bien vascularizado que sangre; una anastomosis isquémica se fistuliza.","Dar vasodilatador.","Poner más puntos."],"answer_index":1,"correct_text":"Resecar hasta tejido bien vascularizado que sangre; una anastomosis isquémica se fistuliza.","explanation":"la anastomosis necesita buena vascularización; un extremo isquémico debe resecarse hasta tejido que sangre. A es incorrecta: el color y el sangrado son signos de viabilidad. C es incorrecta: el vasodilatador no resuelve la isquemia segmentaria. D es incorrecta: más puntos no mejoran la vascularización.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-09-08","number":28,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 8","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"Paciente postoperatorio de laparoscopia con dolor en el hombro derecho y enfisema subcutáneo leve.","questions":[{"id":"puem-r1-cc-r1-09-08-q1","ordinal":1,"stem":"¿Cuál es la explicación más probable?","options":["CO₂ residual bajo el diafragma (irritación frénica) y enfisema por el neumoperitoneo; suele ser autolimitado, con vigilancia.","Infarto.","Neumotórax a tensión.","Lesión diafragmática."],"answer_index":0,"correct_text":"CO₂ residual bajo el diafragma (irritación frénica) y enfisema por el neumoperitoneo; suele ser autolimitado, con vigilancia.","explanation":"el dolor en hombro post-laparoscopia es por CO₂ residual que irrita el diafragma (nervio frénico) y el enfisema subcutáneo leve por el gas; es autolimitado y se vigila. D es incorrecta: la lesión diafragmática es rara y daría otros datos. B es incorrecta: el infarto no explica el enfisema ni el contexto. C es incorrecta: el neumotórax a tensión da disnea grave e hipotensión, no solo dolor de hombro.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-09-09","number":29,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 9","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"El R1 quiere cerrar una herida contaminada (sucia) con puntos en primera intención \"para que quede bonita\".","questions":[{"id":"puem-r1-cc-r1-09-09-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Cerrar con grapas y dar antibiótico por un mes.","No hacer nada.","Cerrar en primera intención; la estética es lo primero.","No cerrar en primera intención una herida sucia/contaminada; dejar abierta o cierre primario diferido (tercera intención) tras desbridamiento y control de la infección."],"answer_index":3,"correct_text":"No cerrar en primera intención una herida sucia/contaminada; dejar abierta o cierre primario diferido (tercera intención) tras desbridamiento y control de la infección.","explanation":"la herida sucia/contaminada no se cierra en primera intención porque se infecta; se deja abierta o se hace cierre primario diferido cuando el tejido está limpio. C es incorrecta: la estética no justifica cerrar una herida infectada. A es incorrecta: las grapas no evitan la infección y un mes de antibiótico no es el tratamiento. B es incorrecta: requiere curaciones y seguimiento.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-09-10","number":30,"title":"Técnica quirúrgica y cirugía de mínima invasión · caso 10","topic":"Técnicas quirúrgicas y cirugía laparoscópica","topicId":"ap-r1-tecnicas","nivel":"R1","context":"Durante una cirugía, el adscrito pide \"hemostasia meticulosa\" antes de cerrar.","questions":[{"id":"puem-r1-cc-r1-09-10-q1","ordinal":1,"stem":"¿Por qué es tan importante?","options":["Solo por estética del campo.","Porque el hematoma es un medio de cultivo, comprime tejidos, aumenta la ISQ y puede requerir reintervención por sangrado.","Porque el paciente lo pide.","Porque la hemostasia no importa si hay drenaje."],"answer_index":1,"correct_text":"Porque el hematoma es un medio de cultivo, comprime tejidos, aumenta la ISQ y puede requerir reintervención por sangrado.","explanation":"el hematoma favorece la infección, comprime tejidos y puede ser sangrado que requiera reintervención; la hemostasia meticulosa previene estas complicaciones. A es incorrecta: no es estética. C es incorrecta: no es por petición del paciente. D es incorrecta: el drenaje no sustituye la hemostasia.","topic":"Técnicas quirúrgicas y cirugía laparoscópica"}]},{"id":"puem-r1-cc-r1-01-01","number":31,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 1","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"Hombre de 58 años, día 2 postoperatorio de laparotomía por perforación intestinal. Fiebre 38.2 °C, FC 108, glucosa 210 mg/dL, Na⁺ 132 mEq/L, gasto urinario 0.4 mL/kg/h, herida limpia sin secreción, sin tos ni disuria, leucocitos 12,000.","questions":[{"id":"puem-r1-cc-r1-01-01-q1","ordinal":1,"stem":"¿Cuál es la interpretación más probable?","options":["Infección urinaria nosocomial.","Hipotiroidismo postoperatorio.","Sepsis por fuga anastomótica que exige reintervención inmediata.","Respuesta fisiológica al estrés quirúrgico, con vigilancia estrecha."],"answer_index":3,"correct_text":"Respuesta fisiológica al estrés quirúrgico, con vigilancia estrecha.","explanation":"en el día 2, fiebre baja, taquicardia, hiperglucemia, hiponatremia leve y oliguria transitoria con herida limpia y sin foco claro corresponden a la respuesta neuroendocrina y metabólica al trauma (cortisol, ADH, catecolaminas, fase *flow*). C es incorrecta: no hay datos de peritonitis, dolor desproporcionado ni salida por drenajes; la fuga es un diagnóstico que se busca, no se asume por fiebre aislada en día 2, aunque la vigilancia debe ser estrecha y reevaluar. A es incorrecta: no hay disuria ni datos urinarios. B es incorrecta: el hipotiroidismo no explica este cuadro agudo postoperatorio.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-01-02","number":32,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 2","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"Mujer de 70 años, día 5 postoperatorio de colectomía, con fiebre persistente 38.8 °C, taquicardia 120, glucosa 260 mg/dL pese a insulina, leucocitos 18,000, dolor abdominal creciente y salida turbia por el drenaje.","questions":[{"id":"puem-r1-cc-r1-01-02-q1","ordinal":1,"stem":"¿Qué indica que ya no es solo respuesta al estrés?","options":["Que tenga leucocitosis.","Que la fiebre sea mayor de 38 °C.","La persistencia y progresión después del día 3-4, con dolor creciente y drenaje turbio.","Que la glucosa esté elevada."],"answer_index":2,"correct_text":"La persistencia y progresión después del día 3-4, con dolor creciente y drenaje turbio.","explanation":"la respuesta fisiológica es autolimitada y mejora; la persistencia/progresión más allá de los primeros días, con dolor creciente y drenaje turbio, orienta a complicación (fuga/infección intraabdominal) y exige buscarla activamente. B es incorrecta: la fiebre aislada también ocurre en la respuesta fisiológica. D es incorrecta: la hiperglucemia de estrés es esperada. A es incorrecta: la leucocitosis acompaña tanto a la respuesta al estrés como a la infección; lo que discrimina es la evolución y el foco.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-01-03","number":33,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 3","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"Paciente quemado con 35% de superficie corporal, día 4, hipermetabólico, con balance nitrogenado negativo de 12 g/día y pérdida de peso rápida.","questions":[{"id":"puem-r1-cc-r1-01-03-q1","ordinal":1,"stem":"¿Cuál es la principal fuente de aminoácidos en esta fase catabólica?","options":["El hígado.","El músculo esquelético.","El tejido adiposo.","El intestino."],"answer_index":1,"correct_text":"El músculo esquelético.","explanation":"en la fase *flow* el músculo esquelético es la principal reserva de aminoácidos (glutamina, alanina) para gluconeogénesis y síntesis de proteínas de fase aguda; por eso el quemado y el politraumatizado pierden masa muscular con rapidez. A es incorrecta: el hígado consume aminoácidos, no es su reserva principal. C es incorrecta: el tejido adiposo aporta ácidos grasos y glicerol, no aminoácidos. D es incorrecta: el intestino es consumidor de glutamina, no la fuente principal.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-01-04","number":34,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 4","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"Hombre de 45 años postoperatorio de cirugía mayor, con albúmina de 2.6 g/dL al día 3, sin pérdidas proteicas evidentes. El R1 dice \"está desnutrido, hay que darle albúmina IV\".","questions":[{"id":"puem-r1-cc-r1-01-04-q1","ordinal":1,"stem":"¿Qué es lo más correcto?","options":["Interpretar la hipoalbuminemia como marcador de inflamación y redistribución, no como indicación de albúmina IV.","Iniciar nutrición parenteral total de inmediato.","Suspender la dieta oral.","Dar albúmina IV para corregir el valor."],"answer_index":0,"correct_text":"Interpretar la hipoalbuminemia como marcador de inflamación y redistribución, no como indicación de albúmina IV.","explanation":"la albúmina cae en el postoperatorio por respuesta de fase aguda (aumento de permeabilidad, redistribución y dilución), no solo por desnutrición, y la albúmina IV no corrige la cicatrización ni el pronóstico en este contexto. D es incorrecta: infundir albúmina no trata la causa. B es incorrecta: la nutrición parenteral no es el primer paso si el tubo digestivo funciona y no hay desnutrición grave documentada. C es incorrecta: suspender la dieta empeora el catabolismo.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-01-05","number":35,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 5","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"Paciente en fase *ebb* (primeras 24 h tras trauma grave): hipotermia, bradicardia relativa, gasto urinario bajo y metabolismo disminuido.","questions":[{"id":"puem-r1-cc-r1-01-05-q1","ordinal":1,"stem":"¿Qué conducta es la prioritaria?","options":["Dar corticoides a dosis altas para \"bloquear el estrés\".","Restringir líquidos para evitar edema.","Iniciar nutrición enteral a dosis plenas de inmediato.","Reanimación, normotermia y perfusión; la nutrición plena corresponde a la fase posterior."],"answer_index":3,"correct_text":"Reanimación, normotermia y perfusión; la nutrición plena corresponde a la fase posterior.","explanation":"en la fase *ebb* la prioridad es la reanimación y la restauración de la perfusión y la temperatura; el hipermetabolismo y la nutrición plena son de la fase *flow*. C es incorrecta: el intestino hipoperfundido no tolera la nutrición plena. A es incorrecta: los corticoides a dosis altas no son el tratamiento de la respuesta al trauma. B es incorrecta: la restricción de líquidos en un paciente hipoperfundido agrava el choque.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-01-06","number":36,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 6","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"Mujer de 62 años, diabética, día 1 postoperatorio de hernioplastia, glucosa 240 mg/dL, sin infección. El adscrito pregunta por qué la glucosa subió si \"no comió nada\".","questions":[{"id":"puem-r1-cc-r1-01-06-q1","ordinal":1,"stem":"¿Cuál es la mejor explicación?","options":["Que necesita insulina basal permanente a partir de ahora.","Error del glucómetro.","Resistencia a la insulina y gluconeogénesis por cortisol y catecolaminas (hiperglucemia de estrés).","Que la cirugía le \"descompuso\" el páncreas."],"answer_index":2,"correct_text":"Resistencia a la insulina y gluconeogénesis por cortisol y catecolaminas (hiperglucemia de estrés).","explanation":"el estrés quirúrgico produce resistencia a la insulina y aumento de la gluconeogénesis hepática mediada por cortisol, catecolaminas y glucagón; la glucosa sube aunque el paciente esté en ayuno. B es incorrecta: es posible un error, pero la explicación fisiológica es la primera. D es incorrecta: no hay lesión pancreática. A es incorrecta: la hiperglucemia de estrés es transitoria y no define diabetes permanente ni insulina basal de por vida.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-01-07","number":37,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 7","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"Hombre de 50 años, postoperatorio de laparotomía, con retención de sodio y agua, peso +3 kg y edema leve, sin disnea ni ingurgitación yugular.","questions":[{"id":"puem-r1-cc-r1-01-07-q1","ordinal":1,"stem":"¿Cuál es el mecanismo principal?","options":["Insuficiencia cardiaca aguda.","Aumento de ADH y aldosterona por la respuesta al estrés, más la reposición de líquidos.","Insuficiencia renal crónica descompensada.","Síndrome nefrótico."],"answer_index":1,"correct_text":"Aumento de ADH y aldosterona por la respuesta al estrés, más la reposición de líquidos.","explanation":"la respuesta al estrés eleva ADH y aldosterona y produce retención hidrosalina fisiológica en el postoperatorio temprano, sumada a los líquidos administrados. A es incorrecta: no hay datos de congestión (disnea, ingurgitación). C es incorrecta: no hay antecedente ni datos de falla renal crónica. D es incorrecta: no hay proteinuria ni hipoalbuminemia nefrótica descrita.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-01-08","number":38,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 8","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"Paciente postoperatorio mayor con dolor mal controlado (EVA 9/10) y taquicardia persistente.","questions":[{"id":"puem-r1-cc-r1-01-08-q1","ordinal":1,"stem":"¿Por qué el adscrito insiste en que la analgesia es parte del tratamiento de la respuesta al estrés?","options":["Porque el dolor mantiene la activación simpática y el catabolismo.","Porque los analgésicos bajan directamente el cortisol.","Porque sin analgesia no se puede dar de alta.","Solo por comodidad del paciente."],"answer_index":0,"correct_text":"Porque el dolor mantiene la activación simpática y el catabolismo.","explanation":"el dolor no controlado perpetúa la descarga simpática y la respuesta neuroendocrina, con taquicardia, hiperglucemia y catabolismo; la analgesia adecuada es una intervención fisiológica, no solo de confort. D es incorrecta: reduce el tratamiento a comodidad. B es incorrecta: los analgésicos no bajan directamente el cortisol; lo hacen indirectamente al controlar el estímulo doloroso. C es incorrecta: el alta no es el mecanismo.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-01-09","number":39,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 9","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"Mujer de 35 años, día 7 postoperatorio de cirugía mayor, con pérdida de 4 kg, debilidad, cicatrización lenta y balance nitrogenado negativo persistente.","questions":[{"id":"puem-r1-cc-r1-01-09-q1","ordinal":1,"stem":"¿Qué fase/proceso predomina?","options":["Hipotiroidismo.","Infección urinaria.","Fase *ebb* prolongada.","Catabolismo persistente de la fase *flow* sin aporte nutricional adecuado."],"answer_index":3,"correct_text":"Catabolismo persistente de la fase *flow* sin aporte nutricional adecuado.","explanation":"a los 7 días la fase *ebb* ya pasó; el catabolismo persistente con pérdida de masa y mala cicatrización indica fase *flow* prolongada sin soporte nutricional suficiente (o con complicación no resuelta que la perpetúa). C es incorrecta: la fase *ebb* dura 24-48 h. A es incorrecta: no hay datos de hipotiroidismo. B es incorrecta: no hay datos urinarios y no explica la pérdida de masa ni la mala cicatrización.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-01-10","number":40,"title":"Respuesta biológica al trauma y fisiología quirúrgica · caso 10","topic":"Respuesta biológica al trauma","topicId":"ap-r1-rbt","nivel":"R1","context":"En el pase de visita, el adscrito pregunta: \"¿Por qué el paciente operado hace fiebre el primer día y eso no siempre es infección?\"","questions":[{"id":"puem-r1-cc-r1-01-10-q1","ordinal":1,"stem":"¿Cuál es la mejor respuesta?","options":["Porque la fiebre del primer día siempre es por atelectasia.","Porque los mediadores inflamatorios (IL-1, IL-6, TNF-α) de la respuesta al trauma producen fiebre sin infección.","Porque el antibiótico profiláctico causa fiebre.","Porque la anestesia produce fiebre."],"answer_index":1,"correct_text":"Porque los mediadores inflamatorios (IL-1, IL-6, TNF-α) de la respuesta al trauma producen fiebre sin infección.","explanation":"la respuesta inflamatoria al trauma libera pirógenos endógenos (IL-1, IL-6, TNF-α) que elevan la temperatura sin infección; la fiebre temprana aislada es frecuente y no equivale a infección. A es incorrecta: la atelectasia es una causa posible, no la única ni la explicación fisiológica general. C es incorrecta: el antibiótico no es la causa habitual de la fiebre del primer día. D es incorrecta: la anestesia no es la causa de la fiebre postoperatoria.","topic":"Respuesta biológica al trauma"}]},{"id":"puem-r1-cc-r1-04-01","number":41,"title":"Cuidados perioperatorios · caso 1","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"Hombre de 68 años, programado para colectomía electiva, con antecedente de infarto hace 6 meses, diabetes y capacidad funcional de 3 METs (no puede subir un piso sin disnea).","questions":[{"id":"puem-r1-cc-r1-04-01-q1","ordinal":1,"stem":"¿Qué indica el riesgo?","options":["Contraindicación absoluta para cirugía.","Riesgo bajo; operar sin más estudios.","Riesgo cardiaco alto; requiere valoración cardiológica y optimización antes de la cirugía electiva.","Riesgo bajo porque el infarto fue hace 6 meses."],"answer_index":2,"correct_text":"Riesgo cardiaco alto; requiere valoración cardiológica y optimización antes de la cirugía electiva.","explanation":"infarto reciente + diabetes + <4 METs = alto riesgo cardiaco (índice de Lee); en cirugía electiva hay que valorar y optimizar antes de operar, no operar \"sin más\". B es incorrecta: subestima el riesgo. D es incorrecta: 6 meses no elimina el riesgo con mala capacidad funcional. A es incorrecta: no es contraindicación absoluta, es indicación de valoración y optimización.","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-04-02","number":42,"title":"Cuidados perioperatorios · caso 2","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"Mujer de 50 años, cirugía electiva a las 8:00 h; cenó a las 22:00 h y tomó agua a las 5:00 h. El R1 quiere cancelar por \"no ayunar\".","questions":[{"id":"puem-r1-cc-r1-04-02-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Dar procinético y operar.","Operar sin anestesia general.","Cancelar; el ayuno fue insuficiente.","No cancelar: sólidos 6 h y líquidos claros 2 h; el agua a las 5:00 h cumple el ayuno de líquidos claros."],"answer_index":3,"correct_text":"No cancelar: sólidos 6 h y líquidos claros 2 h; el agua a las 5:00 h cumple el ayuno de líquidos claros.","explanation":"las guías ASA son sólidos 6 h y líquidos claros 2 h; el agua a las 5:00 h para cirugía a las 8:00 h cumple el ayuno de líquidos. C es incorrecta: el ayuno fue adecuado. A es incorrecta: no se necesita procinético. B es incorrecta: no es la solución.","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-04-03","number":43,"title":"Cuidados perioperatorios · caso 3","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"Paciente para hernioplastia: el antibiótico profiláctico se dio 3 h antes de la incisión.","questions":[{"id":"puem-r1-cc-r1-04-03-q1","ordinal":1,"stem":"¿Qué está mal?","options":["Debe darse dentro de los 60 min previos a la incisión para tener concentración adecuada en el tejido al cortar.","Debe darse después de la cirugía.","Debe darse en dosis triple.","Nada; el antibiótico dura todo el día."],"answer_index":0,"correct_text":"Debe darse dentro de los 60 min previos a la incisión para tener concentración adecuada en el tejido al cortar.","explanation":"la profilaxis debe administrarse dentro de los 60 min antes de la incisión (120 min para vancomicina/fluoroquinolonas) para que el tejido tenga concentración bactericida al momento del corte; 3 h antes es demasiado temprano. D es incorrecta: la concentración cae con el tiempo. B es incorrecta: después de la incisión ya no es profilaxis. C es incorrecta: triplicar la dosis no corrige el tiempo.","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-04-04","number":44,"title":"Cuidados perioperatorios · caso 4","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"Hombre de 70 años, en warfarina por fibrilación auricular, programado para colecistectomía electiva.","questions":[{"id":"puem-r1-cc-r1-04-04-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Operar con INR terapéutico.","Suspender la warfarina con anticipación, valorar puente con heparina según el riesgo trombótico y verificar INR antes de operar.","Suspender la warfarina el día de la cirugía.","No operar nunca."],"answer_index":1,"correct_text":"Suspender la warfarina con anticipación, valorar puente con heparina según el riesgo trombótico y verificar INR antes de operar.","explanation":"hay que balancear riesgo trombótico vs hemorrágico: suspender la warfarina con días de anticipación, puente con heparina si el riesgo trombótico es alto y verificar que el INR esté en rango seguro antes de operar. A es incorrecta: operar con INR terapéutico aumenta el sangrado. C es incorrecta: un día no basta para normalizar el INR. D es incorrecta: no es contraindicación absoluta.","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-04-05","number":45,"title":"Cuidados perioperatorios · caso 5","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"Mujer de 45 años, día 1 postoperatorio de cirugía abdominal, con fiebre 38.5 °C, taquicardia 115, dolor abdominal creciente y salida biliosa por el drenaje. El R1 dice \"es atelectasia, hay que hacer fisioterapia\".","questions":[{"id":"puem-r1-cc-r1-04-05-q1","ordinal":1,"stem":"¿Qué es lo más probable y qué hacer?","options":["Dolor postoperatorio normal; dar analgésico.","Atelectasia; fisioterapia respiratoria.","Fuga anastomótica o complicación intraabdominal; avisar al adscrito y buscarla (imagen, labs, exploración).","Infección urinaria; dar antibiótico."],"answer_index":2,"correct_text":"Fuga anastomótica o complicación intraabdominal; avisar al adscrito y buscarla (imagen, labs, exploración).","explanation":"fiebre + taquicardia + dolor creciente + salida biliosa por el drenaje es un cuadro de fuga anastomótica hasta demostrar lo contrario; la atelectasia no explica la salida biliosa ni el dolor creciente. B es incorrecta: la fisioterapia no trata una fuga. D es incorrecta: no hay datos urinarios. A es incorrecta: el dolor desproporcionado y la salida por el drenaje no son \"normales\".","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-04-06","number":46,"title":"Cuidados perioperatorios · caso 6","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"Paciente de 80 años, frágil, con desnutrición y anemia (Hb 9.5 g/dL), programado para cirugía mayor electiva en 2 semanas.","questions":[{"id":"puem-r1-cc-r1-04-06-q1","ordinal":1,"stem":"¿Qué es lo más útil antes de operar?","options":["Transfundir 2 unidades el día de la cirugía.","Dar antibiótico profiláctico por 2 semanas.","Operar cuanto antes sin optimizar.","Prehabilitación: corregir anemia (hierro), soporte nutricional, dejar de fumar, optimizar comorbilidad y capacidad funcional."],"answer_index":3,"correct_text":"Prehabilitación: corregir anemia (hierro), soporte nutricional, dejar de fumar, optimizar comorbilidad y capacidad funcional.","explanation":"en cirugía electiva, las 2 semanas son una ventana para optimizar: anemia, nutrición, tabaquismo y funcionalidad reducen complicaciones. C es incorrecta: operar sin optimizar en un paciente frágil aumenta el riesgo. A es incorrecta: transfundir el día de la cirugía no corrige la anemia crónica ni es *patient blood management*. B es incorrecta: el antibiótico profiláctico no se da por semanas.","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-04-07","number":47,"title":"Cuidados perioperatorios · caso 7","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"En quirófano, antes de la incisión, el equipo no hace el *checklist* porque \"ya todos se conocen\".","questions":[{"id":"puem-r1-cc-r1-04-07-q1","ordinal":1,"stem":"¿Qué debe hacer el R1?","options":["Pedir que se haga el *checklist* y el marcaje del sitio: es una barrera de seguridad, no burocracia.","Hacerlo solo en silencio.","Cancelar la cirugía.","No decir nada; no es su papel."],"answer_index":0,"correct_text":"Pedir que se haga el *checklist* y el marcaje del sitio: es una barrera de seguridad, no burocracia.","explanation":"el *checklist* de la OMS y el marcaje del sitio previenen errores de sitio, paciente y procedimiento; el R1 debe hablar cuando algo es inseguro (*speak up*), con respeto y firmeza. D es incorrecta: el silencio ante una omisión de seguridad no es profesionalismo. B es incorrecta: el *checklist* es del equipo, no individual y en silencio. C es incorrecta: no es motivo de cancelación, es motivo de hacerlo bien.","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-04-08","number":48,"title":"Cuidados perioperatorios · caso 8","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"Hombre de 60 años, obeso, diabético, postoperatorio de laparotomía, sin profilaxis antitrombótica, con dolor en la pantorrilla y disnea súbita al día 4.","questions":[{"id":"puem-r1-cc-r1-04-08-q1","ordinal":1,"stem":"¿Cuál es la sospecha y qué se omitió?","options":["Neumonía; se omitió fisioterapia.","Tromboembolia venosa / embolia pulmonar; se omitió la profilaxis antitrombótica mecánica y farmacológica.","Infarto; se omitió aspirina.","Atelectasia; se omitió movilización."],"answer_index":1,"correct_text":"Tromboembolia venosa / embolia pulmonar; se omitió la profilaxis antitrombótica mecánica y farmacológica.","explanation":"dolor en pantorrilla + disnea súbita en un paciente de alto riesgo sin profilaxis es tromboembolia venosa/embolia pulmonar hasta demostrar lo contrario; la profilaxis antitrombótica es un estándar perioperatorio. A es incorrecta: la neumonía no explica el dolor en pantorrilla. C es incorrecta: el cuadro es de TEV, no de infarto. D es incorrecta: la atelectasia no da dolor en pantorrilla ni disnea súbita de este tipo.","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-04-09","number":49,"title":"Cuidados perioperatorios · caso 9","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"Mujer de 55 años, postoperatorio de cirugía colorrectal, con sonda vesical desde hace 5 días \"por comodidad\" y fiebre con disuria.","questions":[{"id":"puem-r1-cc-r1-04-09-q1","ordinal":1,"stem":"¿Qué se debió hacer?","options":["Cambiar la sonda cada día.","Mantener la sonda; la fiebre es por la cirugía.","Retirar la sonda vesical lo antes posible (ERAS) y valorar infección urinaria asociada a sonda.","Dar antibiótico sin retirar la sonda."],"answer_index":2,"correct_text":"Retirar la sonda vesical lo antes posible (ERAS) y valorar infección urinaria asociada a sonda.","explanation":"la sonda vesical prolongada es una causa frecuente de infección urinaria nosocomial; ERAS indica retirarla temprano, y la fiebre con disuria en este contexto obliga a valorar infección urinaria asociada a sonda. B es incorrecta: mantenerla perpetúa el riesgo. D es incorrecta: el antibiótico sin retirar la fuente fracasa. A es incorrecta: cambiarla a diario no es la medida; retirarla es la medida.","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-04-10","number":50,"title":"Cuidados perioperatorios · caso 10","topic":"Cuidados perioperatorios","topicId":"ap-r1-perioperatorio","nivel":"R1","context":"Paciente con ASA III, programado para cirugía ambulatoria, con labs \"de rutina\" normales pero sin historia de sangrado. El R1 pide coagulación, pruebas de función pulmonar y ecocardiograma \"por protocolo\".","questions":[{"id":"puem-r1-cc-r1-04-10-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Estudios dirigidos por la historia y la exploración: los estudios indiscriminados no cambian la conducta y retrasan la cirugía.","No pedir ningún estudio.","Pedir solo el ecocardiograma.","Pedir todos los estudios; más es mejor."],"answer_index":0,"correct_text":"Estudios dirigidos por la historia y la exploración: los estudios indiscriminados no cambian la conducta y retrasan la cirugía.","explanation":"la valoración preoperatoria es dirigida: historia, exploración y estudios que cambien la conducta; la \"rutina\" indiscriminada no mejora la seguridad y genera falsos positivos y retrasos. D es incorrecta: más estudios no es más seguridad. B es incorrecta: algunos estudios sí están indicados según el caso. C es incorrecta: el ecocardiograma aislado no es el estudio de rutina.","topic":"Cuidados perioperatorios"}]},{"id":"puem-r1-cc-r1-02-01","number":51,"title":"Líquidos y electrolitos · caso 1","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Hombre de 68 años con Na⁺ 118 mEq/L, confusión y una convulsión; el Na⁺ era 138 hace 2 días (caída aguda).","questions":[{"id":"puem-r1-cc-r1-02-01-q1","ordinal":1,"stem":"¿Cuál es la conducta inicial correcta?","options":["Salina hipertónica 3% para elevar el Na⁺ con rapidez controlada, con monitorización estrecha.","Dar diurético de asa de inmediato.","Corregir el Na⁺ a 140 en 6 horas.","Restricción hídrica y esperar."],"answer_index":0,"correct_text":"Salina hipertónica 3% para elevar el Na⁺ con rapidez controlada, con monitorización estrecha.","explanation":"la hiponatremia aguda grave y sintomática (convulsión) es una emergencia: salina hipertónica 3% para subir el Na⁺ lo suficiente para detener los síntomas, con monitorización; la corrección total debe seguir siendo lenta (≤~8-10 mEq/L en 24 h) para evitar desmielinización osmótica. D es incorrecta: la restricción hídrica es demasiado lenta en un paciente con convulsión. B es incorrecta: el diurético no es el tratamiento de la hiponatremia sintomática aguda. C es incorrecta: corregir 22 mEq en 6 h es peligroso (desmielinización).","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-02-02","number":52,"title":"Líquidos y electrolitos · caso 2","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Mujer de 55 años, postoperatorio de cirugía gástrica, con sonda nasogástrica con gasto de 1,500 mL/día, K⁺ 2.8 mEq/L, Cl⁻ 88 mEq/L, pH 7.52, HCO₃⁻ 34 mEq/L.","questions":[{"id":"puem-r1-cc-r1-02-02-q1","ordinal":1,"stem":"¿Cuál es el trastorno?","options":["Acidosis metabólica hiperclorémica.","Alcalosis metabólica hipoclorémica hipopotasémica por pérdidas gástricas.","Acidosis respiratoria.","Alcalosis respiratoria por hiperventilación."],"answer_index":1,"correct_text":"Alcalosis metabólica hipoclorémica hipopotasémica por pérdidas gástricas.","explanation":"la pérdida de HCl por la sonda produce alcalosis metabólica hipoclorémica con hipopotasemia (el riñón pierde K⁺ en la alcalosis y por la aldosterona secundaria a la depleción de volumen). A es incorrecta: el pH es alcalino, no ácido, y el Cl⁻ está bajo. C es incorrecta: el trastorno es metabólico, no respiratorio. D es incorrecta: el HCO₃⁻ elevado y el Cl⁻ bajo señalan alcalosis metabólica, no respiratoria.","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-02-03","number":53,"title":"Líquidos y electrolitos · caso 3","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Hombre de 72 años con K⁺ 6.8 mEq/L, ondas T picudas y QRS ancho, con insuficiencia renal aguda.","questions":[{"id":"puem-r1-cc-r1-02-03-q1","ordinal":1,"stem":"¿Cuál es la primera acción?","options":["Resina de intercambio iónico.","Insulina + glucosa.","Gluconato de calcio IV.","Furosemida."],"answer_index":2,"correct_text":"Gluconato de calcio IV.","explanation":"con cambios ECG (QRS ancho, T picudas) la prioridad es estabilizar la membrana cardiaca con gluconato de calcio; la insulina+glucosa baja el K⁺ pero no protege de inmediato contra la arritmia. B es incorrecta: es el segundo paso, no el primero cuando hay cambios ECG. D es incorrecta: la furosemida elimina K⁺ lentamente y no sirve si hay oliguria/anuria. A es incorrecta: la resina actúa en horas-días, demasiado lenta en una emergencia.","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-02-04","number":54,"title":"Líquidos y electrolitos · caso 4","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Paciente con K⁺ 3.0 mEq/L que no sube pese a reponer 60 mEq/día de KCl. Mg²⁺ 1.2 mg/dL.","questions":[{"id":"puem-r1-cc-r1-02-04-q1","ordinal":1,"stem":"¿Qué falta corregir?","options":["El sodio.","El fosfato.","El calcio.","El magnesio."],"answer_index":3,"correct_text":"El magnesio.","explanation":"la hipomagnesemia produce hipopotasemia refractaria (el Mg²⁺ regula los canales de K⁺ renales); sin corregir el Mg²⁺, el K⁺ no se mantiene. C es incorrecta: el calcio no explica la hipopotasemia refractaria. A es incorrecta: el sodio no es el factor. B es incorrecta: el fosfato no es la causa de la hipopotasemia refractaria en este caso.","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-02-05","number":55,"title":"Líquidos y electrolitos · caso 5","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Hombre de 60 años, postoperatorio, recibió 6 L de solución salina 0.9% en 24 h; gasometría: pH 7.30, HCO₃⁻ 18 mEq/L, Cl⁻ 112 mEq/L, lactato normal, brecha aniónica normal.","questions":[{"id":"puem-r1-cc-r1-02-05-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico?","options":["Acidosis metabólica hiperclorémica por exceso de salina.","Acidosis respiratoria.","Cetoacidosis diabética.","Acidosis láctica."],"answer_index":0,"correct_text":"Acidosis metabólica hiperclorémica por exceso de salina.","explanation":"la salina 0.9% aporta mucho Cl⁻ sin bicarbonato; en grandes volúmenes produce acidosis metabólica hiperclorémica con brecha aniónica normal y lactato normal. C es incorrecta: no hay hiperglucemia ni cetonas descritas y la brecha es normal. D es incorrecta: el lactato es normal. B es incorrecta: el pH bajo es por HCO₃⁻ bajo, no por retención de CO₂.","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-02-06","number":56,"title":"Líquidos y electrolitos · caso 6","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Mujer de 40 años con Na⁺ 128 mEq/L, euvolémica, sin edemas ni deshidratación, postoperatorio de cirugía mayor, osmolaridad urinaria alta y Na⁺ urinario alto.","questions":[{"id":"puem-r1-cc-r1-02-06-q1","ordinal":1,"stem":"¿Cuál es la causa más probable?","options":["Pérdidas por diarrea.","SIADH postoperatorio.","Insuficiencia cardiaca.","Déficit de agua libre."],"answer_index":1,"correct_text":"SIADH postoperatorio.","explanation":"hiponatremia euvolémica con orina concentrada y Na⁺ urinario alto tras cirugía es típica de SIADH (ADH inapropiada por dolor, estrés y fármacos). A es incorrecta: la diarrea produce hipovolemia, no euvolémia. C es incorrecta: la insuficiencia cardiaca da hipervolémia con edemas. D es incorrecta: el déficit de agua libre produce hipernatremia, no hiponatremia.","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-02-07","number":57,"title":"Líquidos y electrolitos · caso 7","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Hombre de 80 años, post-tiroidectomía, con parestesias peribucales, Chvostek positivo, QT largo y Ca²⁺ 7.0 mg/dL.","questions":[{"id":"puem-r1-cc-r1-02-07-q1","ordinal":1,"stem":"¿Cuál es la causa y la conducta?","options":["Hipermagnesemia; dar calcio como antagonista.","Hipopotasemia; reponer K⁺.","Hipocalcemia por hipoparatiroidismo postoperatorio; reponer calcio (IV si es sintomático/grave) y vigilar.","Hiponatremia; dar salina hipertónica."],"answer_index":2,"correct_text":"Hipocalcemia por hipoparatiroidismo postoperatorio; reponer calcio (IV si es sintomático/grave) y vigilar.","explanation":"tras tiroidectomía, la hipocalcemia por lesión o devascularización de las paratiroides produce parestesias, Chvostek, Trousseau y QT largo; el tratamiento es reponer calcio (IV si hay síntomas o Ca²⁺ muy bajo) y vigilar PTH y vitamina D. B es incorrecta: el cuadro es de calcio, no de potasio. D es incorrecta: el Na⁺ no explica Chvostek ni QT largo. A es incorrecta: la hipermagnesemia no es el cuadro descrito.","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-02-08","number":58,"title":"Líquidos y electrolitos · caso 8","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Paciente con vómitos prolongados, deshidratación, FC 120, PAS 90 mmHg, Na⁺ 130, K⁺ 3.1, Cl⁻ 90, HCO₃⁻ 32.","questions":[{"id":"puem-r1-cc-r1-02-08-q1","ordinal":1,"stem":"¿Qué líquido es el más adecuado para iniciar la reposición?","options":["Solución glucosada 5%.","Ringer lactato.","Agua libre oral.","Solución salina 0.9%."],"answer_index":3,"correct_text":"Solución salina 0.9%.","explanation":"en la alcalosis hipoclorémica hipopotasémica por pérdidas gástricas con hipovolemia, la salina 0.9% repone volumen y Cl⁻, lo que permite al riñón corregir la alcalosis; el Ringer lactato aporta lactato (que se convierte en bicarbonato) y no corrige el déficit de Cl⁻ tan bien. A es incorrecta: la glucosada no repone volumen ni electrolitos. C es incorrecta: el paciente está hipovolémico e hipotenso y no tolera reposición oral.","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-02-09","number":59,"title":"Líquidos y electrolitos · caso 9","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Hombre de 65 años con Na⁺ 155 mEq/L, confusión, mucosas secas y gasto urinario bajo.","questions":[{"id":"puem-r1-cc-r1-02-09-q1","ordinal":1,"stem":"¿Cuál es el trastorno y el cálculo inicial?","options":["Déficit de agua libre; calcular el déficit (ACT × [Na⁺/140 − 1]) y reponer agua con lentitud.","SIADH; restringir líquidos.","Hiponatremia; dar salina hipertónica.","Exceso de sodio; dar diurético."],"answer_index":0,"correct_text":"Déficit de agua libre; calcular el déficit (ACT × [Na⁺/140 − 1]) y reponer agua con lentitud.","explanation":"la hipernatremia es casi siempre déficit de agua libre; se calcula el déficit y se repone con agua (oral o IV hipotónica) a velocidad controlada para no producir edema cerebral. D es incorrecta: el problema no es exceso de sodio sino falta de agua. B es incorrecta: el SIADH produce hiponatremia. C es incorrecta: el Na⁺ está alto, no bajo.","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-02-10","number":60,"title":"Líquidos y electrolitos · caso 10","topic":"Líquidos y electrolitos","topicId":"ap-r1-liquidos","nivel":"R1","context":"Paciente postoperatorio con K⁺ 3.2 mEq/L, íleo prolongado y debilidad. El R1 quiere dar KCl IV rápido por vía periférica (40 mEq/h) para \"resolverlo hoy\".","questions":[{"id":"puem-r1-cc-r1-02-10-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Dar bicarbonato para \"meter\" el K⁺ a la célula.","Dar 40 mEq/h por vía periférica.","Reponer a velocidad segura (aprox. 10-20 mEq/h por vía periférica), con monitorización y ECG, y revisar Mg²⁺.","No reponer; el íleo se resuelve solo."],"answer_index":2,"correct_text":"Reponer a velocidad segura (aprox. 10-20 mEq/h por vía periférica), con monitorización y ECG, y revisar Mg²⁺.","explanation":"la reposición IV rápida de K⁺ por vía periférica es peligrosa (arritmia, flebitis); la velocidad segura es de ~10-20 mEq/h con monitorización, y hay que revisar el Mg²⁺. B es incorrecta: 40 mEq/h por vía periférica es inseguro. D es incorrecta: la hipopotasemia perpetúa el íleo y arriesga arritmia. A es incorrecta: el bicarbonato baja el K⁺ sérico (lo mete a la célula) y empeoraría la hipopotasemia.","topic":"Líquidos y electrolitos"}]},{"id":"puem-r1-cc-r1-07-01","number":61,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 1","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Mujer de 55 años, día 6 postoperatorio de laparotomía, con secreción purulenta por la herida, eritema de 3 cm, fiebre 38.3 °C, sin dehiscencia fascial.","questions":[{"id":"puem-r1-cc-r1-07-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento?","options":["Hematoma; drenar con aguja.","ISQ superficial; abrir la herida, drenar, cultivar y curaciones; antibiótico solo si hay celulitis extensa o fiebre persistente.","Evisceración; quirófano urgente.","Seroma; observar."],"answer_index":1,"correct_text":"ISQ superficial; abrir la herida, drenar, cultivar y curaciones; antibiótico solo si hay celulitis extensa o fiebre persistente.","explanation":"secreción purulenta + eritema limitado a piel/subcutáneo es ISQ superficial (CDC); el tratamiento es abrir y drenar, no solo antibiótico. C es incorrecta: no hay salida de vísceras ni dehiscencia fascial. D es incorrecta: el seroma es líquido claro, no purulento con fiebre. A es incorrecta: no es hematoma (sangre), es pus.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-07-02","number":62,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 2","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Hombre de 70 años, día 8 postoperatorio de laparotomía, con salida de intestino por la herida al toser.","questions":[{"id":"puem-r1-cc-r1-07-02-q1","ordinal":1,"stem":"¿Cuál es la conducta inmediata?","options":["Cubrir con gasas húmedas estériles, NPO, avisar al adscrito y quirófano urgente; no reintroducir vísceras.","Dar antibiótico y observar.","Poner un vendaje compresivo y dar de alta.","Reintroducir el intestino en la cama y suturar la piel."],"answer_index":0,"correct_text":"Cubrir con gasas húmedas estériles, NPO, avisar al adscrito y quirófano urgente; no reintroducir vísceras.","explanation":"es evisceración: cubrir con gasas húmedas estériles para proteger el intestino, NPO, antibiótico y quirófano urgente; reintroducirlo en la cama contamina y lesiona el intestino. D es incorrecta: es peligroso y no estéril. B es incorrecta: el antibiótico solo no resuelve la evisceración. C es incorrecta: es una emergencia quirúrgica.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-07-03","number":63,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 3","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Paciente diabético, fumador, con herida abdominal que no cicatriza a las 3 semanas, con tejido de granulación pálido.","questions":[{"id":"puem-r1-cc-r1-07-03-q1","ordinal":1,"stem":"¿Cuáles son los factores que más contribuyen?","options":["Solo el antibiótico.","La sutura absorbible.","Solo la edad.","Diabetes/hiperglucemia, tabaquismo (isquemia) y desnutrición; todos deterioran la síntesis de colágeno y la perfusión."],"answer_index":3,"correct_text":"Diabetes/hiperglucemia, tabaquismo (isquemia) y desnutrición; todos deterioran la síntesis de colágeno y la perfusión.","explanation":"la hiperglucemia, el tabaquismo (vasoconstricción e hipoxia tisular) y la desnutrición son los factores clásicos que deterioran la cicatrización; hay que corregirlos. C es incorrecta: la edad contribuye, pero no es el único ni el principal factor corregible. A es incorrecta: el antibiótico no es la causa. B es incorrecta: la sutura no explica la mala granulación.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-07-04","number":64,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 4","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Mujer de 30 años con cicatriz que rebasa los límites de la herida original, crece con el tiempo, pica y no mejora.","questions":[{"id":"puem-r1-cc-r1-07-04-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico?","options":["Seroma.","Cicatriz hipertrófica.","Queloide.","ISQ."],"answer_index":2,"correct_text":"Queloide.","explanation":"el queloide rebasa los límites de la herida, crece con el tiempo y no regresa espontáneamente; la hipertrófica se queda dentro de los límites y mejora con el tiempo. B es incorrecta: la hipertrófica no rebasa los límites. D es incorrecta: no hay infección. A es incorrecta: el seroma es una colección líquida, no una cicatriz.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-07-05","number":65,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 5","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Hombre de 45 años, postoperatorio de cirugía limpia, con herida con eritema leve de 1 cm, sin secreción, sin fiebre, dolor decreciente.","questions":[{"id":"puem-r1-cc-r1-07-05-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Abrir la herida y dar antibiótico de amplio espectro.","Observación y curación habitual; es una herida con evolución normal.","Cultivo y TC.","Reintervención."],"answer_index":1,"correct_text":"Observación y curación habitual; es una herida con evolución normal.","explanation":"eritema leve limitado, sin secreción ni fiebre y dolor decreciente es evolución normal de la herida; no toda rojez es infección. A es incorrecta: abrir y dar antibiótico de amplio espectro es excesivo. C es incorrecta: no hay indicación de cultivo ni TC. D es incorrecta: no hay complicación.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-07-06","number":66,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 6","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Paciente con herida abdominal abierta, con tejido necrótico negro y secreción fétida, fiebre y leucocitosis.","questions":[{"id":"puem-r1-cc-r1-07-06-q1","ordinal":1,"stem":"¿Cuál es el tratamiento?","options":["Desbridamiento del tejido necrótico, cultivo, drenaje y antibiótico según gravedad; valorar presión negativa.","Cerrar la herida con puntos.","Solo analgésico.","Curaciones con gasa seca y antibiótico oral."],"answer_index":0,"correct_text":"Desbridamiento del tejido necrótico, cultivo, drenaje y antibiótico según gravedad; valorar presión negativa.","explanation":"el tejido necrótico debe desbridarse: es el foco de infección y impide la granulación; cerrar sobre necrosis es un error. D es incorrecta: la gasa seca y el antibiótico oral no desbridan necrosis. B es incorrecta: no se cierra una herida infectada con necrosis. C es incorrecta: el analgésico no trata la infección.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-07-07","number":67,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 7","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Hombre de 60 años, día 4 postoperatorio, con colección líquida clara bajo la herida, sin fiebre ni eritema.","questions":[{"id":"puem-r1-cc-r1-07-07-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable?","options":["Hematoma.","Fístula.","Absceso.","Seroma."],"answer_index":3,"correct_text":"Seroma.","explanation":"colección líquida clara, sin fiebre ni signos inflamatorios, es seroma (líquido seroso en el espacio muerto); el absceso es purulento con fiebre, el hematoma es sangre y la fístula drena contenido intestinal/biliar. C es incorrecta: no hay pus ni fiebre. A es incorrecta: el hematoma es hemático. B es incorrecta: no hay drenaje de contenido entérico.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-07-08","number":68,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 8","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Mujer de 50 años, postoperatorio de mastectomía, con herida que se abrió superficialmente (piel) pero la fascia está íntegra.","questions":[{"id":"puem-r1-cc-r1-07-08-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["No hacer nada.","Quirófano urgente por evisceración.","Curaciones, vigilancia y cierre por segunda intención o cierre diferido según la evolución; no es evisceración si la fascia está íntegra.","Dar antibiótico de amplio espectro por 4 semanas."],"answer_index":2,"correct_text":"Curaciones, vigilancia y cierre por segunda intención o cierre diferido según la evolución; no es evisceración si la fascia está íntegra.","explanation":"la dehiscencia superficial con fascia íntegra se maneja con curaciones y cierre por segunda intención o diferido; la urgencia es cuando hay dehiscencia fascial/evisceración. B es incorrecta: no hay evisceración. D es incorrecta: 4 semanas de antibiótico no están indicadas sin infección profunda. A es incorrecta: requiere curaciones y seguimiento.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-07-09","number":69,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 9","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Paciente con herida quirúrgica que se infectó; el cultivo reporta *S. aureus* sensible a meticilina.","questions":[{"id":"puem-r1-cc-r1-07-09-q1","ordinal":1,"stem":"¿Cuál es el principio del tratamiento?","options":["Solo antibiótico IV por 14 días sin tocar la herida.","Drenaje/desbridamiento de la herida + antibiótico dirigido según la gravedad y la extensión.","Cerrar la herida de inmediato.","Cambiar el antibiótico profiláctico."],"answer_index":1,"correct_text":"Drenaje/desbridamiento de la herida + antibiótico dirigido según la gravedad y la extensión.","explanation":"la ISQ se trata con drenaje/desbridamiento más antibiótico dirigido; el antibiótico solo no drena una colección. A es incorrecta: sin drenaje, el antibiótico no llega bien al foco. C es incorrecta: no se cierra una herida infectada. D es incorrecta: la profilaxis ya pasó; lo que importa es el tratamiento.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-07-10","number":70,"title":"Cicatrización y cuidado de las heridas quirúrgicas · caso 10","topic":"Cicatrización","topicId":"ap-r1-cicatrizacion","nivel":"R1","context":"Hombre de 40 años, fumador, programado para hernioplastia electiva.","questions":[{"id":"puem-r1-cc-r1-07-10-q1","ordinal":1,"stem":"¿Qué medida preoperatoria mejora más la cicatrización?","options":["Dar antibiótico por una semana antes.","Afeitar la zona con rasuradora la noche antes.","Dar vitamina C en dosis altas el día de la cirugía.","Dejar de fumar (al menos semanas antes) y controlar la glucosa; el tabaquismo es un factor mayor de ISQ y dehiscencia."],"answer_index":3,"correct_text":"Dejar de fumar (al menos semanas antes) y controlar la glucosa; el tabaquismo es un factor mayor de ISQ y dehiscencia.","explanation":"dejar de fumar mejora la oxigenación tisular y reduce ISQ y dehiscencia; el control glucémico también es clave. C es incorrecta: la vitamina A no es la medida principal. A es incorrecta: el antibiótico preoperatorio prolongado no previene más infección. B es incorrecta: afeitar con rasuradora aumenta la ISQ; si hay que retirar vello, se corta.","topic":"Cicatrización"}]},{"id":"puem-r1-cc-r1-08-01","number":71,"title":"Infección en cirugía · caso 1","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Hombre de 55 años con apendicitis perforada, peritonitis difusa, PAS 85 mmHg, lactato 4 mmol/L. En quirófano se controla el foco (apendicectomía y lavado).","questions":[{"id":"puem-r1-cc-r1-08-01-q1","ordinal":1,"stem":"¿Cuánto tiempo de antibiótico se recomienda tras un buen control del foco?","options":["Hasta que la PCR sea cero.","14 días siempre.","Aproximadamente 3-5 días tras control adecuado del foco, con reevaluación clínica.","Un solo día."],"answer_index":2,"correct_text":"Aproximadamente 3-5 días tras control adecuado del foco, con reevaluación clínica.","explanation":"las guías WSES/SIS recomiendan ~3-5 días tras control adecuado del foco en infección intraabdominal complicada; prolongar semanas por inercia no mejora el pronóstico y genera resistencia. B es incorrecta: 14 días no es el estándar tras buen control. D es incorrecta: un día es insuficiente en peritonitis difusa. A es incorrecta: la PCR no tiene que llegar a cero para suspender.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-08-02","number":72,"title":"Infección en cirugía · caso 2","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Mujer de 45 años con celulitis en la pierna que progresa rápidamente, dolor intenso desproporcionado a los hallazgos cutáneos, crepitación y fiebre 39.5 °C, con choque.","questions":[{"id":"puem-r1-cc-r1-08-02-q1","ordinal":1,"stem":"¿Cuál es la sospecha y la conducta?","options":["Trombosis venosa; anticoagular.","Absceso; drenaje ambulatorio.","Celulitis simple; antibiótico oral y alta.","Fascitis necrosante; desbridamiento quirúrgico urgente, sin esperar la imagen, + antibiótico de amplio espectro y UCI."],"answer_index":3,"correct_text":"Fascitis necrosante; desbridamiento quirúrgico urgente, sin esperar la imagen, + antibiótico de amplio espectro y UCI.","explanation":"dolor desproporcionado + progresión rápida + crepitación + choque es fascitis necrosante hasta demostrar lo contrario; el desbridamiento urgente es lo que salva la vida, la imagen no debe retrasarlo. C es incorrecta: la celulitis simple no da dolor desproporcionado ni crepitación ni choque. A es incorrecta: la trombosis no explica la crepitación ni la progresión cutánea. B es incorrecta: no es un absceso simple ambulatorio.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-08-03","number":73,"title":"Infección en cirugía · caso 3","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Hombre de 60 años con infección intraabdominal comunitaria por perforación de colon, sin factores de riesgo de resistencia.","questions":[{"id":"puem-r1-cc-r1-08-03-q1","ordinal":1,"stem":"¿Cuál es la cobertura antibiótica inicial adecuada?","options":["Cobertura de gramnegativos + anaerobios (p. ej. ceftriaxona + metronidazol o piperacilina-tazobactam según la gravedad).","Solo antifúngico.","Solo antibiótico oral.","Solo vancomicina."],"answer_index":0,"correct_text":"Cobertura de gramnegativos + anaerobios (p. ej. ceftriaxona + metronidazol o piperacilina-tazobactam según la gravedad).","explanation":"la flora intraabdominal comunitaria es gramnegativos entéricos + anaerobios; la cobertura debe incluir ambos. D es incorrecta: la vancomicina cubre grampositivos, no la flora entérica. B es incorrecta: el antifúngico no es la cobertura inicial en infección comunitaria sin factores de riesgo. C es incorrecta: la infección intraabdominal complicada requiere antibiótico IV y control del foco.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-08-04","number":74,"title":"Infección en cirugía · caso 4","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Paciente con sepsis abdominal, cultivos tomados, antibiótico iniciado. Al día 3 el cultivo reporta *E. coli* sensible a ceftriaxona; el paciente mejora.","questions":[{"id":"puem-r1-cc-r1-08-04-q1","ordinal":1,"stem":"¿Qué hacer con el antibiótico?","options":["Mantener el de amplio espectro por 14 días.","Desescalar a ceftriaxona (dirigido al cultivo) y completar el curso corto tras control del foco.","Suspender todo antibiótico de inmediato.","Cambiar a vancomicina."],"answer_index":1,"correct_text":"Desescalar a ceftriaxona (dirigido al cultivo) y completar el curso corto tras control del foco.","explanation":"desescalar con el cultivo es el estándar de *antimicrobial stewardship*: antibiótico dirigido, curso corto tras control del foco. A es incorrecta: mantener amplio espectro innecesariamente genera resistencia. C es incorrecta: suspender a los 3 días en peritonitis sin completar el curso no es lo indicado. D es incorrecta: la vancomicina no cubre *E. coli*.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-08-05","number":75,"title":"Infección en cirugía · caso 5","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Mujer de 35 años, día 5 postoperatorio de apendicectomía por apendicitis perforada, con fiebre persistente, dolor en fosa ilíaca derecha y leucocitosis, pese a antibiótico.","questions":[{"id":"puem-r1-cc-r1-08-05-q1","ordinal":1,"stem":"¿Qué se debe buscar?","options":["Infección urinaria.","Que el antibiótico es incorrecto y cambiarlo sin estudiar.","Colección/absceso residual: TC de abdomen para buscarlo y drenarlo si existe.","Que es normal y esperar."],"answer_index":2,"correct_text":"Colección/absceso residual: TC de abdomen para buscarlo y drenarlo si existe.","explanation":"la fiebre persistente tras 48-72 h de tratamiento en infección intraabdominal obliga a buscar colección residual o foco no controlado con imagen; cambiar el antibiótico sin buscar el foco es un error. B es incorrecta: cambiar el antibiótico sin imagen no resuelve una colección. D es incorrecta: no es normal a los 5 días con dolor localizado. A es incorrecta: el dolor en FID orienta a colección pélvica/apendicular, no a infección urinaria.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-08-06","number":76,"title":"Infección en cirugía · caso 6","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Hombre de 50 años con diabetes, absceso en la pierna, fiebre y leucocitosis. Se drena el absceso y se cultiva.","questions":[{"id":"puem-r1-cc-r1-08-06-q1","ordinal":1,"stem":"¿Cuál es el papel del antibiótico?","options":["No se necesita antibiótico nunca en abscesos.","Solo antibiótico tópico.","El antibiótico sustituye al drenaje.","El drenaje es el tratamiento principal; el antibiótico se agrega si hay celulitis extensa, fiebre, inmunosupresión o diabetes con infección grave."],"answer_index":3,"correct_text":"El drenaje es el tratamiento principal; el antibiótico se agrega si hay celulitis extensa, fiebre, inmunosupresión o diabetes con infección grave.","explanation":"el drenaje es el tratamiento del absceso; el antibiótico sistémico se agrega cuando hay celulitis extensa, fiebre, comorbilidad o inmunosupresión. C es incorrecta: el antibiótico no drena. A es incorrecta: en este paciente diabético con fiebre sí está indicado. B es incorrecta: el tópico no trata la infección sistémica.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-08-07","number":77,"title":"Infección en cirugía · caso 7","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Paciente con qSOFA de 2 (FR 24, PAS 95, Glasgow 15) y sospecha de infección abdominal.","questions":[{"id":"puem-r1-cc-r1-08-07-q1","ordinal":1,"stem":"¿Qué significa qSOFA 2?","options":["Tamizaje positivo: alto riesgo de mal pronóstico; requiere evaluación completa (SOFA, lactato, cultivos, antibiótico y búsqueda del foco).","Que no tiene sepsis.","Que necesita intubación.","Diagnóstico de sepsis confirmado."],"answer_index":0,"correct_text":"Tamizaje positivo: alto riesgo de mal pronóstico; requiere evaluación completa (SOFA, lactato, cultivos, antibiótico y búsqueda del foco).","explanation":"qSOFA ≥2 es un tamizaje de riesgo, no un diagnóstico; indica que hay que evaluar sepsis (SOFA, lactato) y actuar rápido. D es incorrecta: qSOFA no diagnostica sepsis. B es incorrecta: es lo contrario. C es incorrecta: qSOFA no indica intubación.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-08-08","number":78,"title":"Infección en cirugía · caso 8","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Hombre de 70 años con infección intraabdominal nosocomial, postoperatorio prolongado, con antibiótico previo y sonda vesical.","questions":[{"id":"puem-r1-cc-r1-08-08-q1","ordinal":1,"stem":"¿En qué difiere la cobertura respecto a la comunitaria?","options":["Es la misma.","Hay que ampliar: considerar *Pseudomonas*, enterococo y *Candida* según los factores de riesgo y la flora local.","Hay que dar menos cobertura.","Solo antifúngico."],"answer_index":1,"correct_text":"Hay que ampliar: considerar *Pseudomonas*, enterococo y *Candida* según los factores de riesgo y la flora local.","explanation":"la infección nosocomial, con antibiótico previo y estancia prolongada, tiene mayor riesgo de microorganismos resistentes y de *Candida*; la cobertura se amplía según los factores de riesgo. A es incorrecta: la flora nosocomial es distinta. C es incorrecta: es lo contrario. D es incorrecta: el antifúngico solo no cubre la flora bacteriana.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-08-09","number":79,"title":"Infección en cirugía · caso 9","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Mujer de 40 años con herida quirúrgica con eritema de 5 cm, calor y dolor, sin secreción, fiebre 38 °C.","questions":[{"id":"puem-r1-cc-r1-08-09-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Dar de alta sin seguimiento.","Abrir la herida de inmediato.","Antibiótico sistémico por celulitis de la herida, con vigilancia estrecha y reevaluación; abrir si hay colección o no mejora.","Solo curación sin antibiótico."],"answer_index":2,"correct_text":"Antibiótico sistémico por celulitis de la herida, con vigilancia estrecha y reevaluación; abrir si hay colección o no mejora.","explanation":"la celulitis de la herida sin colección se trata con antibiótico sistémico y vigilancia; abrir la herida sin colección no está indicado de inicio, pero hay que reevaluar si no mejora. B es incorrecta: no hay colección que drenar. D es incorrecta: con fiebre y celulitis extensa, el antibiótico sistémico está indicado. A es incorrecta: requiere seguimiento.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-08-10","number":80,"title":"Infección en cirugía · caso 10","topic":"Infección y cirugía","topicId":"ap-r1-infeccion","nivel":"R1","context":"Paciente con peritonitis, cultivos de sangre tomados después de iniciar el antibiótico.","questions":[{"id":"puem-r1-cc-r1-08-10-q1","ordinal":1,"stem":"¿Qué está mal en la secuencia?","options":["Los cultivos deben tomarse antes del antibiótico, sin retrasar el antibiótico; tomarlos después reduce su rendimiento.","No se deben tomar cultivos en peritonitis.","El antibiótico debe darse después de la cirugía.","Nada; el orden no importa."],"answer_index":0,"correct_text":"Los cultivos deben tomarse antes del antibiótico, sin retrasar el antibiótico; tomarlos después reduce su rendimiento.","explanation":"los cultivos (sangre y foco) se toman antes del antibiótico, pero sin retrasarlo; tomarlos después disminuye la probabilidad de identificar el microorganismo. D es incorrecta: el orden sí importa. B es incorrecta: los cultivos son fundamentales. C es incorrecta: el antibiótico debe darse en la primera hora, no después de la cirugía.","topic":"Infección y cirugía"}]},{"id":"puem-r1-cc-r1-03-01","number":81,"title":"Estado de choque · caso 1","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Hombre de 30 años, accidente vial, FC 130, PAS 85 mmHg, piel fría y pálida, llenado capilar 4 s, gasto urinario 0.3 mL/kg/h, lactato 5 mmol/L, Hb 9 g/dL, FAST positivo.","questions":[{"id":"puem-r1-cc-r1-03-01-q1","ordinal":1,"stem":"¿Cuál es el tipo de choque y la prioridad?","options":["Choque cardiogénico; dar dobutamina.","Choque hemorrágico; control de la hemorragia y transfusión balanceada, no solo cristaloides.","Choque séptico; antibiótico.","Choque neurogénico; dar vasopresor."],"answer_index":1,"correct_text":"Choque hemorrágico; control de la hemorragia y transfusión balanceada, no solo cristaloides.","explanation":"trauma + taquicardia, hipotensión, piel fría, oliguria, lactato alto y FAST positivo = choque hemorrágico; la prioridad es controlar la hemorragia (quirófano) y transfundir de forma balanceada, no litros de cristaloide que diluyen la coagulación. A es incorrecta: no hay datos de falla de bomba. C es incorrecta: no hay infección. D es incorrecta: el choque neurogénico cursa con bradicardia y piel caliente, no con taquicardia y piel fría.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-03-02","number":82,"title":"Estado de choque · caso 2","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Mujer de 70 años con peritonitis por perforación intestinal, PAS 80 mmHg pese a 2 L de cristaloides, lactato 4.5 mmol/L, FC 120, piel caliente, gasto urinario bajo.","questions":[{"id":"puem-r1-cc-r1-03-02-q1","ordinal":1,"stem":"¿Cuál es el vasopresor de primera línea y qué falta?","options":["Noradrenalina; falta el control del foco quirúrgico y el antibiótico precoz.","Adrenalina; falta intubar.","Fenilefrina; falta dar corticoides.","Dopamina; falta dar más cristaloides."],"answer_index":0,"correct_text":"Noradrenalina; falta el control del foco quirúrgico y el antibiótico precoz.","explanation":"es choque séptico: noradrenalina es el vasopresor de primera línea, y el tratamiento definitivo es el control del foco (cirugía) + antibiótico precoz; el vasopresor sin control del foco no resuelve la sepsis. D es incorrecta: la dopamina no es de primera línea y tiene más arritmias. B es incorrecta: la adrenalina no es de primera línea en sepsis y la intubación no es el paso que falta. C es incorrecta: los corticoides solo se consideran en choque refractario, no como primera medida.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-03-03","number":83,"title":"Estado de choque · caso 3","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Hombre de 25 años con lesión medular cervical, PAS 75 mmHg, FC 55, piel caliente y seca por debajo de la lesión, sin sangrado.","questions":[{"id":"puem-r1-cc-r1-03-03-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico?","options":["Choque cardiogénico.","Choque séptico.","Choque hemorrágico.","Choque neurogénico por pérdida del tono simpático."],"answer_index":3,"correct_text":"Choque neurogénico por pérdida del tono simpático.","explanation":"la lesión medular alta interrumpe el simpático: vasodilatación, hipotensión con bradicardia paradójica y piel caliente por debajo de la lesión. C es incorrecta: no hay sangrado ni taquicardia. A es incorrecta: no hay falla de bomba. B es incorrecta: no hay infección.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-03-04","number":84,"title":"Estado de choque · caso 4","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Paciente con trauma torácico, hipotensión, ingurgitación yugular, ruidos cardiacos apagados y pulso paradójico.","questions":[{"id":"puem-r1-cc-r1-03-04-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y la conducta?","options":["Embolia pulmonar; trombólisis.","Neumotórax a tensión; descompresión con aguja.","Taponamiento cardiaco; pericardiocentesis o cirugía urgente.","Choque séptico; antibiótico."],"answer_index":2,"correct_text":"Taponamiento cardiaco; pericardiocentesis o cirugía urgente.","explanation":"la tríada de Beck (hipotensión, ingurgitación yugular, ruidos apagados) en trauma torácico es taponamiento cardiaco: el tratamiento es drenar el pericardio (pericardiocentesis o ventana quirúrgica) de urgencia. B es incorrecta: el neumotórax a tensión da hipoventilación y desviación traqueal, no ruidos apagados. D es incorrecta: no hay infección. A es incorrecta: la embolia pulmonar no da ruidos apagados ni es el cuadro de trauma torácico con tríada de Beck.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-03-05","number":85,"title":"Estado de choque · caso 5","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Hombre de 55 años con choque hemorrágico clase III (pérdida 30-40%), FC 130, PAS 80, confuso, Hb 8 g/dL, temperatura 35 °C, pH 7.25. El R1 propone dar 3 L más de cristaloide antes de transfundir.","questions":[{"id":"puem-r1-cc-r1-03-05-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Dar los 3 L de cristaloide; la transfusión puede esperar.","Transfusión balanceada 1:1:1, control quirúrgico de la hemorragia, calcio y normotermia; evitar diluir con cristaloide.","Dar vasopresor para subir la presión.","Dar diurético para la acidosis."],"answer_index":1,"correct_text":"Transfusión balanceada 1:1:1, control quirúrgico de la hemorragia, calcio y normotermia; evitar diluir con cristaloide.","explanation":"en choque clase III-IV la transfusión balanceada y el control quirúrgico son prioritarios; el exceso de cristaloide diluye factores y plaquetas, empeora la coagulopatía y enfría al paciente (tríada letal). A es incorrecta: retrasar la transfusión empeora el choque. C es incorrecta: el vasopresor no sustituye volumen ni sangre en hemorragia. D es incorrecta: el diurético no trata la acidosis hemorrágica.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-03-06","number":86,"title":"Estado de choque · caso 6","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Mujer de 60 años, postoperatorio, PAS 95 mmHg, FC 105, lactato 3.2 mmol/L, gasto urinario 0.4 mL/kg/h, piel moteada, pero el R1 dice \"no está en choque porque la presión no está tan baja\".","questions":[{"id":"puem-r1-cc-r1-03-06-q1","ordinal":1,"stem":"¿Qué error comete?","options":["Confundir hipotensión con choque: el choque es hipoperfusión (lactato, oliguria, piel moteada) y puede existir con presión compensada.","Subestimar la taquicardia.","No pedir hemoglobina.","Ninguno; el choque se define por la presión."],"answer_index":0,"correct_text":"Confundir hipotensión con choque: el choque es hipoperfusión (lactato, oliguria, piel moteada) y puede existir con presión compensada.","explanation":"el choque es fallo de perfusión tisular; la hipotensión es tardía porque la compensación simpática mantiene la presión mientras la perfusión ya está comprometida (lactato alto, oliguria, piel moteada). D es incorrecta: el choque no se define por una cifra de presión. B es incorrecta: la taquicardia es un dato, no el error conceptual. C es incorrecta: pedir Hb no corrige el error de interpretación.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-03-07","number":87,"title":"Estado de choque · caso 7","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Paciente con sepsis abdominal, lactato inicial 5 mmol/L; tras reanimación y cirugía, el lactato baja a 2 mmol/L a las 6 h.","questions":[{"id":"puem-r1-cc-r1-03-07-q1","ordinal":1,"stem":"¿Qué significa?","options":["Que hay que dar más líquidos.","Que la sepsis se curó.","Nada; el lactato no sirve.","Aclaramiento de lactato: la perfusión está mejorando; es un buen signo pronóstico."],"answer_index":3,"correct_text":"Aclaramiento de lactato: la perfusión está mejorando; es un buen signo pronóstico.","explanation":"el aclaramiento seriado del lactato refleja mejoría de la perfusión y se asocia a mejor pronóstico; un solo valor no basta, importa la tendencia. C es incorrecta: el lactato es un marcador útil de hipoperfusión. A es incorrecta: no es una indicación automática de más líquidos. B es incorrecta: la sepsis no se \"cura\" en 6 h; el lactato mejorando es solo un signo de mejor perfusión.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-03-08","number":88,"title":"Estado de choque · caso 8","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Hombre de 40 años, trauma, PAS 80 mmHg, sin TCE, hemorragia abdominal activa. El R1 quiere subir la PAS a 120 mmHg con líquidos antes de entrar a quirófano.","questions":[{"id":"puem-r1-cc-r1-03-08-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["No dar nada hasta quirófano.","Subir la PAS a 120 mmHg.","Reanimación hipotensiva permisiva (PAS ~80-90 mmHg) hasta controlar la hemorragia.","Dar vasopresor para llegar a 120."],"answer_index":2,"correct_text":"Reanimación hipotensiva permisiva (PAS ~80-90 mmHg) hasta controlar la hemorragia.","explanation":"en hemorragia sin TCE, subir la presión antes de controlar el sangrado desprende el coágulo y aumenta la hemorragia; la reanimación hipotensiva permisiva (PAS ~80-90 mmHg) mantiene perfusión mínima hasta el control quirúrgico. B es incorrecta: es contraproducente en hemorragia activa. D es incorrecta: el vasopresor no sustituye el control de la hemorragia. A es incorrecta: hay que reanimar, pero con objetivo permisivo, no con nada.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-03-09","number":89,"title":"Estado de choque · caso 9","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Mujer de 75 años con choque séptico que no responde a noradrenalina a dosis altas, con lactato persistente.","questions":[{"id":"puem-r1-cc-r1-03-09-q1","ordinal":1,"stem":"¿Qué se considera en el choque refractario?","options":["Suspender el vasopresor.","Hidrocortisona, además de revisar que el foco esté controlado y descartar otras causas.","Dar antibiótico de amplio espectro por primera vez.","Dar diurético."],"answer_index":1,"correct_text":"Hidrocortisona, además de revisar que el foco esté controlado y descartar otras causas.","explanation":"en el choque séptico refractario a vasopresores se considera hidrocortisona, pero antes hay que verificar que el foco esté controlado y que no haya otra causa (hemorragia, insuficiencia suprarrenal, error de dosis). A es incorrecta: suspender el vasopresor colapsa la perfusión. C es incorrecta: el antibiótico debió darse en la primera hora, no es la medida del choque refractario. D es incorrecta: el diurético no trata el choque.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-03-10","number":90,"title":"Estado de choque · caso 10","topic":"Estado de choque","topicId":"ap-r1-choque","nivel":"R1","context":"Paciente con embolia pulmonar masiva, hipotensión, taquicardia, ingurgitación yugular y saturación baja, sin sangrado.","questions":[{"id":"puem-r1-cc-r1-03-10-q1","ordinal":1,"stem":"¿Cuál es el tipo de choque?","options":["Distributivo.","Cardiogénico por infarto.","Hipovolémico.","Obstructivo."],"answer_index":3,"correct_text":"Obstructivo.","explanation":"la embolia pulmonar masiva obstruye el flujo pulmonar y el llenado del ventrículo izquierdo: es choque obstructivo. C es incorrecta: no hay pérdida de volumen. A es incorrecta: no hay vasodilatación distributiva. B es incorrecta: no es falla primaria de bomba por infarto, aunque el ventrículo derecho falle secundariamente por la obstrucción.","topic":"Estado de choque"}]},{"id":"puem-r1-cc-r1-05-01","number":91,"title":"Nutrición en cirugía · caso 1","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Hombre de 65 años con cáncer de esófago, pérdida de 12 kg en 4 meses (18% del peso), IMC 17, programado para esofagectomía en 3 semanas.","questions":[{"id":"puem-r1-cc-r1-05-01-q1","ordinal":1,"stem":"¿Cuál es la conducta nutricional preoperatoria?","options":["Nutrición parenteral total como primera opción.","Dar suplementos orales solo el día antes.","Operar de inmediato sin soporte.","Soporte nutricional preoperatorio (7-14 días o más) con vía enteral si es posible, y valorar inmunonutrición; no operar desnutrido grave sin intentar optimizar."],"answer_index":3,"correct_text":"Soporte nutricional preoperatorio (7-14 días o más) con vía enteral si es posible, y valorar inmunonutrición; no operar desnutrido grave sin intentar optimizar.","explanation":"la desnutrición grave (>10-15% de pérdida) antes de cirugía mayor oncológica exige soporte preoperatorio; la vía enteral es preferible y la inmunonutrición tiene evidencia en cirugía digestiva mayor (ESPEN). C es incorrecta: operar desnutrido grave aumenta fugas e infecciones. A es incorrecta: la parenteral es el plan B si el tubo no funciona. B es incorrecta: un día de suplementos no corrige la desnutrición grave.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-05-02","number":92,"title":"Nutrición en cirugía · caso 2","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Mujer de 50 años, desnutrida grave, en ayuno prolongado, inicia nutrición enteral a dosis plenas. A las 48 h presenta debilidad, arritmia, fósforo 1.8 mg/dL, K⁺ 3.0 y Mg²⁺ 1.3.","questions":[{"id":"puem-r1-cc-r1-05-02-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico?","options":["Deshidratación.","Sepsis.","Síndrome de realimentación.","Hipotiroidismo."],"answer_index":2,"correct_text":"Síndrome de realimentación.","explanation":"al reiniciar la alimentación en el desnutrido grave, la insulina mete fósforo, potasio y magnesio a la célula y caen en sangre, con arritmia y debilidad: es el síndrome de realimentación; se previene iniciando lento y reponiendo electrolitos. B es incorrecta: no hay datos de infección. D es incorrecta: no explica la caída de fósforo tras realimentar. A es incorrecta: la deshidratación no produce este patrón.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-05-03","number":93,"title":"Nutrición en cirugía · caso 3","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Hombre de 70 años, postoperatorio de cirugía mayor, con íleo leve, sonda nasogástrica con gasto bajo y yeyunostomía de alimentación. El R1 quiere mantenerlo en ayuno total \"hasta que el íleo se resuelva\".","questions":[{"id":"puem-r1-cc-r1-05-03-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Ayuno total hasta que haya evacuaciones.","Nutrición enteral precoz por la yeyunostomía (distal al íleo gástrico), si no hay contraindicación.","Nutrición parenteral total de inmediato.","Solo líquidos orales."],"answer_index":1,"correct_text":"Nutrición enteral precoz por la yeyunostomía (distal al íleo gástrico), si no hay contraindicación.","explanation":"la nutrición enteral precoz por acceso distal (yeyunal) es posible y beneficiosa aunque haya íleo gástrico leve; el ayuno prolongado empeora el catabolismo. A es incorrecta: el ayuno total innecesario es dañino. C es incorrecta: la parenteral no es el primer paso si hay acceso enteral funcional. D es incorrecta: los líquidos orales no cubren los requerimientos.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-05-04","number":94,"title":"Nutrición en cirugía · caso 4","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Paciente crítico, día 3 en UCI, con tubo digestivo funcionante, sin nutrición. El R1 dice \"esperemos a que esté estable para nutrirlo\".","questions":[{"id":"puem-r1-cc-r1-05-04-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Iniciar nutrición enteral precoz (24-48 h) en el paciente crítico si el tubo funciona y no hay contraindicación.","Dar solo glucosa IV.","Nutrición parenteral desde el día 1.","Esperar a la estabilidad completa."],"answer_index":0,"correct_text":"Iniciar nutrición enteral precoz (24-48 h) en el paciente crítico si el tubo funciona y no hay contraindicación.","explanation":"las guías recomiendan nutrición enteral precoz (24-48 h) en el paciente crítico; esperar a la \"estabilidad completa\" prolonga el catabolismo y la pérdida muscular. D es incorrecta: la espera innecesaria es dañina. B es incorrecta: la glucosa sola no cubre proteína ni energía. C es incorrecta: la parenteral no es el primer paso si el tubo funciona.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-05-05","number":95,"title":"Nutrición en cirugía · caso 5","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Mujer de 60 años con NRS-2002 de 4 al ingreso, programada para cirugía mayor.","questions":[{"id":"puem-r1-cc-r1-05-05-q1","ordinal":1,"stem":"¿Qué significa el puntaje?","options":["Desnutrición grave confirmada.","Que no necesita nutrición.","Sin riesgo nutricional.","Riesgo nutricional; requiere valoración y plan de soporte."],"answer_index":3,"correct_text":"Riesgo nutricional; requiere valoración y plan de soporte.","explanation":"NRS-2002 ≥3 indica riesgo nutricional y obliga a valoración y plan de soporte; no es por sí solo el diagnóstico de desnutrición grave (que requiere criterios GLIM). C es incorrecta: 4 es mayor que 3. A es incorrecta: el tamizaje no confirma desnutrición grave. B es incorrecta: es lo contrario.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-05-06","number":96,"title":"Nutrición en cirugía · caso 6","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Hombre de 55 años, postoperatorio, con nutrición parenteral por catéter central, fiebre 39 °C, sin otro foco.","questions":[{"id":"puem-r1-cc-r1-05-06-q1","ordinal":1,"stem":"¿Qué debe sospecharse primero?","options":["Infección de herida.","Que la nutrición parenteral causa fiebre por sí misma.","Infección del catéter; valorar el catéter como foco y cultivarlo.","Atelectasia."],"answer_index":2,"correct_text":"Infección del catéter; valorar el catéter como foco y cultivarlo.","explanation":"la fiebre sin foco en un paciente con catéter central para nutrición parenteral obliga a sospechar infección relacionada con el catéter (cultivos, revisión del sitio, valorar retiro). D es incorrecta: la atelectasia no es el primer foco en este contexto. A es incorrecta: no hay datos de herida. B es incorrecta: la nutrición parenteral no causa fiebre por sí misma; la causa es la infección del acceso.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-05-07","number":97,"title":"Nutrición en cirugía · caso 7","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Paciente con requerimientos de 1,800 kcal/día, recibe nutrición enteral de 800 kcal/día porque \"no tolera más\" (residuo gástrico alto).","questions":[{"id":"puem-r1-cc-r1-05-07-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Aceptar 800 kcal; es lo que tolera.","Revisar la causa de la intolerancia (posición, procinéticos, acceso postpilórico, velocidad) y ajustar para acercarse al requerimiento; medir la ingesta real.","Suspender la nutrición enteral y dar parenteral.","Dar el resto por vía oral aunque no coma."],"answer_index":1,"correct_text":"Revisar la causa de la intolerancia (posición, procinéticos, acceso postpilórico, velocidad) y ajustar para acercarse al requerimiento; medir la ingesta real.","explanation":"la intolerancia tiene causas tratables (velocidad, posición, procinéticos, acceso yeyunal); hay que ajustar para cubrir el requerimiento, no conformarse con menos de la mitad. A es incorrecta: aceptar el déficit perpetúa el catabolismo. C es incorrecta: la parenteral no es el primer paso ante intolerancia gástrica. D es incorrecta: si no come, la vía oral no cubre.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-05-08","number":98,"title":"Nutrición en cirugía · caso 8","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Hombre de 48 años, quemado grave, con requerimientos proteicos altos. El R1 prescribe 0.8 g/kg/día de proteína \"como en el sano\".","questions":[{"id":"puem-r1-cc-r1-05-08-q1","ordinal":1,"stem":"¿Qué está mal?","options":["El paciente crítico/quemado necesita ~1.2-2 g/kg/día; 0.8 es insuficiente y perpetúa el catabolismo.","Necesita menos proteína por el riñón.","La proteína no importa en el quemado.","Nada; es lo estándar."],"answer_index":0,"correct_text":"El paciente crítico/quemado necesita ~1.2-2 g/kg/día; 0.8 es insuficiente y perpetúa el catabolismo.","explanation":"el estrés grave aumenta el catabolismo proteico y los requerimientos (aprox. 1.2-2 g/kg/día, individualizando en insuficiencia renal); 0.8 g/kg/día es la recomendación para el adulto sano, no para el paciente crítico. D es incorrecta: subestima el requerimiento. B es incorrecta: solo se restringe si hay insuficiencia renal grave y se individualiza. C es incorrecta: la proteína es central en el quemado.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-05-09","number":99,"title":"Nutrición en cirugía · caso 9","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Mujer de 70 años, postoperatorio, con albúmina 2.8 g/dL y prealbúmina baja, con PCR 180 mg/L. El R1 dice \"está desnutrida por la albúmina\".","questions":[{"id":"puem-r1-cc-r1-05-09-q1","ordinal":1,"stem":"¿Qué matiz falta?","options":["Hay que dar albúmina IV.","La PCR no importa.","Ninguno; la albúmina diagnostica desnutrición.","La albúmina y la prealbúmina son reactantes de fase aguda: bajan por inflamación, no solo por desnutrición; el diagnóstico requiere criterios GLIM (pérdida de peso, IMC, masa muscular + etiología)."],"answer_index":3,"correct_text":"La albúmina y la prealbúmina son reactantes de fase aguda: bajan por inflamación, no solo por desnutrición; el diagnóstico requiere criterios GLIM (pérdida de peso, IMC, masa muscular + etiología).","explanation":"con PCR alta, la hipoalbuminemia refleja inflamación; el diagnóstico de desnutrición requiere criterios clínicos (GLIM), no un solo laboratorio. C es incorrecta: la albúmina aislada no diagnostica desnutrición. A es incorrecta: la albúmina IV no trata la desnutrición. B es incorrecta: la PCR es la clave para interpretar la albúmina.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-05-10","number":100,"title":"Nutrición en cirugía · caso 10","topic":"Nutrición en cirugía","topicId":"ap-r1-nutricion","nivel":"R1","context":"Paciente con fístula entero-cutánea de alto gasto, en ayuno, con nutrición parenteral.","questions":[{"id":"puem-r1-cc-r1-05-10-q1","ordinal":1,"stem":"¿Por qué la parenteral es adecuada aquí y no la enteral?","options":["Porque la enteral siempre es mala.","Porque el tubo digestivo no puede usarse (fístula de alto gasto, ayuno terapéutico) y la parenteral es la vía indicada cuando el tubo no funciona o no se puede usar.","Porque la parenteral es más barata.","Porque el paciente prefiere la parenteral."],"answer_index":1,"correct_text":"Porque el tubo digestivo no puede usarse (fístula de alto gasto, ayuno terapéutico) y la parenteral es la vía indicada cuando el tubo no funciona o no se puede usar.","explanation":"la nutrición parenteral está indicada cuando el tubo digestivo no funciona o no se puede usar (fístula de alto gasto, obstrucción, íleo grave prolongado); es el plan B justificado, no el primero en general. A es incorrecta: la enteral es preferible cuando el tubo funciona. C es incorrecta: la parenteral es más cara y con más complicaciones. D es incorrecta: la preferencia no es la indicación.","topic":"Nutrición en cirugía"}]},{"id":"puem-r1-cc-r1-06-01","number":101,"title":"Sangre, hemostasia y transfusión · caso 1","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Hombre de 60 años, postoperatorio de cirugía mayor, Hb 7.2 g/dL, estable, sin sangrado activo, sin cardiopatía isquémica, sin disnea.","questions":[{"id":"puem-r1-cc-r1-06-01-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["No transfundir; vigilancia, corregir hierro si hay deficiencia y tolerar Hb 7.2 en el paciente estable (umbral restrictivo).","Transfundir plasma.","Dar eritropoyetina de urgencia.","Transfundir 2 unidades de inmediato."],"answer_index":0,"correct_text":"No transfundir; vigilancia, corregir hierro si hay deficiencia y tolerar Hb 7.2 en el paciente estable (umbral restrictivo).","explanation":"en el paciente estable sin isquemia, el umbral restrictivo es Hb <7 g/dL; con 7.2 y sin síntomas no hay indicación de transfundir. D es incorrecta: transfundir por la cifra sin síntomas expone a TRALI/TACO sin beneficio. B es incorrecta: el plasma no trata la anemia. C es incorrecta: la eritropoyetina no es tratamiento agudo.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-06-02","number":102,"title":"Sangre, hemostasia y transfusión · caso 2","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Mujer de 70 años con cardiopatía isquémica, Hb 7.8 g/dL, angina y disnea postoperatoria.","questions":[{"id":"puem-r1-cc-r1-06-02-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["No transfundir; el umbral es 7.","Transfundir (umbral <8 g/dL con cardiopatía isquémica sintomática) y valorar la causa.","Dar plasma.","Dar diurético."],"answer_index":1,"correct_text":"Transfundir (umbral <8 g/dL con cardiopatía isquémica sintomática) y valorar la causa.","explanation":"con cardiopatía isquémica sintomática el umbral restrictivo sube a ~8 g/dL; la angina y la disnea son síntomas de isquemia que justifican transfundir. A es incorrecta: el umbral de 7 es para el paciente estable sin cardiopatía. C es incorrecta: el plasma no corrige la anemia ni la isquemia. D es incorrecta: el diurético no trata la anemia isquémica.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-06-03","number":103,"title":"Sangre, hemostasia y transfusión · caso 3","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Hombre de 35 años, trauma, hemorragia masiva, recibió 8 unidades de concentrado eritrocitario, con sangrado difuso en sábana, temperatura 35 °C, pH 7.22, Ca²⁺ ionizado bajo, plaquetas 60,000, fibrinógeno 120 mg/dL.","questions":[{"id":"puem-r1-cc-r1-06-03-q1","ordinal":1,"stem":"¿Qué falta en la reanimación?","options":["Diurético.","Más concentrado eritrocitario solo.","Transfusión balanceada (plasma y plaquetas), fibrinógeno, calcio y normotermia; corregir la tríada letal.","Vasopresor."],"answer_index":2,"correct_text":"Transfusión balanceada (plasma y plaquetas), fibrinógeno, calcio y normotermia; corregir la tríada letal.","explanation":"el sangrado difuso con hipotermia, acidosis, hipocalcemia, trombocitopenia y fibrinógeno bajo es coagulopatía por dilución y consumo; necesita plasma, plaquetas, fibrinógeno, calcio y calor, no solo glóbulos. B es incorrecta: más glóbulos sin plasma/plaquetas empeora la dilución. D es incorrecta: el vasopresor no corrige la coagulopatía. A es incorrecta: el diurético no tiene papel.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-06-04","number":104,"title":"Sangre, hemostasia y transfusión · caso 4","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Paciente con hemorragia masiva, TEG muestra tiempo de formación de coágulo prolongado y amplitud máxima baja.","questions":[{"id":"puem-r1-cc-r1-06-04-q1","ordinal":1,"stem":"¿Qué indica?","options":["Hipercoagulabilidad.","Que el TEG no sirve.","Exceso de fibrinólisis.","Déficit de fibrinógeno y plaquetas (mala firmeza del coágulo)."],"answer_index":3,"correct_text":"Déficit de fibrinógeno y plaquetas (mala firmeza del coágulo).","explanation":"la amplitud máxima baja refleja mala firmeza del coágulo por déficit de plaquetas y/o fibrinógeno; el TEG/ROTEM guía qué componente reponer. C es incorrecta: la fibrinólisis se ve como lisis (LY30 alto), no como amplitud baja. A es incorrecta: es lo contrario. B es incorrecta: el TEG es útil en hemorragia masiva.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-06-05","number":105,"title":"Sangre, hemostasia y transfusión · caso 5","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Mujer de 50 años, en warfarina, INR 4.5, con hemorragia digestiva grave.","questions":[{"id":"puem-r1-cc-r1-06-05-q1","ordinal":1,"stem":"¿Cuál es la reversión más rápida y eficaz?","options":["Complejo protrombínico concentrado + vitamina K IV.","Plasma fresco congelado solo.","Esperar a que se metabolice la warfarina.","Vitamina K oral."],"answer_index":0,"correct_text":"Complejo protrombínico concentrado + vitamina K IV.","explanation":"el complejo protrombínico concentrado revierte rápido el INR en hemorragia grave, con vitamina K IV para sostener la reversión; el plasma solo es más lento y requiere gran volumen. D es incorrecta: la vitamina K oral es lenta (horas-días). B es incorrecta: el plasma solo es menos eficaz y más lento que el complejo protrombínico. C es incorrecta: esperar en hemorragia grave es peligroso.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-06-06","number":106,"title":"Sangre, hemostasia y transfusión · caso 6","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Hombre de 65 años, post-transfusión de 1 unidad, con disnea súbita, hipoxemia y edema pulmonar en la radiografía, sin sobrecarga de volumen evidente.","questions":[{"id":"puem-r1-cc-r1-06-06-q1","ordinal":1,"stem":"¿Cuál es la sospecha?","options":["TACO (sobrecarga circulatoria).","TRALI (lesión pulmonar aguda asociada a transfusión).","Reacción hemolítica.","Ansiedad."],"answer_index":1,"correct_text":"TRALI (lesión pulmonar aguda asociada a transfusión).","explanation":"disnea e hipoxemia con edema pulmonar en las primeras 6 h post-transfusión sin sobrecarga de volumen es TRALI; TACO es por sobrecarga (hipertensión, ingurgitación, respuesta a diurético). A es incorrecta: TACO implica sobrecarga de volumen. C es incorrecta: la reacción hemolítica da fiebre, dolor lumbar, hemoglobinuria y choque, no edema pulmonar aislado. D es incorrecta: la hipoxemia con edema no es ansiedad.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-06-07","number":107,"title":"Sangre, hemostasia y transfusión · caso 7","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Paciente con plaquetas 45,000/µL, sin sangrado, programado para cirugía mayor electiva.","questions":[{"id":"puem-r1-cc-r1-06-07-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Cancelar la cirugía para siempre.","Operar sin transfundir.","Transfundir plaquetas para subir a >50,000/µL antes de cirugía mayor.","Dar plasma."],"answer_index":2,"correct_text":"Transfundir plaquetas para subir a >50,000/µL antes de cirugía mayor.","explanation":"para cirugía mayor se busca plaquetas >50,000/µL; con 45,000 y cirugía mayor, transfundir plaquetas es lo indicado. B es incorrecta: operar con plaquetas bajas en cirugía mayor aumenta el sangrado. D es incorrecta: el plasma no sube plaquetas. A es incorrecta: es corregible, no contraindicación permanente.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-06-08","number":108,"title":"Sangre, hemostasia y transfusión · caso 8","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Hombre de 40 años con trauma y hemorragia, llegó 1 h después del accidente.","questions":[{"id":"puem-r1-cc-r1-06-08-q1","ordinal":1,"stem":"¿Cuándo debe darse el ácido tranexámico?","options":["Nunca en trauma.","Solo si hay fibrinólisis documentada.","Después de 3 h, cuando esté estable.","Lo antes posible, dentro de las primeras 3 h."],"answer_index":3,"correct_text":"Lo antes posible, dentro de las primeras 3 h.","explanation":"el ácido tranexámico reduce la mortalidad en hemorragia traumática si se da en las primeras 3 h; después de ese tiempo el beneficio se pierde y puede haber daño. C es incorrecta: después de 3 h no es el momento. A es incorrecta: está indicado en trauma hemorrágico. B es incorrecta: no hay que esperar a documentar fibrinólisis.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-06-09","number":109,"title":"Sangre, hemostasia y transfusión · caso 9","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Mujer de 60 años, postoperatorio, Hb 10 g/dL, con sangrado por la herida que no se controla con compresión, TP prolongado, TTPa prolongado, plaquetas normales.","questions":[{"id":"puem-r1-cc-r1-06-09-q1","ordinal":1,"stem":"¿Qué sugiere?","options":["Coagulopatía por déficit de factores (vía común) o anticoagulante; revisar fármacos, dilución y vitamina K.","Que el sangrado es solo técnico.","Que hay que dar plaquetas.","Trombocitopenia."],"answer_index":0,"correct_text":"Coagulopatía por déficit de factores (vía común) o anticoagulante; revisar fármacos, dilución y vitamina K.","explanation":"TP y TTPa prolongados con plaquetas normales sugieren déficit de factores de coagulación (dilución, anticoagulante, déficit de vitamina K, hepatopatía); hay que revisar fármacos y corregir la causa. D es incorrecta: las plaquetas son normales. B es incorrecta: el sangrado puede ser técnico, pero los tiempos prolongados indican coagulopatía concomitante. C es incorrecta: las plaquetas son normales; darlas no corrige el TP/TTPa.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-06-10","number":110,"title":"Sangre, hemostasia y transfusión · caso 10","topic":"Sangre: coagulación y transfusión","topicId":"ap-r1-sangre","nivel":"R1","context":"Paciente con anemia preoperatoria (Hb 10.5 g/dL, ferritina baja) programado para cirugía mayor electiva en 4 semanas.","questions":[{"id":"puem-r1-cc-r1-06-10-q1","ordinal":1,"stem":"¿Cuál es la mejor conducta de *patient blood management*?","options":["Dar eritropoyetina sin hierro.","Programar transfusión el día de la cirugía.","Corregir la deficiencia de hierro (oral o IV según el tiempo y la tolerancia) antes de la cirugía y reevaluar la Hb.","No hacer nada; 10.5 es normal."],"answer_index":2,"correct_text":"Corregir la deficiencia de hierro (oral o IV según el tiempo y la tolerancia) antes de la cirugía y reevaluar la Hb.","explanation":"la anemia ferropénica preoperatoria se corrige con hierro antes de la cirugía electiva, lo que reduce transfusiones y complicaciones; es el pilar del *patient blood management*. B es incorrecta: transfundir el día de la cirugía no corrige la causa. D es incorrecta: 10.5 con ferritina baja es anemia ferropénica que debe corregirse. A es incorrecta: la eritropoyetina sin hierro no funciona si hay deficiencia de hierro.","topic":"Sangre: coagulación y transfusión"}]},{"id":"puem-r1-cc-r1-10-01","number":111,"title":"Trauma: evaluación inicial ATLS · caso 1","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Hombre de 28 años, accidente vial, Glasgow 7, con vómito y sangre en la boca, saturación 88%.","questions":[{"id":"puem-r1-cc-r1-10-01-q1","ordinal":1,"stem":"¿Cuál es la prioridad?","options":["TC de cráneo de inmediato.","Vía aérea definitiva (intubación con control cervical) antes de la TC.","Dar líquidos.","Poner sonda vesical."],"answer_index":1,"correct_text":"Vía aérea definitiva (intubación con control cervical) antes de la TC.","explanation":"Glasgow ≤8 = no protege la vía aérea; la vía aérea definitiva es la prioridad (A) antes de la TC, con control cervical. A es incorrecta: no se lleva a TC a un paciente sin vía aérea protegida. C es incorrecta: los líquidos no son la prioridad sobre la vía aérea. D es incorrecta: la sonda no es prioritaria.","topic":"Trauma"}]},{"id":"puem-r1-cc-r1-10-02","number":112,"title":"Trauma: evaluación inicial ATLS · caso 2","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Paciente con trauma torácico, disnea grave, hipotensión, desviación traqueal a la izquierda, ingurgitación yugular y ausencia de murmullo vesicular derecho.","questions":[{"id":"puem-r1-cc-r1-10-02-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y la acción?","options":["Neumotórax a tensión derecho; descompresión inmediata (aguja/toracostomía) sin esperar la radiografía.","Taponamiento; pericardiocentesis.","Contusión pulmonar; oxígeno.","Hemotórax; tubo pleural."],"answer_index":0,"correct_text":"Neumotórax a tensión derecho; descompresión inmediata (aguja/toracostomía) sin esperar la radiografía.","explanation":"disnea + hipotensión + desviación traqueal + ausencia de murmullo + ingurgitación es neumotórax a tensión; la descompresión inmediata salva la vida y no debe esperar la imagen. D es incorrecta: el hemotórax no desvía la tráquea de esta forma ni es la emergencia inmediata de la misma manera. B es incorrecta: el taponamiento no da ausencia de murmullo ni desviación traqueal. C es incorrecta: la contusión no explica la desviación traqueal ni la hipotensión súbita.","topic":"Trauma"}]},{"id":"puem-r1-cc-r1-10-03","number":113,"title":"Trauma: evaluación inicial ATLS · caso 3","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Hombre de 35 años, trauma abdominal contuso, FC 125, PAS 85, FAST positivo, pelvis estable, sin TCE.","questions":[{"id":"puem-r1-cc-r1-10-03-q1","ordinal":1,"stem":"¿A dónde va?","options":["A observación en piso.","A dar líquidos por 6 h y reevaluar.","A TC de abdomen.","A quirófano (laparotomía) por inestabilidad con FAST positivo."],"answer_index":3,"correct_text":"A quirófano (laparotomía) por inestabilidad con FAST positivo.","explanation":"el paciente inestable con FAST positivo y sangrado abdominal va a quirófano, no a TC; la TC es para el paciente estable. C es incorrecta: llevar a TC a un paciente inestable retrasa el control de la hemorragia. A es incorrecta: no es un paciente para observación. B es incorrecta: los líquidos no sustituyen el control quirúrgico.","topic":"Trauma"}]},{"id":"puem-r1-cc-r1-10-04","number":114,"title":"Trauma: evaluación inicial ATLS · caso 4","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Mujer de 22 años, caída de altura, pelvis inestable, hipotensión, FC 130, sin sangrado externo.","questions":[{"id":"puem-r1-cc-r1-10-04-q1","ordinal":1,"stem":"¿Cuál es la medida inmediata en pelvis?","options":["Dar vasopresor.","TC de pelvis.","*Binder* pélvico (o sábana) para estabilizar la pelvis y reducir el sangrado, además de transfusión.","Sonda vesical."],"answer_index":2,"correct_text":"*Binder* pélvico (o sábana) para estabilizar la pelvis y reducir el sangrado, además de transfusión.","explanation":"la pelvis inestable con hipotensión sangra por el plexo venoso y la fractura; el *binder* pélvico reduce el volumen pélvico y el sangrado. B es incorrecta: la TC no es la medida inmediata en inestabilidad. D es incorrecta: la sonda no controla el sangrado. A es incorrecta: el vasopresor no sustituye el control mecánico del sangrado.","topic":"Trauma"}]},{"id":"puem-r1-cc-r1-10-05","number":115,"title":"Trauma: evaluación inicial ATLS · caso 5","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Hombre de 50 años, politrauma, temperatura 34.5 °C, pH 7.20, coagulopatía, sangrado difuso. El cirujano planea hacer la reparación definitiva de todas las lesiones en una sola cirugía de 6 h.","questions":[{"id":"puem-r1-cc-r1-10-05-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Hacer la cirugía definitiva completa.","Cirugía de control de daños: controlar hemorragia y contaminación, empaquetar, abdomen abierto, UCI, reoperación programada.","No operar.","Dar solo líquidos."],"answer_index":1,"correct_text":"Cirugía de control de daños: controlar hemorragia y contaminación, empaquetar, abdomen abierto, UCI, reoperación programada.","explanation":"el paciente frío, ácido y coagulopático (tríada letal) no tolera la cirugía definitiva; el control de daños salva la vida y la reparación definitiva se hace cuando se corrige la fisiología. A es incorrecta: la cirugía larga empeora la tríada letal. C es incorrecta: hay que controlar la hemorragia y la contaminación. D es incorrecta: los líquidos no controlan la hemorragia.","topic":"Trauma"}]},{"id":"puem-r1-cc-r1-10-06","number":116,"title":"Trauma: evaluación inicial ATLS · caso 6","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Paciente con TCE grave, Glasgow 8, pupila derecha dilatada y sin reacción, FC 50, PAS 180 mmHg.","questions":[{"id":"puem-r1-cc-r1-10-06-q1","ordinal":1,"stem":"¿Qué sugiere?","options":["Hipertensión intracraneal con herniación (tríada de Cushing: hipertensión, bradicardia, alteración respiratoria) y hematoma con efecto de masa.","Hipoglucemia.","Intoxicación.","Choque hemorrágico."],"answer_index":0,"correct_text":"Hipertensión intracraneal con herniación (tríada de Cushing: hipertensión, bradicardia, alteración respiratoria) y hematoma con efecto de masa.","explanation":"anisocoria con pupila dilatada + bradicardia + hipertensión es herniación por hipertensión intracraneal/hematoma; es una emergencia neuroquirúrgica (TC urgente, medidas antihipertensión intracraneal, neurocirugía). D es incorrecta: el choque hemorrágico da taquicardia e hipotensión. B es incorrecta: la hipoglucemia no da anisocoria ni tríada de Cushing. C es incorrecta: la intoxicación no explica la anisocoria con bradicardia e hipertensión.","topic":"Trauma"}]},{"id":"puem-r1-cc-r1-10-07","number":117,"title":"Trauma: evaluación inicial ATLS · caso 7","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Hombre de 30 años, trauma penetrante en abdomen, estable, sin peritonitis, con eFAST negativo.","questions":[{"id":"puem-r1-cc-r1-10-07-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Alta.","Observación sin imagen.","Laparotomía de inmediato.","TC de abdomen con contraste (paciente estable) para definir la lesión y la conducta."],"answer_index":3,"correct_text":"TC de abdomen con contraste (paciente estable) para definir la lesión y la conducta.","explanation":"el paciente estable con trauma penetrante sin peritonitis se estudia con TC para definir si hay lesión que requiera cirugía; la laparotomía inmediata es para el inestable o con peritonitis. C es incorrecta: no hay indicación de laparotomía inmediata en el estable sin peritonitis. A es incorrecta: no se da de alta sin estudiar un trauma penetrante. B es incorrecta: la observación sin imagen es insuficiente en trauma penetrante.","topic":"Trauma"}]},{"id":"puem-r1-cc-r1-10-08","number":118,"title":"Trauma: evaluación inicial ATLS · caso 8","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Paciente con trauma torácico, hemotórax masivo: drenaje inicial por tubo pleural de 1,800 mL de sangre y sangrado continuo de 250 mL/h.","questions":[{"id":"puem-r1-cc-r1-10-08-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Dar vasopresor.","Seguir con el tubo pleural y líquidos.","Toracotomía de urgencia (criterios de hemotórax masivo: >1,500 mL inicial o >200 mL/h).","Dar antibiótico."],"answer_index":2,"correct_text":"Toracotomía de urgencia (criterios de hemotórax masivo: >1,500 mL inicial o >200 mL/h).","explanation":"el hemotórax masivo (aprox. >1,500 mL inicial o >200 mL/h) es indicación de toracotomía para controlar el sangrado. B es incorrecta: el tubo no controla el sangrado arterial. D es incorrecta: el antibiótico no trata el hemotórax masivo. A es incorrecta: el vasopresor no controla la hemorragia.","topic":"Trauma"}]},{"id":"puem-r1-cc-r1-10-09","number":119,"title":"Trauma: evaluación inicial ATLS · caso 9","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Mujer de 40 años, accidente vial, Glasgow 15, con dolor cervical, sin déficit neurológico, radiografía cervical normal.","questions":[{"id":"puem-r1-cc-r1-10-09-q1","ordinal":1,"stem":"¿Qué falta en la evaluación?","options":["Nada; ya está descartado.","Evaluación secundaria completa: exploración de cabeza a pies, historia AMPLE, revisar la espalda (logroll) y descartar lesiones ocultas; la radiografía normal no descarta todas las lesiones.","TC de cráneo.","Dar de alta de inmediato."],"answer_index":1,"correct_text":"Evaluación secundaria completa: exploración de cabeza a pies, historia AMPLE, revisar la espalda (logroll) y descartar lesiones ocultas; la radiografía normal no descarta todas las lesiones.","explanation":"la evaluación secundaria (AMPLE, exploración completa, logroll) busca lesiones ocultas; una radiografía normal no descarta lesión ligamentaria ni otras lesiones. A es incorrecta: falta la evaluación secundaria. C es incorrecta: no hay indicación de TC de cráneo con Glasgow 15 sin datos. D es incorrecta: no se da de alta sin evaluación secundaria.","topic":"Trauma"}]},{"id":"puem-r1-cc-r1-10-10","number":120,"title":"Trauma: evaluación inicial ATLS · caso 10","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R1","context":"Hombre de 25 años, trauma, FC 110, PAS 100, lactato 2.5, Hb 12 g/dL, con sangrado controlado. El R1 dice \"está en choque clase I, no necesita transfusión\".","questions":[{"id":"puem-r1-cc-r1-10-10-q1","ordinal":1,"stem":"¿Es correcto?","options":["No, toda pérdida requiere transfusión.","Sí, pero hay que dar plasma.","No, hay que dar vasopresor.","Sí, clase I (<15% de pérdida) no requiere transfusión; reposición con cristaloides y vigilancia."],"answer_index":3,"correct_text":"Sí, clase I (<15% de pérdida) no requiere transfusión; reposición con cristaloides y vigilancia.","explanation":"el choque hemorrágico clase I (<15%, <750 mL) se maneja con cristaloides y vigilancia, sin transfusión; la taquicardia leve y la PAS conservada son compatibles. A es incorrecta: no toda pérdida requiere transfusión. B es incorrecta: el plasma no está indicado en clase I. C es incorrecta: el vasopresor no está indicado en choque hemorrágico compensado.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-01","number":121,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 1","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Hombre de 28 años, accidente automovilístico, llega con TA 85/55 mmHg, FC 125 lpm, dolor abdominal difuso, defensa en hipocondrio izquierdo, FAST positivo con líquido libre en Morrison y pelvis. Está consciente, vía aérea permeable, tórax normal. Hemoglobina 9.5 g/dL, lactato 3.8 mmol/L.","questions":[{"id":"puem-r1-cc-r2-12-01-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Observación en urgencias con FAST seriado y analgésicos.","Angioembolización esplénica inmediata sin cirugía.","Reanimación con transfusión balanceada y laparotomía urgente por inestabilidad con FAST positivo.","Tomografía de abdomen con contraste para graduar la lesión antes de decidir."],"answer_index":2,"correct_text":"Reanimación con transfusión balanceada y laparotomía urgente por inestabilidad con FAST positivo.","explanation":"Paciente inestable con FAST positivo y signos de hemorragia intraabdominal: la tomografía retrasaría el control del sangrado y el paciente no tolera el traslado al tomógrafo; la conducta es reanimación y laparotomía urgente. D es incorrecta: la TC es para el paciente estable. A es incorrecta: observar a un paciente en choque con sangrado activo es peligroso. B es incorrecta: la angioembolización requiere estabilidad y tiempo, y no sustituye la laparotomía en inestabilidad.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-02","number":122,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 2","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Mujer de 34 años, trauma contuso por caída, estable, TA 120/75 mmHg, FC 88 lpm, dolor en hipocondrio izquierdo. TC: laceración esplénica grado III, sin sangrado activo, sin lesión de víscera hueca, sin líquido libre masivo. Hb 11.2 g/dL estable.","questions":[{"id":"puem-r1-cc-r2-12-02-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Esplenectomía inmediata por ser grado III.","Laparotomía exploradora por el dolor en hipocondrio izquierdo.","Alta a domicilio con analgésicos.","Manejo no operatorio con vigilancia estrecha en hospital, reposo y control de hemoglobina."],"answer_index":3,"correct_text":"Manejo no operatorio con vigilancia estrecha en hospital, reposo y control de hemoglobina.","explanation":"La lesión esplénica grado III en paciente estable, sin sangrado activo ni peritonitis, se maneja de forma no operatoria con vigilancia, que tiene alta tasa de éxito. A es incorrecta: la esplenectomía no es obligada en grado III estable. B es incorrecta: no hay indicación quirúrgica sin inestabilidad ni peritonitis. C es incorrecta: requiere vigilancia hospitalaria por riesgo de resangrado.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-03","number":123,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 3","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Hombre de 55 años con perforación de úlcera duodenal, dolor abdominal súbito de 6 horas, rigidez en tabla, neumoperitoneo en radiografía. TA 100/65 mmHg, FC 110 lpm, lactato 2.8 mmol/L, leucocitos 17,000/µL.","questions":[{"id":"puem-r1-cc-r2-12-03-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Reanimación, antibióticos, inhibidor de bomba de protones y laparotomía urgente con cierre de la perforación (parche de Graham) y lavado.","Tratamiento conservador con antibióticos y ayuno, sin cirugía.","Endoscopia terapéutica con clip para cerrar la perforación y alta.","Drenaje percutáneo del neumoperitoneo."],"answer_index":0,"correct_text":"Reanimación, antibióticos, inhibidor de bomba de protones y laparotomía urgente con cierre de la perforación (parche de Graham) y lavado.","explanation":"La perforación duodenal con peritonitis generalizada y neumoperitoneo es una urgencia quirúrgica: reanimación, antibióticos y cierre de la perforación con lavado peritoneal. B es incorrecta: el manejo conservador solo es opción en casos muy seleccionados, estables, con perforación sellada y sin peritonitis generalizada. C es incorrecta: la endoscopia no sustituye la cirugía en peritonitis generalizada. D es incorrecta: el drenaje percutáneo no trata la perforación ni la contaminación.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-04","number":124,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 4","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Mujer de 70 años con diverticulitis perforada, Hinchey III (peritonitis purulenta generalizada), TA 88/55 mmHg, lactato 4.5 mmol/L, leucocitos 20,000/µL, creatinina 1.8 mg/dL. TC: neumoperitoneo, líquido libre, engrosamiento sigmoideo.","questions":[{"id":"puem-r1-cc-r2-12-04-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Antibióticos solos y cirugía electiva en 6 semanas.","Reanimación, antibióticos de amplio espectro y laparotomía urgente con resección sigmoidea y colostomía terminal (Hartmann), sin anastomosis primaria.","Drenaje percutáneo del absceso y antibióticos, sin cirugía.","Sigmoidectomía con anastomosis primaria e ileostomía de protección."],"answer_index":1,"correct_text":"Reanimación, antibióticos de amplio espectro y laparotomía urgente con resección sigmoidea y colostomía terminal (Hartmann), sin anastomosis primaria.","explanation":"Peritonitis purulenta generalizada con choque séptico: requiere control urgente del foco con resección y estoma; la anastomosis primaria en choque séptico con contaminación fecal tiene alto riesgo de fuga y muerte. C es incorrecta: el drenaje percutáneo es para absceso localizado, no para peritonitis generalizada. D es incorrecta: la anastomosis primaria no es segura en este contexto. A es incorrecta: retrasar la cirugía en peritonitis generalizada con choque aumenta la mortalidad.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-05","number":125,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 5","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Hombre de 45 años con herida por arma de fuego en abdomen, orificio de entrada en flanco derecho, TA 90/60 mmHg, FC 120 lpm, dolor abdominal, defensa generalizada, FAST positivo.","questions":[{"id":"puem-r1-cc-r2-12-05-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Manejo no operatorio con observación seriada.","Laparoscopia diagnóstica electiva en 24 horas.","Laparotomía exploradora urgente tras reanimación inicial.","Tomografía de abdomen para definir el trayecto del proyectil."],"answer_index":2,"correct_text":"Laparotomía exploradora urgente tras reanimación inicial.","explanation":"Herida por arma de fuego con inestabilidad y peritonitis: la laparotomía urgente es la indicación; el proyectil tiene trayecto impredecible y alta probabilidad de lesión visceral. D es incorrecta: la TC retrasaría el control del sangrado en un paciente inestable con peritonitis. A es incorrecta: el manejo no operatorio no aplica en arma de fuego con inestabilidad y peritonitis. B es incorrecta: la laparoscopia electiva no es el manejo en este escenario.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-06","number":126,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 6","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Mujer de 62 años, día 5 tras hemicolectomía derecha, con fiebre de 38.8 °C, taquicardia, dolor abdominal, leucocitos 19,000/µL, salida de material fecaloide por el drenaje y lactato 3.2 mmol/L. TC: colección con aire junto a la anastomosis.","questions":[{"id":"puem-r1-cc-r2-12-06-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable y el manejo?","options":["Íleo posoperatorio; manejo conservador con sonda nasogástrica.","Infección de herida superficial; curación local y antibióticos orales.","Neumonía posoperatoria; antibióticos y fisioterapia respiratoria.","Fuga anastomótica con peritonitis; reanimación, antibióticos y reintervención quirúrgica urgente."],"answer_index":3,"correct_text":"Fuga anastomótica con peritonitis; reanimación, antibióticos y reintervención quirúrgica urgente.","explanation":"El cuadro es clásico de fuga anastomótica: fiebre, taquicardia, leucocitosis, salida fecaloide por drenaje y colección con aire en TC; requiere reintervención urgente para control del foco. A es incorrecta: el íleo no da salida fecaloide por drenaje ni colección con aire. B es incorrecta: la infección superficial no explica la colección profunda ni el material fecaloide. C es incorrecta: no hay síntomas respiratorios y los hallazgos apuntan al abdomen.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-07","number":127,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 7","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Hombre de 58 años con absceso intraabdominal de 6 cm en fosa iliaca derecha, 3 semanas tras apendicectomía, estable, TA 125/80 mmHg, afebril con antibióticos, leucocitos 12,000/µL, sin peritonitis generalizada. TC: colección bien delimitada, sin aire libre.","questions":[{"id":"puem-r1-cc-r2-12-07-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Drenaje percutáneo guiado por imagen más antibióticos.","Laparotomía urgente con lavado peritoneal.","Antibióticos solos por 14 días sin drenaje.","Observación sin antibióticos."],"answer_index":0,"correct_text":"Drenaje percutáneo guiado por imagen más antibióticos.","explanation":"Un absceso bien delimitado en paciente estable sin peritonitis generalizada se maneja con drenaje percutáneo más antibióticos, que es el control del foco menos invasivo y efectivo. B es incorrecta: la laparotomía es innecesaria en un absceso localizado estable. C es incorrecta: un absceso de 6 cm rara vez se resuelve solo con antibióticos. D es incorrecta: dejarlo sin tratamiento permite que progrese.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-08","number":128,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 8","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Mujer de 48 años con sepsis de origen abdominal, TA 78/50 mmHg pese a 30 mL/kg de cristaloides, lactato 4.8 mmol/L, oliguria, SOFA 7. Se inició antibiótico de amplio espectro y se tomó hemocultivo. El foco es una colecistitis perforada.","questions":[{"id":"puem-r1-cc-r2-12-08-q1","ordinal":1,"stem":"¿Cuál es el siguiente paso prioritario?","options":["Iniciar dopamina como vasopresor de primera línea.","Iniciar norepinefrina para mantener presión arterial media mayor de 65 mmHg y llevar a control urgente del foco (colecistectomía).","Dar más cristaloides indefinidamente sin vasopresor ni cirugía.","Esperar el resultado del hemocultivo para elegir el antibiótico."],"answer_index":1,"correct_text":"Iniciar norepinefrina para mantener presión arterial media mayor de 65 mmHg y llevar a control urgente del foco (colecistectomía).","explanation":"Es choque séptico: requiere vasopresor de primera línea (norepinefrina) para mantener perfusión y control urgente del foco; retrasar la cirugía aumenta la mortalidad. C es incorrecta: la sobrecarga de líquidos sin vasopresor ni control del foco no resuelve el choque. D es incorrecta: no se espera el cultivo para tratar ni para operar. A es incorrecta: la norepinefrina, no la dopamina, es el vasopresor de primera línea en choque séptico.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-09","number":129,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 9","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Hombre de 30 años, trauma penetrante por arma blanca en abdomen anterior, estable, TA 125/80 mmHg, FC 90 lpm, sin peritonitis, sin evisceración, FAST negativo. La herida penetra fascia en exploración local.","questions":[{"id":"puem-r1-cc-r2-12-09-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Alta a domicilio tras curación de la herida.","Observación sin ningún estudio de imagen.","Tomografía de abdomen con contraste (o laparoscopia diagnóstica según disponibilidad) para descartar lesión visceral, con vigilancia estrecha.","Laparotomía exploradora inmediata en todos los casos de arma blanca."],"answer_index":2,"correct_text":"Tomografía de abdomen con contraste (o laparoscopia diagnóstica según disponibilidad) para descartar lesión visceral, con vigilancia estrecha.","explanation":"En trauma penetrante por arma blanca estable, sin peritonitis ni inestabilidad, el manejo selectivo con tomografía o laparoscopia diagnóstica y vigilancia es adecuado; la laparotomía mandatoria en todos los casos tiene alta tasa de laparotomías no terapéuticas. D es incorrecta: no todo arma blanca estable requiere laparotomía inmediata. A es incorrecta: penetra fascia y debe descartarse lesión visceral. B es incorrecta: sin estudio ni vigilancia se puede pasar por alto una lesión intestinal.","topic":"Trauma"}]},{"id":"puem-r1-cc-r2-12-10","number":130,"title":"Trauma abdominal, infección intraabdominal y sepsis quirúrgica (ATLS 10a ed., WSES) · caso 10","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R2","context":"Hombre de 67 años con peritonitis secundaria por perforación colónica, operado con resección y colostomía, lavado y drenaje adecuados, en terapia intensiva, estable, afebril al día 4, leucocitos en descenso, lactato normal. Recibe piperacilina-tazobactam desde la cirugía.","questions":[{"id":"puem-r1-cc-r2-12-10-q1","ordinal":1,"stem":"¿Cuál es la conducta antibiótica más adecuada?","options":["Suspender el antibiótico alrededor del día 4-5 tras control adecuado del foco y mejoría clínica.","Mantener el antibiótico por 14 días en todos los casos de peritonitis.","Cambiar a antibiótico oral de amplio espectro por 10 días más.","Suspender el antibiótico al día 1 porque ya se operó."],"answer_index":0,"correct_text":"Suspender el antibiótico alrededor del día 4-5 tras control adecuado del foco y mejoría clínica.","explanation":"Tras un control adecuado del foco y mejoría clínica, 3 a 5 días de antibiótico son suficientes en infección intraabdominal complicada; prolongarlo aumenta resistencia y efectos adversos sin beneficio. B es incorrecta: los cursos largos no mejoran el pronóstico tras control del foco. C es incorrecta: no hay indicación de prolongar con otro esquema. D es incorrecta: un día es insuficiente para tratar la infección residual peritoneal.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-01","number":131,"title":"Trauma complejo y cirugía de control de daños · caso 1","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Hombre de 28 años con herida por arma de fuego en abdomen, hipotenso 85/50, taquicárdico, abdomen doloroso.","questions":[{"id":"puem-r1-cc-r3-09-01-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["TC de abdomen con contraste para estadificar.","Laparotomía exploradora inmediata: trauma penetrante abdominal con inestabilidad hemodinámica es indicación quirúrgica sin TC previa.","FAST y observación.","Dar antibióticos y esperar."],"answer_index":1,"correct_text":"Laparotomía exploradora inmediata: trauma penetrante abdominal con inestabilidad hemodinámica es indicación quirúrgica sin TC previa.","explanation":"El paciente inestable con trauma penetrante no va a TC: va a quirófano; la TC en inestable retrasa el control del sangrado y puede ser mortal. **A es incorrecta:** la TC es para el paciente estable. **C es incorrecta:** el FAST no sustituye la laparotomía en inestable penetrante. **D es incorrecta:** los antibióticos no controlan la hemorragia.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-02","number":132,"title":"Trauma complejo y cirugía de control de daños · caso 2","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Paciente con trauma cerrado de abdomen, estable, TC: lesión esplénica grado III, sin sangrado activo, sin otras lesiones.","questions":[{"id":"puem-r1-cc-r3-09-02-q1","ordinal":1,"stem":"¿Cuál es el manejo?","options":["Manejo no quirúrgico (conservador): reposo, vigilancia en hospital, hemoglobina seriada, TC de control si cambia; la esplenectomía se reserva para inestabilidad o falla del manejo.","Alta inmediata.","Embolización esplénica en todos los casos.","Esplenectomía inmediata."],"answer_index":0,"correct_text":"Manejo no quirúrgico (conservador): reposo, vigilancia en hospital, hemoglobina seriada, TC de control si cambia; la esplenectomía se reserva para inestabilidad o falla del manejo.","explanation":"El estándar en lesión esplénica estable es el manejo conservador; la mayoría se resuelve sin cirugía. **D es incorrecta:** operar un bazo estable es sobretratamiento. **B es incorrecta:** requiere vigilancia hospitalaria. **C es incorrecta:** la embolización es para sangrado activo o alto riesgo, no universal.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-03","number":133,"title":"Trauma complejo y cirugía de control de daños · caso 3","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Hombre de 35 años con trauma abdominal cerrado, hipotenso, frío (34.5 °C), pH 7.15, coagulopatía. En la laparotomía hay sangrado hepático y perforación de colon.","questions":[{"id":"puem-r1-cc-r3-09-03-q1","ordinal":1,"stem":"¿Cuál es la estrategia correcta?","options":["Cerrar el abdomen y no hacer nada más.","Dar solo transfusión sin cirugía.","Hacer la reparación definitiva completa (hepatectomía + anastomosis de colon) en esta cirugía.","Cirugía de control de daños: empaquetamiento hepático, grapado del colon sin anastomosis, cierre temporal y reanimación en terapia intensiva; reoperar definitivo a las 24-48 h cuando esté caliente, no ácido y sin coagulopatía."],"answer_index":3,"correct_text":"Cirugía de control de daños: empaquetamiento hepático, grapado del colon sin anastomosis, cierre temporal y reanimación en terapia intensiva; reoperar definitivo a las 24-48 h cuando esté caliente, no ácido y sin coagulopatía.","explanation":"El paciente tiene la tríada letal: la cirugía definitiva prolongada lo mataría; el control de daños salva la vida. **C es incorrecta:** es el error clásico que perpetúa la tríada. **A es incorrecta:** no controla sangrado ni contaminación. **B es incorrecta:** la transfusión sin control quirúrgico no detiene el sangrado.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-04","number":134,"title":"Trauma complejo y cirugía de control de daños · caso 4","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Paciente politraumatizado con hemorragia masiva.","questions":[{"id":"puem-r1-cc-r3-09-04-q1","ordinal":1,"stem":"¿Cuál es la reanimación correcta según el control de daños?","options":["Solo cristaloides y vasopresores.","Cristaloides en grandes volúmenes (5-6 L) antes de transfundir.","Transfusión masiva balanceada 1:1:1 (globulos:plasma:plaquetas), ácido tranexámico en las primeras 3 h, calcio, evitar hipotermia y cristaloides limitados.","Solo plasma."],"answer_index":2,"correct_text":"Transfusión masiva balanceada 1:1:1 (globulos:plasma:plaquetas), ácido tranexámico en las primeras 3 h, calcio, evitar hipotermia y cristaloides limitados.","explanation":"La reanimación hemostática balanceada con TXA temprano es el estándar; los cristaloides en exceso diluyen y empeoran la coagulopatía. **B es incorrecta:** es el manejo antiguo, hoy contraindicado en exceso. **D es incorrecta:** el plasma solo no repone glóbulos ni plaquetas. **A es incorrecta:** los vasopresores no sustituyen la sangre.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-05","number":135,"title":"Trauma complejo y cirugía de control de daños · caso 5","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Hombre de 40 años con trauma cerrado, FAST positivo, hipotenso pese a 2 L de cristaloides y 2 unidades de sangre.","questions":[{"id":"puem-r1-cc-r3-09-05-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["TC de abdomen para confirmar.","Laparotomía exploradora inmediata: FAST positivo + inestabilidad persistente = sangrado intraabdominal que requiere control quirúrgico.","Dar más cristaloides y esperar.","Angiografía."],"answer_index":1,"correct_text":"Laparotomía exploradora inmediata: FAST positivo + inestabilidad persistente = sangrado intraabdominal que requiere control quirúrgico.","explanation":"FAST positivo con inestabilidad que no responde es indicación de laparotomía; la TC en este paciente es insegura. **A es incorrecta:** la TC demora el control del sangrado. **C es incorrecta:** más cristaloides empeoran la coagulopatía. **D es incorrecta:** la angiografía es para el paciente estable o con sangrado pélvico, no para abdomen inestable.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-06","number":136,"title":"Trauma complejo y cirugía de control de daños · caso 6","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Paciente esplenectomizado por trauma.","questions":[{"id":"puem-r1-cc-r3-09-06-q1","ordinal":1,"stem":"¿Qué se le debe indicar al alta?","options":["Vacunación contra neumococo, meningococo y Haemophilus influenzae (y educación sobre el riesgo de sepsis posesplenectomía y la necesidad de antibióticos tempranos ante fiebre), además de la cartilla de vacunación.","Solo analgésicos.","Antibióticos de por vida en todos los casos.","Nada especial."],"answer_index":0,"correct_text":"Vacunación contra neumococo, meningococo y Haemophilus influenzae (y educación sobre el riesgo de sepsis posesplenectomía y la necesidad de antibióticos tempranos ante fiebre), además de la cartilla de vacunación.","explanation":"El asplénico tiene riesgo de sepsis fulminante por bacterias encapsuladas; la vacunación y la educación son obligatorias. **D es incorrecta:** el alta sin vacunación es un error. **B es incorrecta:** no cubre el riesgo. **C es incorrecta:** la profilaxis antibiótica de por vida no es universal; se individualiza.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-07","number":137,"title":"Trauma complejo y cirugía de control de daños · caso 7","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Mujer de 30 años con fractura de pelvis inestable, hipotensa, con sangrado pélvico.","questions":[{"id":"puem-r1-cc-r3-09-07-q1","ordinal":1,"stem":"¿Cuál es el manejo inicial del sangrado?","options":["Solo transfusión.","Dar anticoagulantes.","Laparotomía inmediata.","Fijación externa o sábana pélvica (binder) + empaquetamiento pélvico y/o angiografía con embolización, según estabilidad y recursos; el sangrado pélvico es venoso y óseo en su mayoría y no se controla con laparotomía sola."],"answer_index":3,"correct_text":"Fijación externa o sábana pélvica (binder) + empaquetamiento pélvico y/o angiografía con embolización, según estabilidad y recursos; el sangrado pélvico es venoso y óseo en su mayoría y no se controla con laparotomía sola.","explanation":"El sangrado pélvico se controla con estabilización mecánica (binder/fijación) y empaquetamiento o embolización; la laparotomía sola no controla el sangrado venoso/óseo pélvico. **C es incorrecta:** la laparotomía no es el primer paso en pelvis. **A es incorrecta:** la transfusión sin control mecánico no basta. **B es incorrecta:** los anticoagulantes empeoran el sangrado.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-08","number":138,"title":"Trauma complejo y cirugía de control de daños · caso 8","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Paciente con trauma abdominal, 48 h pos-laparotomía de control de daños, con abdomen abierto y presión intraabdominal de 25 mmHg, oliguria y dificultad ventilatoria.","questions":[{"id":"puem-r1-cc-r3-09-08-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y la conducta?","options":["Es normal tras control de daños.","Sepsis: antibióticos.","Síndrome compartimental abdominal: descompresión (mantener abdomen abierto, no cerrar a tensión) y manejo en terapia intensiva; cerrar un abdomen hipertenso empeora la perfusión de órganos.","Íleo: procinéticos."],"answer_index":2,"correct_text":"Síndrome compartimental abdominal: descompresión (mantener abdomen abierto, no cerrar a tensión) y manejo en terapia intensiva; cerrar un abdomen hipertenso empeora la perfusión de órganos.","explanation":"Presión intraabdominal alta + disfunción orgánica (renal y respiratoria) es síndrome compartimental: la descompresión es el tratamiento. **B es incorrecta:** los antibióticos no bajan la presión intraabdominal. **D es incorrecta:** el íleo no da este cuadro. **A es incorrecta:** nunca es normal.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-09","number":139,"title":"Trauma complejo y cirugía de control de daños · caso 9","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Hombre de 25 años con herida por arma blanca en el epigastrio, estable, sin peritonitis, TC sin lesión evidente.","questions":[{"id":"puem-r1-cc-r3-09-09-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Laparotomía obligatoria en todo trauma penetrante.","Manejo selectivo: observación con exploración seriada, laboratorios y TC; la laparotomía obligatoria ya no es el estándar en el paciente estable sin peritonitis por arma blanca (a diferencia del arma de fuego).","Alta inmediata.","Dar de alta con antibióticos."],"answer_index":1,"correct_text":"Manejo selectivo: observación con exploración seriada, laboratorios y TC; la laparotomía obligatoria ya no es el estándar en el paciente estable sin peritonitis por arma blanca (a diferencia del arma de fuego).","explanation":"El matiz: en arma blanca estable sin peritonitis el manejo selectivo con observación es válido; en arma de fuego el umbral quirúrgico es mucho más bajo. **A es incorrecta:** la laparotomía obligatoria universal es manejo antiguo para arma blanca. **C y D son incorrectas:** requiere observación hospitalaria, no alta.","topic":"Trauma"}]},{"id":"puem-r1-cc-r3-09-10","number":140,"title":"Trauma complejo y cirugía de control de daños · caso 10","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R3","context":"Paciente con trauma hepático grado IV, inestable, en quirófano.","questions":[{"id":"puem-r1-cc-r3-09-10-q1","ordinal":1,"stem":"¿Cuál es la maniobra correcta?","options":["Ligadura de la arteria hepática común siempre.","No tocar el hígado.","Hepatectomía mayor inmediata.","Empaquetamiento perihepático (packing) con compresas y cierre temporal, con reoperación programada; la resección definitiva en el paciente inestable y coagulopático es mortal."],"answer_index":3,"correct_text":"Empaquetamiento perihepático (packing) con compresas y cierre temporal, con reoperación programada; la resección definitiva en el paciente inestable y coagulopático es mortal.","explanation":"El empaquetamiento es la maniobra de control de daños en hígado; la resección mayor en inestable es el error clásico. **C es incorrecta:** la hepatectomía en tríada letal mata. **A es incorrecta:** la ligadura arterial es una opción en sangrado arterial selectivo, no universal. **B es incorrecta:** el sangrado debe controlarse.","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-01","number":141,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 1","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Hombre 25 años, trauma cerrado, hipotensión 80/50, taquicardia 130, FAST positivo, pelvis inestable.","questions":[{"id":"puem-r1-cc-r4-06-01-q1","ordinal":1,"stem":"¿Primera acción tras ABCDE?","options":["Solo cristaloides 3 L","Esperar laboratorio","TC de cuerpo entero inmediata","Binder pélvico, transfusión balanceada, control de hemorragia y quirófano/angio según respuesta"],"answer_index":3,"correct_text":"Binder pélvico, transfusión balanceada, control de hemorragia y quirófano/angio según respuesta","explanation":"Pelvis inestable + choque: binder + reanimación balanceada y control de hemorragia; la TC en paciente que no responde retrasa el control. Cristaloides solos agravan coagulopatía.","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-02","number":142,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 2","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Paciente politraumatizado, pH 7.15, temperatura 34.5 °C, INR 2.0, calcio bajo.","questions":[{"id":"puem-r1-cc-r4-06-02-q1","ordinal":1,"stem":"¿Qué describe?","options":["Hipotermia benigna","Coagulopatía por warfarina","Tríada/tétrada letal del trauma; requiere normotermia, calcio, transfusión balanceada y control quirúrgico rápido","Acidosis respiratoria aislada"],"answer_index":2,"correct_text":"Tríada/tétrada letal del trauma; requiere normotermia, calcio, transfusión balanceada y control quirúrgico rápido","explanation":"Hipotermia + acidosis + coagulopatía (+ hipocalcemia) = tétrada letal. El tratamiento es reanimación balanceada y control de hemorragia, no solo corregir un número.","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-03","number":143,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 3","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Hombre con trauma abdominal cerrado, estable, lesión esplénica AAST III, sin sangrado activo en TC.","questions":[{"id":"puem-r1-cc-r4-06-03-q1","ordinal":1,"stem":"¿Manejo?","options":["Esplenectomía inmediata","Manejo no operatorio con vigilancia estrecha en UCI ± embolización si hay sangrado","Alta domiciliaria","Solo analgésicos"],"answer_index":1,"correct_text":"Manejo no operatorio con vigilancia estrecha en UCI ± embolización si hay sangrado","explanation":"Bazo AAST III estable sin sangrado activo: manejo no operatorio con vigilancia es el estándar. Operar un paciente estable pierde el bazo innecesariamente.","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-04","number":144,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 4","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Paciente en damage control, abdomen abierto día 6, fístula enteroatmosférica.","questions":[{"id":"puem-r1-cc-r4-06-04-q1","ordinal":1,"stem":"¿Prevención y manejo?","options":["Presión negativa con protección visceral, nutrición, control de sepsis y cierre precoz cuando sea posible; la fístula se maneja con aislamiento y plan diferido","Dejar el abdomen abierto indefinidamente sin plan","Solo antibiótico","Forzar cierre fascial con tensión"],"answer_index":0,"correct_text":"Presión negativa con protección visceral, nutrición, control de sepsis y cierre precoz cuando sea posible; la fístula se maneja con aislamiento y plan diferido","explanation":"La fístula enteroatmosférica se previene con protección visceral y cierre precoz; una vez presente, se aísla, se nutre y se planea reparación diferida. Forzar cierre con tensión empeora.","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-05","number":145,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 5","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Mujer con trauma penetrante abdominal, evisceración, hipotensa.","questions":[{"id":"puem-r1-cc-r4-06-05-q1","ordinal":1,"stem":"¿Conducta?","options":["TC primero aunque esté hipotensa","Solo cubrir con gasa y esperar","Reducir intestino en urgencias y observar","Quirófano inmediato: control de hemorragia y contaminación (damage control)"],"answer_index":3,"correct_text":"Quirófano inmediato: control de hemorragia y contaminación (damage control)","explanation":"Evisceración + hipotensión = quirófano inmediato; la TC en paciente inestable retrasa el control. Cubrir y esperar sin cirugía es letal.","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-06","number":146,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 6","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Hombre con hemotórax, tubo drena 1 800 mL de sangre inicial.","questions":[{"id":"puem-r1-cc-r4-06-06-q1","ordinal":1,"stem":"¿Conducta?","options":["Solo transfusión","Mantener tubo y observar","Toracotomía urgente: hemotórax masivo","Retirar tubo"],"answer_index":2,"correct_text":"Toracotomía urgente: hemotórax masivo","explanation":"Hemotórax masivo (>1 500 mL inicial) es indicación de toracotomía. Observar con ese débito perpetúa el choque.","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-07","number":147,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 7","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Paciente con trauma torácico, hipotensión, ingurgitación yugular, ruidos apagados, pulso paradójico.","questions":[{"id":"puem-r1-cc-r4-06-07-q1","ordinal":1,"stem":"¿Diagnóstico y acción?","options":["Neumotórax a tensión; descompresión","Taponamiento cardiaco; pericardiocentesis/toracotomía según escenario ATLS","Shock séptico","Embolia pulmonar"],"answer_index":1,"correct_text":"Taponamiento cardiaco; pericardiocentesis/toracotomía según escenario ATLS","explanation":"Tríada de Beck = taponamiento. En trauma con taponamiento, la pericardiocentesis es puente y la toracotomía el tratamiento definitivo según escenario. No es neumotórax a tensión (ese da desviación traqueal y ausencia de murmullo).","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-08","number":148,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 8","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Hombre con lesión hepática AAST IV, estable, sangrado contenido en TC.","questions":[{"id":"puem-r1-cc-r4-06-08-q1","ordinal":1,"stem":"¿Manejo?","options":["Manejo no operatorio con vigilancia ± angioembolización","Packing profiláctico","Alta","Hepatectomía inmediata"],"answer_index":0,"correct_text":"Manejo no operatorio con vigilancia ± angioembolización","explanation":"Hígado AAST IV estable: manejo no operatorio ± embolización es el estándar actual. La hepatectomía de inicio en paciente estable es excesiva.","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-09","number":149,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 9","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Politraumatizado con TCE grave y choque hemorrágico.","questions":[{"id":"puem-r1-cc-r4-06-09-q1","ordinal":1,"stem":"¿Meta de presión arterial?","options":["Solo cristaloides","No transfundir","Hipotensión permisiva 80 mmHg como en trauma sin TCE","Evitar hipotensión: mantener PAM adecuada para perfusión cerebral (no hipotensión permisiva)"],"answer_index":3,"correct_text":"Evitar hipotensión: mantener PAM adecuada para perfusión cerebral (no hipotensión permisiva)","explanation":"Con TCE, la hipotensión permisiva está contraindicada: un solo episodio hipotensivo empeora el pronóstico neurológico. La reanimación debe mantener perfusión cerebral.","topic":"Trauma"}]},{"id":"puem-r1-cc-r4-06-10","number":150,"title":"Trauma complejo, abdomen abierto y cuidados críticos · caso 10","topic":"Trauma","topicId":"ap-r1-trauma","nivel":"R4","context":"Paciente postdamage control, reoperación 24 h: contaminación controlada, edema moderado.","questions":[{"id":"puem-r1-cc-r4-06-10-q1","ordinal":1,"stem":"¿Plan?","options":["Malla sintética intraperitoneal definitiva en abdomen contaminado","Cierre fascial si es posible sin tensión; si no, cierre temporal y plan de cierre progresivo","Cierre forzado con tensión siempre","Dejar abierto sin revalorar"],"answer_index":1,"correct_text":"Cierre fascial si es posible sin tensión; si no, cierre temporal y plan de cierre progresivo","explanation":"El objetivo es el cierre fascial precoz sin tensión; si no es posible, cierre temporal y plan progresivo. Forzar cierre causa síndrome compartimental; malla definitiva en contaminación es de alto riesgo.","topic":"Trauma"}]},{"id":"puem-r2-cc-r1-11-01","number":1,"title":"Piel y tejido adiposo subcutáneo · caso 1","topic":"Piel","topicId":"piel","nivel":"R1","context":"Hombre de 35 años con tumor doloroso, fluctuante, eritematoso de 4 cm en la axila, fiebre 38.5 °C. El R1 propone antibiótico oral y cita en una semana.","questions":[{"id":"puem-r2-cc-r1-11-01-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Antibiótico oral y cita en una semana.","Incisión y drenaje + cultivo; el antibiótico solo no cura un absceso.","Compresas calientes solamente.","Biopsia."],"answer_index":1,"correct_text":"Incisión y drenaje + cultivo; el antibiótico solo no cura un absceso.","explanation":"un absceso fluctuante con fiebre requiere incisión y drenaje; el antibiótico no penetra bien en la colección ni la drena. A es incorrecta: esperar una semana con fiebre y absceso es peligroso. C es incorrecta: las compresas no sustituyen el drenaje. D es incorrecta: no es una lesión para biopsia de inicio.","topic":"Piel"}]},{"id":"puem-r2-cc-r1-11-02","number":2,"title":"Piel y tejido adiposo subcutáneo · caso 2","topic":"Piel","topicId":"piel","nivel":"R1","context":"Mujer de 60 años, diabética, con celulitis en la pierna, eritema que avanza 2 cm en 6 h, fiebre, sin fluctuación ni crepitación.","questions":[{"id":"puem-r2-cc-r1-11-02-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Antibiótico sistémico (cobertura de estreptococo y *S. aureus*), elevar la extremidad, marcar el borde y reevaluar; drenar solo si hay colección.","Solo curación tópica.","Dar de alta sin antibiótico.","Drenaje quirúrgico."],"answer_index":0,"correct_text":"Antibiótico sistémico (cobertura de estreptococo y *S. aureus*), elevar la extremidad, marcar el borde y reevaluar; drenar solo si hay colección.","explanation":"la celulitis sin colección se trata con antibiótico sistémico, elevación y vigilancia del borde; el drenaje es para el absceso, no para la celulitis difusa. D es incorrecta: no hay colección que drenar. B es incorrecta: el tópico no trata la celulitis con fiebre. C es incorrecta: la celulitis que avanza con fiebre requiere antibiótico y seguimiento.","topic":"Piel"}]},{"id":"puem-r2-cc-r1-11-03","number":3,"title":"Piel y tejido adiposo subcutáneo · caso 3","topic":"Piel","topicId":"piel","nivel":"R1","context":"Hombre de 45 años con tumor blando, móvil, indoloro de 3 cm en el hombro, de crecimiento lento en 2 años. El R1 quiere drenarlo como absceso.","questions":[{"id":"puem-r2-cc-r1-11-03-q1","ordinal":1,"stem":"¿Qué es lo correcto?","options":["Dar antibiótico.","Biopsia con aguja gruesa de inmediato.","Drenarlo.","No drenarlo: es un lipoma; la conducta es observación o resección completa si es sintomático o el diagnóstico es dudoso."],"answer_index":3,"correct_text":"No drenarlo: es un lipoma; la conducta es observación o resección completa si es sintomático o el diagnóstico es dudoso.","explanation":"el tumor blando, móvil, indoloro y de crecimiento lento es un lipoma; drenarlo es un error (no hay pus) y la resección, si se hace, debe ser completa. C es incorrecta: no es un absceso. A es incorrecta: no hay infección. B es incorrecta: no es la primera conducta en un lipoma típico.","topic":"Piel"}]},{"id":"puem-r2-cc-r1-11-04","number":4,"title":"Piel y tejido adiposo subcutáneo · caso 4","topic":"Piel","topicId":"piel","nivel":"R1","context":"Mujer de 70 años, encamada, con úlcera de 4 cm sobre el sacro, con tejido necrótico negro y secreción.","questions":[{"id":"puem-r2-cc-r1-11-04-q1","ordinal":1,"stem":"¿Cuál es la primera medida?","options":["Cerrar con colgajo de inmediato.","Poner un apósito y no tocarla.","Aliviar la presión (cambios posturales, superficie especial), desbridar el tejido necrótico, valorar infección y nutrición.","Dar antibiótico oral solamente."],"answer_index":2,"correct_text":"Aliviar la presión (cambios posturales, superficie especial), desbridar el tejido necrótico, valorar infección y nutrición.","explanation":"en la úlcera por presión lo primero es aliviar la presión (sin eso no cicatriza), desbridar necrosis y tratar la infección y la nutrición; el colgajo es para casos seleccionados tras preparar el lecho. B es incorrecta: el apósito sin aliviar la presión no resuelve. D es incorrecta: el antibiótico solo no desbrida ni alivia la presión. A es incorrecta: no se hace colgajo sobre tejido necrótico e infectado.","topic":"Piel"}]},{"id":"puem-r2-cc-r1-11-05","number":5,"title":"Piel y tejido adiposo subcutáneo · caso 5","topic":"Piel","topicId":"piel","nivel":"R1","context":"Hombre de 50 años con quiste epidérmico en la espalda que se drenó (se vació el contenido) pero a los 2 meses recidivó.","questions":[{"id":"puem-r2-cc-r1-11-05-q1","ordinal":1,"stem":"¿Por qué?","options":["Porque no se dio antibiótico.","Porque quedó la cápsula del quiste; la resección debe ser completa con cápsula.","Porque es un lipoma.","Porque es cáncer."],"answer_index":1,"correct_text":"Porque quedó la cápsula del quiste; la resección debe ser completa con cápsula.","explanation":"el quiste recidiva si queda la cápsula (que sigue produciendo queratina); el tratamiento definitivo es la resección completa con cápsula. A es incorrecta: el antibiótico no evita la recidiva del quiste. C es incorrecta: el quiste no es lipoma. D es incorrecta: la recidiva por cápsula residual es la explicación, no el cáncer.","topic":"Piel"}]},{"id":"puem-r2-cc-r1-11-06","number":6,"title":"Piel y tejido adiposo subcutáneo · caso 6","topic":"Piel","topicId":"piel","nivel":"R1","context":"Mujer de 65 años con lesión perlada, con telangiectasias, en la nariz, que crece lentamente y sangra con facilidad.","questions":[{"id":"puem-r2-cc-r1-11-06-q1","ordinal":1,"stem":"¿Cuál es la sospecha?","options":["Carcinoma basocelular; requiere biopsia y resección con márgenes.","Lipoma.","Verruga.","Queratosis seborreica."],"answer_index":0,"correct_text":"Carcinoma basocelular; requiere biopsia y resección con márgenes.","explanation":"la lesión perlada con telangiectasias en zona fotoexpuesta es clásica de carcinoma basocelular; requiere biopsia y resección. D es incorrecta: la queratosis seborreica es pigmentada, verrugosa y no perlada con telangiectasias. B es incorrecta: el lipoma es subcutáneo, no una lesión cutánea perlada. C es incorrecta: la verruga no tiene este aspecto.","topic":"Piel"}]},{"id":"puem-r2-cc-r1-11-07","number":7,"title":"Piel y tejido adiposo subcutáneo · caso 7","topic":"Piel","topicId":"piel","nivel":"R1","context":"Hombre de 40 años con lunar que cambió: asimétrico, bordes irregulares, varios colores, diámetro 8 mm y crecimiento en 6 meses.","questions":[{"id":"puem-r2-cc-r1-11-07-q1","ordinal":1,"stem":"¿Cuál es la sospecha y la conducta?","options":["Dermatofibroma; no hacer nada.","Quiste; drenar.","Lunar benigno; observar.","Melanoma (criterios ABCDE); biopsia excisional con margen y derivación urgente."],"answer_index":3,"correct_text":"Melanoma (criterios ABCDE); biopsia excisional con margen y derivación urgente.","explanation":"los criterios ABCDE (asimetría, bordes, color, diámetro >6 mm, evolución) positivos son sospecha de melanoma; la conducta es biopsia excisional y derivación urgente. C es incorrecta: observar un lunar con ABCDE positivo es peligroso. A es incorrecta: el dermatofibroma no cumple ABCDE. B es incorrecta: no es un quiste.","topic":"Piel"}]},{"id":"puem-r2-cc-r1-11-08","number":8,"title":"Piel y tejido adiposo subcutáneo · caso 8","topic":"Piel","topicId":"piel","nivel":"R1","context":"Paciente con absceso perianal, dolor intenso, fiebre, sin fluctuación clara por el dolor.","questions":[{"id":"puem-r2-cc-r1-11-08-q1","ordinal":1,"stem":"¿Qué estudio ayuda a confirmar la colección?","options":["Ninguno; esperar a que fluctúe.","Radiografía simple.","Ecografía (o TC/RM según el caso) para confirmar la colección y su extensión; el drenaje no debe retrasarse si la sospecha es alta.","Colonoscopia."],"answer_index":2,"correct_text":"Ecografía (o TC/RM según el caso) para confirmar la colección y su extensión; el drenaje no debe retrasarse si la sospecha es alta.","explanation":"la ecografía (endonal o de partes blandas) confirma la colección y su profundidad cuando la exploración es limitada por el dolor; esperar a la fluctuación retrasa el tratamiento. B es incorrecta: la radiografía no muestra el absceso. D es incorrecta: la colonoscopia no es el estudio para un absceso perianal agudo. A es incorrecta: esperar es peligroso.","topic":"Piel"}]},{"id":"puem-r2-cc-r1-11-09","number":9,"title":"Piel y tejido adiposo subcutáneo · caso 9","topic":"Piel","topicId":"piel","nivel":"R1","context":"Mujer de 55 años con celulitis en la pierna que no mejora con cefalexina en 48 h, con antecedente de MRSA en la familia y pústulas.","questions":[{"id":"puem-r2-cc-r1-11-09-q1","ordinal":1,"stem":"¿Qué debe considerarse?","options":["Que la cefalexina es suficiente; esperar una semana.","Cobertura para MRSA (según la guía local y la gravedad), con reevaluación y cultivo.","Que es una trombosis.","Que es una fascitis."],"answer_index":1,"correct_text":"Cobertura para MRSA (según la guía local y la gravedad), con reevaluación y cultivo.","explanation":"la falta de respuesta con factores de riesgo de MRSA (contacto, pústulas, antecedente) obliga a considerar cobertura para MRSA y cultivar; la cefalexina no cubre MRSA. A es incorrecta: esperar con progresión es peligroso. C es incorrecta: la trombosis no explica las pústulas ni la fiebre. D es incorrecta: no hay dolor desproporcionado ni crepitación que sugieran fascitis, aunque hay que vigilarla.","topic":"Piel"}]},{"id":"puem-r2-cc-r1-11-10","number":10,"title":"Piel y tejido adiposo subcutáneo · caso 10","topic":"Piel","topicId":"piel","nivel":"R1","context":"Hombre de 30 años con herida por mordedura de perro en la mano, con eritema y dolor a las 12 h.","questions":[{"id":"puem-r2-cc-r1-11-10-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Solo curación.","Dar analgésico.","Suturar de inmediato en primera intención.","Lavado profuso, desbridamiento, valoración de tendones/nervios/hueso, antibiótico (cobertura de *Pasteurella* y flora oral) y no cerrar de inicio en herida de alto riesgo; valorar profilaxis antitetánica y antirrábica según el caso."],"answer_index":3,"correct_text":"Lavado profuso, desbridamiento, valoración de tendones/nervios/hueso, antibiótico (cobertura de *Pasteurella* y flora oral) y no cerrar de inicio en herida de alto riesgo; valorar profilaxis antitetánica y antirrábica según el caso.","explanation":"las mordeduras en la mano son de alto riesgo por la flora oral (*Pasteurella*), la cercanía de tendones y articulaciones y la mala vascularización; requieren lavado, desbridamiento, antibiótico y no cierre primario en la mayoría. C es incorrecta: cerrar de inicio una mordedura de alto riesgo aumenta la infección. A es incorrecta: la curación sola es insuficiente. B es incorrecta: el analgésico no trata la infección.","topic":"Piel"}]},{"id":"puem-r2-cc-r3-01-01","number":11,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 1","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"Mujer de 58 años con tumor de colon sigmoides de 5 cm, TC sin metástasis, colonoscopia con biopsia de adenocarcinoma moderadamente diferenciado. En la laparotomía el tumor está adherido a la vejiga sin invadirla.","questions":[{"id":"puem-r2-cc-r3-01-01-q1","ordinal":1,"stem":"¿Cuál es la conducta oncológica correcta?","options":["Resecar en bloque sigmoides + porción de vejiga adherida, con márgenes libres y linfadenectomía regional.","Hacer biopsia incisional de la adherencia y cerrar para decidir en comité después.","Resecar el tumor y dar radioterapia intraoperatoria sin tocar la vejiga.","Resecar el sigmoides con margen de 5 cm y dejar la vejiga intacta, pues no hay invasión demostrada."],"answer_index":0,"correct_text":"Resecar en bloque sigmoides + porción de vejiga adherida, con márgenes libres y linfadenectomía regional.","explanation":"Una adherencia tumoral no puede distinguirse de invasión real en quirófano; el principio oncológico es la resección en bloque del órgano adherido para lograr R0. Separar el tumor de la vejiga deja enfermedad microscópica casi seguro. **D es incorrecta:** dejar la vejiga asumiendo que no hay invasión viola el principio de resección en bloque y arriesga R1. **B es incorrecta:** la biopsia incisional en un tumor resecable siembra y retrasa el tratamiento curativo. **C es incorrecta:** la radioterapia no sustituye la resección en bloque ni garantiza margen libre.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r3-01-02","number":12,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 2","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"Hombre de 62 años con cáncer de recto medio, RM: T3 N1, sin metástasis. El comité propone quimiorradioterapia neoadyuvante y luego resección. El paciente pregunta por qué no operarlo ya.","questions":[{"id":"puem-r2-cc-r3-01-02-q1","ordinal":1,"stem":"¿Cuál es la mejor explicación?","options":["La neoadyuvancia solo se usa cuando el tumor es irresecable; en este caso es un error y debe operarse ya.","La quimiorradioterapia neoadyuvante reduce el tumor, mejora la probabilidad de resección R0 con preservación de esfínter y trata micrometástasis, con mejor control local que operar directo.","Operar primero es siempre mejor porque la radioterapia hace la cirugía más difícil y no cambia el pronóstico.","La neoadyuvancia es solo paliativa y se indica cuando el paciente rechaza la cirugía."],"answer_index":1,"correct_text":"La quimiorradioterapia neoadyuvante reduce el tumor, mejora la probabilidad de resección R0 con preservación de esfínter y trata micrometástasis, con mejor control local que operar directo.","explanation":"En recto localmente avanzado (T3/T4 o N+), la neoadyuvancia es estándar: disminuye el estadio, facilita R0 y preservación esfinteriana y esteriliza micrometástasis, con mejor control local demostrado. **A es incorrecta:** la neoadyuvancia no es solo para irresecables. **C es incorrecta:** aunque la radioterapia aumenta la dificultad técnica, el beneficio oncológico la justifica. **D es incorrecta:** es tratamiento con intención curativa, no paliativa.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r3-01-03","number":13,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 3","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"Paciente con adenocarcinoma de colon derecho pT3 N2 (6/18 ganglios positivos), márgenes libres, MSI estable.","questions":[{"id":"puem-r2-cc-r3-01-03-q1","ordinal":1,"stem":"¿Qué define principalmente la necesidad de quimioterapia adyuvante?","options":["El valor del CEA preoperatorio, que es el único factor pronóstico validado.","El tamaño del tumor primario, porque a mayor T mayor riesgo.","La afectación ganglionar (N2) y el estadio III, que implican enfermedad microscópica sistémica con beneficio demostrado de la adyuvancia.","La edad del paciente, porque los jóvenes no necesitan quimioterapia."],"answer_index":2,"correct_text":"La afectación ganglionar (N2) y el estadio III, que implican enfermedad microscópica sistémica con beneficio demostrado de la adyuvancia.","explanation":"El estadio III (N+) es la indicación clásica de quimioterapia adyuvante en colon: trata enfermedad microscópica y mejora supervivencia. **B es incorrecta:** el T por sí solo no indica adyuvancia en colon (un T4 N0 es estadio II, de decisión más matizada). **D es incorrecta:** la edad no contraindica ni sustituye la indicación. **A es incorrecta:** el CEA es marcador de seguimiento, no el factor que decide la adyuvancia.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r3-01-04","number":14,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 4","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"Durante una gastrectomía oncológica se rompe accidentalmente el tumor y se derrama contenido en la cavidad.","questions":[{"id":"puem-r2-cc-r3-01-04-q1","ordinal":1,"stem":"¿Cuál es la implicación oncológica principal y la conducta inmediata?","options":["La rotura convierte la cirugía en paliativa y debe abandonarse la resección.","Se debe dar quimioterapia intraperitoneal hipertérmica (HIPEC) en ese mismo acto a todo paciente.","No tiene implicación si se lava abundantemente con solución salina.","Siembra peritoneal con alto riesgo de carcinomatosis; lavar, aspirar, evitar más diseminación, documentarlo y avisar al comité para planear adyuvancia/vigilancia."],"answer_index":3,"correct_text":"Siembra peritoneal con alto riesgo de carcinomatosis; lavar, aspirar, evitar más diseminación, documentarlo y avisar al comité para planear adyuvancia/vigilancia.","explanation":"La rotura tumoral siembra células viables en peritoneo y empeora el pronóstico; la conducta es contención, lavado, documentación honesta en la nota operatoria y ajuste del plan con oncología. **C es incorrecta:** el lavado no elimina el riesgo de siembra. **A es incorrecta:** no se abandona la resección; se completa la mejor resección posible. **B es incorrecta:** HIPEC no es indicación universal ni se improvisa en cualquier caso.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r3-01-05","number":15,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 5","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"Mujer con cáncer de mama, biopsia tru-cut: carcinoma ductal infiltrante, RE+/RP+, HER2 negativo, Ki67 8%.","questions":[{"id":"puem-r2-cc-r3-01-05-q1","ordinal":1,"stem":"¿Qué información falta para planear el tratamiento sistémico y por qué importa?","options":["El estadio clínico completo (tamaño, ganglios, metástasis) y pruebas genómicas/moleculares si aplican, porque el tratamiento depende de estadio y biología, no solo de receptores.","Solo falta el grupo sanguíneo para la cirugía.","Solo falta saber si la paciente acepta quimioterapia, porque el resto es irrelevante.","Nada falta: el receptor hormonal positivo basta para decidir cirugía."],"answer_index":0,"correct_text":"El estadio clínico completo (tamaño, ganglios, metástasis) y pruebas genómicas/moleculares si aplican, porque el tratamiento depende de estadio y biología, no solo de receptores.","explanation":"Receptores + bajo Ki67 sugieren tumor luminal de bajo riesgo, pero sin estadio (TNM) no se puede decidir neoadyuvancia vs cirugía primaria ni el esquema adyuvante; las pruebas genómicas (p. ej., Oncotype DX en casos seleccionados) refinan la decisión. **D es incorrecta:** los receptores solos no bastan. **A y C son incorrectas:** el grupo sanguíneo es preoperatorio rutinario y la preferencia del paciente se integra, pero no sustituye la estadificación.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r3-01-06","number":16,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 6","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"Paciente con tumor de páncreas resecable en TC, sin metástasis, bilirrubina 8 mg/dL, colangitis.","questions":[{"id":"puem-r2-cc-r3-01-06-q1","ordinal":1,"stem":"¿Cuál es la secuencia correcta?","options":["Operar de inmediato sin drenaje biliar, porque el drenaje retrasa la cirugía curativa.","Drenaje biliar endoscópico, resolver la colangitis y optimizar, luego cirugía; el drenaje rutinario preoperatorio sin colangitis no se recomienda, pero con colangitis es obligatorio.","Dar quimioterapia neoadyuvante primero en todos los casos resecables.","Colocar prótesis metálica definitiva y no operar."],"answer_index":1,"correct_text":"Drenaje biliar endoscópico, resolver la colangitis y optimizar, luego cirugía; el drenaje rutinario preoperatorio sin colangitis no se recomienda, pero con colangitis es obligatorio.","explanation":"La colangitis es indicación de drenaje urgente; sin colangitis el drenaje preoperatorio rutinario aumenta complicaciones y no se recomienda. La distinción es el punto clave del caso. **A es incorrecta:** operar con colangitis activa es inseguro. **C es incorrecta:** la neoadyuvancia no es estándar universal en resecable. **D es incorrecta:** la prótesis definitiva es paliativa y renuncia a la curación.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r3-01-07","number":17,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 7","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"En el reporte de patología de una colectomía oncológica,","questions":[{"id":"puem-r2-cc-r3-01-07-q1","ordinal":1,"stem":"¿cuál dato es más importante para juzgar la calidad de la cirugía?","options":["El tiempo quirúrgico.","El peso de la pieza quirúrgica.","El número de ganglios examinados (mínimo aprox. 12 en colon) y el estado de los márgenes (R0/R1).","El color de la mucosa resecada."],"answer_index":2,"correct_text":"El número de ganglios examinados (mínimo aprox. 12 en colon) y el estado de los márgenes (R0/R1).","explanation":"La linfadenectomía adecuada (≥12 ganglios examinados como estándar de calidad) y los márgenes libres son los indicadores de calidad oncológica; pocos ganglios pueden subestadificar. **B, A y A son incorrectas:** peso, color y tiempo no miden calidad oncológica.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r3-01-08","number":18,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 8","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"Hombre de 70 años con cáncer gástrico avanzado con metástasis peritoneales y obstrucción pilórica. No tolera vía oral.","questions":[{"id":"puem-r2-cc-r3-01-08-q1","ordinal":1,"stem":"¿Cuál es la intención quirúrgica más apropiada?","options":["No hacer nada quirúrgico porque todo procedimiento está contraindicado.","Gastrectomía parcial con intención curativa aunque haya metástasis.","Gastrectomía total curativa con linfadenectomía D2.","Derivación paliativa (gastro-yeyuno anastomosis) o stent para aliviar la obstrucción, con manejo sintomático y oncología médica; cirugía con intención paliativa, no curativa."],"answer_index":3,"correct_text":"Derivación paliativa (gastro-yeyuno anastomosis) o stent para aliviar la obstrucción, con manejo sintomático y oncología médica; cirugía con intención paliativa, no curativa.","explanation":"Con metástasis peritoneales la intención es paliativa: aliviar la obstrucción con la menor morbilidad (derivación o stent endoscópico según el caso). **A y B son incorrectas:** no hay cirugía curativa con enfermedad metastásica peritoneal diseminada. **A es incorrecta:** la paliación quirúrgica/endoscópica está indicada para el síntoma.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r3-01-09","number":19,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 9","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"Paciente con melanoma de 2.5 mm de espesor en espalda, sin adenopatías palpables.","questions":[{"id":"puem-r2-cc-r3-01-09-q1","ordinal":1,"stem":"¿Cuál es la conducta de estadificación ganglionar correcta?","options":["Biopsia de ganglio centinela, indicada en melanomas intermedios/gruesos (aprox. >0.8-1 mm) para estadificar y guiar adyuvancia, además de escisión amplia con margen.","Linfadenectomía radical profiláctica de toda la región.","Tomar biopsia de un ganglio al azar durante la escisión.","No estudiar ganglios porque no son palpables."],"answer_index":0,"correct_text":"Biopsia de ganglio centinela, indicada en melanomas intermedios/gruesos (aprox. >0.8-1 mm) para estadificar y guiar adyuvancia, además de escisión amplia con margen.","explanation":"El ganglio centinela estadifica el melanoma de espesor intermedio/grueso aunque no haya adenopatías palpables y define pronóstico y adyuvancia. **D es incorrecta:** la ausencia de adenopatías palpables no excluye micrometástasis. **B es incorrecta:** la linfadenectomía radical profiláctica no mejora supervivencia. **C es incorrecta:** el centinela es un procedimiento mapeado, no aleatorio.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r3-01-10","number":20,"title":"Cirugía oncológica: principios, estadificación y manejo multidisciplinario · caso 10","topic":"Neoplasias","topicId":"neoplasias","nivel":"R3","context":"Mujer de 45 años, antecedente familiar de cáncer de mama y ovario, prueba genética BRCA1 positiva, sin cáncer actual. Solicita opciones.","questions":[{"id":"puem-r2-cc-r3-01-10-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Hacer mamografía anual solamente y no ofrecer cirugía.","No hacer nada porque no tiene cáncer.","Mastectomía profiláctica bilateral y salpingo-ooforectomía reductora de riesgo, discutidas en comité y con asesoría genética, como cirugía profiláctica; además vigilancia intensiva si declina cirugía.","Dar quimioterapia preventiva."],"answer_index":2,"correct_text":"Mastectomía profiláctica bilateral y salpingo-ooforectomía reductora de riesgo, discutidas en comité y con asesoría genética, como cirugía profiláctica; además vigilancia intensiva si declina cirugía.","explanation":"BRCA1 confiere riesgo muy elevado; la cirugía reductora de riesgo es la medida más eficaz y debe ofrecerse con asesoría genética y decisión informada. **B es incorrecta:** el riesgo justifica acción. **D es incorrecta:** no existe quimioterapia preventiva estándar en este escenario. **A es incorrecta:** la vigilancia sola es una opción válida si la paciente la elige informada, pero no debe ser la única oferta sin discutir la cirugía.","topic":"Neoplasias"}]},{"id":"puem-r2-cc-r1-14-01","number":21,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 1","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Hombre de 60 años con tumor inguinal derecho doloroso, tenso, no reducible, de 6 h, con vómito, distensión y ausencia de evacuaciones.","questions":[{"id":"puem-r2-cc-r1-14-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y la conducta?","options":["Hernia incarcerada/estrangulada con obstrucción; cirugía urgente (no intentar reducción forzada).","Lipoma; resección electiva.","Hidrocele; observar.","Hernia reductible; observar."],"answer_index":0,"correct_text":"Hernia incarcerada/estrangulada con obstrucción; cirugía urgente (no intentar reducción forzada).","explanation":"tumor doloroso, tenso, no reducible + obstrucción es hernia complicada; la estrangulación es posible y la cirugía urgente es la conducta, no la reducción forzada. D es incorrecta: no es reductible ni para observar. B es incorrecta: el lipoma no da obstrucción. C es incorrecta: el hidrocele es indoloro y transilumina, no da obstrucción.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r1-14-02","number":22,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 2","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Mujer de 75 años, operada de laparotomía hace 2 años, con dolor cólico, distensión, vómito bilioso, ausencia de flatos, radiografía con niveles hidroaéreos y asas dilatadas.","questions":[{"id":"puem-r2-cc-r1-14-02-q1","ordinal":1,"stem":"¿Cuál es la causa más probable?","options":["Hernia estrangulada.","Obstrucción por adherencias (la más frecuente en el paciente operado).","Cáncer de colon.","Íleo paralítico."],"answer_index":1,"correct_text":"Obstrucción por adherencias (la más frecuente en el paciente operado).","explanation":"en el paciente con cirugía abdominal previa, la causa más frecuente de obstrucción de intestino delgado es adherencias; la hernia y el cáncer son diferenciales que la TC debe descartar. A es incorrecta: no hay tumor herniario descrito. C es incorrecta: el cáncer es causa de obstrucción de colon, menos frecuente como primera causa en este contexto. D es incorrecta: el íleo no da niveles hidroaéreos con dolor cólico y vómito bilioso de esta forma.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r1-14-03","number":23,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 3","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Hombre de 70 años con obstrucción por adherencias, sin fiebre, sin taquicardia, sin leucocitosis, sin peritonitis, TC sin isquemia.","questions":[{"id":"puem-r2-cc-r1-14-03-q1","ordinal":1,"stem":"¿Cuál es la conducta inicial?","options":["Solo analgésico.","Laparotomía de urgencia.","Manejo conservador (ayuno, sonda nasogástrica, reposición hidroelectrolítica, vigilancia estrecha) con criterios de operación si no resuelve en 48-72 h o hay datos de isquemia.","Alta."],"answer_index":2,"correct_text":"Manejo conservador (ayuno, sonda nasogástrica, reposición hidroelectrolítica, vigilancia estrecha) con criterios de operación si no resuelve en 48-72 h o hay datos de isquemia.","explanation":"la obstrucción por adherencias sin isquemia se maneja conservadoramente al inicio, con vigilancia estrecha y criterios claros de operación; operar de inmediato sin isquemia es innecesario. B es incorrecta: no hay indicación de laparotomía inmediata sin isquemia. D es incorrecta: requiere hospitalización y vigilancia. A es incorrecta: el analgésico solo no trata la obstrucción.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r1-14-04","number":24,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 4","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Paciente con obstrucción intestinal, fiebre 38.8 °C, FC 125, leucocitos 18,000, lactato 4 mmol/L, dolor continuo (no cólico), TC con pared intestinal engrosada sin realce y neumatosis.","questions":[{"id":"puem-r2-cc-r1-14-04-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Dar antibiótico y esperar.","Endoscopia.","Manejo conservador.","Cirugía urgente: hay isquemia intestinal (dolor continuo, fiebre, leucocitosis, lactato, TC sin realce/neumatosis)."],"answer_index":3,"correct_text":"Cirugía urgente: hay isquemia intestinal (dolor continuo, fiebre, leucocitosis, lactato, TC sin realce/neumatosis).","explanation":"el dolor que pasa de cólico a continuo + fiebre + leucocitosis + lactato + TC con falta de realce y neumatosis es isquemia/necrosis intestinal: cirugía urgente, no manejo conservador. C es incorrecta: el manejo conservador en isquemia es letal. A es incorrecta: el antibiótico no revierte la necrosis. B es incorrecta: la endoscopia no trata la isquemia de intestino delgado.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r1-14-05","number":25,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 5","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Hombre de 80 años con distensión abdominal marcada, dolor, ausencia de evacuaciones, radiografía con colon dilatado y TC con vólvulo de sigmoides sin isquemia.","questions":[{"id":"puem-r2-cc-r1-14-05-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Desvolvulación endoscópica (sigmoidoscopia/colonoscopia) si no hay isquemia ni perforación, con cirugía electiva posterior (resección) por el alto riesgo de recurrencia.","Manejo conservador sin endoscopia.","Dar laxante.","Laparotomía de urgencia."],"answer_index":0,"correct_text":"Desvolvulación endoscópica (sigmoidoscopia/colonoscopia) si no hay isquemia ni perforación, con cirugía electiva posterior (resección) por el alto riesgo de recurrencia.","explanation":"el vólvulo de sigmoides sin isquemia se desvolvula por endoscopia y luego se opera electivamente (sigmoidectomía) por la alta recurrencia; la laparotomía inmediata es para isquemia/perforación. D es incorrecta: no hay isquemia. B es incorrecta: el manejo conservador solo no desvolvula. C es incorrecta: el laxante no trata el vólvulo.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r1-14-06","number":26,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 6","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Mujer de 45 años con hernia umbilical de 2 cm, reductible, sin dolor, que le molesta estéticamente.","questions":[{"id":"puem-r2-cc-r1-14-06-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Cirugía urgente.","Hernioplastia electiva (con malla según el tamaño y el caso), con control de factores de riesgo; no es urgencia.","No operar nunca.","Faja para siempre."],"answer_index":1,"correct_text":"Hernioplastia electiva (con malla según el tamaño y el caso), con control de factores de riesgo; no es urgencia.","explanation":"la hernia umbilical sintomática o con riesgo de complicación se opera electivamente; no es urgencia si es reductible y sin dolor, pero la faja no la cura. A es incorrecta: no es urgencia. C es incorrecta: la hernia no se cura sola y puede complicarse. D es incorrecta: la faja es paliativa, no tratamiento.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r1-14-07","number":27,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 7","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Hombre de 55 años, postoperatorio de laparotomía, con distensión, sin evacuaciones, sin dolor cólico, sin fiebre, radiografía sin niveles hidroaéreos claros, K⁺ 3.0 mEq/L.","questions":[{"id":"puem-r2-cc-r1-14-07-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable?","options":["Hernia estrangulada.","Obstrucción mecánica.","Íleo paralítico postoperatorio (con hipopotasemia como contribuyente).","Peritonitis."],"answer_index":2,"correct_text":"Íleo paralítico postoperatorio (con hipopotasemia como contribuyente).","explanation":"distensión sin dolor cólico, sin niveles hidroaéreos claros, con hipopotasemia postoperatoria, es íleo paralítico; la obstrucción mecánica da dolor cólico y niveles hidroaéreos. B es incorrecta: falta el dolor cólico y los niveles. D es incorrecta: no hay fiebre ni peritonitis. A es incorrecta: no hay tumor herniario.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r1-14-08","number":28,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 8","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Paciente con hernia inguinal indirecta, reductible, sin complicaciones, programado para hernioplastia.","questions":[{"id":"puem-r2-cc-r1-14-08-q1","ordinal":1,"stem":"¿Cuál es la técnica de referencia en la mayoría de los adultos?","options":["No usar malla nunca.","Solo faja.","Reparación sin malla (técnica de Bassini) en todos.","Hernioplastia con malla (Lichtenstein abierta o TAPP/TEP laparoscópica, según el servicio y el paciente)."],"answer_index":3,"correct_text":"Hernioplastia con malla (Lichtenstein abierta o TAPP/TEP laparoscópica, según el servicio y el paciente).","explanation":"la hernioplastia con malla es el estándar en el adulto por menor recidiva; la técnica (abierta vs laparoscópica) depende del servicio, la hernia y el paciente. C es incorrecta: la reparación sin malla tiene más recidiva en el adulto. A es incorrecta: la malla es el estándar. B es incorrecta: la faja no cura la hernia.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r1-14-09","number":29,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 9","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Hombre de 65 años con hernia incisional grande, con intestino incarcerado, necrosis segmentaria y contaminación en quirófano.","questions":[{"id":"puem-r2-cc-r1-14-09-q1","ordinal":1,"stem":"¿Se debe poner malla?","options":["No (o valorar malla biológica según el servicio): con necrosis y contaminación, la malla sintética tiene alto riesgo de infección; se cierra sin malla o se difiere la reparación.","Sí, pero sin antibiótico.","No operar.","Sí, siempre."],"answer_index":0,"correct_text":"No (o valorar malla biológica según el servicio): con necrosis y contaminación, la malla sintética tiene alto riesgo de infección; se cierra sin malla o se difiere la reparación.","explanation":"con contaminación y necrosis, la malla sintética se infecta con facilidad; la conducta es no ponerla (o valorar malla biológica según el servicio) y reparar sin tensión o diferir. D es incorrecta: no siempre. B es incorrecta: el antibiótico no evita la infección de la malla en contaminación grave. C es incorrecta: hay que operar la estrangulación.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r1-14-10","number":30,"title":"Hernias de pared abdominal y obstrucción intestinal · caso 10","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R1","context":"Paciente con obstrucción de colon, distensión, vómito fecaloide, TC con masa en colon sigmoides que obstruye.","questions":[{"id":"puem-r2-cc-r1-14-10-q1","ordinal":1,"stem":"¿Cuál es la causa más probable y qué se debe descartar?","options":["Vólvulo; desvolvulación.","Adherencias; nada más.","Cáncer de colon como causa de obstrucción de colon; requiere estadificación y manejo oncológico-quirúrgico (no solo descompresión).","Íleo; manejo conservador."],"answer_index":2,"correct_text":"Cáncer de colon como causa de obstrucción de colon; requiere estadificación y manejo oncológico-quirúrgico (no solo descompresión).","explanation":"la obstrucción de colon en el adulto mayor con masa es cáncer hasta demostrar lo contrario; requiere estudio y manejo quirúrgico-oncológico, no solo manejo conservador. B es incorrecta: las adherencias son causa de intestino delgado, no la primera en colon con masa. D es incorrecta: el vómito fecaloide con masa no es íleo. A es incorrecta: el vólvulo no es una masa.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-01","number":31,"title":"Hernias de la pared abdominal · caso 1","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Varón de 68 años, fumador, con tos crónica y prostatismo, acude por tumoración inguinal derecha de 6 meses que aumenta al estar de pie y desaparece al acostarse. A la exploración: masa blanda en conducto inguinal que se reduce, con impulso tusígeno, sin dolor. Tacto rectal: próstata grado II. Laboratorios normales.","questions":[{"id":"puem-r2-cc-r2-07-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable y la conducta inicial más adecuada?","options":["Hernia femoral incarcerada; cirugía de urgencia inmediata","Hernia inguinal directa reducible; reparación electiva con malla y valoración urológica del prostatismo","Hidrocele comunicante; observación sin cirugía","Lipoma del cordón; resección local sin malla"],"answer_index":1,"correct_text":"Hernia inguinal directa reducible; reparación electiva con malla y valoración urológica del prostatismo","explanation":"La tumoración inguinal reducible con impulso tusígeno en un varón mayor con factores de presión intraabdominal y debilitamiento del piso inguinal corresponde a hernia inguinal, más probablemente directa por la edad y el mecanismo. Es electiva con malla, y el prostatismo debe tratarse porque perpetúa la hernia. A es incorrecta: la femoral es bajo el ligamento inguinal, más frecuente en mujeres y la incarcerada no se reduce ni es indolora. C es incorrecta: el hidrocele es escrotal, transilumina y no tiene impulso tusígeno ni se reduce a la cavidad. D es incorrecta: el lipoma no se reduce ni tiene impulso tusígeno.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-02","number":32,"title":"Hernias de la pared abdominal · caso 2","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Mujer de 74 años, diabética, con dolor inguinal derecho súbito de 8 horas, vómito y distensión abdominal. Exploración: tumoración tensa, dolorosa, irreductible bajo el ligamento inguinal, sin impulso tusígeno, piel eritematosa. Leucocitos 16,000/µL, lactato 3.2 mmol/L, glucosa 210 mg/dL. Radiografía: niveles hidroaéreos.","questions":[{"id":"puem-r2-cc-r2-07-02-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Analgesia, ayuno, reanimación y cirugía de urgencia sin intentar reducción forzada","Ultrasonido y observación 24 horas con antibiótico oral","Reparación electiva en 4 semanas tras control glucémico","Intentar reducción manual con sedación y enviar a casa si se reduce"],"answer_index":0,"correct_text":"Analgesia, ayuno, reanimación y cirugía de urgencia sin intentar reducción forzada","explanation":"Es una hernia femoral estrangulada probable: mujer mayor, bulto bajo el ligamento inguinal, irreductible, doloroso, con obstrucción, leucocitosis y lactato elevado. Requiere reanimación y cirugía inmediata; la reducción forzada puede devolver intestino necrótico a la cavidad. A es peligrosa por ese motivo y por el tiempo de evolución. C retrasa una urgencia con isquemia. C es incorrecta: no es un caso electivo.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-03","number":33,"title":"Hernias de la pared abdominal · caso 3","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Varón de 32 años, deportista, con dolor inguinal izquierdo de 3 meses al correr, sin tumoración palpable evidente. Exploración en bipedestación con Valsalva: leve abultamiento dudoso. Ultrasonido dinámico: saco herniario indirecto pequeño que protruye con Valsalva. Resonancia de pelvis: sin lesión muscular ni pubalgia ósea.","questions":[{"id":"puem-r2-cc-r2-07-03-q1","ordinal":1,"stem":"¿Cuál es el mejor manejo?","options":["Infiltración de corticoide en la sínfisis del pubis","Reposo absoluto 6 meses sin cirugía","Reparación abierta sin malla tipo Bassini","Reparación laparoscópica TEP/TAPP electiva"],"answer_index":3,"correct_text":"Reparación laparoscópica TEP/TAPP electiva","explanation":"Hernia inguinal indirecta oculta demostrada por ultrasonido dinámico en un paciente joven y activo, con dolor relacionado con el esfuerzo. La reparación laparoscópica preperitoneal es adecuada: cubre el orificio miopectíneo, tiene retorno rápido a la actividad y es útil cuando el diagnóstico era dudoso. B trata una pubalgia que la resonancia descartó. B no resuelve una hernia sintomática demostrada. D es posible pero menos favorable en un paciente joven activo y con hernia pequeña; la malla sin tensión tiene menor recurrencia.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-04","number":34,"title":"Hernias de la pared abdominal · caso 4","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Varón de 58 años, obeso, con hernia umbilical de 4 cm dolorosa al esfuerzo y antecedente de laparotomía media por apendicitis complicada hace 2 años, con abultamiento en la cicatriz. Tomografía: defecto umbilical de 4 cm con grasa y defecto incisional medial de 6 cm con asa intestinal. HbA1c 8.5%, tabaquismo activo.","questions":[{"id":"puem-r2-cc-r2-07-04-q1","ordinal":1,"stem":"¿Cuál es la conducta más adecuada antes de la cirugía electiva?","options":["Faja abdominal definitiva y no operar por obesidad","Operar mañana con malla intraperitoneal en ambos defectos","Optimizar: control glucémico, cese de tabaquismo, pérdida de peso, y planear reparación con malla retromuscular","Reparación solo del defecto umbilical con sutura primaria"],"answer_index":2,"correct_text":"Optimizar: control glucémico, cese de tabaquismo, pérdida de peso, y planear reparación con malla retromuscular","explanation":"Hernia ventral compleja, con dos defectos, obesidad, diabetes descontrolada y tabaquismo: el riesgo de infección y recurrencia es alto. La optimización preoperatoria y la reparación planeada con malla retromuscular (sublay) es lo correcto; la sutura primaria de un defecto de 4-6 cm tiene alta recurrencia. A ignora la optimización y opera un paciente de alto riesgo sin plan. C deja sin tratar el defecto incisional de 6 cm. D condena a obstrucción e incarceración futuras sin resolver el problema.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-05","number":35,"title":"Hernias de la pared abdominal · caso 5","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Niño de 2 años con abultamiento inguinal derecho intermitente al llorar, que desaparece al dormir. Sin dolor, sin vómito. Exploración: masa blanda reducible en conducto inguinal, testículo en escroto.","questions":[{"id":"puem-r2-cc-r2-07-05-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Criptorquidia; orquidopexia urgente","Hernia inguinal indirecta congénita; reparación electiva pronta con ligadura alta del saco","Hernia directa del adulto; vigilancia hasta la adolescencia","Hidrocele no comunicante; observación hasta los 5 años"],"answer_index":1,"correct_text":"Hernia inguinal indirecta congénita; reparación electiva pronta con ligadura alta del saco","explanation":"En el niño la hernia inguinal es casi siempre indirecta por persistencia del conducto peritoneo-vaginal. Aunque ahora es reducible e indolora, el riesgo de incarceración es mayor que en el adulto y la reparación es electiva pero pronta, con ligadura alta del saco, habitualmente sin malla. C es incorrecta: la directa es del adulto con piso débil. D es incorrecta: el hidrocele no comunicante no se reduce al abdomen ni protruye por el conducto. A es incorrecta: el testículo está en escroto.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-06","number":36,"title":"Hernias de la pared abdominal · caso 6","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Varón de 45 años, 6 horas después de reparación inguinal abierta con malla, con dolor escrotal intenso, escroto edematoso y equimótico, sin fiebre. Signos vitales estables, leucocitos normales.","questions":[{"id":"puem-r2-cc-r2-07-06-q1","ordinal":1,"stem":"¿Cuál es la complicación más probable y la conducta?","options":["Hematoma escrotal posoperatorio; vigilancia, soporte escrotal, analgesia y descartar sangrado activo","Infección de malla; retiro de malla y antibiótico intravenoso","Orquitis bacteriana; antibiótico oral y alta","Estrangulación de asa en el saco residual; reintervención inmediata"],"answer_index":0,"correct_text":"Hematoma escrotal posoperatorio; vigilancia, soporte escrotal, analgesia y descartar sangrado activo","explanation":"El hematoma/equimosis escrotal en las primeras horas tras la reparación inguinal es una complicación temprana frecuente por sangrado del lecho o del cordón; si el paciente está estable, sin datos de choque ni expansión rápida, se vigila con soporte y analgesia, descartando sangrado activo que requiera reexploración. A es improbable: no hay datos de obstrucción ni peritonismo y la reparación ya cerró el defecto. C es tardía habitualmente y cursa con fiebre, eritema de herida y secreción. C no explica la equimosis inmediata posquirúrgica.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-07","number":37,"title":"Hernias de la pared abdominal · caso 7","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Mujer de 62 años con dolor abdominal cólico, distensión y vómito de 12 horas. Evacúa escaso moco con sangre. Exploración: tumoración dolorosa en región inguinal izquierda, no reducible, sin eritema. No hay niveles hidroaéreos francos en radiografía y ha evacuado una vez hoy. El residente propone descartar estrangulación porque evacua.","questions":[{"id":"puem-r2-cc-r2-07-07-q1","ordinal":1,"stem":"¿Qué debe hacerse?","options":["Solicitar colonoscopia urgente para descartar cáncer de colon","Dar laxante y enema para confirmar que no hay obstrucción","Aceptar el argumento y dar manejo conservador por probable gastroenteritis","Sospechar hernia de Richter y operar de urgencia: la evacuación no excluye isquemia parcial de la pared intestinal"],"answer_index":3,"correct_text":"Sospechar hernia de Richter y operar de urgencia: la evacuación no excluye isquemia parcial de la pared intestinal","explanation":"La hernia de Richter atrapa solo parte de la circunferencia del asa: puede estrangularse y necrosarse sin obstrucción completa, por lo que el paciente puede evacuar y la radiografía puede ser poco concluyente. La tumoración inguinal irreductible y dolorosa con dolor cólico es suficiente para operar de urgencia. A minimiza un signo clásico. C retrasa la cirugía y la colonoscopia en obstrucción es riesgosa. D es peligroso ante sospecha de isquemia.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-08","number":38,"title":"Hernias de la pared abdominal · caso 8","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Varón de 70 años con hernia inguinal derecha gigante de años de evolución, con gran parte del intestino en el escroto y disnea al acostarse. Tomografía: pérdida de dominio, con más del 50% del contenido abdominal en el saco.","questions":[{"id":"puem-r2-cc-r2-07-08-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Reducción forzada en urgencias y reparación con malla en el mismo acto","Reparación electiva inmediata con malla sin preparación","Valoración multidisciplinaria, preparación con neumoperitoneo progresivo o toxina botulínica según protocolo local, y reparación planeada en centro con experiencia","No operar nunca por el tamaño"],"answer_index":2,"correct_text":"Valoración multidisciplinaria, preparación con neumoperitoneo progresivo o toxina botulínica según protocolo local, y reparación planeada en centro con experiencia","explanation":"La hernia con pérdida de dominio no se reduce de golpe: devolver bruscamente todo el contenido eleva la presión intraabdominal y puede causar síndrome compartimental, insuficiencia respiratoria e íleo grave. Requiere preparación —neumoperitoneo progresivo, toxina botulínica en pared, optimización respiratoria— y cirugía planeada por equipo con experiencia. A y B exponen a esa complicación. D es incorrecta: es operable, pero no como una hernia común.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-09","number":39,"title":"Hernias de la pared abdominal · caso 9","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Durante una reparación inguinal laparoscópica TAPP, el cirujano identifica un saco con el apéndice cecal inflamado en su interior. No hay perforación ni pus libre.","questions":[{"id":"puem-r2-cc-r2-07-09-q1","ordinal":1,"stem":"¿Cómo se denomina este hallazgo y cuál es el manejo más aceptado?","options":["Hernia de Littre; dejar el apéndice y reparar solo la hernia","Hernia de Amyand tipo 1 con apendicitis; apendicectomía y reparación herniaria, valorando malla según contaminación","Hernia de Garengeot; apendicectomía por vía femoral exclusiva","Hernia de Richter; resección intestinal obligada"],"answer_index":1,"correct_text":"Hernia de Amyand tipo 1 con apendicitis; apendicectomía y reparación herniaria, valorando malla según contaminación","explanation":"Es una hernia de Amyand: apéndice dentro del saco inguinal. Con apendicitis aguda se hace apendicectomía y reparación herniaria; la malla se valora según el grado de contaminación —en apendicitis no complicada muchos la colocan, en contaminación franca se prefiere reparación sin malla o diferirla—. A es incorrecta: Littre es divertículo de Meckel, no apéndice. C es el apéndice en saco femoral, no inguinal. D es otro mecanismo, de pared intestinal parcial.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-07-10","number":40,"title":"Hernias de la pared abdominal · caso 10","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R2","context":"Varón de 55 años, 8 meses después de reparación inguinal con malla, con dolor inguinal crónico quemante que se irradia a la cara interna del muslo, empeora al caminar y no responde a analgésicos habituales. Sin tumoración ni datos de recurrencia en ultrasonido.","questions":[{"id":"puem-r2-cc-r2-07-10-q1","ordinal":1,"stem":"¿Cuál es la causa más probable y el siguiente paso?","options":["Infección crónica de malla; retiro inmediato sin estudios","Hernia femoral contralateral; exploración del otro lado","Recurrencia oculta; reoperar de inmediato","Inguinodinia por lesión o atrapamiento del nervio ilioinguinal; manejo escalonado: fármacos neuropáticos, bloqueo diagnóstico y valoración por clínica del dolor antes de reintervenir"],"answer_index":3,"correct_text":"Inguinodinia por lesión o atrapamiento del nervio ilioinguinal; manejo escalonado: fármacos neuropáticos, bloqueo diagnóstico y valoración por clínica del dolor antes de reintervenir","explanation":"El dolor crónico quemante e irradiado meses después de la reparación, sin tumoración ni recurrencia en imagen, sugiere inguinodinia neuropática por lesión o atrapamiento del nervio ilioinguinal, iliohipogástrico o rama genital. El manejo es escalonado y conservador primero: fármacos para dolor neuropático, bloqueo diagnóstico y clínica del dolor; la reintervención con neurectomía es último recurso. A opera sin evidencia de recurrencia. A no tiene datos de infección. B no explica el dolor del lado operado.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-01","number":41,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 1","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Hombre de 65 años con hernia inguinal derecha reducible, sin dolor, que aumenta al toser.","questions":[{"id":"puem-r2-cc-r3-10-01-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Usar faja de por vida como tratamiento definitivo.","Cirugía de urgencia inmediata.","Reparación electiva con malla (Lichtenstein o laparoscópica) tras valoración; la vigilancia (watchful waiting) es una opción en varones asintomáticos o con síntomas mínimos, pero la reparación es el tratamiento definitivo.","No operar nunca."],"answer_index":2,"correct_text":"Reparación electiva con malla (Lichtenstein o laparoscópica) tras valoración; la vigilancia (watchful waiting) es una opción en varones asintomáticos o con síntomas mínimos, pero la reparación es el tratamiento definitivo.","explanation":"La hernia inguinal sintomática se repara electivamente con malla; en asintomático la vigilancia es una opción válida discutida con el paciente. **B es incorrecta:** no es urgencia. **D es incorrecta:** la hernia no se cura sola. **A es incorrecta:** la faja no es tratamiento definitivo.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-02","number":42,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 2","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Mujer de 70 años con hernia femoral derecha incarcerada, dolor intenso, vómitos, distensión y fiebre.","questions":[{"id":"puem-r2-cc-r3-10-02-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Dar analgésicos y observar 48 h.","Colocar malla por vía laparoscópica electiva en 1 mes.","Intentar reducción manual y dar de alta.","Cirugía de urgencia: explorar, valorar viabilidad del contenido (resección intestinal si hay necrosis) y reparar; la hernia femoral se estrangula con facilidad y no se deja para después."],"answer_index":3,"correct_text":"Cirugía de urgencia: explorar, valorar viabilidad del contenido (resección intestinal si hay necrosis) y reparar; la hernia femoral se estrangula con facilidad y no se deja para después.","explanation":"La hernia femoral incarcerada con signos de estrangulación es urgencia quirúrgica; la demora causa necrosis intestinal. **C es incorrecta:** la reducción manual en estrangulación es peligrosa. **A es incorrecta:** observar una estrangulación es negligente. **B es incorrecta:** no es electiva.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-03","number":43,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 3","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Paciente con hernia incisional de 12 cm en línea media, recidivada, con pérdida de dominio.","questions":[{"id":"puem-r2-cc-r3-10-03-q1","ordinal":1,"stem":"¿Cuál es el plan correcto?","options":["Preparación preoperatoria (toxina botulínica y/o neumoperitoneo progresivo) y reparación con malla sublay + separación de componentes (TAR) en centro con experiencia; la sutura primaria en defectos grandes recidiva.","No operar nunca.","Cerrar con malla onlay sin preparación.","Reparación simple con sutura primaria."],"answer_index":0,"correct_text":"Preparación preoperatoria (toxina botulínica y/o neumoperitoneo progresivo) y reparación con malla sublay + separación de componentes (TAR) en centro con experiencia; la sutura primaria en defectos grandes recidiva.","explanation":"El defecto grande con pérdida de dominio exige preparación y reconstrucción con TAR + malla; la sutura primaria fracasa. **D es incorrecta:** la sutura primaria en 12 cm recidiva casi siempre. **B es incorrecta:** es operable con preparación. **C es incorrecta:** sin preparación, el cierre a tensión causa síndrome compartimental y recurrencia.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-04","number":44,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 4","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Hombre de 50 años con hernia incisional infectada, con fístula enterocutánea y malla expuesta.","questions":[{"id":"puem-r2-cc-r3-10-04-q1","ordinal":1,"stem":"¿Cuál es la conducta respecto a la malla?","options":["Dejar la malla infectada y dar antibióticos.","Retirar la malla infectada (o el segmento comprometido), controlar la fístula y la sepsis, y diferir la reconstrucción definitiva de la pared hasta resolver la infección.","Colocar otra malla sintética encima.","Cerrar la piel sobre la malla infectada."],"answer_index":1,"correct_text":"Retirar la malla infectada (o el segmento comprometido), controlar la fístula y la sepsis, y diferir la reconstrucción definitiva de la pared hasta resolver la infección.","explanation":"La malla infectada con fístula debe retirarse (al menos el segmento afectado) y la reconstrucción se difiere; la malla nueva sobre infección fracasa. **A es incorrecta:** los antibióticos no esterilizan una malla infectada con fístula. **C es incorrecta:** poner malla sobre infección es un error. **D es incorrecta:** cerrar sobre infección perpetúa la sepsis.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-05","number":45,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 5","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Paciente con reflujo grave, pirosis diaria pese a inhibidor de bomba de protones, endoscopia con esofagitis, pHmetría positiva. Se propone funduplicatura.","questions":[{"id":"puem-r2-cc-r3-10-05-q1","ordinal":1,"stem":"¿Qué estudio es obligatorio antes?","options":["Gammagrafía.","Solo la endoscopia basta.","Manometría esofágica (descartar acalasia o trastorno motor grave) + pHmetría; operar un trastorno motor como si fuera reflujo causa disfagia grave posoperatoria.","Colonoscopia."],"answer_index":2,"correct_text":"Manometría esofágica (descartar acalasia o trastorno motor grave) + pHmetría; operar un trastorno motor como si fuera reflujo causa disfagia grave posoperatoria.","explanation":"La manometría es obligatoria antes de funduplicatura: la acalasia se presenta como 'reflujo' y la funduplicatura la empeora catastróficamente. **B es incorrecta:** la endoscopia no evalúa motilidad. **A y A son irrelevantes.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-06","number":46,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 6","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Hombre de 45 años con hernia inguinal bilateral, deportista, desea cirugía mínimamente invasiva.","questions":[{"id":"puem-r2-cc-r3-10-06-q1","ordinal":1,"stem":"¿Qué opción es adecuada?","options":["No operar hernias bilaterales.","Reparación sin malla obligatoria.","Lichtenstein bilateral en un tiempo.","TAPP o TEP laparoscópico, especialmente útil en hernia bilateral y recidivada, con malla; la elección entre TAPP y TEP depende de la experiencia del cirujano."],"answer_index":3,"correct_text":"TAPP o TEP laparoscópico, especialmente útil en hernia bilateral y recidivada, con malla; la elección entre TAPP y TEP depende de la experiencia del cirujano.","explanation":"La laparoscopia (TAPP/TEP) es ventajosa en bilateral y recidivada; el Lichtenstein también es válido, pero la pregunta pide la opción mínimamente invasiva. **C es incorrecta:** no es la opción mínimamente invasiva pedida (aunque es válida). **A es incorrecta:** las bilaterales se operan. **B es incorrecta:** la malla es el estándar.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-07","number":47,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 7","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Paciente pos-hernioplastia inguinal con dolor crónico en la ingle a los 6 meses, que interfiere con su trabajo.","questions":[{"id":"puem-r2-cc-r3-10-07-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Inguinodinia (dolor crónico poshernioplastia): manejo escalonado (analgesia, fisioterapia, bloqueo nervioso, valoración de causa) y reintervención solo en casos seleccionados (neurectomía) tras agotar el manejo conservador.","Es normal y no requiere nada.","Infección de malla: retirar la malla de inmediato.","Recurrencia: reoperar de inmediato."],"answer_index":0,"correct_text":"Inguinodinia (dolor crónico poshernioplastia): manejo escalonado (analgesia, fisioterapia, bloqueo nervioso, valoración de causa) y reintervención solo en casos seleccionados (neurectomía) tras agotar el manejo conservador.","explanation":"El dolor crónico inguinal es una complicación real que se maneja de forma escalonada; reoperar de inmediato no es el primer paso. **D es incorrecta:** el dolor no es sinónimo de recurrencia. **B es incorrecta:** el dolor que interfiere con el trabajo exige manejo. **C es incorrecta:** no hay datos de infección.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-08","number":48,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 8","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Durante una colecistectomía laparoscópica se lesiona el intestino delgado con el trocar de entrada.","questions":[{"id":"puem-r2-cc-r3-10-08-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["No mencionarlo y terminar la cirugía.","Reconocer la lesión, repararla (laparoscópica o abierta según el caso), lavar, valorar contaminación y documentarla; la lesión inadvertida es la complicación más grave de la laparoscopia.","Convertir a cirugía abierta siempre, sin reparar.","Dar antibióticos y cerrar."],"answer_index":1,"correct_text":"Reconocer la lesión, repararla (laparoscópica o abierta según el caso), lavar, valorar contaminación y documentarla; la lesión inadvertida es la complicación más grave de la laparoscopia.","explanation":"La lesión intestinal por trocar debe reconocerse y repararse en el mismo acto; la lesión inadvertida causa peritonitis y muerte. **A es incorrecta:** ocultarla es negligencia grave. **C es incorrecta:** la conversión es una opción, no obligatoria si se puede reparar por laparoscopia. **D es incorrecta:** los antibióticos no reparan el intestino.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-09","number":49,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 9","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Paciente con hernia inguinal estrangulada, en quirófano se encuentra un asa intestinal necrótica de 20 cm.","questions":[{"id":"puem-r2-cc-r3-10-09-q1","ordinal":1,"stem":"¿Cuál es la conducta respecto a la malla?","options":["Cerrar sin reparar la hernia y sin resecar.","Colocar malla sintética de rutina tras la resección.","Resección del segmento necrótico con anastomosis (o estoma si hay inestabilidad/contaminación grave) y reparar la hernia sin malla sintética permanente o diferir la reparación con malla; la malla en campo contaminado con necrosis aumenta la infección.","No resecar el intestino necrótico."],"answer_index":2,"correct_text":"Resección del segmento necrótico con anastomosis (o estoma si hay inestabilidad/contaminación grave) y reparar la hernia sin malla sintética permanente o diferir la reparación con malla; la malla en campo contaminado con necrosis aumenta la infección.","explanation":"En estrangulación con necrosis hay contaminación: la malla sintética permanente está contraindicada de rutina; se reseca y se repara sin malla o se difiere. **B es incorrecta:** la malla en campo contaminado se infecta. **D es incorrecta:** el intestino necrótico debe resecarse. **A es incorrecta:** no resuelve nada.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r3-10-10","number":50,"title":"Cirugía mínimamente invasiva avanzada, pared abdominal y hernias complejas · caso 10","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R3","context":"Mujer de 60 años con hernia hiatal tipo III (paraesofágica) grande, con dolor torácico, disfagia y episodios de vólvulo gástrico.","questions":[{"id":"puem-r2-cc-r3-10-10-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Reparación quirúrgica (reducción, cierre del hiato y funduplicatura) porque la hernia paraesofágica sintomática con riesgo de vólvulo/estrangulación es indicación quirúrgica; la tipo I (deslizante) con reflujo es la que se maneja médicamente.","Funduplicatura sin reparar el hiato.","Gastrectomía.","Solo antiácidos, la hernia paraesofágica no se opera."],"answer_index":0,"correct_text":"Reparación quirúrgica (reducción, cierre del hiato y funduplicatura) porque la hernia paraesofágica sintomática con riesgo de vólvulo/estrangulación es indicación quirúrgica; la tipo I (deslizante) con reflujo es la que se maneja médicamente.","explanation":"La distinción clave: la hernia paraesofágica (tipos II-IV) sintomática se opera por riesgo de complicación mecánica; la deslizante tipo I con reflujo se maneja médicamente o con funduplicatura por reflujo. **D es incorrecta:** la paraesofágica sintomática sí se opera. **B es incorrecta:** sin cierre del hiato recidiva. **C es incorrecta:** no hay indicación de gastrectomía.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-01","number":51,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 1","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Mujer 42 años, IMC 42, diabetes descontrolada, ERGE grave con esofagitis.","questions":[{"id":"puem-r2-cc-r4-08-01-q1","ordinal":1,"stem":"¿Cirugía bariátrica preferida?","options":["Bypass gástrico en Y de Roux","Banda gástrica","Balón intragástrico definitivo","Manga gástrica"],"answer_index":0,"correct_text":"Bypass gástrico en Y de Roux","explanation":"Con ERGE grave, el bypass es preferido: la manga empeora el reflujo. La banda y el balón no son definitivos ni tratan la diabetes igual.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-02","number":52,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 2","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Hombre con hernia ventral gigante, pérdida de dominio 30%, fumador, HbA1c 9%.","questions":[{"id":"puem-r2-cc-r4-08-02-q1","ordinal":1,"stem":"¿Primera conducta?","options":["Operar ya con malla","Optimización: dejar de fumar, control glucémico, pérdida de peso, y plan de TAR ± neumoperitoneo/toxina botulínica","Solo faja abdominal","Malla sin optimización"],"answer_index":1,"correct_text":"Optimización: dejar de fumar, control glucémico, pérdida de peso, y plan de TAR ± neumoperitoneo/toxina botulínica","explanation":"La pared compleja se optimiza antes de operar; operar un fumador diabético descontrolado con pérdida de dominio es recidiva/infección casi segura. La malla no compensa la falta de optimización.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-03","number":53,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 3","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Postmanga gástrica día 4, fiebre, taquicardia, dolor epigástrico.","questions":[{"id":"puem-r2-cc-r4-08-03-q1","ordinal":1,"stem":"¿Sospecha prioritaria?","options":["Solo gastritis","ERGE postoperatoria","Fuga de línea de grapas; TC con contraste oral/IV y manejo en equipo","Normal postoperatorio"],"answer_index":2,"correct_text":"Fuga de línea de grapas; TC con contraste oral/IV y manejo en equipo","explanation":"Fiebre + taquicardia tras manga = fuga hasta demostrar lo contrario. La TC con contraste y el manejo multidisciplinario son urgentes; atribuirlo a reflujo retrasa el control.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-04","number":54,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 4","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Paciente con hernia inguinal estrangulada, eritema, lactato 4, dolor súbito.","questions":[{"id":"puem-r2-cc-r4-08-04-q1","ordinal":1,"stem":"¿Conducta?","options":["Solo analgésicos y observación","TC en 24 h","Reducción manual e ingreso electivo","Cirugía urgente: exploración, resección de intestino no viable si hace falta"],"answer_index":3,"correct_text":"Cirugía urgente: exploración, resección de intestino no viable si hace falta","explanation":"Estrangulación = quirófano urgente; la reducción manual en estrangulación puede devolver intestino necrótico. Esperar imagen retrasa la resección.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-05","number":55,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 5","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Mujer postbypass 2 años, anemia ferropénica y B12 baja, sin suplementos.","questions":[{"id":"puem-r2-cc-r4-08-05-q1","ordinal":1,"stem":"¿Causa y manejo?","options":["Deficiencia por malabsorción y falta de suplementos; reposición y seguimiento de por vida","Sangrado activo seguro sin estudio","Normal tras bypass","Solo dieta"],"answer_index":0,"correct_text":"Deficiencia por malabsorción y falta de suplementos; reposición y seguimiento de por vida","explanation":"El bypass causa malabsorción de hierro/B12: el seguimiento y la suplementación son de por vida. Atribuirlo a dieta sin reponer perpetúa la anemia.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-06","number":56,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 6","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Hombre con hernia incisional recidivada, malla previa infectada.","questions":[{"id":"puem-r2-cc-r4-08-06-q1","ordinal":1,"stem":"¿Principio?","options":["Colocar malla sintética nueva en campo infectado siempre","Retirar malla infectada, controlar infección y reconstrucción diferida/individualizada","Solo antibiótico de por vida","No operar nunca"],"answer_index":1,"correct_text":"Retirar malla infectada, controlar infección y reconstrucción diferida/individualizada","explanation":"La malla infectada generalmente se retira y la reconstrucción se difiere; colocar malla nueva en infección perpetúa el problema. La decisión es individualizada en centro experto.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-07","number":57,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 7","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Paciente con obesidad IMC 38, diabetes, SAOS, sin cirugía previa.","questions":[{"id":"puem-r2-cc-r4-08-07-q1","ordinal":1,"stem":"¿Es candidato a bariátrica?","options":["No, la cirugía es estética","No, solo IMC >40","Sí, con comorbilidades (ASMBS/IFSO 2022) y evaluación multidisciplinaria","Solo si fracasa dieta 10 años"],"answer_index":2,"correct_text":"Sí, con comorbilidades (ASMBS/IFSO 2022) y evaluación multidisciplinaria","explanation":"IMC 35-40 con comorbilidades graves es indicación con evaluación multidisciplinaria. Exigir IMC >40 ignora las guías actuales.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-08","number":58,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 8","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Hernia ventral con obstrucción intestinal, estable, sin isquemia.","questions":[{"id":"puem-r2-cc-r4-08-08-q1","ordinal":1,"stem":"¿Plan?","options":["Solo sonda nasogástrica indefinida","Reducción manual y alta","Faja y control en un mes","Cirugía urgente con reparación según contaminación y estabilidad; no forzar malla en campo contaminado"],"answer_index":3,"correct_text":"Cirugía urgente con reparación según contaminación y estabilidad; no forzar malla en campo contaminado","explanation":"La obstrucción por hernia requiere cirugía urgente; la malla en contaminación se decide caso por caso. Descomprimir sin resolver perpetúa la obstrucción.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-09","number":59,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 9","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Postbypass, vómitos y dolor epigástrico, TC: estenosis de anastomosis gastroyeyunal.","questions":[{"id":"puem-r2-cc-r4-08-09-q1","ordinal":1,"stem":"¿Manejo inicial?","options":["Dilatación endoscópica con balón","Reoperación inmediata siempre","Solo dieta líquida de por vida","Alta sin seguimiento"],"answer_index":0,"correct_text":"Dilatación endoscópica con balón","explanation":"La estenosis anastomótica postbypass se trata primero con dilatación endoscópica. Reoperar de inicio es excesivo sin intentar endoscopia.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r4-08-10","number":60,"title":"Cirugía bariátrica y metabólica y pared abdominal compleja · caso 10","topic":"Pared Abdominal y Hernias","topicId":"pared","nivel":"R4","context":"Hombre con pérdida de dominio, se propone neumoperitoneo progresivo preoperatorio.","questions":[{"id":"puem-r2-cc-r4-08-10-q1","ordinal":1,"stem":"¿Objetivo?","options":["Solo diagnóstico","Estética","Aumentar la capacidad abdominal y adaptar la pared para lograr cierre sin tensión ni síndrome compartimental","Evitar la cirugía"],"answer_index":2,"correct_text":"Aumentar la capacidad abdominal y adaptar la pared para lograr cierre sin tensión ni síndrome compartimental","explanation":"El neumoperitoneo progresivo expande la cavidad y permite el cierre en pérdida de dominio. No es estético ni evita la cirugía: la prepara.","topic":"Pared Abdominal y Hernias"}]},{"id":"puem-r2-cc-r2-01-01","number":61,"title":"Patología esofágica y ERGE · caso 1","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Hombre de 52 años con pirosis diaria de 3 años, regurgitación nocturna y tos crónica. IMC 33. Toma omeprazol 20 mg con mejoría parcial. Niega disfagia, pérdida de peso o hematemesis. Endoscopia: esofagitis grado B de Los Ángeles, hernia hiatal de 3 cm, sin Barrett. Manometría: EEI hipotensivo, peristalsis conservada. pH-metría: exposición ácida anormal. Quiere dejar el IBP de por vida.","questions":[{"id":"puem-r2-cc-r2-01-01-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Funduplicatura de Toupet laparoscópica","Aumentar IBP a dosis doble de por vida y no operar","Gastrectomía en manga como tratamiento antirreflujo","Funduplicatura de Nissen laparoscópica con crurorrafia"],"answer_index":3,"correct_text":"Funduplicatura de Nissen laparoscópica con crurorrafia","explanation":"Reflujo comprobado por pH-metría, esofagitis, hernia hiatal y buena respuesta parcial a IBP, con peristalsis conservada: es candidato ideal a Nissen 360°, que da el mejor control antirreflujo. La Toupet (A) se reserva para dismotilidad, que aquí no hay; sacrificaría control antirreflujo sin necesidad. Mantener IBP de por vida (B) es válido, pero el paciente lo rechaza y cumple indicación quirúrgica. La manga gástrica (C) empeora el reflujo y está contraindicada como tratamiento antirreflujo; el bypass gástrico sería la opción bariátrica en obesidad con ERGE, no la manga.","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-01-02","number":62,"title":"Patología esofágica y ERGE · caso 2","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Mujer de 45 años con disfagia progresiva a sólidos y líquidos de 8 meses, regurgitación de alimento no digerido, pérdida de 8 kg y tos nocturna. Endoscopia: esófago dilatado con restos alimentarios, unión gastroesofágica estrecha que se abre con presión. Manometría de alta resolución: ausencia de relajación del EEI y aperistalsis, con presurización panesofágica.","questions":[{"id":"puem-r2-cc-r2-01-02-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento con mejor respuesta esperada?","options":["Espasmo esofágico distal; nifedipino de por vida","Esclerodermia; funduplicatura de Nissen","Acalasia tipo II; miotomía de Heller con Dor o POEM","Acalasia tipo I; dilatación neumática como primera opción definitiva"],"answer_index":2,"correct_text":"Acalasia tipo II; miotomía de Heller con Dor o POEM","explanation":"La presurización panesofágica define la acalasia tipo II de Chicago, la de mejor respuesta a cualquier intervención. Heller con funduplicatura parcial o POEM son tratamientos definitivos. La tipo I (D) no es este caso y la dilatación, aunque útil, tiene menor durabilidad que la miotomía. El espasmo distal (A) cursa con contracciones prematuras, no con aperistalsis y presurización panesofágica. La esclerodermia (B) produce EEI hipotensivo y aperistalsis por atrofia, no falta de relajación; el Nissen empeoraría la disfagia.","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-01-03","number":63,"title":"Patología esofágica y ERGE · caso 3","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Hombre de 68 años con disfagia progresiva a sólidos de 4 meses, pérdida de 12 kg, fumador de 40 paquetes-año y consumo alto de alcohol. Endoscopia: masa ulcerada en esófago medio que ocluye parcialmente la luz; biopsia: carcinoma epidermoide. TC: engrosamiento esofágico sin metástasis a distancia, ganglios mediastínicos sospechosos.","questions":[{"id":"puem-r2-cc-r2-01-03-q1","ordinal":1,"stem":"¿Cuál es el siguiente paso más adecuado antes de decidir tratamiento curativo?","options":["Esofagectomía inmediata sin neoadyuvancia","Ultrasonido endoscópico y PET-TC para estadificación completa","Stent esofágico metálico y quimioterapia paliativa","Dilatación endoscópica de la masa para aliviar la disfagia"],"answer_index":1,"correct_text":"Ultrasonido endoscópico y PET-TC para estadificación completa","explanation":"Antes de cualquier plan curativo se necesita estadificación completa: el USE define T y N locorregional y el PET-TC busca metástasis ocultas que cambiarían el plan a paliativo. Operar sin estadificar (A) arriesga una cirugía fútil o insuficiente en enfermedad localmente avanzada, que requiere neoadyuvancia. El stent paliativo (C) se reserva para enfermedad metastásica o no resecable, no antes de estadificar. Dilatar un tumor (D) no trata el cáncer y puede perforar o sangrar.","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-01-04","number":64,"title":"Patología esofágica y ERGE · caso 4","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Hombre de 38 años, 6 horas después de vómito forzado tras ingesta copiosa de alcohol, con dolor torácico súbito, disnea, enfisema subcutáneo cervical y fiebre de 38.5 °C. Radiografía de tórax: ensanchamiento mediastínico y derrame pleural izquierdo.","questions":[{"id":"puem-r2-cc-r2-01-04-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable y la conducta inicial?","options":["Perforación esofágica (Boerhaave); TC con contraste hidrosoluble, ayuno, antibióticos y valoración quirúrgica urgente","Neumotórax espontáneo; sonda pleural sin más estudios","Disección aórtica; control de presión arterial y cirugía","Infarto agudo de miocardio; trombólisis"],"answer_index":0,"correct_text":"Perforación esofágica (Boerhaave); TC con contraste hidrosoluble, ayuno, antibióticos y valoración quirúrgica urgente","explanation":"Vómito forzado seguido de dolor torácico, enfisema subcutáneo, fiebre y derrame pleural izquierdo es la presentación clásica de Boerhaave, perforación del esófago distal izquierdo. La conducta es ayuno, antibióticos de amplio espectro, TC para confirmar y delimitar, y valoración quirúrgica urgente, pues el retraso aumenta marcadamente la mortalidad. El infarto (D) no explica el enfisema ni el derrame. El neumotórax (B) no explica el antecedente de vómito ni el ensanchamiento mediastínico. La disección (C) no produce enfisema subcutáneo cervical ni derrame por perforación esofágica.","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-01-05","number":65,"title":"Patología esofágica y ERGE · caso 5","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Mujer de 60 años con ERGE de 10 años. Endoscopia: segmento de mucosa asalmonada de 4 cm por arriba de la unión gastroesofágica. Biopsias: metaplasia intestinal con células caliciformes, sin displasia.","questions":[{"id":"puem-r2-cc-r2-01-05-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el seguimiento correcto?","options":["Esofagitis eosinofílica; esteroides tópicos","Adenocarcinoma; esofagectomía inmediata","Esófago de Barrett; ablación por radiofrecuencia inmediata sin vigilancia","Esófago de Barrett sin displasia; IBP y vigilancia endoscópica periódica"],"answer_index":3,"correct_text":"Esófago de Barrett sin displasia; IBP y vigilancia endoscópica periódica","explanation":"Mucosa asalmonada más metaplasia intestinal con células caliciformes confirma Barrett sin displasia. El manejo es IBP y vigilancia endoscópica programada (intervalo según guías, habitualmente cada 3-5 años sin displasia). La esofagitis eosinofílica (A) muestra anillos y eosinófilos, no metaplasia intestinal. No hay cáncer (B). La ablación (C) no se indica sin displasia; se reserva para displasia confirmada.","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-01-06","number":66,"title":"Patología esofágica y ERGE · caso 6","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Hombre de 47 años operado de funduplicatura de Nissen hace 6 meses, con disfagia persistente a sólidos y líquidos, incapacidad para eructar, distensión y dolor posprandial. Esofagograma: funduplicatura apretada sin deslizamiento, tránsito lento. Manometría: EEI hipertensivo, peristalsis débil.","questions":[{"id":"puem-r2-cc-r2-01-06-q1","ordinal":1,"stem":"¿Cuál es la complicación más probable y el manejo inicial?","options":["Estenosis péptica; dilatación con balón de inmediato sin estudiar","Recurrencia del reflujo; reiniciar IBP a dosis doble","Funduplicatura demasiado apretada con síndrome de gas-bloat; manejo conservador, dieta blanda y reevaluación; dilatación o revisión quirúrgica si persiste","Acalasia de novo; miotomía de Heller"],"answer_index":2,"correct_text":"Funduplicatura demasiado apretada con síndrome de gas-bloat; manejo conservador, dieta blanda y reevaluación; dilatación o revisión quirúrgica si persiste","explanation":"Disfagia a sólidos y líquidos, incapacidad para eructar y distensión tras Nissen apuntan a funduplicatura demasiado apretada y síndrome de gas-bloat, con EEI hipertensivo en manometría. El manejo inicial es conservador (dieta, tiempo, evitar gas), y si persiste, dilatación endoscópica o revisión quirúrgica. No es recurrencia de reflujo (B): el síntoma dominante es disfagia, no pirosis. No es acalasia de novo (D): la manometría preoperatoria era normal y el cuadro es posquirúrgico mecánico. La estenosis péptica (A) daría disfagia predominante a sólidos y no explicaría el gas-bloat.","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-01-07","number":67,"title":"Patología esofágica y ERGE · caso 7","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Mujer de 70 años con disfagia a sólidos, regurgitación con halitosis, gorgoteo cervical al comer y episodios de aspiración. Esofagograma: divertículo de 3 cm en la pared posterior de la unión faringoesofágica.","questions":[{"id":"puem-r2-cc-r2-01-07-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento indicado?","options":["Acalasia; dilatación neumática","Divertículo de Zenker; diverticulotomía con miotomía del cricofaríngeo","Divertículo epifrénico; funduplicatura de Nissen sola","Anillo de Schatzki; dilatación con bujía"],"answer_index":1,"correct_text":"Divertículo de Zenker; diverticulotomía con miotomía del cricofaríngeo","explanation":"Divertículo posterior en la unión faringoesofágica (triángulo de Killian) con disfagia, halitosis y gorgoteo es el divertículo de Zenker, por pulsión por incoordinación del cricofaríngeo. El tratamiento es la diverticulotomía con miotomía del cricofaríngeo (abierta o endoscópica). El epifrénico (C) es distal, cerca del diafragma, y requiere miotomía del cuerpo esofágico. El anillo de Schatzki (D) es un anillo mucoso distal con disfagia intermitente a sólidos, sin divertículo. La acalasia (A) no produce divertículo cervical.","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-01-08","number":68,"title":"Patología esofágica y ERGE · caso 8","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Hombre de 55 años con pirosis que no mejora con omeprazol 40 mg dos veces al día durante 8 semanas, con adherencia comprobada. Endoscopia normal, sin esofagitis ni Barrett. pH-impedancia con IBP: exposición ácida normal, sin correlación síntoma-reflujo. Manometría normal.","questions":[{"id":"puem-r2-cc-r2-01-08-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable?","options":["Pirosis funcional; no hay reflujo patológico, evitar cirugía antirreflujo","Esofagitis eosinofílica; no se descartó por endoscopia normal","Acalasia incipiente; miotomía profiláctica","ERGE refractaria por reflujo ácido persistente; funduplicatura"],"answer_index":0,"correct_text":"Pirosis funcional; no hay reflujo patológico, evitar cirugía antirreflujo","explanation":"Pirosis persistente con endoscopia normal, pH-impedancia normal y sin correlación síntoma-reflujo define pirosis funcional (trastorno de hipersensibilidad esofágica). Operarlo (D) sería un error: sin reflujo documentado la funduplicatura no aliviará los síntomas. La esofagitis eosinofílica (B) requiere biopsias esofágicas, pero típicamente produce disfagia e impactación, no pirosis aislada con pH normal, y no es la primera explicación aquí. No hay datos de acalasia (C).","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-01-09","number":69,"title":"Patología esofágica y ERGE · caso 9","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Hombre de 62 años con adenocarcinoma de la unión gastroesofágica, cT3N1M0 por USE y PET-TC, buen estado funcional. Comité multidisciplinario recomienda tratamiento curativo.","questions":[{"id":"puem-r2-cc-r2-01-09-q1","ordinal":1,"stem":"¿Cuál es el esquema con mejor evidencia según las guías actuales?","options":["Quimioterapia paliativa sola","Resección endoscópica de la lesión","Esofagectomía sola sin tratamiento previo","Quimiorradioterapia neoadyuvante seguida de esofagectomía"],"answer_index":3,"correct_text":"Quimiorradioterapia neoadyuvante seguida de esofagectomía","explanation":"En adenocarcinoma esofágico localmente avanzado (T3N1), la quimiorradioterapia neoadyuvante (esquema tipo CROSS) seguida de esofagectomía mejora la supervivencia frente a cirugía sola, según NCCN y la evidencia que sustenta Sabiston y Schwartz. La cirugía sola (C) deja mayor riesgo de recurrencia. La quimioterapia paliativa (A) es para enfermedad metastásica. La resección endoscópica (B) solo es curativa en T1a sin invasión submucosa profunda ni ganglios.","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-01-10","number":70,"title":"Patología esofágica y ERGE · caso 10","topic":"Esófago","topicId":"esofago","nivel":"R2","context":"Mujer de 29 años con disfagia intermitente a sólidos, impactación alimentaria en dos ocasiones y antecedente de atopia. Endoscopia: anillos traqueales, surcos longitudinales y exudados blanquecinos. Biopsias: más de 15 eosinófilos por campo de gran aumento.","questions":[{"id":"puem-r2-cc-r2-01-10-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento inicial?","options":["Cáncer esofágico; esofagectomía","Esofagitis eosinofílica; IBP y esteroides tópicos deglutidos, con dilatación si hay estenosis","ERGE grave; funduplicatura de Nissen urgente","Acalasia tipo III; POEM"],"answer_index":1,"correct_text":"Esofagitis eosinofílica; IBP y esteroides tópicos deglutidos, con dilatación si hay estenosis","explanation":"Anillos, surcos, exudados y más de 15 eosinófilos por campo confirman esofagitis eosinofílica, enfermedad inmunoalérgica distinta de la ERGE. El tratamiento es IBP, esteroides tópicos deglutidos (fluticasona o budesonida) y, si hay estenosis, dilatación cuidadosa. El Nissen (C) no trata la inflamación eosinofílica. No hay aperistalsis ni falta de relajación del EEI para acalasia (D), ni masa maligna (A).","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-01","number":71,"title":"Cirugía esofagogástrica avanzada · caso 1","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Hombre 65 años, disfagia a sólidos que progresa a líquidos, pérdida de 10 kg, fumador.","questions":[{"id":"puem-r2-cc-r4-05-01-q1","ordinal":1,"stem":"¿Primer estudio?","options":["Manometría","Endoscopia digestiva alta con biopsia","pH-metría","Solo TC de tórax"],"answer_index":1,"correct_text":"Endoscopia digestiva alta con biopsia","explanation":"Disfagia progresiva + pérdida ponderal es cáncer hasta demostrar lo contrario: endoscopia con biopsia primero. Manometría/pH son para ERGE/acalasia, no para descartar tumor.","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-02","number":72,"title":"Cirugía esofagogástrica avanzada · caso 2","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Mujer 58 años, cáncer esofágico T3N1, ECOG 0.","questions":[{"id":"puem-r2-cc-r4-05-02-q1","ordinal":1,"stem":"¿Plan estándar?","options":["Quimiorradiación neoadyuvante (CROSS) + esofagectomía","Solo quimioterapia","Stent esofágico curativo","Esofagectomía directa"],"answer_index":0,"correct_text":"Quimiorradiación neoadyuvante (CROSS) + esofagectomía","explanation":"Cáncer esofágico localmente avanzado: CROSS + cirugía mejora supervivencia vs. cirugía sola (NCCN). El stent es paliativo, no curativo.","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-03","number":73,"title":"Cirugía esofagogástrica avanzada · caso 3","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Hombre con cáncer gástrico T3, TC sin metástasis.","questions":[{"id":"puem-r2-cc-r4-05-03-q1","ordinal":1,"stem":"¿Estudio antes de decidir cirugía curativa?","options":["Solo CEA","PET siempre obligatorio","Ninguno, a quirófano directo","Laparoscopia estadificadora con citología peritoneal"],"answer_index":3,"correct_text":"Laparoscopia estadificadora con citología peritoneal","explanation":"La laparoscopia estadificadora detecta carcinomatosis/citología positiva oculta en gástrico avanzado y evita laparotomías fútiles. Ir directo arriesga encontrar M1 en quirófano.","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-04","number":74,"title":"Cirugía esofagogástrica avanzada · caso 4","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Paciente con ERGE refractaria, se propone funduplicatura sin manometría.","questions":[{"id":"puem-r2-cc-r4-05-04-q1","ordinal":1,"stem":"¿Por qué es error?","options":["La funduplicatura no necesita evaluación","No lo es, la manometría es innecesaria","Sin manometría puedes funduplicar una acalasia no diagnosticada y empeorar la disfagia","La manometría solo sirve para cáncer"],"answer_index":2,"correct_text":"Sin manometría puedes funduplicar una acalasia no diagnosticada y empeorar la disfagia","explanation":"La funduplicatura sobre una acalasia no diagnosticada causa disfagia grave. Manometría + pH-metría son obligatorias antes de cirugía antirreflujo.","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-05","number":75,"title":"Cirugía esofagogástrica avanzada · caso 5","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Hombre 50 años, acalasia tipo II (Chicago), disfagia y regurgitación.","questions":[{"id":"puem-r2-cc-r4-05-05-q1","ordinal":1,"stem":"¿Tratamiento definitivo?","options":["Funduplicatura Nissen completa sola","Miotomía de Heller + funduplicatura parcial o POEM","Solo inhibidores de bomba de protones","Dilatación con balón como única opción definitiva en jóvenes"],"answer_index":1,"correct_text":"Miotomía de Heller + funduplicatura parcial o POEM","explanation":"La acalasia se trata con miotomía (Heller + parcial o POEM); los IBP no tratan el trastorno motor. La dilatación es opción, pero en jóvenes la miotomía es más duradera.","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-06","number":76,"title":"Cirugía esofagogástrica avanzada · caso 6","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Paciente post-Ivor Lewis día 6, fiebre, débito turbio por drenaje torácico, taquicardia.","questions":[{"id":"puem-r2-cc-r4-05-06-q1","ordinal":1,"stem":"¿Sospecha y conducta?","options":["Fuga anastomótica esofágica; TC con contraste, drenaje, antibiótico, soporte y manejo en equipo (endoscopia/stent/cirugía según caso)","Neumonía sin más; solo antibiótico","Alta","Retirar drenaje"],"answer_index":0,"correct_text":"Fuga anastomótica esofágica; TC con contraste, drenaje, antibiótico, soporte y manejo en equipo (endoscopia/stent/cirugía según caso)","explanation":"La fuga esofágica se sospecha por clínica; requiere imagen, drenaje y manejo multidisciplinario. Atribuirlo solo a neumonía retrasa el control del foco.","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-07","number":77,"title":"Cirugía esofagogástrica avanzada · caso 7","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Mujer con cáncer gástrico difuso, CDH1 positivo, familiar.","questions":[{"id":"puem-r2-cc-r4-05-07-q1","ordinal":1,"stem":"¿Implicación?","options":["Solo dieta","Quimioterapia preventiva para toda la familia","No tiene implicación","Cáncer gástrico difuso hereditario: consejo genético y vigilancia/familia, gastrectomía profiláctica en casos seleccionados"],"answer_index":3,"correct_text":"Cáncer gástrico difuso hereditario: consejo genético y vigilancia/familia, gastrectomía profiláctica en casos seleccionados","explanation":"CDH1 implica síndrome hereditario con alto riesgo; requiere genética, vigilancia y valoración de gastrectomía profiláctica en seleccionados. Ignorarlo deja a la familia sin prevención.","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-08","number":78,"title":"Cirugía esofagogástrica avanzada · caso 8","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Hombre 70 años, perforación esofágica (Boerhaave) de 12 h, contaminación mediastínica, estable.","questions":[{"id":"puem-r2-cc-r4-05-08-q1","ordinal":1,"stem":"¿Manejo?","options":["Stent siempre sin drenaje","Esofagectomía obligatoria","Reparación primaria + drenaje amplio, según tiempo/contaminación y equipo","Solo antibiótico"],"answer_index":2,"correct_text":"Reparación primaria + drenaje amplio, según tiempo/contaminación y equipo","explanation":"Boerhaave temprano y estable: reparación primaria + drenaje es lo habitual; el plan depende de tiempo, contaminación y estabilidad. Solo antibiótico no controla la contaminación mediastínica.","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-09","number":79,"title":"Cirugía esofagogástrica avanzada · caso 9","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Postgastrectomía total, mareo, sudoración y diarrea 30 min tras comer.","questions":[{"id":"puem-r2-cc-r4-05-09-q1","ordinal":1,"stem":"¿Diagnóstico?","options":["Hipoglucemia por insulinoma","Síndrome de dumping; dieta fraccionada, evitar azúcares simples, seguimiento nutricional","Fuga anastomótica","Recurrencia tumoral"],"answer_index":1,"correct_text":"Síndrome de dumping; dieta fraccionada, evitar azúcares simples, seguimiento nutricional","explanation":"Dumping temprano postgastrectomía: síntomas vasomotores y GI tras comer, por vaciamiento rápido. Se maneja con dieta y seguimiento; no es fuga aguda.","topic":"Esófago"}]},{"id":"puem-r2-cc-r4-05-10","number":80,"title":"Cirugía esofagogástrica avanzada · caso 10","topic":"Esófago","topicId":"esofago","nivel":"R4","context":"Cáncer de unión esofagogástrica, centro del tumor 1 cm por encima de la unión.","questions":[{"id":"puem-r2-cc-r4-05-10-q1","ordinal":1,"stem":"¿Clasificación Siewert?","options":["Siewert II","Siewert III","No aplica","Siewert I"],"answer_index":3,"correct_text":"Siewert I","explanation":"Siewert I: tumor 1-5 cm por encima de la unión esofagogástrica (adenocarcinoma esofágico distal). II es en la unión (±1-2 cm) y III por debajo.","topic":"Esófago"}]},{"id":"puem-r2-cc-r2-02-01","number":81,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 1","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Hombre de 58 años con hematemesis de 500 mL, melena, taquicardia de 118 lpm y presión arterial 92/60 mmHg. Hemoglobina 8.2 g/dL, urea 68 mg/dL, creatinina 1.0 mg/dL. Endoscopia: úlcera duodenal posterior de 1.5 cm con vaso visible no sangrante (Forrest IIa).","questions":[{"id":"puem-r2-cc-r2-02-01-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Hemostasia endoscópica combinada (clip o térmico más adrenalina) e IBP intravenoso","Solo inyección de adrenalina y alta en 24 horas","Cirugía inmediata sin intentar endoscopia","Solo IBP oral y observación sin endoscopia terapéutica"],"answer_index":0,"correct_text":"Hemostasia endoscópica combinada (clip o térmico más adrenalina) e IBP intravenoso","explanation":"Forrest IIa (vaso visible) tiene alto riesgo de resangrado y requiere hemostasia endoscópica combinada —adrenalina más clip o método térmico— e IBP intravenoso en dosis altas. La adrenalina sola (B) tiene mayor tasa de resangrado. La cirugía inmediata (C) no es primera línea si la endoscopia puede lograr hemostasia; se reserva para fracaso endoscópico o inestabilidad refractaria. Solo IBP (D) es insuficiente en vaso visible.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r2-02-02","number":82,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 2","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Hombre de 45 años con dolor abdominal súbito en puñalada, abdomen en tabla y taquicardia. Radiografía de tórax de pie: aire libre subdiafragmático. Antecedente de uso crónico de AINE por lumbalgia y tabaquismo.","questions":[{"id":"puem-r2-cc-r2-02-02-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento?","options":["Colecistitis aguda; colecistectomía laparoscópica","Perforación de úlcera péptica; laparotomía o laparoscopia con parche de Graham y lavado peritoneal","Pancreatitis aguda; manejo conservador con ayuno","Apendicitis perforada; apendicectomía"],"answer_index":1,"correct_text":"Perforación de úlcera péptica; laparotomía o laparoscopia con parche de Graham y lavado peritoneal","explanation":"Dolor súbito, abdomen en tabla y aire libre subdiafragmático en un consumidor de AINE es perforación de úlcera péptica hasta demostrar lo contrario. El tratamiento es quirúrgico urgente con cierre con parche de epiplón (Graham) y lavado peritoneal. La colecistitis (A) no produce aire libre ni abdomen en tabla generalizado. La pancreatitis (C) no produce aire libre. La apendicitis (D) inicia periumbilical y migra a fosa iliaca derecha, sin aire libre subdiafragmático típico.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r2-02-03","number":83,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 3","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Mujer de 62 años con úlcera gástrica de 2 cm en curvatura menor, biopsiada. Reporte: adenocarcinoma gástrico bien diferenciado. TC: sin metástasis a distancia, ganglios perigástricos sospechosos. Buen estado funcional.","questions":[{"id":"puem-r2-cc-r2-02-03-q1","ordinal":1,"stem":"¿Cuál es el manejo con intención curativa?","options":["Quimioterapia paliativa sola","IBP de por vida y vigilancia endoscópica","Gastrectomía subtotal con linfadenectomía D2 más quimioterapia perioperatoria","Resección endoscópica de la úlcera sin más tratamiento"],"answer_index":2,"correct_text":"Gastrectomía subtotal con linfadenectomía D2 más quimioterapia perioperatoria","explanation":"Adenocarcinoma gástrico localizado con ganglios sospechosos se trata con gastrectomía oncológica (subtotal si la localización lo permite) con linfadenectomía D2 más quimioterapia perioperatoria tipo FLOT, según NCCN. El IBP (B) no trata el cáncer. La resección endoscópica (D) solo es curativa en cáncer temprano muy seleccionado (T1a, bien diferenciado, sin invasión linfovascular). La quimioterapia paliativa (A) es para enfermedad metastásica o irresecable.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r2-02-04","number":84,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 4","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Hombre de 70 años con vómitos de contenido alimentario retenido de días previos, distensión epigástrica, pérdida de 10 kg y ondas peristálticas visibles. Laboratorios: Cl 88 mEq/L, K 3.0 mEq/L, pH 7.52, bicarbonato 32 mEq/L. Endoscopia: estenosis pilórica fibrótica que no permite el paso del endoscopio.","questions":[{"id":"puem-r2-cc-r2-02-04-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el paso inicial?","options":["Íleo paralítico; procinéticos y alta","Cáncer de páncreas; quimioterapia inmediata","Gastroparesia diabética; metoclopramida sola sin descompresión","Obstrucción pilórica por úlcera; descompresión nasogástrica, corrección hidroelectrolítica e IBP antes de decidir cirugía"],"answer_index":3,"correct_text":"Obstrucción pilórica por úlcera; descompresión nasogástrica, corrección hidroelectrolítica e IBP antes de decidir cirugía","explanation":"Vómitos retenidos, pérdida de peso y alcalosis hipoclorémica hipopotasémica son clásicos de obstrucción pilórica por úlcera cicatrizada. El paso inicial es descompresión nasogástrica, reposición de líquidos y electrolitos e IBP; operar con el paciente deshidratado y alcalótico es peligroso. Después se decide dilatación o cirugía según la fibrosis. El íleo (A) no produce vómitos de días ni alcalosis de este tipo. No hay datos de cáncer de páncreas (B). La gastroparesia (C) no produce estenosis fibrótica que impida el paso del endoscopio.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r2-02-05","number":85,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 5","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Hombre de 50 años con hematemesis tras vómito forzado, hemodinámicamente estable, hemoglobina 13.5 g/dL. Endoscopia: desgarro lineal de 1 cm en la unión gastroesofágica, sin sangrado activo.","questions":[{"id":"puem-r2-cc-r2-02-05-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo más adecuado?","options":["Desgarro de Mallory-Weiss; manejo conservador con IBP y observación","Várices esofágicas rotas; ligadura con bandas urgente","Úlcera duodenal sangrante; cirugía inmediata","Síndrome de Boerhaave; cirugía torácica urgente"],"answer_index":0,"correct_text":"Desgarro de Mallory-Weiss; manejo conservador con IBP y observación","explanation":"Desgarro mucoso en la unión gastroesofágica tras vómito, sin sangrado activo y con paciente estable, es Mallory-Weiss, habitualmente autolimitado. El manejo es conservador con IBP, ayuno breve y observación. Las várices (B) se ven como cordones tortuosos sangrantes en un paciente con hepatopatía. No hay úlcera duodenal (C). Boerhaave (D) es perforación transmural con dolor torácico, enfisema y sepsis, no un desgarro mucoso estable.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r2-02-06","number":86,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 6","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Mujer de 35 años con úlceras duodenales múltiples, refractarias a IBP a dosis altas, diarrea crónica y antecedente de litiasis renal. Gastrina sérica 1,200 pg/mL (normal <100) con pH gástrico 1.0.","questions":[{"id":"puem-r2-cc-r2-02-06-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable?","options":["Úlcera por AINE; suspender AINE y listo","Síndrome de Zollinger-Ellison por gastrinoma; localizar tumor y tratar hipersecreción con IBP a dosis altas","Úlcera por H. pylori; triple terapia estándar","Enfermedad de Crohn gastroduodenal; esteroides"],"answer_index":1,"correct_text":"Síndrome de Zollinger-Ellison por gastrinoma; localizar tumor y tratar hipersecreción con IBP a dosis altas","explanation":"Úlceras múltiples y refractarias, diarrea y gastrina muy elevada con pH gástrico bajo confirman Zollinger-Ellison por gastrinoma, que puede asociarse a neoplasia endocrina múltiple tipo 1 (la litiasis renal sugiere hiperparatiroidismo). El manejo es IBP a dosis altas y localización del gastrinoma (TC, USE, gammagrafía de receptores de somatostatina) para resección. H. pylori (C) no produce gastrina de 1,200. Crohn (D) no produce hipersecreción ácida de este grado. Los AINE (A) no explican la gastrina elevada.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r2-02-07","number":87,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 7","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Hombre de 68 años con melena de 3 días, hemoglobina 7.0 g/dL, estable tras reanimación. Endoscopia: úlcera gástrica de 2 cm con base limpia (Forrest III), sin estigmas de sangrado. Prueba de ureasa positiva para H. pylori.","questions":[{"id":"puem-r2-cc-r2-02-07-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Transfusión hasta hemoglobina de 10 g/dL antes de cualquier decisión","Hemostasia endoscópica urgente con clip aunque la base esté limpia","IBP oral, erradicación de H. pylori, biopsias de la úlcera y egreso temprano con seguimiento","Gastrectomía parcial profiláctica"],"answer_index":2,"correct_text":"IBP oral, erradicación de H. pylori, biopsias de la úlcera y egreso temprano con seguimiento","explanation":"Forrest III (base limpia) tiene bajo riesgo de resangrado y no requiere hemostasia endoscópica. El manejo es IBP oral, erradicación de H. pylori, biopsias de la úlcera gástrica para descartar malignidad y egreso temprano con seguimiento. Hacer hemostasia (B) en base limpia no aporta beneficio. La gastrectomía (D) no está indicada. La transfusión restrictiva (A) no busca llevar la hemoglobina a 10 g/dL en un paciente estable; el umbral es alrededor de 7 g/dL.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r2-02-08","number":88,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 8","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Hombre de 60 años con tumor gástrico submucoso de 4 cm en cuerpo gástrico, biopsia endoscópica no diagnóstica. TC: masa exofítica bien delimitada sin adenopatías ni metástasis. Inmunohistoquímica de biopsia por USE: CD117 positivo.","questions":[{"id":"puem-r2-cc-r2-02-08-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento?","options":["Linfoma gástrico; quimioterapia sola sin cirugía","Leiomioma; observación de por vida sin cirugía","Adenocarcinoma gástrico; gastrectomía total con D2","Tumor del estroma gastrointestinal (GIST); resección quirúrgica con márgenes negativos sin linfadenectomía sistemática"],"answer_index":3,"correct_text":"Tumor del estroma gastrointestinal (GIST); resección quirúrgica con márgenes negativos sin linfadenectomía sistemática","explanation":"Masa submucosa gástrica CD117 positiva es GIST. El tratamiento es la resección quirúrgica con márgenes negativos; no requiere linfadenectomía sistemática porque rara vez metastatiza a ganglios. El adenocarcinoma (C) es epitelial y requiere D2. El linfoma (A) no es CD117 positivo. El leiomioma (B) es CD117 negativo y, aunque benigno, un GIST de 4 cm tiene potencial maligno y debe resecarse.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r2-02-09","number":89,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 9","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Hombre de 75 años con HDA por úlcera duodenal, tratado con hemostasia endoscópica combinada. A las 36 horas presenta de nuevo hematemesis, taquicardia y caída de hemoglobina de 2 g/dL. Segunda endoscopia: resangrado activo del mismo vaso, no controlable. Angiografía no disponible en el hospital.","questions":[{"id":"puem-r2-cc-r2-02-09-q1","ordinal":1,"stem":"¿Cuál es la conducta más adecuada?","options":["Cirugía urgente: duodenotomía, ligadura de la arteria gastroduodenal y vagotomía con piloroplastia según estabilidad","Solo transfusión y esperar a que ceda espontáneamente","Alta con IBP oral","Tercera endoscopia con la misma técnica"],"answer_index":0,"correct_text":"Cirugía urgente: duodenotomía, ligadura de la arteria gastroduodenal y vagotomía con piloroplastia según estabilidad","explanation":"Resangrado tras dos intentos endoscópicos, sin angiografía disponible, es indicación de cirugía urgente. En úlcera duodenal posterior, la técnica es duodenotomía, ligadura del vaso (arteria gastroduodenal) y control ácido con vagotomía y drenaje, o gastrectomía según la estabilidad y la localización. Repetir la misma endoscopia fallida (D) retrasa el control definitivo. Solo transfundir (B) o dar de alta (C) deja un sangrado activo sin control.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r2-02-10","number":90,"title":"Úlcera péptica, hemorragia digestiva alta y patología gástrica quirúrgica · caso 10","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R2","context":"Mujer de 48 años con dispepsia crónica, saciedad temprana y anemia ferropénica. Endoscopia: úlcera gástrica de 3 cm en curvatura menor con bordes irregulares y elevados. Biopsias: adenocarcinoma. La paciente pregunta por qué no se le dio solo tratamiento para úlcera.","questions":[{"id":"puem-r2-cc-r2-02-10-q1","ordinal":1,"stem":"¿Cuál es la explicación correcta?","options":["Porque el tratamiento médico nunca funciona en úlceras gástricas","Porque la endoscopia no sirve para diagnosticar úlcera","Porque las úlceras gástricas con bordes irregulares siempre deben biopsiarse: pueden ser cáncer que simula úlcera benigna","Porque todas las úlceras gástricas son cáncer"],"answer_index":2,"correct_text":"Porque las úlceras gástricas con bordes irregulares siempre deben biopsiarse: pueden ser cáncer que simula úlcera benigna","explanation":"La úlcera gástrica maligna puede simular una úlcera benigna; los bordes irregulares, elevados o nodulares son datos de alarma que obligan a biopsiar. Por eso toda úlcera gástrica se biopsia y se reevalúa su cicatrización. No todas las úlceras gástricas son cáncer (D): la mayoría son benignas por H. pylori o AINE. El tratamiento médico sí funciona en úlceras benignas (A). La endoscopia es el estudio de elección (B).","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-01","number":91,"title":"Cáncer gástrico y de esófago · caso 1","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Hombre de 65 años con dispepsia de 6 meses, pérdida de 10 kg y anemia. Endoscopia: úlcera gástrica de 3 cm en curvatura menor, bordes irregulares.","questions":[{"id":"puem-r2-cc-r3-04-01-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Tratar como úlcera péptica con inhibidor de bomba de protones y repetir endoscopia en 6 meses.","Biopsias múltiples de los bordes y del fondo de la úlcera en la misma endoscopia, porque una úlcera gástrica es cáncer hasta demostrar lo contrario; luego estadificación completa.","Dar antibiótico contra *H. pylori* y dar de alta.","Gastrectomía inmediata sin biopsia."],"answer_index":1,"correct_text":"Biopsias múltiples de los bordes y del fondo de la úlcera en la misma endoscopia, porque una úlcera gástrica es cáncer hasta demostrar lo contrario; luego estadificación completa.","explanation":"Toda úlcera gástrica se biopsia (múltiples tomas de borde y fondo) porque el cáncer gástrico puede simular úlcera benigna; además se estadifica antes de decidir cirugía. **A es incorrecta:** tratar sin biopsia retrasa un cáncer. **C es incorrecta:** el antibiótico no excluye malignidad. **D es incorrecta:** no se opera sin diagnóstico histológico ni estadificación.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-02","number":92,"title":"Cáncer gástrico y de esófago · caso 2","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Paciente con adenocarcinoma gástrico distal T3 N1, sin metástasis, buen estado funcional.","questions":[{"id":"puem-r2-cc-r3-04-02-q1","ordinal":1,"stem":"¿Cuál es el tratamiento con mejor evidencia?","options":["Gastrectomía subtotal con linfadenectomía D2 + quimioterapia perioperatoria (esquema FLOT), discutido en comité.","Gastrectomía total sin linfadenectomía para reducir morbilidad.","Solo quimioterapia, la cirugía no aporta nada.","Resección endoscópica del tumor."],"answer_index":0,"correct_text":"Gastrectomía subtotal con linfadenectomía D2 + quimioterapia perioperatoria (esquema FLOT), discutido en comité.","explanation":"El estándar es resección con D2 más quimio perioperatoria en enfermedad localmente avanzada. **B es incorrecta:** omitir la linfadenectomía D2 subestadifica y empeora el control. **C es incorrecta:** sin cirugía no hay curación en enfermedad resecable. **D es incorrecta:** la resección endoscópica es solo para lesiones tempranas seleccionadas (T1a).","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-03","number":93,"title":"Cáncer gástrico y de esófago · caso 3","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Hombre de 58 años con cáncer de esófago medio, epidermoide, T3 N1, sin metástasis.","questions":[{"id":"puem-r2-cc-r3-04-03-q1","ordinal":1,"stem":"¿Cuál es la secuencia terapéutica correcta?","options":["Radioterapia exclusiva como tratamiento definitivo en todos los casos.","Stent esofágico definitivo.","Esofagectomía inmediata.","Quimiorradioterapia neoadyuvante (esquema CROSS) seguida de esofagectomía con reconstrucción gástrica."],"answer_index":3,"correct_text":"Quimiorradioterapia neoadyuvante (esquema CROSS) seguida de esofagectomía con reconstrucción gástrica.","explanation":"En esófago localmente avanzado, la neoadyuvancia con CROSS seguida de cirugía es el estándar con mejor supervivencia. **C es incorrecta:** operar directo un T3 N1 pierde el beneficio neoadyuvante. **A es incorrecta:** la quimiorradioterapia definitiva es opción en pacientes no quirúrgicos, no el estándar en operables. **B es incorrecta:** el stent es paliativo.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-04","number":94,"title":"Cáncer gástrico y de esófago · caso 4","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Mujer de 70 años con cáncer gástrico, TC sin metástasis visibles. El cirujano propone laparoscopia de estadificación antes de la laparotomía.","questions":[{"id":"puem-r2-cc-r3-04-04-q1","ordinal":1,"stem":"¿Por qué?","options":["Porque así se opera el tumor por laparoscopia.","Es un paso innecesario que solo retrasa la cirugía.","Porque la TC no detecta carcinomatosis peritoneal pequeña ni metástasis hepáticas superficiales; la laparoscopia con lavado peritoneal detecta enfermedad oculta en una proporción importante y evita laparotomías innecesarias.","Porque la laparoscopia sustituye a la biopsia."],"answer_index":2,"correct_text":"Porque la TC no detecta carcinomatosis peritoneal pequeña ni metástasis hepáticas superficiales; la laparoscopia con lavado peritoneal detecta enfermedad oculta en una proporción importante y evita laparotomías innecesarias.","explanation":"La laparoscopia de estadificación es estándar en gástrico avanzado: detecta carcinomatosis oculta que la TC no ve y cambia el plan. **B es incorrecta:** evita cirugías fútiles. **D es incorrecta:** no sustituye la biopsia. **A es incorrecta:** es diagnóstica, no terapéutica en este contexto.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-05","number":95,"title":"Cáncer gástrico y de esófago · caso 5","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Paciente con tumor de la unión gastroesofágica, Siewert II.","questions":[{"id":"puem-r2-cc-r3-04-05-q1","ordinal":1,"stem":"¿Qué implica esta clasificación?","options":["Que el tumor es benigno.","Que el epicentro está en la unión (1 cm por arriba a 2 cm por debajo del cardias) y el abordaje quirúrgico se decide entre esofagectomía y gastrectomía extendida según la extensión; es el tipo más debatido.","Que no necesita cirugía.","Que el tumor es de esófago cervical."],"answer_index":1,"correct_text":"Que el epicentro está en la unión (1 cm por arriba a 2 cm por debajo del cardias) y el abordaje quirúrgico se decide entre esofagectomía y gastrectomía extendida según la extensión; es el tipo más debatido.","explanation":"Siewert II es el tumor de la unión propiamente dicha y su abordaje es el más controvertido; Siewert I es esofágico y III es gástrico. **A, C y D son incorrectas:** es una clasificación anatómica de un cáncer, no de benignidad ni de localización cervical.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-06","number":96,"title":"Cáncer gástrico y de esófago · caso 6","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Hombre de 62 años, 7 días pos-esofagectomía, con fiebre, taquicardia, dolor torácico y salida de contenido por el drenaje cervical.","questions":[{"id":"puem-r2-cc-r3-04-06-q1","ordinal":1,"stem":"¿Cuál es la sospecha principal?","options":["Fuga de la anastomosis esofagogástrica, la complicación más temida de la esofagectomía; requiere TC con contraste oral, antibióticos, drenaje y valoración de reintervención o manejo endoscópico según el caso.","Es normal y no requiere estudios.","Tromboembolia pulmonar.","Neumonía posoperatoria."],"answer_index":0,"correct_text":"Fuga de la anastomosis esofagogástrica, la complicación más temida de la esofagectomía; requiere TC con contraste oral, antibióticos, drenaje y valoración de reintervención o manejo endoscópico según el caso.","explanation":"El cuadro es clásico de fuga anastomótica esofágica; su mortalidad es alta y el diagnóstico no debe demorarse. **D es incorrecta:** la neumonía no da salida de contenido por el drenaje cervical. **B es incorrecta:** nunca es normal. **C es incorrecta:** la TEP no explica el drenaje.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-07","number":97,"title":"Cáncer gástrico y de esófago · caso 7","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Paciente con cáncer gástrico difuso, células en anillo de sello, con carcinomatosis peritoneal confirmada.","questions":[{"id":"puem-r2-cc-r3-04-07-q1","ordinal":1,"stem":"¿Cuál es el pronóstico y la intención del tratamiento?","options":["No requiere tratamiento porque el difuso no responde a nada.","Gastrectomía profiláctica.","Pronóstico favorable y cirugía curativa con D2.","Mal pronóstico con diseminación peritoneal; la intención es sistémica/paliativa (quimio ± inmunoterapia según biomarcadores) y control de síntomas; la cirugía curativa no es posible con carcinomatosis diseminada."],"answer_index":3,"correct_text":"Mal pronóstico con diseminación peritoneal; la intención es sistémica/paliativa (quimio ± inmunoterapia según biomarcadores) y control de síntomas; la cirugía curativa no es posible con carcinomatosis diseminada.","explanation":"El gástrico difuso con carcinomatosis es enfermedad sistémica de mal pronóstico; la cirugía mayor no cura y solo se considera paliación sintomática. **C es incorrecta:** la D2 no cura la carcinomatosis. **A es incorrecta:** sí hay tratamiento sistémico. **B es incorrecta:** no hay nada que prevenir quirúrgicamente aquí.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-08","number":98,"title":"Cáncer gástrico y de esófago · caso 8","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Mujer de 55 años con lesión gástrica de 1.5 cm, adenocarcinoma intramucoso (T1a), sin ulceración, diferenciada, ecoendoscopia sin ganglios sospechosos.","questions":[{"id":"puem-r2-cc-r3-04-08-q1","ordinal":1,"stem":"¿Qué opción es correcta?","options":["No hacer nada.","Gastrectomía total obligatoria.","Resección endoscópica (ESD) como opción curativa en lesión temprana seleccionada, con vigilancia endoscópica estricta, porque el riesgo ganglionar es mínimo.","Quimioterapia neoadyuvante."],"answer_index":2,"correct_text":"Resección endoscópica (ESD) como opción curativa en lesión temprana seleccionada, con vigilancia endoscópica estricta, porque el riesgo ganglionar es mínimo.","explanation":"Las lesiones T1a diferenciadas, pequeñas y sin ulceración ni ganglios pueden curarse con resección endoscópica; la gastrectomía sería sobretratamiento. **B es incorrecta:** es excesiva para T1a seleccionado. **D es incorrecta:** no hay indicación de neoadyuvancia. **A es incorrecta:** es un cáncer que requiere tratamiento.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-09","number":99,"title":"Cáncer gástrico y de esófago · caso 9","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Paciente con cáncer de esófago inferior, adenocarcinoma sobre Barrett, T2 N0. La ecoendoscopia confirma T2.","questions":[{"id":"puem-r2-cc-r3-04-09-q1","ordinal":1,"stem":"¿Por qué no basta la resección endoscópica?","options":["Porque la resección endoscópica siempre es mejor.","Porque T2 invade la muscular propia, con riesgo ganglionar significativo; la resección endoscópica es para T1a (mucosa) seleccionado, no para T2.","Porque el Barrett lo impide siempre.","Porque el paciente es mayor."],"answer_index":1,"correct_text":"Porque T2 invade la muscular propia, con riesgo ganglionar significativo; la resección endoscópica es para T1a (mucosa) seleccionado, no para T2.","explanation":"La profundidad T2 implica riesgo ganglionar que la resección endoscópica no trata; el límite de la endoscopia curativa es la mucosa (T1a) y casos seleccionados de T1b. **A es incorrecta:** la endoscopia no es mejor en T2. **C es incorrecta:** el Barrett por sí solo no contraindica endoscopia en lesiones tempranas. **D es irrelevante.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r3-04-10","number":100,"title":"Cáncer gástrico y de esófago · caso 10","topic":"Estómago y Duodeno","topicId":"estomago","nivel":"R3","context":"Hombre de 68 años pos-gastrectomía total por cáncer, 1 año después, con fatiga, parestesias y anemia macrocítica.","questions":[{"id":"puem-r2-cc-r3-04-10-q1","ordinal":1,"stem":"¿Cuál es la causa más probable?","options":["Déficit de hierro por sangrado.","Infección por *H. pylori*.","Recurrencia tumoral.","Déficit de vitamina B12 por ausencia de factor intrínseco tras gastrectomía total; requiere suplementación de por vida."],"answer_index":3,"correct_text":"Déficit de vitamina B12 por ausencia de factor intrínseco tras gastrectomía total; requiere suplementación de por vida.","explanation":"Sin estómago no hay factor intrínseco: el déficit de B12 es esperado y se previene con suplementación de por vida; la anemia macrocítica con parestesias es clásica. **C es incorrecta:** la recurrencia no explica este cuadro hematoneurológico. **A es incorrecta:** el déficit de hierro da anemia microcítica. **B es incorrecta:** sin estómago, *H. pylori* no explica el cuadro.","topic":"Estómago y Duodeno"}]},{"id":"puem-r2-cc-r4-11-01","number":101,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 1","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Hombre postcolectomía día 4, fiebre 39 °C, hipotensión, lactato 4, abdomen doloroso.","questions":[{"id":"puem-r2-cc-r4-11-01-q1","ordinal":1,"stem":"¿Prioridad?","options":["Alta","Esperar cultivos 48 h","Surviving Sepsis: cultivos, antibiótico en la primera hora en shock, reanimación y control del foco (TC/drenaje/reoperación)","Solo antipiréticos"],"answer_index":2,"correct_text":"Surviving Sepsis: cultivos, antibiótico en la primera hora en shock, reanimación y control del foco (TC/drenaje/reoperación)","explanation":"El shock séptico postoperatorio exige antibiótico precoz y control del foco; esperar cultivos mata. El control del foco (drenaje o reoperación) es tan importante como el antibiótico.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r4-11-02","number":102,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 2","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Mujer con fístula enterocutánea de alto gasto (800 mL/día), desnutrición, sepsis controlada.","questions":[{"id":"puem-r2-cc-r4-11-02-q1","ordinal":1,"stem":"¿Plan (SNAP)?","options":["Solo octreótido y alta","Cerrar la fístula con sutura en la cama","Cirugía definitiva inmediata","Optimizar: reposición hidroelectrolítica, nutrición, protección cutánea, definir anatomía y cirugía diferida 6-12 semanas si no cierra"],"answer_index":3,"correct_text":"Optimizar: reposición hidroelectrolítica, nutrición, protección cutánea, definir anatomía y cirugía diferida 6-12 semanas si no cierra","explanation":"SNAP: primero sepsis y nutrición, luego anatomía y plan diferido. Operar en caliente con desnutrición fracasa; el octreótido solo no cierra una fístula con causa persistente.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r4-11-03","number":103,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 3","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Paciente con fístula que no cierra, antecedente de radioterapia pélvica y esteroides.","questions":[{"id":"puem-r2-cc-r4-11-03-q1","ordinal":1,"stem":"¿Qué explica la persistencia?","options":["FRIENDS: radiación y esteroides impiden cicatrización, entre otros factores","Mala suerte sin causa","Solo falta de antibiótico","La fístula siempre cierra sola"],"answer_index":0,"correct_text":"FRIENDS: radiación y esteroides impiden cicatrización, entre otros factores","explanation":"FRIENDS (cuerpo extraño, radiación, infección, epitelización, neoplasia, obstrucción distal, esteroides) explica fístulas que no cierran. Ignorar la causa perpetúa la fístula.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r4-11-04","number":104,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 4","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Hombre grave en UCI, NRS-2002 alto, íleo prolongado.","questions":[{"id":"puem-r2-cc-r4-11-04-q1","ordinal":1,"stem":"¿Nutrición?","options":["Ayuno hasta que el íleo resuelva por completo","Nutrición enteral precoz si es posible (trófica/progresiva) y parenteral solo si la enteral es imposible/prolongada","Sobrealimentación parenteral inmediata","Sin nutrición una semana"],"answer_index":1,"correct_text":"Nutrición enteral precoz si es posible (trófica/progresiva) y parenteral solo si la enteral es imposible/prolongada","explanation":"La nutrición enteral precoz protege la mucosa y mejora pronóstico en el grave; la parenteral es segunda opción. El ayuno prolongado y la sobrealimentación empeoran.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r4-11-05","number":105,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 5","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Postoperatorio con infección de sitio quirúrgico órgano-espacio, colección en TC.","questions":[{"id":"puem-r2-cc-r4-11-05-q1","ordinal":1,"stem":"¿Manejo?","options":["Alta","Solo antibiótico oral","Drenaje percutáneo de la colección + antibiótico y control del foco","Retirar puntos sin más"],"answer_index":2,"correct_text":"Drenaje percutáneo de la colección + antibiótico y control del foco","explanation":"La colección órgano-espacio requiere drenaje + antibiótico; solo antibiótico no drena el foco. El drenaje percutáneo es primera opción si es accesible.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r4-11-06","number":106,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 6","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Paciente con sepsis abdominal, TC: colección accesible percutáneamente, estable.","questions":[{"id":"puem-r2-cc-r4-11-06-q1","ordinal":1,"stem":"¿Control del foco?","options":["Solo antibiótico","Esperar a que se rompa sola","Laparotomía obligatoria siempre","Drenaje percutáneo guiado por imagen como control del foco mínimamente invasivo"],"answer_index":3,"correct_text":"Drenaje percutáneo guiado por imagen como control del foco mínimamente invasivo","explanation":"El control del foco puede ser percutáneo en colecciones accesibles y paciente estable (WSES). La laparotomía no es obligatoria si el drenaje controla el foco.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r4-11-07","number":107,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 7","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Mujer con dehiscencia de herida y evisceración parcial.","questions":[{"id":"puem-r2-cc-r4-11-07-q1","ordinal":1,"stem":"¿Conducta?","options":["Quirófano: lavado, valoración de viabilidad y cierre/reparación según contaminación","Solo curación local","Alta con faja","Reducir en la cama y vendar"],"answer_index":0,"correct_text":"Quirófano: lavado, valoración de viabilidad y cierre/reparación según contaminación","explanation":"La evisceración exige quirófano para valorar viabilidad y reparar; reducir en la cama sin explorar arriesga intestino comprometido.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r4-11-08","number":108,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 8","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Hombre con fuga anastomótica grado C (ISREC), peritonitis.","questions":[{"id":"puem-r2-cc-r4-11-08-q1","ordinal":1,"stem":"¿Manejo?","options":["Solo antibiótico","Reoperación: lavado, desmontaje de anastomosis y estoma (control del foco)","Drenaje percutáneo exclusivo","Observación"],"answer_index":1,"correct_text":"Reoperación: lavado, desmontaje de anastomosis y estoma (control del foco)","explanation":"La fuga grado C con peritonitis exige reoperación y desmontaje; el drenaje percutáneo no controla peritonitis generalizada.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r4-11-09","number":109,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 9","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Paciente séptico, procalcitonina baja.","questions":[{"id":"puem-r2-cc-r4-11-09-q1","ordinal":1,"stem":"¿Interpretación?","options":["Alta","Descarta sepsis por completo","La procalcitonina apoya pero no diagnostica ni descarta sepsis por sí sola; manda la clínica y el SOFA","No se necesitan cultivos"],"answer_index":2,"correct_text":"La procalcitonina apoya pero no diagnostica ni descarta sepsis por sí sola; manda la clínica y el SOFA","explanation":"La procalcitonina es apoyo, no regla diagnóstica; la sepsis se diagnostica por clínica + disfunción orgánica (Sepsis-3/SOFA). Negar sepsis por un marcador es peligroso.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r4-11-10","number":110,"title":"Complicaciones quirúrgicas complejas, sepsis, fístulas y nutrición · caso 10","topic":"Intestino Delgado","topicId":"delgado","nivel":"R4","context":"Hombre con fístula de bajo gasto que cierra con manejo conservador.","questions":[{"id":"puem-r2-cc-r4-11-10-q1","ordinal":1,"stem":"¿Seguimiento?","options":["Vigilar nutrición, electrolitos, piel y causa; seguimiento hasta cierre completo y rehabilitación","Cirugía profiláctica","Solo dieta líquida de por vida","Alta sin seguimiento"],"answer_index":0,"correct_text":"Vigilar nutrición, electrolitos, piel y causa; seguimiento hasta cierre completo y rehabilitación","explanation":"Incluso la fístula que cierra exige seguimiento nutricional y de la causa hasta el cierre completo. Dar de alta sin seguimiento pierde recurrencia y desnutrición.","topic":"Intestino Delgado"}]},{"id":"puem-r2-cc-r1-12-01","number":111,"title":"Abdomen agudo y apendicitis aguda · caso 1","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Hombre de 22 años con dolor periumbilical de 12 h que migró a fosa ilíaca derecha, anorexia, náusea, fiebre 38 °C, McBurney positivo, leucocitos 14,000.","questions":[{"id":"puem-r2-cc-r1-12-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable y el estudio?","options":["Enfermedad inflamatoria pélvica.","Gastroenteritis; no necesita imagen.","Apendicitis aguda; Alvarado alto, TC de abdomen con contraste (o ecografía según disponibilidad) y apendicectomía.","Litiasis ureteral; EGO."],"answer_index":2,"correct_text":"Apendicitis aguda; Alvarado alto, TC de abdomen con contraste (o ecografía según disponibilidad) y apendicectomía.","explanation":"la secuencia clásica (migración, anorexia, náusea después del dolor, McBurney, leucocitosis) es apendicitis; el Alvarado es alto y la TC confirma y descarta diferenciales. B es incorrecta: la gastroenteritis da diarrea y el dolor no migra de esta forma. D es incorrecta: la litiasis da dolor cólico irradiado a ingle y hematuria. A es incorrecta: es un hombre joven, no es el cuadro de EIP.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r1-12-02","number":112,"title":"Abdomen agudo y apendicitis aguda · caso 2","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Mujer de 28 años con dolor en fosa ilíaca derecha, fiebre, leucocitosis, con flujo vaginal y dolor a la movilización cervical.","questions":[{"id":"puem-r2-cc-r1-12-02-q1","ordinal":1,"stem":"¿Qué debe descartarse antes de operar por apendicitis?","options":["Litiasis ureteral solamente.","Colecistitis.","Nada; operar de inmediato.","Enfermedad inflamatoria pélvica y embarazo ectópico (β-hCG, EGO, exploración ginecológica, ecografía pélvica)."],"answer_index":3,"correct_text":"Enfermedad inflamatoria pélvica y embarazo ectópico (β-hCG, EGO, exploración ginecológica, ecografía pélvica).","explanation":"en la mujer en edad fértil con dolor en FID, la EIP y el embarazo ectópico son diferenciales que cambian la conducta; hay que descartarlos con β-hCG, exploración y ecografía antes de operar. C es incorrecta: operar sin descartar EIP/ectópico es un error. A es incorrecta: la litiasis no explica el flujo ni el dolor cervical. B es incorrecta: la colecistitis es en hipocondrio derecho, no FID.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r1-12-03","number":113,"title":"Abdomen agudo y apendicitis aguda · caso 3","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Hombre de 65 años con dolor en fosa ilíaca derecha de 5 días, masa palpable dolorosa, fiebre, leucocitos 16,000, TC con plastrón apendicular y absceso de 6 cm, sin peritonitis difusa, estable.","questions":[{"id":"puem-r2-cc-r1-12-03-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Drenaje percutáneo del absceso + antibiótico y apendicectomía de intervalo en casos seleccionados; cirugía inmediata si hay peritonitis difusa o inestabilidad.","Solo antibiótico oral y alta.","Observación sin antibiótico.","Apendicectomía de urgencia de inmediato."],"answer_index":0,"correct_text":"Drenaje percutáneo del absceso + antibiótico y apendicectomía de intervalo en casos seleccionados; cirugía inmediata si hay peritonitis difusa o inestabilidad.","explanation":"el plastrón/absceso en paciente estable sin peritonitis difusa se maneja con drenaje percutáneo + antibiótico e intervalo; la cirugía inmediata en un plastrón inflamado es técnicamente difícil y con más complicaciones. D es incorrecta: no es la conducta en plastrón estable. B es incorrecta: el absceso de 6 cm requiere drenaje, no solo antibiótico oral. C es incorrecta: requiere tratamiento activo.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r1-12-04","number":114,"title":"Abdomen agudo y apendicitis aguda · caso 4","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Mujer de 30 años, embarazada de 20 semanas, con dolor en fosa ilíaca derecha, náusea, leucocitos 13,000, ecografía no concluyente.","questions":[{"id":"puem-r2-cc-r1-12-04-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["No operar por el embarazo.","Operar sin retraso si la sospecha es alta (laparoscopia con técnica adecuada; RM si la ecografía no concluye y el diagnóstico es dudoso, sin retrasar la cirugía si hay alta sospecha).","Dar antibiótico y esperar.","Esperar al parto para operar."],"answer_index":1,"correct_text":"Operar sin retraso si la sospecha es alta (laparoscopia con técnica adecuada; RM si la ecografía no concluye y el diagnóstico es dudoso, sin retrasar la cirugía si hay alta sospecha).","explanation":"la apendicitis en el embarazo se opera sin retraso: la perforación pone en riesgo a la madre y al feto más que la cirugía; la RM ayuda si el diagnóstico es dudoso, pero no debe retrasar la cirugía con alta sospecha. D es incorrecta: esperar al parto es peligroso. A es incorrecta: el embarazo no contraindica la cirugía. C es incorrecta: el antibiótico solo no trata la apendicitis.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r1-12-05","number":115,"title":"Abdomen agudo y apendicitis aguda · caso 5","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Niño de 8 años con dolor abdominal, fiebre, vómito, dolor en fosa ilíaca derecha, leucocitos 15,000, PCR alta.","questions":[{"id":"puem-r2-cc-r1-12-05-q1","ordinal":1,"stem":"¿Cuál es el estudio inicial de elección?","options":["Ningún estudio; operar por clínica.","TC de abdomen con contraste.","Ecografía abdominal (apéndice no compresible >6 mm), sin radiación, de primera línea en niños.","Radiografía simple."],"answer_index":2,"correct_text":"Ecografía abdominal (apéndice no compresible >6 mm), sin radiación, de primera línea en niños.","explanation":"en niños la ecografía es el estudio inicial (sin radiación, buena sensibilidad si se ve el apéndice); la TC se reserva si la ecografía no concluye. B es incorrecta: la TC es el estudio en el adulto, no el inicial en el niño por la radiación. D es incorrecta: la radiografía no diagnostica apendicitis. A es incorrecta: la imagen ayuda cuando el diagnóstico no es claro, sobre todo en niños.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r1-12-06","number":116,"title":"Abdomen agudo y apendicitis aguda · caso 6","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Hombre de 40 años con dolor en fosa ilíaca derecha, Alvarado 3, sin fiebre, leucocitos normales, sin irritación peritoneal.","questions":[{"id":"puem-r2-cc-r1-12-06-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["TC de inmediato y operar aunque sea negativa.","Dar antibiótico de amplio espectro.","Apendicectomía de urgencia.","Bajo riesgo: observación, reevaluación, EGO y β-hCG si aplica, y alta con indicaciones de alarma si mejora; imagen si empeora o el diagnóstico es dudoso."],"answer_index":3,"correct_text":"Bajo riesgo: observación, reevaluación, EGO y β-hCG si aplica, y alta con indicaciones de alarma si mejora; imagen si empeora o el diagnóstico es dudoso.","explanation":"Alvarado <4 es bajo riesgo: observación y reevaluación es lo adecuado; operar o dar TC/antibiótico de inmediato es excesivo. C es incorrecta: no hay indicación quirúrgica con Alvarado 3. A es incorrecta: la TC no se hace \"para operar aunque sea negativa\". B es incorrecta: no hay indicación de antibiótico de amplio espectro.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r1-12-07","number":117,"title":"Abdomen agudo y apendicitis aguda · caso 7","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Hombre de 70 años con apendicitis aguda operada; la histopatología reporta adenocarcinoma del apéndice.","questions":[{"id":"puem-r2-cc-r1-12-07-q1","ordinal":1,"stem":"¿Qué se debe hacer?","options":["Derivar a oncología/cirugía oncológica para estadificación y valorar hemicolectomía derecha según el tipo y la extensión; en el anciano, descartar neoplasia es parte del seguimiento.","Dar antibiótico por un mes.","Repetir la apendicectomía.","Nada; la apendicectomía lo curó."],"answer_index":0,"correct_text":"Derivar a oncología/cirugía oncológica para estadificación y valorar hemicolectomía derecha según el tipo y la extensión; en el anciano, descartar neoplasia es parte del seguimiento.","explanation":"el adenocarcinoma apendicular requiere estadificación y valoración oncológica (a menudo hemicolectomía derecha); la apendicectomía sola no es el tratamiento oncológico. D es incorrecta: subestima el hallazgo. B es incorrecta: el antibiótico no trata el cáncer. C es incorrecta: repetir la apendicectomía no es el tratamiento.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r1-12-08","number":118,"title":"Abdomen agudo y apendicitis aguda · caso 8","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Mujer de 25 años con dolor en fosa ilíaca derecha, vómito que precedió al dolor, diarrea, fiebre, sin irritación peritoneal.","questions":[{"id":"puem-r2-cc-r1-12-08-q1","ordinal":1,"stem":"¿Qué diagnóstico es más probable que apendicitis?","options":["Apendicitis aguda.","Gastroenteritis / adenitis mesentérica; el vómito y la diarrea antes del dolor y la ausencia de irritación peritoneal orientan fuera de apendicitis.","Embarazo ectópico.","Colecistitis."],"answer_index":1,"correct_text":"Gastroenteritis / adenitis mesentérica; el vómito y la diarrea antes del dolor y la ausencia de irritación peritoneal orientan fuera de apendicitis.","explanation":"en apendicitis el dolor precede al vómito y hay anorexia e irritación peritoneal; el vómito/diarrea que preceden al dolor con ausencia de irritación orientan a gastroenteritis/adenitis. A es incorrecta: la secuencia es atípica para apendicitis. C es incorrecta: no hay datos de ectópico (amenorrea, sangrado). D es incorrecta: la colecistitis es en hipocondrio derecho.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r1-12-09","number":119,"title":"Abdomen agudo y apendicitis aguda · caso 9","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Hombre de 30 años con apendicitis no complicada, operado por laparoscopia, sin perforación.","questions":[{"id":"puem-r2-cc-r1-12-09-q1","ordinal":1,"stem":"¿Cuánto antibiótico postoperatorio necesita?","options":["Antibiótico de por vida.","7 días de antibiótico IV.","Profilaxis preoperatoria (dosis única) y no prolongar antibiótico terapéutico si no hubo perforación ni peritonitis.","14 días oral."],"answer_index":2,"correct_text":"Profilaxis preoperatoria (dosis única) y no prolongar antibiótico terapéutico si no hubo perforación ni peritonitis.","explanation":"en apendicitis no complicada sin perforación, la profilaxis preoperatoria es suficiente; prolongar el antibiótico no reduce infecciones y genera resistencia. B es incorrecta: 7 días IV es excesivo. D es incorrecta: 14 días oral no está indicado. A es incorrecta: no hay indicación.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r1-12-10","number":120,"title":"Abdomen agudo y apendicitis aguda · caso 10","topic":"Colon y Apéndice","topicId":"colon","nivel":"R1","context":"Paciente con apendicitis aguda y fecalito visible en la TC.","questions":[{"id":"puem-r2-cc-r1-12-10-q1","ordinal":1,"stem":"¿Qué implica el fecalito?","options":["Mayor riesgo de complicación (gangrena/perforación) y de fracaso del manejo no operatorio; orienta a apendicectomía.","Que no necesita cirugía.","Que es una apendicitis crónica.","Nada; es un hallazgo incidental."],"answer_index":0,"correct_text":"Mayor riesgo de complicación (gangrena/perforación) y de fracaso del manejo no operatorio; orienta a apendicectomía.","explanation":"el fecalito se asocia a mayor riesgo de complicación y a fracaso del tratamiento antibiótico sin cirugía; es un dato que orienta a operar. D es incorrecta: no es incidental. B es incorrecta: es lo contrario. C es incorrecta: no define cronicidad.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-01","number":121,"title":"Apendicitis aguda y abdomen agudo · caso 1","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 24 años con dolor periumbilical de 10 horas que migró a la fosa ilíaca derecha, anorexia, náusea y un vómito. Fiebre de 38.1 °C. Exploración: dolor en fosa ilíaca derecha, McBurney positivo, rebote leve, sin rigidez generalizada. Laboratorio: leucocitos 13,800/µL con neutrofilia de 82%, PCR 45 mg/L. Ultrasonido no concluyente por gas.","questions":[{"id":"puem-r2-cc-r2-06-01-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Tomografía contrastada para confirmar y apendicectomía laparoscópica temprana.","Antibiótico oral y egreso con seguimiento en 48 horas.","Colonoscopia urgente.","Observación por 72 horas sin estudios."],"answer_index":0,"correct_text":"Tomografía contrastada para confirmar y apendicectomía laparoscópica temprana.","explanation":"El cuadro es clásico de apendicitis aguda: migración del dolor, anorexia, náusea, fiebre baja y leucocitosis con neutrofilia, con McBurney positivo. El ultrasonido no concluyente no descarta la enfermedad. La tomografía contrastada es el estudio más sensible y específico en adultos y, confirmada la apendicitis, procede la apendicectomía laparoscópica temprana dentro de 24 horas. B es incorrecta porque el manejo conservador con antibiótico oral y egreso en un caso típico con leucocitosis y rebote deja el riesgo de perforación y no es el estándar en un joven operable. C es incorrecta porque la colonoscopia no diagnostica apendicitis aguda y retrasaría la cirugía. D es incorrecta porque observar 72 horas sin estudios en apendicitis probable aumenta el riesgo de perforación.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-02","number":122,"title":"Apendicitis aguda y abdomen agudo · caso 2","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 28 años, embarazada de 18 semanas, con dolor en fosa ilíaca derecha de 14 horas, náusea y fiebre de 38 °C. Exploración: dolor en fosa ilíaca derecha con defensa leve. Laboratorio: leucocitos 12,500/µL. Ultrasonido: apéndice no compresible de 8 mm con fecalito, sin líquido libre. Prueba de embarazo positiva ya conocida.","questions":[{"id":"puem-r2-cc-r2-06-02-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Manejo conservador con antibiótico y diferir la cirugía hasta después del parto.","Apendicectomía laparoscópica temprana sin retraso.","Tomografía contrastada para confirmar antes de operar.","Egreso con analgésicos porque la leucocitosis es normal en el embarazo."],"answer_index":1,"correct_text":"Apendicectomía laparoscópica temprana sin retraso.","explanation":"La apendicitis en el embarazo se opera sin retraso: el ultrasonido ya muestra un apéndice no compresible de 8 mm con fecalito, compatible con apendicitis, y el retraso aumenta la perforación, la peritonitis y el riesgo de pérdida fetal. La apendicectomía laparoscópica es segura en cualquier trimestre. A es incorrecta porque diferir la cirugía hasta el parto expondría a la paciente a perforación y sepsis durante meses. C es incorrecta porque la tomografía implica radiación y ya hay un ultrasonido diagnóstico; la resonancia sería la alternativa si el ultrasonido no fuera concluyente, no la tomografía de primera línea. D es incorrecta porque, aunque la leucocitosis puede elevarse en el embarazo, aquí se acompaña de dolor localizado, defensa, fiebre y un apéndice patológico por imagen.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-03","number":123,"title":"Apendicitis aguda y abdomen agudo · caso 3","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 67 años con dolor en fosa ilíaca derecha de 5 días, fiebre de 38.5 °C, masa dolorosa palpable en fosa ilíaca derecha, sin signos de peritonitis generalizada. Laboratorio: leucocitos 16,000/µL, PCR 180 mg/L. Tomografía: masa inflamatoria en fosa ilíaca derecha con apéndice perforado contenido y absceso de 5 cm, sin líquido libre generalizado.","questions":[{"id":"puem-r2-cc-r2-06-03-q1","ordinal":1,"stem":"¿Cuál es el manejo inicial más adecuado?","options":["Egreso con antibiótico oral.","Apendicectomía laparoscópica inmediata con resección de ciego.","Antibiótico intravenoso, ayuno, líquidos y drenaje percutáneo del absceso, con apendicectomía de intervalo a las 6-8 semanas.","Colonoscopia urgente para descartar cáncer."],"answer_index":2,"correct_text":"Antibiótico intravenoso, ayuno, líquidos y drenaje percutáneo del absceso, con apendicectomía de intervalo a las 6-8 semanas.","explanation":"Es un plastrón apendicular con absceso contenido de 5 días de evolución, sin peritonitis generalizada. El manejo inicial es conservador: antibiótico intravenoso, ayuno, líquidos y drenaje percutáneo del absceso si es accesible, con apendicectomía de intervalo a las 6-8 semanas cuando la inflamación se resuelva. Operar de inicio en un plastrón aumenta el riesgo de resección intestinal innecesaria, lesión y complicaciones. B es incorrecta por esa razón: la cirugía inmediata en un plastrón maduro es más mórbida y puede obligar a una resección mayor. D es incorrecta porque la colonoscopia no es urgente en el cuadro agudo; el estudio del colon se hace después de resolver el plastrón, especialmente en mayores de 40 años. A es incorrecta porque un absceso de 5 cm con fiebre y leucocitosis requiere manejo hospitalario con antibiótico intravenoso y drenaje, no egreso con antibiótico oral.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-04","number":124,"title":"Apendicitis aguda y abdomen agudo · caso 4","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 22 años con dolor en fosa ilíaca derecha de 8 horas, náusea y fiebre de 37.8 °C. Exploración: dolor en fosa ilíaca derecha, rebote leve. Laboratorio: leucocitos 11,000/µL, examen de orina con 15 leucocitos por campo y nitritos negativos, prueba de embarazo negativa. Tomografía: apéndice normal de 5 mm, sin engrosamiento de grasa, ovario derecho con quiste de 4 cm sin torsión ni líquido libre.","questions":[{"id":"puem-r2-cc-r2-06-04-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable?","options":["Embarazo ectópico roto.","Apendicitis aguda.","Infección de vías urinarias.","Quiste ovárico sintomático / dolor ovulatorio como causa del cuadro, con apendicitis descartada por imagen."],"answer_index":3,"correct_text":"Quiste ovárico sintomático / dolor ovulatorio como causa del cuadro, con apendicitis descartada por imagen.","explanation":"La tomografía muestra un apéndice normal y un quiste ovárico de 4 cm sin torsión, que explica el dolor en fosa ilíaca derecha en una mujer joven. La piuria leve con nitritos negativos es inespecífica y puede deberse a contigüidad, sin el cuadro de infección urinaria. B es incorrecta porque el apéndice es normal por tomografía, el estudio más sensible, y no hay engrosamiento de grasa ni fecalito. C es incorrecta porque no hay disuria, polaquiuria ni nitritos positivos, y la piuria aislada no confirma infección urinaria. A es incorrecta porque la prueba de embarazo es negativa y no hay líquido libre ni masa anexial compatible con ectópico roto.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-05","number":125,"title":"Apendicitis aguda y abdomen agudo · caso 5","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 72 años, diabético, con dolor abdominal difuso de 2 días, fiebre de 38.2 °C, vómito y distensión. Exploración: dolor generalizado sin localización clara, defensa leve, ruidos intestinales disminuidos. Laboratorio: leucocitos 14,000/µL, lactato 2.2 mmol/L, glucosa 280 mg/dL. Tomografía: apéndice dilatado de 11 mm con pared engrosada, fecalito, gas extraluminal y líquido libre en pelvis.","questions":[{"id":"puem-r2-cc-r2-06-05-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Apendicitis complicada perforada con peritonitis; reanimación, antibióticos y apendicectomía urgente con lavado.","Obstrucción intestinal por bridas; sonda nasogástrica y observación.","Colecistitis aguda; colecistectomía laparoscópica.","Apendicitis no complicada; apendicectomía electiva en 6 semanas."],"answer_index":0,"correct_text":"Apendicitis complicada perforada con peritonitis; reanimación, antibióticos y apendicectomía urgente con lavado.","explanation":"En un anciano diabético el cuadro de apendicitis es atípico y se presenta tarde; la tomografía muestra perforación con gas extraluminal, líquido libre y fecalito, es decir, apendicitis complicada con peritonitis. El manejo es reanimación, antibióticos de amplio espectro y apendicectomía urgente con lavado y control de la fuente; no es un plastrón contenido que permita manejo conservador. D es incorrecta porque no es una apendicitis no complicada y diferir 6 semanas una perforación con peritonitis sería mortal. B es incorrecta porque no hay distensión de asas con niveles ni antecedente quirúrgico que sustente bridas, y la tomografía muestra la causa apendicular. C es incorrecta porque el dolor es difuso y pélvico, no en hipocondrio derecho, y la imagen muestra el apéndice perforado, no la vesícula.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-06","number":126,"title":"Apendicitis aguda y abdomen agudo · caso 6","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 35 años con apendicitis aguda no complicada confirmada por tomografía. El paciente pregunta si puede tratarse solo con antibiótico sin cirugía.","questions":[{"id":"puem-r2-cc-r2-06-06-q1","ordinal":1,"stem":"¿Cuál es la información correcta que debes darle?","options":["El antibiótico cura definitivamente la apendicitis en todos los casos y nunca recurre.","El antibiótico puede resolver el episodio agudo en casos seleccionados, pero la recurrencia es de aproximadamente 25-40% al año, por lo que la apendicectomía sigue siendo el estándar.","El antibiótico está contraindicado en apendicitis y siempre empeora el cuadro.","La apendicitis no complicada no necesita ningún tratamiento."],"answer_index":1,"correct_text":"El antibiótico puede resolver el episodio agudo en casos seleccionados, pero la recurrencia es de aproximadamente 25-40% al año, por lo que la apendicectomía sigue siendo el estándar.","explanation":"El manejo conservador con antibiótico es una opción en pacientes seleccionados con apendicitis no complicada que lo prefieren o tienen alto riesgo quirúrgico, pero no es curativo definitivo: la recurrencia es de aproximadamente 25-40% en el primer año y una proporción requerirá cirugía posterior. La apendicectomía laparoscópica sigue siendo el estándar, especialmente en jóvenes operables. A es incorrecta porque exagera la eficacia del antibiótico y niega la recurrencia demostrada. C es incorrecta porque el antibiótico sí es parte del tratamiento perioperatorio y del manejo conservador en casos seleccionados; no está contraindicado. D es incorrecta porque la apendicitis no tratada progresa a gangrena y perforación en una proporción importante.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-07","number":127,"title":"Apendicitis aguda y abdomen agudo · caso 7","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 45 años con dolor abdominal súbito, intenso, desproporcionado a la exploración, antecedente de fibrilación auricular sin anticoagulación, vómito y evacuaciones con sangre. Exploración: abdomen blando, dolor difuso, ruidos intestinales disminuidos, sin defensa ni rebote. Laboratorio: leucocitos 18,000/µL, lactato 5.5 mmol/L, pH 7.28. Tomografía con contraste: engrosamiento de asas de intestino delgado, ausencia de realce de un segmento de íleon, gas en vena porta.","questions":[{"id":"puem-r2-cc-r2-06-07-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable y la conducta?","options":["Obstrucción intestinal por bridas; sonda nasogástrica.","Apendicitis aguda; apendicectomía laparoscópica.","Isquemia mesentérica aguda por embolia; reanimación, anticoagulación, valoración vascular urgente y laparotomía para resección del segmento necrótico.","Gastroenteritis; líquidos orales y egreso."],"answer_index":2,"correct_text":"Isquemia mesentérica aguda por embolia; reanimación, anticoagulación, valoración vascular urgente y laparotomía para resección del segmento necrótico.","explanation":"El dolor desproporcionado a la exploración en una paciente con fibrilación auricular sin anticoagulación, con lactato elevado, acidosis, sangre en evacuaciones y tomografía con falta de realce intestinal y gas en vena porta es isquemia mesentérica aguda por embolia, una urgencia con alta mortalidad. El manejo es reanimación, anticoagulación, valoración vascular urgente y laparotomía para resecar el intestino necrótico y valorar la revascularización. B es incorrecta porque el dolor no está localizado en fosa ilíaca derecha, no hay hallazgos apendiculares y el cuadro sistémico con lactato de 5.5 no corresponde a apendicitis. D es incorrecta porque la gastroenteritis no produce lactato de 5.5, gas en vena porta ni falta de realce intestinal. A es incorrecta porque no hay distensión con niveles hidroaéreos ni antecedente quirúrgico, y la sonda no trata la isquemia.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-08","number":128,"title":"Apendicitis aguda y abdomen agudo · caso 8","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 30 años, 5 días después de apendicectomía laparoscópica por apendicitis perforada, con fiebre de 38.7 °C, dolor en fosa ilíaca derecha y leucocitos 15,000/µL. Tomografía: colección líquida de 6 cm en fosa ilíaca derecha, sin gas, sin fuga del muñón.","questions":[{"id":"puem-r2-cc-r2-06-08-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Suspender antibióticos porque la fiebre es normal tras la cirugía.","Colonoscopia para descartar cáncer.","Laparotomía urgente con lavado.","Drenaje percutáneo de la colección guiado por imagen más antibióticos, con vigilancia."],"answer_index":3,"correct_text":"Drenaje percutáneo de la colección guiado por imagen más antibióticos, con vigilancia.","explanation":"Es un absceso intraabdominal postapendicectomía, complicación frecuente tras apendicitis perforada. El manejo de elección en una colección accesible de 6 cm es el drenaje percutáneo guiado por imagen más antibióticos, que controla la fuente con menor morbilidad que la reintervención. C es incorrecta porque la laparotomía urgente se reserva para peritonitis generalizada, fuga del muñón o fracaso del drenaje; una colección localizada sin fuga se maneja primero por vía percutánea. A es incorrecta porque la fiebre con leucocitosis al quinto día postoperatorio y una colección demostrada no es normal y requiere tratamiento. B es incorrecta porque la colonoscopia no trata un absceso postoperatorio y no es el estudio indicado en este momento.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-09","number":129,"title":"Apendicitis aguda y abdomen agudo · caso 9","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 58 años con dolor en fosa ilíaca derecha de 3 días, fiebre de 38.3 °C, leucocitos 13,000/µL. Tomografía: apéndice dilatado de 9 mm con fecalito y engrosamiento de la grasa, sin perforación ni absceso. El reporte de patología tras la apendicectomía muestra un tumor carcinoide de 1.8 cm en la punta del apéndice, con invasión de la muscularis y márgenes negativos.","questions":[{"id":"puem-r2-cc-r2-06-09-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Hemicolectomía derecha por el tamaño de 1.8 cm con invasión, valorando factores de riesgo y márgenes, con seguimiento oncológico.","Quimioterapia adyuvante inmediata sin cirugía adicional.","No hacer nada más; la apendicectomía fue curativa.","Hemicolectomía derecha por el tamaño mayor de 2 cm."],"answer_index":0,"correct_text":"Hemicolectomía derecha por el tamaño de 1.8 cm con invasión, valorando factores de riesgo y márgenes, con seguimiento oncológico.","explanation":"Los tumores carcinoides apendiculares menores de 1 cm se curan con apendicectomía; los mayores de 2 cm requieren hemicolectomía derecha. Entre 1 y 2 cm, la decisión depende de factores de riesgo: invasión de la muscularis, invasión linfovascular, localización en la base, márgenes positivos o alto índice mitótico. Un tumor de 1.8 cm con invasión de la muscularis está en el grupo en que la hemicolectomía derecha es la conducta recomendada en la mayoría de las guías, con valoración oncológica. C es incorrecta porque 1.8 cm con invasión no se considera curado con apendicectomía simple en todos los casos; requiere valoración de resección más amplia. D es incorrecta en su justificación: el tumor mide 1.8 cm, no más de 2 cm, por lo que el criterio no es el tamaño mayor de 2 cm sino la combinación de tamaño e invasión. B es incorrecta porque la quimioterapia no sustituye a la resección quirúrgica en un carcinoide localizado; la cirugía es el tratamiento principal.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-06-10","number":130,"title":"Apendicitis aguda y abdomen agudo · caso 10","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 40 años con dolor abdominal epigástrico súbito, intenso, que se irradia a la espalda, vómito, sudoración y palidez, antecedente de úlcera péptica no tratada. Exploración: abdomen en tabla, rigidez generalizada, rebote, ruidos intestinales ausentes. Radiografía de abdomen de pie: aire libre subdiafragmático. Laboratorio: leucocitos 16,500/µL, lactato 3.0 mmol/L.","questions":[{"id":"puem-r2-cc-r2-06-10-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Colecistitis aguda; colecistectomía laparoscópica.","Pancreatitis aguda; reanimación y ayuno.","Úlcera péptica perforada con peritonitis secundaria; reanimación, antibióticos, inhibidor de bomba de protones y laparotomía urgente con cierre de la perforación.","Apendicitis perforada; apendicectomía."],"answer_index":2,"correct_text":"Úlcera péptica perforada con peritonitis secundaria; reanimación, antibióticos, inhibidor de bomba de protones y laparotomía urgente con cierre de la perforación.","explanation":"El dolor epigástrico súbito con abdomen en tabla, rigidez generalizada y aire libre subdiafragmático en un paciente con úlcera péptica es una perforación gastroduodenal con peritonitis secundaria, una urgencia quirúrgica. El manejo es reanimación, antibióticos de amplio espectro, inhibidor de bomba de protones y laparotomía urgente para cerrar la perforación (habitualmente con parche de Graham) y lavar la cavidad. B es incorrecta porque la pancreatitis no produce aire libre ni abdomen en tabla de esta magnitud, y el antecedente de úlcera con aire libre define perforación. D es incorrecta porque el dolor es epigástrico y generalizado, no en fosa ilíaca derecha, y el aire libre apunta a perforación alta. A es incorrecta porque el dolor no está en hipocondrio derecho y no hay datos de patología biliar; la colecistectomía no trata una perforación duodenal.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-01","number":131,"title":"Enfermedad diverticular y patología benigna de colon · caso 1","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 68 años con dolor en fosa iliaca izquierda de 3 días, fiebre de 38.3 °C, náusea y leucocitos 14,000/µL. Exploración: dolor a la palpación en fosa iliaca izquierda sin peritonismo. Tomografía: engrosamiento de sigmoide, estriación de grasa pericólica y divertículos, sin absceso ni aire libre.","questions":[{"id":"puem-r2-cc-r2-09-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo más adecuado?","options":["Apendicitis; apendicectomía urgente","Cáncer de colon perforado; colectomía de urgencia","Colitis ulcerosa; esteroides intravenosos inmediatos","Diverticulitis no complicada; hospitalización o manejo ambulatorio con dieta, analgesia y antibiótico según gravedad, sin colonoscopia aguda"],"answer_index":3,"correct_text":"Diverticulitis no complicada; hospitalización o manejo ambulatorio con dieta, analgesia y antibiótico según gravedad, sin colonoscopia aguda","explanation":"Diverticulitis no complicada: dolor izquierdo, fiebre, leucocitosis y tomografía con engrosamiento y estriación sin absceso ni perforación. Se maneja con dieta, analgesia y antibiótico en la mayoría de los casos, ambulatorio si está estable o hospitalario si hay comorbilidad; la colonoscopia aguda está contraindicada. B es del lado contrario y con otro cuadro. B no tiene masa ni perforación en tomografía. D es diarrea sanguinolenta continua, no dolor localizado con divertículos.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-02","number":132,"title":"Enfermedad diverticular y patología benigna de colon · caso 2","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Varón de 72 años con diverticulitis conocida, fiebre persistente de 39 °C a pesar de 48 horas de antibiótico intravenoso, dolor en fosa iliaca izquierda y masa palpable. Tomografía: absceso pericólico de 5.5 cm en sigmoide, sin aire libre. Leucocitos 17,000/µL.","questions":[{"id":"puem-r2-cc-r2-09-02-q1","ordinal":1,"stem":"¿Cuál es el siguiente paso?","options":["Sigmoidectomía de urgencia con anastomosis primaria sin preparación","Cambiar solo el antibiótico oral y enviar a casa","Drenaje percutáneo guiado por tomografía más antibiótico intravenoso","Colonoscopia urgente para drenar el absceso"],"answer_index":2,"correct_text":"Drenaje percutáneo guiado por tomografía más antibiótico intravenoso","explanation":"Absceso mayor de aproximadamente 3 a 4 cm que no responde a antibiótico: el drenaje percutáneo guiado por imagen es el tratamiento indicado, junto con antibiótico. A es insuficiente para un absceso de 5.5 cm con fiebre persistente. C es peligrosa en diverticulitis aguda con absceso por riesgo de perforación. D es excesiva sin peritonitis ni perforación libre; la cirugía electiva se planea después de resolver el absceso.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-03","number":133,"title":"Enfermedad diverticular y patología benigna de colon · caso 3","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 80 años con dolor abdominal generalizado súbito, rigidez abdominal, fiebre de 38.8 °C, taquicardia y leucocitos 19,000/µL. Tomografía: aire libre, líquido libre y engrosamiento sigmoideo con divertículos. Lactato 3.5 mmol/L.","questions":[{"id":"puem-r2-cc-r2-09-03-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Drenaje percutáneo del aire libre","Cirugía de urgencia: reanimación, antibiótico de amplio espectro y resección del sigmoide con colostomía de Hartmann o anastomosis según estabilidad","Colonoscopia urgente para localizar la perforación","Manejo conservador con antibiótico y observación"],"answer_index":1,"correct_text":"Cirugía de urgencia: reanimación, antibiótico de amplio espectro y resección del sigmoide con colostomía de Hartmann o anastomosis según estabilidad","explanation":"Diverticulitis perforada Hinchey IV, peritonitis fecal con aire y líquido libres, rigidez y choque incipiente: es una urgencia quirúrgica con resección del segmento enfermo. La decisión entre Hartmann y anastomosis primaria depende de la estabilidad y la contaminación. D y A no tratan una peritonitis fecal. D está contraindicada ante perforación libre.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-04","number":134,"title":"Enfermedad diverticular y patología benigna de colon · caso 4","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Varón de 65 años con infecciones urinarias recurrentes, neumaturia y fecaluria de 2 meses. Antecedente de diverticulitis. Tomografía: engrosamiento sigmoideo adherido a la vejiga, con aire en vejiga y trayecto fistuloso.","questions":[{"id":"puem-r2-cc-r2-09-04-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo definitivo?","options":["Fístula colovesical por diverticulitis complicada; sigmoidectomía electiva con resección de la fístula y reparación vesical","Cáncer vesical; cistectomía","Enfermedad de Crohn; tratamiento médico exclusivo","Infección urinaria complicada; antibiótico prolongado"],"answer_index":0,"correct_text":"Fístula colovesical por diverticulitis complicada; sigmoidectomía electiva con resección de la fístula y reparación vesical","explanation":"Neumaturia y fecaluria en un paciente con diverticulitis son clásicas de fístula colovesical. El tratamiento definitivo es quirúrgico y electivo tras resolver la infección: sigmoidectomía con resección del trayecto y cierre vesical. A solo trata la consecuencia. B no explica el antecedente diverticular ni el engrosamiento sigmoideo adherido. D puede dar fístulas, pero el cuadro y la tomografía apuntan a diverticulitis complicada.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-05","number":135,"title":"Enfermedad diverticular y patología benigna de colon · caso 5","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Varón de 78 años, hipertenso, con hematoquecia indolora abundante de inicio súbito, sin fiebre ni dolor abdominal. Presión arterial 95/60 mmHg, frecuencia cardiaca 110 lpm, hemoglobina 8.5 g/dL. Tacto rectal con sangre fresca. Colonoscopia previa hace 2 años: diverticulosis sigmoidea extensa.","questions":[{"id":"puem-r2-cc-r2-09-05-q1","ordinal":1,"stem":"¿Cuál es la causa más probable y el primer paso?","options":["Hemorroides sangrantes; ligadura en consultorio","Cáncer de colon; colectomía inmediata sin localizar","Colitis isquémica; ayuno y antibiótico sin endoscopia","Hemorragia diverticular; reanimación, transfusión según umbral y colonoscopia urgente tras preparación cuando esté estable"],"answer_index":3,"correct_text":"Hemorragia diverticular; reanimación, transfusión según umbral y colonoscopia urgente tras preparación cuando esté estable","explanation":"Hematoquecia indolora, abundante y súbita en un adulto mayor con diverticulosis conocida: hemorragia diverticular, la causa más frecuente de sangrado digestivo bajo en este grupo. El primer paso es reanimar y estabilizar, luego colonoscopia para localizar y tratar endoscópicamente. A no explica el volumen ni la inestabilidad. C opera sin localizar el sangrado. D cursa con dolor y diarrea, no con hematoquecia masiva indolora.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-06","number":136,"title":"Enfermedad diverticular y patología benigna de colon · caso 6","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 55 años, 7 semanas después de un episodio de diverticulitis con absceso que resolvió con drenaje percutáneo. Está asintomática, con estudios normales. Su médico propone no hacer más estudios porque ya se hizo tomografía.","questions":[{"id":"puem-r2-cc-r2-09-06-q1","ordinal":1,"stem":"¿Qué debe hacerse?","options":["Sigmoidectomía profiláctica inmediata sin colonoscopia","Aceptar: la tomografía ya descartó cáncer","Colonoscopia para descartar cáncer colorrectal o enfermedad inflamatoria, indicada tras diverticulitis complicada","Repetir tomografía cada 3 meses"],"answer_index":2,"correct_text":"Colonoscopia para descartar cáncer colorrectal o enfermedad inflamatoria, indicada tras diverticulitis complicada","explanation":"Tras una diverticulitis, sobre todo complicada con absceso, se recomienda colonoscopia a las 6 a 8 semanas para descartar cáncer, que puede simular o coexistir con diverticulitis; la tomografía no sustituye la visualización endoscópica ni la biopsia. A deja sin descartar una neoplasia. C irradia sin dar diagnóstico histológico. D opera sin confirmar la indicación ni descartar cáncer.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-07","number":137,"title":"Enfermedad diverticular y patología benigna de colon · caso 7","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Varón de 62 años con dos episodios previos de diverticulitis no complicada que resolvieron con antibiótico. Ahora está asintomático y pregunta si debe operarse para evitar un tercer episodio. No tiene inmunosupresión, fístula ni estenosis.","questions":[{"id":"puem-r2-cc-r2-09-07-q1","ordinal":1,"stem":"¿Cuál es la recomendación actual?","options":["Sigmoidectomía electiva obligada tras el segundo episodio","No indicar cirugía electiva solo por el número de episodios; individualizar según recurrencia, gravedad, comorbilidad y calidad de vida, con dieta alta en fibra","Colectomía total profiláctica","Antibiótico profiláctico de por vida"],"answer_index":1,"correct_text":"No indicar cirugía electiva solo por el número de episodios; individualizar según recurrencia, gravedad, comorbilidad y calidad de vida, con dieta alta en fibra","explanation":"Las guías actuales ya no indican cirugía electiva de rutina por el número de episodios; la decisión se individualiza por diverticulitis complicada, inmunosupresión, fístula, estenosis, recurrencia frecuente o impacto en la calidad de vida. A aplica una regla antigua abandonada. C es desproporcionada. D no previene la diverticulitis y genera resistencia.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-08","number":138,"title":"Enfermedad diverticular y patología benigna de colon · caso 8","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 34 años con enfermedad de Crohn ileocecal, con dolor en fosa iliaca derecha, masa palpable, fiebre y pérdida de peso. Tomografía: estenosis ileal de 8 cm con dilatación proximal y absceso de 3 cm. Ha recibido esteroides e infliximab sin mejoría de la estenosis.","questions":[{"id":"puem-r2-cc-r2-09-08-q1","ordinal":1,"stem":"¿Cuál es el manejo quirúrgico más adecuado?","options":["Resección limitada del segmento estenótico o estricturoplastia, con drenaje del absceso, preservando al máximo el intestino","Colectomía total con ileostomía definitiva","No operar nunca en Crohn; continuar solo tratamiento médico","Hemicolectomía derecha amplia con resección de 50 cm de íleon sano"],"answer_index":0,"correct_text":"Resección limitada del segmento estenótico o estricturoplastia, con drenaje del absceso, preservando al máximo el intestino","explanation":"En Crohn la cirugía es conservadora porque la enfermedad recurre y el intestino debe preservarse para evitar intestino corto: resección limitada del segmento enfermo o estricturoplastia, con manejo del absceso. A reseca intestino sano innecesariamente. C es para colitis ulcerosa grave o megacolon, no para estenosis ileal de Crohn. D deja una estenosis fibrótica que no responde a fármacos y un absceso sin tratar.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-09","number":139,"title":"Enfermedad diverticular y patología benigna de colon · caso 9","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Varón de 58 años en colonoscopia de tamizaje: pólipo pediculado de 2.5 cm en sigmoide, resecado por completo por polipectomía. Histología: adenoma tubular con displasia de alto grado, bordes libres, sin invasión linfovascular.","questions":[{"id":"puem-r2-cc-r2-09-09-q1","ordinal":1,"stem":"¿Cuál es el seguimiento?","options":["Sigmoidectomía inmediata por displasia de alto grado","Repetir colonoscopia en 10 años como tamizaje habitual","No requiere vigilancia; el pólipo ya se quitó","Colonoscopia de vigilancia en intervalo corto según guías (habitualmente 3 años o menos por displasia de alto grado y tamaño), con vigilancia posterior según hallazgos"],"answer_index":3,"correct_text":"Colonoscopia de vigilancia en intervalo corto según guías (habitualmente 3 años o menos por displasia de alto grado y tamaño), con vigilancia posterior según hallazgos","explanation":"Un adenoma grande con displasia de alto grado, aunque resecado por completo, es de alto riesgo y requiere vigilancia colonoscópica en intervalo corto, no el intervalo habitual de tamizaje. A ignora el riesgo de lesiones sincrónicas y metacrónicas. C es excesiva si la resección fue completa con bordes libres y sin factores de mal pronóstico. D es el intervalo para un tamizaje normal, no para un adenoma avanzado.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-09-10","number":140,"title":"Enfermedad diverticular y patología benigna de colon · caso 10","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Varón de 70 años con diverticulitis no complicada que se maneja ambulatoriamente. Pregunta qué puede hacer para prevenir otro episodio. No tiene alergias, tolera la vía oral y está afebril a las 48 horas.","questions":[{"id":"puem-r2-cc-r2-09-10-q1","ordinal":1,"stem":"¿Qué recomendación es correcta?","options":["Evitar para siempre semillas, nueces y palomitas porque causan diverticulitis","Dieta alta en fibra, hidratación adecuada, actividad física y evitar el estreñimiento; no hay evidencia de que las semillas o nueces desencadenen diverticulitis","Dieta baja en fibra de por vida para no irritar el colon","Ayuno prolongado cada mes como prevención"],"answer_index":1,"correct_text":"Dieta alta en fibra, hidratación adecuada, actividad física y evitar el estreñimiento; no hay evidencia de que las semillas o nueces desencadenen diverticulitis","explanation":"La prevención de la enfermedad diverticular es dieta alta en fibra, hidratación y actividad física; los estudios no han demostrado que las semillas, nueces o palomitas desencadenen diverticulitis, por lo que no deben prohibirse de forma rutinaria. A repite un mito sin evidencia. C empeora el mecanismo: la dieta baja en fibra aumenta la presión intraluminal. D no tiene sustento y es innecesario.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-01","number":141,"title":"Cáncer de colon · caso 1","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 68 años, con diabetes e hipertensión, acude por astenia de 4 meses, pérdida de 8 kg y melena intermitente. Niega dolor abdominal. Exploración: palidez conjuntival, masa no dolorosa en fosa iliaca derecha de 5 cm, tacto rectal sin sangre visible. Laboratorios: Hb 8.2 g/dL, VCM 72 fL, ferritina 9 ng/mL, ACE 12 ng/mL. Colonoscopia: lesión ulcerada en ciego de 6 cm, biopsia adenocarcinoma moderadamente diferenciado. TC: engrosamiento cecal, 2 ganglios pericolónicos de 9 mm, sin metástasis hepáticas.","questions":[{"id":"puem-r2-cc-r2-10-01-q1","ordinal":1,"stem":"¿Cuál es el manejo inicial más adecuado?","options":["Colonoscopia terapéutica con resección endoscópica de la lesión y vigilancia.","Hemicolectomía derecha laparoscópica con linfadenectomía y ligadura alta de ileocólica y cólica derecha.","Quimioterapia neoadyuvante con FOLFOX por 3 meses y luego reestadificar.","Radioterapia pélvica neoadyuvante seguida de hemicolectomía derecha."],"answer_index":1,"correct_text":"Hemicolectomía derecha laparoscópica con linfadenectomía y ligadura alta de ileocólica y cólica derecha.","explanation":"En cáncer de colon localizado resecable, el tratamiento curativo es la resección oncológica de entrada; no hay neoadyuvancia estándar. La hemicolectomía derecha con ligadura vascular alta y linfadenectomía completa cumple los principios oncológicos. C es incorrecta: la quimioterapia neoadyuvante no es estándar en colon resecable, a diferencia del recto; se da adyuvante según la etapa patológica. D es incorrecta: la radioterapia no tiene papel en cáncer de colon. A es incorrecta: una lesión ulcerada de 6 cm con biopsia de adenocarcinoma invasor no es resecable endoscópicamente ni curable con vigilancia.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-02","number":142,"title":"Cáncer de colon · caso 2","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 54 años con cáncer de sigmoides T3N1M0 resecado con sigmoidectomía laparoscópica, 18 ganglios resecados, 3 positivos, márgenes negativos, invasión linfovascular presente. Recuperación sin complicaciones. Oncología médica pregunta el plan.","questions":[{"id":"puem-r2-cc-r2-10-02-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Quimioterapia adyuvante con FOLFOX o CAPEOX.","Radioterapia adyuvante pélvica.","Quimioterapia adyuvante solo con capecitabina porque es mujer mayor de 50 años.","Vigilancia sin quimioterapia porque los márgenes son negativos."],"answer_index":0,"correct_text":"Quimioterapia adyuvante con FOLFOX o CAPEOX.","explanation":"Es etapa III (N1) y la quimioterapia adyuvante con fluoropirimidina más oxaliplatino es el estándar y mejora la sobrevida libre de enfermedad y global. D es incorrecta: en etapa III la vigilancia sola deja enfermedad micrometastásica sin tratar. B es incorrecta: la radioterapia no es adyuvancia en colon. C es incorrecta: la monoterapia es inferior en etapa III de alto riesgo en un paciente que tolera el doblete; el sexo y la edad por sí solos no la justifican.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-03","number":143,"title":"Cáncer de colon · caso 3","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 72 años con obstrucción intestinal por cáncer de colon descendente. Llega con distensión, vómito fecaloide, dolor cólico y radiografía con niveles hidroaéreos y colon dilatado. TA 85/55 mmHg, FC 118 lpm, lactato 4.2 mmol/L, creatinina 1.9 mg/dL, leucocitos 18,000/µL. TC: tumor estenosante en descendente, colon proximal dilatado a 9 cm, sin neumoperitoneo, sin metástasis.","questions":[{"id":"puem-r2-cc-r2-10-03-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado en este momento?","options":["Prótesis metálica autoexpandible de urgencia y alta en 24 horas.","Colonoscopia descompresiva y quimioterapia neoadyuvante.","Anastomosis primaria con ileostomía de protección y alta precoz.","Reanimación, antibióticos, sonda nasogástrica y cirugía urgente: resección del segmento con colostomía terminal (Hartmann), sin anastomosis primaria."],"answer_index":3,"correct_text":"Reanimación, antibióticos, sonda nasogástrica y cirugía urgente: resección del segmento con colostomía terminal (Hartmann), sin anastomosis primaria.","explanation":"Paciente en choque con hipoperfusión, lesión obstructiva y alto riesgo de isquemia y perforación; requiere reanimación y cirugía urgente, y en ese contexto la opción segura es resección con estoma, no anastomosis primaria en colon no preparado, dilatado e isquémico en un paciente inestable. A es incorrecta: la prótesis como puente requiere paciente estable, equipo disponible y ausencia de perforación o isquemia inminente; no resuelve el choque ni el riesgo inmediato. B es incorrecta: no hay tiempo ni indicación para neoadyuvancia en obstrucción con choque. C es incorrecta: la anastomosis primaria en estas condiciones tiene alto riesgo de fuga y muerte.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-04","number":144,"title":"Cáncer de colon · caso 4","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 47 años con antecedente de padre con cáncer de colon a los 52 años y tía materna con cáncer de endometrio a los 48. Ella tiene adenocarcinoma de colon ascendente, poco diferenciado, mucinoso, con infiltrado linfocitario. La inmunohistoquímica muestra pérdida de MLH1 y PMS2.","questions":[{"id":"puem-r2-cc-r2-10-04-q1","ordinal":1,"stem":"¿Cuál es el siguiente paso más importante?","options":["Descartar síndrome hereditario porque solo un familiar tuvo cáncer de colon.","Solicitar únicamente BRAF V600E y, si es positivo, descartar Lynch sin más estudios.","Asumir síndrome de Lynch y pedir estudio germinal, consejería genética y tamizaje familiar, además de evaluar inestabilidad de microsatélites.","Iniciar quimioterapia con cetuximab porque el tumor es de colon derecho."],"answer_index":2,"correct_text":"Asumir síndrome de Lynch y pedir estudio germinal, consejería genética y tamizaje familiar, además de evaluar inestabilidad de microsatélites.","explanation":"El cuadro sugiere deficiencia de reparación de errores de apareamiento y posible síndrome de Lynch: edad joven, historia familiar de cáncer de colon y endometrio, histología mucinosa poco diferenciada con infiltrado linfocitario y pérdida de MLH1/PMS2. El paso correcto es estudio germinal y consejería genética, con tamizaje de familiares. D es incorrecta: el anti-EGFR depende del estado RAS, no de la lateralidad aislada, y no es el paso diagnóstico prioritario. A es incorrecta: los criterios familiares y el fenotipo tumoral son suficientes para sospecharlo. B es incorrecta: BRAF mutado hace menos probable Lynch en tumores esporádicos con pérdida de MLH1 por metilación, pero no lo descarta por sí solo ni sustituye la evaluación genética completa.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-05","number":145,"title":"Cáncer de colon · caso 5","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 60 años con cáncer de colon transverso T4b con invasión a duodeno, sin metástasis a distancia. Está estable, sin obstrucción. El cirujano plantea resección en bloque.","questions":[{"id":"puem-r2-cc-r2-10-05-q1","ordinal":1,"stem":"¿Cuál es la conducta oncológicamente correcta?","options":["Derivación intestinal (bypass) sin resecar el tumor.","Resección en bloque del colon transverso con la porción duodenal invadida, con márgenes negativos, sin separar el tumor del duodeno.","Separar el tumor del duodeno para conservarlo y resecar solo el colon.","Quimioterapia paliativa definitiva sin cirugía porque es T4b."],"answer_index":1,"correct_text":"Resección en bloque del colon transverso con la porción duodenal invadida, con márgenes negativos, sin separar el tumor del duodeno.","explanation":"En T4b resecable, el principio es la resección en bloque con el órgano invadido y márgenes negativos; separar el tumor viola el plano oncológico y deja enfermedad residual. C es incorrecta por esa razón. D es incorrecta: T4b sin metástasis puede ser curable con resección en bloque más adyuvancia. A es incorrecta: el bypass es paliativo y no trata el tumor en un paciente potencialmente curable.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-06","number":146,"title":"Cáncer de colon · caso 6","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 63 años, 2 años después de hemicolectomía derecha por adenocarcinoma T3N0M0, con ACE basal de 2 ng/mL. En seguimiento, el ACE sube a 18 ng/mL y luego a 34 ng/mL en dos mediciones consecutivas. Está asintomática, exploración normal.","questions":[{"id":"puem-r2-cc-r2-10-06-q1","ordinal":1,"stem":"¿Cuál es el siguiente paso?","options":["Solicitar TC de tórax, abdomen y pelvis y colonoscopia para buscar recurrencia.","Iniciar quimioterapia empírica sin estudios de imagen.","Solicitar solo radiografía de tórax y ultrasonido hepático.","Repetir ACE en 6 meses y tranquilizarla porque no tiene síntomas."],"answer_index":0,"correct_text":"Solicitar TC de tórax, abdomen y pelvis y colonoscopia para buscar recurrencia.","explanation":"El aumento sostenido del ACE tras una basal normal es sospechoso de recurrencia y obliga a estudio de imagen completo y colonoscopia; la recurrencia puede ser asintomática y resecable si se detecta a tiempo. D es incorrecta: esperar retrasa el diagnóstico. B es incorrecta: no se inicia quimioterapia sin confirmar enfermedad y su localización. C es incorrecta: es un estudio insuficiente frente a la sospecha de recurrencia metastásica.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-07","number":147,"title":"Cáncer de colon · caso 7","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 58 años con cáncer de colon metastásico a hígado: 3 lesiones en lóbulo derecho, resecables, sin enfermedad extrahepática. Tumor primario en sigmoides, RAS nativo, microsatélites estables. ECOG 0.","questions":[{"id":"puem-r2-cc-r2-10-07-q1","ordinal":1,"stem":"¿Cuál es el plan con mayor probabilidad curativa?","options":["Quimioterapia paliativa indefinida sin cirugía hepática porque ya hay metástasis.","Resección hepática sin quimioterapia y sin resecar el primario.","Radioterapia hepática como único tratamiento.","Quimioterapia perioperatoria y resección del primario y de las metástasis hepáticas en centro especializado."],"answer_index":3,"correct_text":"Quimioterapia perioperatoria y resección del primario y de las metástasis hepáticas en centro especializado.","explanation":"Las metástasis hepáticas resecables son la única situación potencialmente curativa en cáncer de colon estadio IV; el manejo es multimodal con quimioterapia perioperatoria y resección del primario y del hígado en un centro con experiencia. A es incorrecta: condena a tratamiento paliativo a un paciente potencialmente curable. B es incorrecta: deja el primario sin tratar y omite la quimioterapia perioperatoria que mejora el control. C es incorrecta: la radioterapia no sustituye la resección hepática curativa.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-08","number":148,"title":"Cáncer de colon · caso 8","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 66 años con adenocarcinoma de ciego T2N0M0 resecado con hemicolectomía derecha, 9 ganglios resecados, todos negativos, sin invasión linfovascular ni perineural, márgenes negativos.","questions":[{"id":"puem-r2-cc-r2-10-08-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta respecto a la adyuvancia y la estadificación?","options":["Dar radioterapia adyuvante por ganglios insuficientes.","Repetir la cirugía para completar 12 ganglios.","No dar quimioterapia adyuvante; es etapa I y documentar que la linfadenectomía fue insuficiente (<12 ganglios).","Dar FOLFOX adyuvante porque se resecaron menos de 12 ganglios."],"answer_index":2,"correct_text":"No dar quimioterapia adyuvante; es etapa I y documentar que la linfadenectomía fue insuficiente (<12 ganglios).","explanation":"Es etapa I (T2N0), sin factores de alto riesgo, por lo que no requiere quimioterapia adyuvante; sin embargo, 9 ganglios son menos de los 12 recomendados, lo que se debe documentar como estadificación potencialmente insuficiente y considerar en el seguimiento. D es incorrecta: el número bajo de ganglios por sí solo no convierte una etapa I en indicación de FOLFOX. A es incorrecta: la radioterapia no tiene papel aquí. B es incorrecta: no se reopera para completar el conteo ganglionar.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-09","number":149,"title":"Cáncer de colon · caso 9","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Hombre de 71 años con cáncer de colon izquierdo metastásico, KRAS mutado, microsatélites estables, con metástasis hepáticas múltiples no resecables y buen estado funcional.","questions":[{"id":"puem-r2-cc-r2-10-09-q1","ordinal":1,"stem":"¿Cuál es el esquema sistémico inicial más adecuado?","options":["Capecitabina sola en dosis bajas por la edad.","FOLFOX o CAPEOX más bevacizumab (anti-VEGF).","FOLFOX más cetuximab (anti-EGFR).","Inmunoterapia con pembrolizumab como monoterapia de primera línea."],"answer_index":1,"correct_text":"FOLFOX o CAPEOX más bevacizumab (anti-VEGF).","explanation":"Con KRAS mutado, los anti-EGFR no son efectivos, por lo que el estándar es quimioterapia con oxaliplatino más bevacizumab. C es incorrecta: cetuximab requiere RAS nativo. D es incorrecta: la inmunoterapia de primera línea es para tumores con inestabilidad de microsatélites alta, no para microsatélites estables. A es incorrecta: la monoterapia es insuficiente en un paciente con buen estado funcional y enfermedad voluminosa.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-10-10","number":150,"title":"Cáncer de colon · caso 10","topic":"Colon y Apéndice","topicId":"colon","nivel":"R2","context":"Mujer de 52 años con pólipo en colon ascendente de 2.5 cm resecado por colonoscopia. Patología: adenocarcinoma intramucoso con invasión a submucosa superficial, márgenes de resección negativos, sin invasión linfovascular, bien diferenciado, resección en bloque. Colonoscopia completa sin otras lesiones.","questions":[{"id":"puem-r2-cc-r2-10-10-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Hemicolectomía derecha inmediata en todos los casos de pólipo maligno.","Quimioterapia adyuvante con FOLFOX.","Radioterapia endorrectal.","Vigilancia con colonoscopia de control, sin colectomía, porque es un pólipo maligno de bajo riesgo."],"answer_index":3,"correct_text":"Vigilancia con colonoscopia de control, sin colectomía, porque es un pólipo maligno de bajo riesgo.","explanation":"Es un pólipo maligno de bajo riesgo: resección en bloque, márgenes negativos, bien diferenciado, sin invasión linfovascular y con invasión submucosa superficial; en ese escenario la polipectomía es curativa y la vigilancia endoscópica es suficiente. A es incorrecta: la colectomía se reserva para pólipos malignos de alto riesgo (margen positivo, invasión linfovascular, poco diferenciado, resección fragmentada). B es incorrecta: no hay indicación de quimioterapia en enfermedad localizada de bajo riesgo resecada endoscópicamente. C es incorrecta: la radioterapia no tiene papel en colon.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-01","number":151,"title":"Cáncer colorrectal · caso 1","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Hombre de 68 años con anemia ferropénica, pérdida de 8 kg y masa palpable en flanco derecho. Colonoscopia: tumor en ciego, biopsia adenocarcinoma. TC sin metástasis.","questions":[{"id":"puem-r2-cc-r3-03-01-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Colostomía derivativa definitiva.","Dar hierro y repetir colonoscopia en 6 meses.","Hemicolectomía derecha con linfadenectomía e ileotransverso anastomosis, con márgenes adecuados y estudio de ganglios.","Radioterapia neoadyuvante y luego cirugía."],"answer_index":2,"correct_text":"Hemicolectomía derecha con linfadenectomía e ileotransverso anastomosis, con márgenes adecuados y estudio de ganglios.","explanation":"Cáncer de colon derecho resecable: resección oncológica con linfadenectomía; no hay neoadyuvancia estándar en colon resecable. **B es incorrecta:** la anemia ferropénica en un hombre mayor es cáncer hasta demostrar lo contrario; demorarlo es un error grave. **D es incorrecta:** la radioterapia neoadyuvante no es estándar en colon (sí en recto). **A es incorrecta:** la colostomía definitiva no es tratamiento curativo.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-02","number":152,"title":"Cáncer colorrectal · caso 2","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Mujer de 55 años con cáncer de recto inferior, RM: T3 N1, CRM amenazado (1 mm de la fascia mesorrectal).","questions":[{"id":"puem-r2-cc-r3-03-02-q1","ordinal":1,"stem":"¿Cuál es el manejo inicial correcto?","options":["Cirugía transanal local.","Solo quimioterapia paliativa.","Resección abdominoperineal inmediata.","Quimiorradioterapia neoadyuvante (o terapia neoadyuvante total) para reducir el tumor y lograr CRM libre, luego TME con preservación de esfínter si es posible."],"answer_index":3,"correct_text":"Quimiorradioterapia neoadyuvante (o terapia neoadyuvante total) para reducir el tumor y lograr CRM libre, luego TME con preservación de esfínter si es posible.","explanation":"CRM amenazado + N+ exige neoadyuvancia para lograr resección R0; operar directo dejaría margen positivo. **C es incorrecta:** operar con CRM amenazado es oncológicamente incorrecto. **A es incorrecta:** la escisión local no trata un T3 N1. **B es incorrecta:** es enfermedad curable, no paliativa.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-03","number":153,"title":"Cáncer colorrectal · caso 3","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Paciente con cáncer de colon pT3 N0, 8 ganglios examinados, todos negativos, MSI alto, sin factores de alto riesgo.","questions":[{"id":"puem-r2-cc-r3-03-03-q1","ordinal":1,"stem":"¿Qué se debe discutir sobre quimioterapia adyuvante?","options":["El estadio II con MSI alto tiene buen pronóstico y la fluoropirimidina sola aporta poco beneficio; la adyuvancia es opcional y se decide con el paciente y oncología, valorando factores de riesgo.","No necesita seguimiento porque el MSI alto lo cura todo.","Debe recibir radioterapia adyuvante.","Quimioterapia adyuvante obligatoria por el T3."],"answer_index":0,"correct_text":"El estadio II con MSI alto tiene buen pronóstico y la fluoropirimidina sola aporta poco beneficio; la adyuvancia es opcional y se decide con el paciente y oncología, valorando factores de riesgo.","explanation":"El punto fino: MSI alto en estadio II predice buen pronóstico y resistencia relativa a 5-FU solo; además solo se examinaron 8 ganglios (<12), lo que es un factor de riesgo que debe ponderarse en comité. **D es incorrecta:** el estadio II no tiene adyuvancia obligatoria. **B es incorrecta:** sigue necesitando seguimiento. **C es incorrecta:** la radioterapia no es adyuvante en colon.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-04","number":154,"title":"Cáncer colorrectal · caso 4","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Hombre de 60 años con cáncer de colon izquierdo obstructivo, distensión, vómitos, TC: tumor en sigmoides con obstrucción completa, sin perforación ni metástasis.","questions":[{"id":"puem-r2-cc-r3-03-04-q1","ordinal":1,"stem":"¿Cuál es la mejor conducta?","options":["Colonoscopia urgente para desobstruir con pinzas.","Stent colónico como puente a cirugía electiva en centro con experiencia, o cirugía de urgencia (resección con estoma) según el estado del paciente y los recursos; no hay una única respuesta, pero la decisión debe ser inmediata.","Dar laxantes y esperar resolución.","Quimioterapia neoadyuvante primero."],"answer_index":1,"correct_text":"Stent colónico como puente a cirugía electiva en centro con experiencia, o cirugía de urgencia (resección con estoma) según el estado del paciente y los recursos; no hay una única respuesta, pero la decisión debe ser inmediata.","explanation":"La obstrucción maligna exige descompresión: el stent como puente permite cirugía electiva con anastomosis en pacientes seleccionados; la cirugía de urgencia con estoma (Hartmann) es la alternativa clásica, sobre todo si hay isquemia o el paciente está inestable. **A es incorrecta:** la colonoscopia no desobstruye un tumor. **C es incorrecta:** los laxantes no resuelven una obstrucción mecánica completa. **D es incorrecta:** la neoadyuvancia no trata la obstrucción aguda.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-05","number":155,"title":"Cáncer colorrectal · caso 5","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Paciente con cáncer de recto medio tratado con quimiorradioterapia y TME; la patología muestra respuesta completa (ypT0 N0). El paciente pregunta si puede evitar la cirugía... ya operado.","questions":[{"id":"puem-r2-cc-r3-03-05-q1","ordinal":1,"stem":"¿Qué se le explica sobre la estrategia de 'watch and wait'?","options":["Que ya no necesita seguimiento.","Que la estrategia de vigilancia sin cirugía es estándar para todos los pacientes con respuesta completa.","Que 'watch and wait' es una opción solo en protocolos/centros con experiencia y vigilancia intensiva, para pacientes con respuesta clínica completa que rechazan o no toleran cirugía, con riesgo de recrecimiento local; en su caso, ya operado, el dato es pronóstico favorable.","Que la respuesta completa significa que la radioterapia falló."],"answer_index":2,"correct_text":"Que 'watch and wait' es una opción solo en protocolos/centros con experiencia y vigilancia intensiva, para pacientes con respuesta clínica completa que rechazan o no toleran cirugía, con riesgo de recrecimiento local; en su caso, ya operado, el dato es pronóstico favorable.","explanation":"El matiz: watch and wait no es estándar universal; exige respuesta clínica completa, vigilancia estricta y aceptar riesgo de recrecimiento que puede requerir cirugía de rescate. **B es incorrecta:** no es para todos. **D es incorrecta:** la respuesta completa es éxito. **A es incorrecta:** el seguimiento continúa.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-06","number":156,"title":"Cáncer colorrectal · caso 6","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Mujer de 45 años con cáncer de colon, KRAS mutado, metástasis hepáticas. El oncólogo propone quimioterapia.","questions":[{"id":"puem-r2-cc-r3-03-06-q1","ordinal":1,"stem":"¿Por qué no se agrega cetuximab (anti-EGFR)?","options":["Porque el cetuximab está contraindicado en metástasis hepáticas.","Porque la paciente es mujer.","Porque el cetuximab solo se usa en cáncer de mama.","Porque los tumores con mutación RAS no responden a anti-EGFR; el biomarcador predice la falta de beneficio y evita toxicidad innecesaria."],"answer_index":3,"correct_text":"Porque los tumores con mutación RAS no responden a anti-EGFR; el biomarcador predice la falta de beneficio y evita toxicidad innecesaria.","explanation":"RAS mutado = resistencia a anti-EGFR; es el ejemplo clásico de medicina de precisión en colorrectal. **C es incorrecta:** el cetuximab es un anti-EGFR usado en colorrectal y cabeza/cuello. **A es incorrecta:** no hay contraindicación por metástasis hepáticas. **D es irrelevante.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-07","number":157,"title":"Cáncer colorrectal · caso 7","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Hombre de 72 años, 5 días posoperatorio de resección anterior baja de recto, con fiebre, dolor pélvico, taquicardia y salida de material turbio por el drenaje.","questions":[{"id":"puem-r2-cc-r3-03-07-q1","ordinal":1,"stem":"¿Cuál es la complicación más probable y la conducta?","options":["Fuga anastomótica: TC con contraste rectal, antibióticos, drenaje percutáneo si hay colección y valorar reintervención; en inestabilidad, cirugía inmediata.","Infección de herida superficial: curación local.","Es normal en el posoperatorio de recto y no requiere estudios.","Íleo posoperatorio: esperar y dar procinéticos."],"answer_index":0,"correct_text":"Fuga anastomótica: TC con contraste rectal, antibióticos, drenaje percutáneo si hay colección y valorar reintervención; en inestabilidad, cirugía inmediata.","explanation":"Fiebre + dolor pélvico + drenaje turbio tras resección de recto = fuga anastomótica hasta demostrar lo contrario; el manejo es escalonado según estabilidad. **D es incorrecta:** el íleo no da drenaje turbio ni fiebre así. **B es incorrecta:** no es solo herida superficial. **C es incorrecta:** nunca es normal.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-08","number":158,"title":"Cáncer colorrectal · caso 8","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Paciente con cáncer de colon derecho y metástasis hepática única de 3 cm en segmento VI, resecable, sin enfermedad extrahepática.","questions":[{"id":"puem-r2-cc-r3-03-08-q1","ordinal":1,"stem":"¿Cuál es la conducta con mejor pronóstico?","options":["Quimioterapia paliativa indefinida sin cirugía.","Resección del primario y de la metástasis hepática (simultánea o escalonada) con quimioterapia perioperatoria, en centro con experiencia: la metástasis hepática resecable puede ser curable.","Solo resección del primario, la metástasis no se toca.","Radioterapia hepática exclusiva."],"answer_index":1,"correct_text":"Resección del primario y de la metástasis hepática (simultánea o escalonada) con quimioterapia perioperatoria, en centro con experiencia: la metástasis hepática resecable puede ser curable.","explanation":"La metástasis hepática resecable en colorrectal es potencialmente curable con resección + quimio perioperatoria; es un error tratarla como paliativa de entrada. **A es incorrecta:** renuncia a la curación. **C es incorrecta:** dejar la metástasis no es curativo. **D es incorrecta:** la radioterapia no sustituye la resección en metástasis resecable.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-09","number":159,"title":"Cáncer colorrectal · caso 9","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Hombre de 50 años con antecedente familiar de cáncer colorrectal (padre a los 45, hermano a los 48) y pólipos múltiples.","questions":[{"id":"puem-r2-cc-r3-03-09-q1","ordinal":1,"stem":"¿Qué síndrome se sospecha y qué estudio se pide?","options":["No hay síndrome, es coincidencia.","Solo se pide CEA.","Poliposis adenomatosa familiar: estudio genético APC y colonoscopia de vigilancia; el síndrome de Lynch se sospecha más por cáncer sin poliposis y se estudia con MSI/MMR e inmunohistoquímica.","Síndrome de Lynch: estudio genético APC."],"answer_index":2,"correct_text":"Poliposis adenomatosa familiar: estudio genético APC y colonoscopia de vigilancia; el síndrome de Lynch se sospecha más por cáncer sin poliposis y se estudia con MSI/MMR e inmunohistoquímica.","explanation":"Pólipos múltiples + historia familiar temprana sugieren PAF (APC); Lynch es cáncer colorrectal hereditario no polipósico (MSI/MMR). La distinción es el punto del caso. **D es incorrecta:** Lynch no se estudia con APC. **A es incorrecta:** la agregación familiar temprana no es coincidencia. **B es incorrecta:** el CEA no diagnostica síndromes hereditarios.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r3-03-10","number":160,"title":"Cáncer colorrectal · caso 10","topic":"Colon y Apéndice","topicId":"colon","nivel":"R3","context":"Paciente con cáncer de recto inferior a 3 cm del margen anal, T2 N0, esfínter comprometido por el tumor.","questions":[{"id":"puem-r2-cc-r3-03-10-q1","ordinal":1,"stem":"¿Cuál es la cirugía indicada?","options":["Resección abdominoperineal (operación de Miles) con colostomía definitiva, porque no se puede lograr margen distal libre con preservación esfinteriana.","Escisión transanal local.","Solo radioterapia.","Resección anterior baja con anastomosis coloanal."],"answer_index":0,"correct_text":"Resección abdominoperineal (operación de Miles) con colostomía definitiva, porque no se puede lograr margen distal libre con preservación esfinteriana.","explanation":"Tumor a 3 cm con esfínter comprometido: no hay preservación esfinteriana oncológicamente segura; Miles con colostomía definitiva es la opción. **D es incorrecta:** la anastomosis coloanal con esfínter invadido deja margen positivo. **B es incorrecta:** la escisión local no es para T2 con esfínter comprometido. **C es incorrecta:** la radioterapia sola no es curativa aquí.","topic":"Colon y Apéndice"}]},{"id":"puem-r2-cc-r2-11-01","number":161,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 1","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Hombre de 62 años con rectorragia de 3 meses, tenesmo y cambio del hábito intestinal. Tacto rectal: masa ulcerada en recto medio, a 7 cm del margen anal, ocupa 50% de la circunferencia, móvil. Colonoscopia: adenocarcinoma moderadamente diferenciado. Resonancia magnética de pelvis: T3, 2 ganglios mesorrectales, fascia mesorrectal libre, margen circunferencial de 3 mm. TC de tórax y abdomen sin metástasis.","questions":[{"id":"puem-r2-cc-r2-11-01-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Quimiorradioterapia neoadyuvante seguida de resección anterior baja con escisión total del mesorrecto.","Resección anterior baja inmediata sin neoadyuvancia.","Resección abdominoperineal inmediata con colostomía definitiva.","Resección local transanal (TAMIS) como tratamiento definitivo."],"answer_index":0,"correct_text":"Quimiorradioterapia neoadyuvante seguida de resección anterior baja con escisión total del mesorrecto.","explanation":"Es un cáncer de recto medio localmente avanzado (T3N1) y el estándar es terapia neoadyuvante seguida de cirugía con escisión total del mesorrecto, que reduce la recurrencia local y permite preservación esfinteriana. B es incorrecta: operar de entrada un T3N1 aumenta el riesgo de recurrencia local. C es incorrecta: a 7 cm, con esfínter libre, es candidato a preservación esfinteriana; la amputación no es obligada. D es incorrecta: la resección local es para T1 seleccionados, no para T3N1.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r2-11-02","number":162,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 2","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Mujer de 48 años, VIH positiva, con masa anal dolorosa, sangrado y adenopatía inguinal derecha de 2 cm. Biopsia: carcinoma epidermoide de canal anal, bien diferenciado. Resonancia: tumor de 3.5 cm, sin invasión a órganos vecinos, ganglio inguinal sospechoso. Sin metástasis a distancia.","questions":[{"id":"puem-r2-cc-r2-11-02-q1","ordinal":1,"stem":"¿Cuál es el tratamiento inicial de elección?","options":["Quimioterapia sola con cisplatino.","Quimiorradioterapia con 5-fluorouracilo y mitomicina (protocolo Nigro).","Resección abdominoperineal inmediata.","Hemorroidectomía y vigilancia."],"answer_index":1,"correct_text":"Quimiorradioterapia con 5-fluorouracilo y mitomicina (protocolo Nigro).","explanation":"El carcinoma epidermoide de ano se trata de entrada con quimiorradioterapia, que logra curación con preservación del esfínter en la mayoría de los casos. C es incorrecta: la amputación se reserva para persistencia o recurrencia tras quimiorradioterapia. D es incorrecta: no es una hemorroide y la resección local no trata el cáncer anal. A es incorrecta: la quimioterapia sola sin radioterapia es inferior al tratamiento combinado.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r2-11-03","number":163,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 3","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Hombre de 35 años con dolor anal intenso tipo cortante al defecar desde hace 6 semanas, sangrado escaso en el papel, estreñimiento. Exploración: fisura posterior en línea media, plicoma centinela, papila hipertrófica, esfínter hipertónico. No hay masa ni secreción.","questions":[{"id":"puem-r2-cc-r2-11-03-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo inicial más adecuado?","options":["Fístula perianal; fistulotomía inmediata.","Fisura anal aguda; esfinterotomía lateral interna de urgencia.","Fisura anal crónica; fibra, laxantes, baños de asiento y nitroglicerina tópica o bloqueador de calcio tópico.","Hemorroides grado III; ligadura con banda elástica inmediata."],"answer_index":2,"correct_text":"Fisura anal crónica; fibra, laxantes, baños de asiento y nitroglicerina tópica o bloqueador de calcio tópico.","explanation":"Los hallazgos (fisura posterior, plicoma centinela, papila hipertrófica, más de 6 semanas) definen fisura crónica, perpetuada por hipertonía esfinteriana; el manejo inicial es conservador más relajante tópico del esfínter interno. D es incorrecta: no hay prolapso hemorroidal descrito. A es incorrecta: no hay orificio externo ni trayecto fistuloso. B es incorrecta: la esfinterotomía es de segunda línea tras fracaso del tratamiento médico y tiene riesgo de incontinencia; no es de urgencia.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r2-11-04","number":164,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 4","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Hombre de 42 años con dolor perianal pulsátil de 3 días, fiebre de 38.5 °C, induración y eritema perianal derecho, sin fluctuación clara. Leucocitos 16,000/µL. Antecedente de absceso perianal hace 1 año.","questions":[{"id":"puem-r2-cc-r2-11-04-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Antibióticos orales por 10 días y revaloración si no mejora.","Incisión y drenaje en consultorio sin anestesia.","Baños de asiento y analgésicos, con drenaje solo si se forma fluctuación.","Drenaje quirúrgico urgente del absceso bajo anestesia, con exploración del trayecto."],"answer_index":3,"correct_text":"Drenaje quirúrgico urgente del absceso bajo anestesia, con exploración del trayecto.","explanation":"El absceso perianal es una urgencia quirúrgica: el drenaje oportuno bajo anestesia adecuada evita progresión, sepsis y formación de fístula; los antibióticos solos no drenan la colección. A es incorrecta: retrasa el drenaje y no resuelve el absceso. B es incorrecta: el drenaje sin anestesia adecuada es incompleto y doloroso. C es incorrecta: esperar a la fluctuación retrasa el tratamiento en un absceso profundo.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r2-11-05","number":165,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 5","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Mujer de 58 años con cáncer de recto bajo, tumor a 3 cm del margen anal, T3N0, que invade el esfínter interno en resonancia magnética. Recibió quimiorradioterapia neoadyuvante con buena respuesta parcial. El esfínter externo está libre pero el tumor está muy bajo.","questions":[{"id":"puem-r2-cc-r2-11-05-q1","ordinal":1,"stem":"¿Cuál es la opción quirúrgica más adecuada?","options":["Resección abdominoperineal con colostomía definitiva.","Resección anterior baja con anastomosis coloanal e ileostomía temporal.","Resección local transanal como tratamiento definitivo.","Vigilancia y espera sin cirugía porque hubo respuesta parcial."],"answer_index":0,"correct_text":"Resección abdominoperineal con colostomía definitiva.","explanation":"Con invasión esfinteriana y tumor a 3 cm, la preservación esfinteriana no es oncológicamente segura; la resección abdominoperineal con colostomía definitiva es la opción adecuada. B es incorrecta: una anastomosis coloanal con esfínter invadido deja enfermedad y mala función. C es incorrecta: la resección local no es adecuada para T3 con invasión esfinteriana. D es incorrecta: la vigilancia y espera requiere respuesta clínica completa y protocolo estricto, no respuesta parcial.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r2-11-06","number":166,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 6","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Hombre de 50 años con sangrado rectal rojo brillante indoloro al defecar desde hace 2 meses, sin dolor, sin prolapso. Anososcopia: hemorroides internas grado II. Hb 13.5 g/dL, sin pérdida de peso.","questions":[{"id":"puem-r2-cc-r2-11-06-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta antes de atribuir todo a hemorroides?","options":["Dar hierro oral y vigilar el sangrado.","Colonoscopia completa para descartar cáncer colorrectal o lesiones proximales.","Ligadura con banda elástica inmediata sin más estudios por la edad.","Hemorroidectomía inmediata."],"answer_index":1,"correct_text":"Colonoscopia completa para descartar cáncer colorrectal o lesiones proximales.","explanation":"Aunque las hemorroides explican el sangrado, a los 50 años con sangrado rectal debe descartarse cáncer colorrectal con colonoscopia completa; atribuirlo sin estudiarlo es un error grave. C es incorrecta: la ligadura puede ser parte del tratamiento hemorroidal, pero no sustituye el estudio. D es incorrecta: no hay indicación de hemorroidectomía en grado II sin fracaso previo. A es incorrecta: no hay anemia y el hierro no descarta una neoplasia.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r2-11-07","number":167,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 7","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Mujer de 39 años con enfermedad de Crohn, con secreción purulenta crónica por un orificio perianal a 3 cm del ano, episodios de absceso recurrente. Resonancia magnética: fístula transesfinteriana alta con trayecto complejo y absceso asociado.","questions":[{"id":"puem-r2-cc-r2-11-07-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Antibióticos solos por 6 semanas sin cirugía.","Resección abdominoperineal.","Drenaje del absceso, colocación de setón y manejo médico de la enfermedad de Crohn, con técnica de preservación esfinteriana; no fistulotomía amplia.","Fistulotomía amplia inmediata del trayecto completo."],"answer_index":2,"correct_text":"Drenaje del absceso, colocación de setón y manejo médico de la enfermedad de Crohn, con técnica de preservación esfinteriana; no fistulotomía amplia.","explanation":"En fístula compleja alta y en Crohn, la fistulotomía amplia sacrifica esfínter y causa incontinencia; el manejo es drenaje, setón, control de la enfermedad de base y técnica de preservación esfinteriana. D es incorrecta por el alto riesgo de incontinencia. A es incorrecta: los antibióticos no cierran la fístula ni drenan el absceso. B es incorrecta: es una cirugía radical injustificada para una fístula benigna.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r2-11-08","number":168,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 8","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Hombre de 66 años con cáncer de recto T2N0M0, tumor de 2 cm, bien diferenciado, a 10 cm del margen anal, sin invasión linfovascular en biopsia, móvil. Resonancia: T2, sin ganglios, fascia libre.","questions":[{"id":"puem-r2-cc-r2-11-08-q1","ordinal":1,"stem":"¿Cuál es una opción razonable?","options":["Quimiorradioterapia neoadyuvante obligatoria en todos los T2N0.","Resección abdominoperineal obligatoria por ser recto.","Vigilancia sin tratamiento porque es T2.","Resección anterior baja con escisión total del mesorrecto, o resección local transanal en un paciente muy seleccionado con vigilancia estrecha."],"answer_index":3,"correct_text":"Resección anterior baja con escisión total del mesorrecto, o resección local transanal en un paciente muy seleccionado con vigilancia estrecha.","explanation":"En T2N0 de recto alto, la resección anterior baja con escisión total del mesorrecto es el estándar; la resección local es una opción en tumores pequeños, bien diferenciados y sin factores de riesgo, con vigilancia estrecha y aceptando el riesgo de ganglios ocultos. A es incorrecta: la neoadyuvancia no es obligatoria en T2N0. B es incorrecta: a 10 cm es candidato a preservación esfinteriana. C es incorrecta: requiere tratamiento, no vigilancia.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r2-11-09","number":169,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 9","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Hombre de 29 años con masa perianal azulada, tensa y muy dolorosa de inicio súbito hace 12 horas, tras esfuerzo defecatorio. Sin fiebre, sin secreción. Exploración: hemorroide externa trombosada de 2 cm.","questions":[{"id":"puem-r2-cc-r2-11-09-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Escisión del trombo bajo anestesia local por el dolor intenso y la presentación en las primeras 72 horas, o manejo conservador con analgesia y baños de asiento si el dolor es tolerable.","Antibióticos intravenosos y drenaje quirúrgico amplio bajo anestesia general.","Ligadura con banda elástica de la hemorroide externa.","Esfinterotomía lateral interna de urgencia."],"answer_index":0,"correct_text":"Escisión del trombo bajo anestesia local por el dolor intenso y la presentación en las primeras 72 horas, o manejo conservador con analgesia y baños de asiento si el dolor es tolerable.","explanation":"En las primeras 72 horas, la escisión del trombo bajo anestesia local alivia el dolor rápidamente; el manejo conservador también es válido si el dolor es tolerable, y después de 72 horas suele preferirse. B es incorrecta: no hay infección ni absceso. C es incorrecta: la ligadura es para hemorroides internas, no externas trombosadas. D es incorrecta: no hay fisura ni indicación de esfinterotomía.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r2-11-10","number":170,"title":"Cáncer de recto y ano, y patología anorrectal benigna (hemorroides, fisura anal, fístula y absceso perianal) · caso 10","topic":"Recto y Ano","topicId":"recto","nivel":"R2","context":"Mujer de 61 años, 18 meses después de resección anterior baja por cáncer de recto T3N1, con quimiorradioterapia neoadyuvante y adyuvancia completa. Acude por urgencia fecal, evacuaciones fragmentadas en 5-6 ocasiones al día, incontinencia ocasional a gases y tenesmo. Sin sangrado, sin pérdida de peso. ACE normal, colonoscopia sin recurrencia.","questions":[{"id":"puem-r2-cc-r2-11-10-q1","ordinal":1,"stem":"¿Cuál es la explicación más probable?","options":["Fístula rectovaginal.","Colitis por radioterapia activa con sangrado.","Síndrome de resección anterior baja por pérdida del reservorio rectal y disfunción esfinteriana y nerviosa.","Recurrencia local del cáncer de recto."],"answer_index":2,"correct_text":"Síndrome de resección anterior baja por pérdida del reservorio rectal y disfunción esfinteriana y nerviosa.","explanation":"El cuadro es el síndrome de resección anterior baja: urgencia, fragmentación, incontinencia a gases y tenesmo tras resección rectal, por pérdida del reservorio y alteración de la función anorrectal; la colonoscopia sin recurrencia y el ACE normal apoyan que no es recurrencia. D es incorrecta: no hay masa ni ACE elevado y la colonoscopia es normal. A es incorrecta: no hay salida de heces o gases por vagina. B es incorrecta: no hay sangrado ni diarrea con sangre que sugiera proctitis activa.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-01","number":171,"title":"Cirugía colorrectal avanzada · caso 1","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Hombre 68 años, cáncer de recto medio, RM: T3, fascia mesorrectal comprometida, N+.","questions":[{"id":"puem-r2-cc-r4-04-01-q1","ordinal":1,"stem":"¿Plan?","options":["Terapia neoadyuvante total (quimiorradiación/quimio) y luego TME, según NCCN","Solo radioterapia paliativa","Watch-and-wait sin tratamiento","Cirugía directa sin neoadyuvancia"],"answer_index":0,"correct_text":"Terapia neoadyuvante total (quimiorradiación/quimio) y luego TME, según NCCN","explanation":"Recto localmente avanzado con fascia comprometida: neoadyuvancia (TNT) antes de TME mejora R0 y control local. Operar directo arriesga margen positivo; watch-and-wait exige respuesta completa tras neoadyuvancia.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-02","number":172,"title":"Cirugía colorrectal avanzada · caso 2","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Mujer 55 años, diverticulitis Hinchey IV, peritonitis fecal, choque séptico.","questions":[{"id":"puem-r2-cc-r4-04-02-q1","ordinal":1,"stem":"¿Cirugía?","options":["Lavado laparoscópico","Hartmann (resección + colostomía terminal)","Resección con anastomosis primaria sin protección","Solo antibiótico"],"answer_index":1,"correct_text":"Hartmann (resección + colostomía terminal)","explanation":"Hinchey IV + choque: Hartmann es la opción segura (control del foco, sin anastomosis en paciente inestable). El lavado no controla peritonitis fecal; anastomosis primaria en choque es temeraria.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-03","number":173,"title":"Cirugía colorrectal avanzada · caso 3","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Hombre 40 años, CUCI grave refractaria a tratamiento médico, megacolon tóxico.","questions":[{"id":"puem-r2-cc-r4-04-03-q1","ordinal":1,"stem":"¿Cirugía?","options":["Solo esteroides altas dosis indefinidas","Alta con mesalazina","Colectomía subtotal con ileostomía terminal (cirugía en 2-3 tiempos)","Reservorio ileoanal (J-pouch) en la misma cirugía urgente"],"answer_index":2,"correct_text":"Colectomía subtotal con ileostomía terminal (cirugía en 2-3 tiempos)","explanation":"En CUCI grave/megacolon, la colectomía subtotal con ileostomía es la cirugía de urgencia segura; el pouch se difiere. Hacer pouch en paciente grave y séptico es de alto riesgo.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-04","number":174,"title":"Cirugía colorrectal avanzada · caso 4","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Postcolectomía día 5, fiebre, taquicardia, dolor, leucocitosis, drenaje turbio. TC no concluyente.","questions":[{"id":"puem-r2-cc-r4-04-04-q1","ordinal":1,"stem":"¿Conducta?","options":["Alta con antibiótico oral","Retirar drenaje","Esperar a que la TC sea concluyente","Sospechar fuga anastomótica y explorar quirúrgicamente si hay deterioro"],"answer_index":3,"correct_text":"Sospechar fuga anastomótica y explorar quirúrgicamente si hay deterioro","explanation":"La fuga se sospecha por clínica antes de confirmarse por imagen; la TC tiene falsos negativos. Esperar con deterioro aumenta mortalidad; explorar es la decisión R4 correcta.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-05","number":175,"title":"Cirugía colorrectal avanzada · caso 5","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Hombre 72 años, cáncer de colon derecho, obstrucción completa, estable.","questions":[{"id":"puem-r2-cc-r4-04-05-q1","ordinal":1,"stem":"¿Plan?","options":["Colectomía derecha de urgencia con estadificación, según comité y estado","Solo descompresión nasogástrica indefinida","Colonoscopia terapéutica curativa","Stent colónico como puente siempre"],"answer_index":0,"correct_text":"Colectomía derecha de urgencia con estadificación, según comité y estado","explanation":"Obstrucción de colon derecho: la cirugía (colectomía) es lo habitual; el stent como puente es más para colon izquierdo y casos seleccionados. Descomprimir sin resolver perpetúa isquemia.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-06","number":176,"title":"Cirugía colorrectal avanzada · caso 6","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Mujer 35 años, Crohn ileal estenosante B2, obstrucción recurrente, sin sepsis.","questions":[{"id":"puem-r2-cc-r4-04-06-q1","ordinal":1,"stem":"¿Estrategia?","options":["Colectomía total","Resección conservadora del segmento estenótico, preservando intestino","Resección amplia de 1 metro de íleon sano","Solo esteroides de por vida"],"answer_index":1,"correct_text":"Resección conservadora del segmento estenótico, preservando intestino","explanation":"En Crohn, la cirugía conserva intestino: resección limitada del segmento enfermo (o estricturoplastia). Resecar amplio genera intestino corto; los esteroides no resuelven una estenosis fibrótica.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-07","number":177,"title":"Cirugía colorrectal avanzada · caso 7","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Cáncer rectal bajo, respuesta clínica completa tras neoadyuvancia, paciente apto.","questions":[{"id":"puem-r2-cc-r4-04-07-q1","ordinal":1,"stem":"¿Opción válida?","options":["Solo quimioterapia adyuvante","Alta sin seguimiento","Watch-and-wait en protocolo/centro experto con vigilancia estrecha","TME obligatoria siempre sin excepción"],"answer_index":2,"correct_text":"Watch-and-wait en protocolo/centro experto con vigilancia estrecha","explanation":"La respuesta completa permite watch-and-wait en protocolo con vigilancia estrecha (NCCN, centros expertos). No es 'no tratar': es vigilancia intensiva con rescate quirúrgico si recurre.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-08","number":178,"title":"Cirugía colorrectal avanzada · caso 8","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Hombre con diverticulitis Hinchey III, peritonitis purulenta, estable.","questions":[{"id":"puem-r2-cc-r4-04-08-q1","ordinal":1,"stem":"¿Opción aceptada?","options":["Hartmann obligatorio siempre","Solo antibiótico","Resección con anastomosis sin valorar estabilidad","Lavado laparoscópico con drenaje, en paciente estable y seleccionado (WSES)"],"answer_index":3,"correct_text":"Lavado laparoscópico con drenaje, en paciente estable y seleccionado (WSES)","explanation":"Hinchey III estable: el lavado laparoscópico es opción aceptada en seleccionados; Hartmann también lo es. La clave es estabilidad y selección, no un dogma único.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-09","number":179,"title":"Cirugía colorrectal avanzada · caso 9","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Paciente con cáncer de colon, CEA 120, TC: metástasis hepáticas bilobares.","questions":[{"id":"puem-r2-cc-r4-04-09-q1","ordinal":1,"stem":"¿Primer paso?","options":["Estudio completo (MSI/MMR, RAS/BRAF), comité multidisciplinario y plan perioperatorio","Solo CEA seriado","Quimioterapia sin biopsia","Colectomía urgente sin estadificar"],"answer_index":0,"correct_text":"Estudio completo (MSI/MMR, RAS/BRAF), comité multidisciplinario y plan perioperatorio","explanation":"El cáncer metastásico exige histología, biología molecular y comité antes de decidir secuencia (cirugía/quimio). Operar sin estadificar pierde la estrategia; tratar sin biopsia es inaceptable.","topic":"Recto y Ano"}]},{"id":"puem-r2-cc-r4-04-10","number":180,"title":"Cirugía colorrectal avanzada · caso 10","topic":"Recto y Ano","topicId":"recto","nivel":"R4","context":"Mujer post-TME, incontinencia y urgencia defecatoria grave.","questions":[{"id":"puem-r2-cc-r4-04-10-q1","ordinal":1,"stem":"¿Qué es?","options":["Recurrencia tumoral segura","Normal, sin tratamiento","Síndrome de resección anterior baja (LARS); rehabilitación, dieta, fármacos y seguimiento","Fuga anastomótica aguda"],"answer_index":2,"correct_text":"Síndrome de resección anterior baja (LARS); rehabilitación, dieta, fármacos y seguimiento","explanation":"LARS es la disfunción intestinal tras TME: urgencia, fragmentación e incontinencia. Requiere rehabilitación y seguimiento, no es 'normal' ni equivale a recurrencia sin estudio.","topic":"Recto y Ano"}]},{"id":"puem-r3-cc-r2-08-01","number":1,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 1","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Varón de 62 años, con antecedente de apendicectomía y colecistectomía, con dolor cólico central, distensión, vómito bilioso y ausencia de evacuaciones de 24 horas. Exploración: distensión, ruidos hiperactivos, sin peritonismo, sin tumoración herniaria. Leucocitos 9,500/µL, lactato 1.1 mmol/L. Radiografía: niveles hidroaéreos en intestino delgado. Tomografía: punto de transición en íleon por adherencia, sin falta de reforzamiento ni neumatosis.","questions":[{"id":"puem-r3-cc-r2-08-01-q1","ordinal":1,"stem":"¿Cuál es el manejo inicial más adecuado?","options":["Laparotomía inmediata por obstrucción completa","Ayuno, sonda nasogástrica, líquidos, corrección electrolítica y contraste hidrosoluble, con vigilancia estrecha de datos de estrangulación","Colonoscopia urgente para destorsión","Alta con laxantes y dieta líquida"],"answer_index":1,"correct_text":"Ayuno, sonda nasogástrica, líquidos, corrección electrolítica y contraste hidrosoluble, con vigilancia estrecha de datos de estrangulación","explanation":"Es una obstrucción adhesiva de intestino delgado sin datos de isquemia: dolor cólico, sin peritonismo, leucocitos y lactato normales, tomografía sin signos de sufrimiento vascular. El manejo inicial conservador con sonda, líquidos y contraste hidrosoluble es el estándar, con cirugía si no resuelve en 48 a 72 horas o si aparece deterioro. A opera de entrada una obstrucción simple que suele resolver sin cirugía. C no tiene papel en intestino delgado. D es insegura y no trata la deshidratación ni vigila la isquemia.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-08-02","number":2,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 2","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Mujer de 78 años con fibrilación auricular sin anticoagulación, con dolor abdominal súbito e intenso de 4 horas, vómito y diarrea con sangre. Exploración: abdomen blando, doloroso de forma difusa, sin peritonismo, ruidos disminuidos. Leucocitos 18,000/µL, lactato 4.8 mmol/L, pH 7.28. Angiotomografía: oclusión de la arteria mesentérica superior a 4 cm de su origen.","questions":[{"id":"puem-r3-cc-r2-08-02-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y la conducta?","options":["Isquemia mesentérica aguda embólica; reanimación, cirugía de urgencia con embolectomía/revascularización y resección de lo necrótico","Colitis isquémica leve; ayuno y antibiótico oral","Obstrucción adhesiva; sonda nasogástrica y observación","Pancreatitis aguda; manejo conservador y analgesia"],"answer_index":0,"correct_text":"Isquemia mesentérica aguda embólica; reanimación, cirugía de urgencia con embolectomía/revascularización y resección de lo necrótico","explanation":"Dolor desproporcionado a la exploración, fibrilación auricular, lactato y leucocitos elevados, acidosis y oclusión de la mesentérica superior en angiotomografía: isquemia mesentérica aguda embólica. Es una urgencia con mortalidad alta; requiere reanimación y revascularización urgente más resección del intestino no viable y second look. D no explica la oclusión vascular ni la diarrea sanguinolenta. C subestima una oclusión arterial mayor. C no corresponde: no hay punto de transición obstructivo ni antecedente quirúrgico relevante.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-08-03","number":3,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 3","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Varón de 84 años, encamado, con estreñimiento crónico y demencia, con distensión abdominal masiva de 3 días, dolor leve y estreñimiento total. Tacto rectal: ampolla vacía, sin sangre. Radiografía: asa colónica gigante en forma de grano de café que asciende desde la pelvis. Signos vitales estables, sin fiebre, leucocitos 10,000/µL, lactato 1.3 mmol/L.","questions":[{"id":"puem-r3-cc-r2-08-03-q1","ordinal":1,"stem":"¿Cuál es el manejo inicial?","options":["Enema de bario terapéutico","Laxantes y dieta alta en fibra","Laparotomía inmediata con hemicolectomía","Destorsión endoscópica con sigmoidoscopia y sonda rectal, y planear sigmoidectomía electiva en el mismo ingreso"],"answer_index":3,"correct_text":"Destorsión endoscópica con sigmoidoscopia y sonda rectal, y planear sigmoidectomía electiva en el mismo ingreso","explanation":"Vólvulo sigmoideo no complicado: anciano con estreñimiento crónico, distensión masiva, signo del grano de café, ampolla vacía, sin peritonitis ni datos de isquemia. La destorsión endoscópica es el tratamiento inicial y la sigmoidectomía electiva en el mismo ingreso previene la recurrencia, que es muy alta sin resección. A es excesiva sin peritonitis ni necrosis. A no es el método de destorsión en el adulto y retrasa el tratamiento. B no resuelve un vólvulo establecido.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-08-04","number":4,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 4","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Mujer de 45 años con dolor en fosa iliaca derecha de 12 horas, distensión, vómito y fiebre de 38.5 °C. Leucocitos 15,000/µL. Se piensa en apendicitis, pero la tomografía muestra ciego dilatado y desplazado a la izquierda, con signo del remolino en el mesenterio y falta de reforzamiento de la pared cecal.","questions":[{"id":"puem-r3-cc-r2-08-04-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Vólvulo sigmoideo; destorsión endoscópica","Apendicitis complicada; apendicectomía laparoscópica","Vólvulo cecal con isquemia; cirugía de urgencia con hemicolectomía derecha","Enfermedad de Crohn; esteroides intravenosos"],"answer_index":2,"correct_text":"Vólvulo cecal con isquemia; cirugía de urgencia con hemicolectomía derecha","explanation":"Vólvulo cecal con signos de isquemia: ciego desplazado, signo del remolino y falta de reforzamiento. El vólvulo cecal simula apendicitis pero casi siempre requiere cirugía, y con isquemia la hemicolectomía derecha es lo indicado. A operaría el órgano equivocado y dejaría el ciego necrótico. D no explica el remolino ni la falta de reforzamiento. D es otro segmento y otro manejo.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-08-05","number":5,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 5","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Varón de 58 años con choque séptico por neumonía, en vasopresor, con distensión abdominal, íleo y dolor difuso leve. Lactato 5.5 mmol/L, leucocitos 20,000/µL. Angiotomografía: arterias mesentéricas permeables, sin oclusión, con intestino engrosado y falta de reforzamiento segmentario.","questions":[{"id":"puem-r3-cc-r2-08-05-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable?","options":["Colecistitis enfisematosa","Isquemia mesentérica no oclusiva por bajo gasto y vasoconstricción","Trombosis venosa mesentérica por hipercoagulabilidad","Obstrucción por tumor de colon no visto"],"answer_index":1,"correct_text":"Isquemia mesentérica no oclusiva por bajo gasto y vasoconstricción","explanation":"Isquemia mesentérica no oclusiva: paciente en choque con vasopresor, vasos permeables en angiotomografía pero con signos de hipoperfusión intestinal. El tratamiento es optimizar el gasto, retirar vasoconstrictores en lo posible e infundir vasodilatador mesentérico, además de cirugía si hay necrosis. B cursaría con oclusión venosa visible y edema marcado. C daría un punto de transición obstructivo. A no explica el cuadro sistémico ni la tomografía.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-08-06","number":6,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 6","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Mujer de 66 años con dolor abdominal, distensión y vómito fecaloide de 48 horas. Exploración: distensión, cicatriz de laparotomía media, hernia incisional dolorosa e irreductible en la cicatriz. Leucocitos 13,000/µL, lactato 2.6 mmol/L. Tomografía: asa de intestino delgado atrapada en el defecto incisional, con falta de reforzamiento.","questions":[{"id":"puem-r3-cc-r2-08-06-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Cirugía de urgencia: liberación, valoración de viabilidad, resección si hay necrosis y reparación herniaria según contaminación","Reducción manual de la hernia en urgencias y alta","Colonoscopia para descartar tumor","Manejo conservador con sonda y contraste hidrosoluble 72 horas"],"answer_index":0,"correct_text":"Cirugía de urgencia: liberación, valoración de viabilidad, resección si hay necrosis y reparación herniaria según contaminación","explanation":"Hernia incisional incarcerada con signos de isquemia: asa atrapada sin reforzamiento, lactato elevado, dolor e irreductibilidad. Es una obstrucción estrangulada y requiere cirugía inmediata; el manejo conservador y la reducción manual son inseguros y pueden devolver intestino necrótico. D retrasa una urgencia.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-08-07","number":7,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 7","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Varón de 70 años con aterosclerosis difusa, dolor abdominal posprandial de 45 minutos, miedo a comer y pérdida de 12 kg en 6 meses. Sin diarrea ni fiebre. Angiotomografía: estenosis grave de tronco celiaco y de arteria mesentérica superior.","questions":[{"id":"puem-r3-cc-r2-08-07-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento definitivo?","options":["Úlcera péptica; inhibidor de bomba de protones","Cáncer gástrico; gastrectomía","Isquemia aguda embólica; embolectomía de urgencia","Isquemia mesentérica crónica; revascularización mesentérica"],"answer_index":3,"correct_text":"Isquemia mesentérica crónica; revascularización mesentérica","explanation":"La tríada de dolor posprandial, miedo a comer y pérdida de peso con estenosis de dos vasos mesentéricos es isquemia mesentérica crónica o angina intestinal. El tratamiento definitivo es la revascularización —angioplastia con stent o bypass— y el control de factores vasculares. A y B no explican la estenosis vascular ni el patrón posprandial. D es un cuadro agudo con oclusión súbita, no crónico con pérdida de peso de meses.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-08-08","number":8,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 8","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Mujer de 60 años con dolor en fosa iliaca izquierda, diarrea sanguinolenta y urgencia de 2 días, tras hipotensión por hemorragia digestiva. Sin fiebre alta, leucocitos 12,000/µL, lactato 1.8 mmol/L. Colonoscopia: mucosa edematosa, pálida, con úlceras superficiales en colon descendente y ángulo esplénico, sin necrosis transmural.","questions":[{"id":"puem-r3-cc-r2-08-08-q1","ordinal":1,"stem":"¿Cuál es el manejo?","options":["Angioplastia mesentérica urgente","Colectomía total de urgencia","Ayuno, líquidos intravenosos, antibiótico, corrección de la hipotensión y vigilancia, con colonoscopia de control","Mesalazina y esteroides por colitis ulcerosa"],"answer_index":2,"correct_text":"Ayuno, líquidos intravenosos, antibiótico, corrección de la hipotensión y vigilancia, con colonoscopia de control","explanation":"Colitis isquémica no gangrenosa en zona limítrofe tras hipotensión: dolor izquierdo, diarrea sanguinolenta, mucosa pálida y ulcerada sin necrosis. El manejo es conservador: ayuno, líquidos, antibiótico y corregir la causa de la hipoperfusión, con vigilancia por si progresa a gangrena. A es excesiva sin necrosis ni peritonitis. C trata una enfermedad inflamatoria que no es el diagnóstico. D se reserva para isquemia mesentérica aguda o crónica con oclusión mayor, no para colitis isquémica no gangrenosa.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-08-09","number":9,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 9","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Varón de 50 años, operado de laparotomía por trauma hace 5 días, con distensión, ausencia de evacuaciones y vómito. Leucocitos 11,000/µL, potasio 3.1 mEq/L, sin fiebre, abdomen blando sin peritonismo. Radiografía: distensión difusa de intestino delgado y colon con gas en todo el trayecto.","questions":[{"id":"puem-r3-cc-r2-08-09-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable?","options":["Obstrucción mecánica por adherencias tempranas; laparotomía inmediata","Íleo paralítico posoperatorio con hipopotasemia; corregir electrolitos, ayuno, sonda nasogástrica y deambulación","Isquemia mesentérica aguda; angiotomografía urgente","Dehiscencia de anastomosis; reintervención inmediata"],"answer_index":1,"correct_text":"Íleo paralítico posoperatorio con hipopotasemia; corregir electrolitos, ayuno, sonda nasogástrica y deambulación","explanation":"Íleo posoperatorio: distensión difusa con gas en todo el intestino, sin punto de transición, abdomen blando, hipopotasemia que lo perpetúa. El manejo es conservador y de soporte, corrigiendo electrolitos. A requiere un punto de transición y datos de obstrucción mecánica. C daría dolor desproporcionado, lactato elevado y signos vasculares. D cursaría con fiebre, taquicardia, dolor y salida por drenajes.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-08-10","number":10,"title":"Obstrucción intestinal, vólvulo e isquemia intestinal · caso 10","topic":"Obstrucción intestinal y hemorragia digestiva baja","topicId":"ap-r3-intestino","nivel":"R2","context":"Mujer de 55 años con trombosis venosa mesentérica confirmada por tomografía, dolor abdominal moderado de 3 días, sin peritonismo, leucocitos 13,000/µL, lactato 1.9 mmol/L. Antecedente de trombofilia.","questions":[{"id":"puem-r3-cc-r2-08-10-q1","ordinal":1,"stem":"¿Cuál es el pilar del tratamiento?","options":["Laparotomía inmediata con resección amplia de intestino","Embolectomía arterial de urgencia","Trombólisis sistémica en todos los casos","Anticoagulación sistémica inmediata y vigilancia; cirugía solo si hay infarto o peritonitis"],"answer_index":3,"correct_text":"Anticoagulación sistémica inmediata y vigilancia; cirugía solo si hay infarto o peritonitis","explanation":"En la trombosis venosa mesentérica sin peritonitis ni infarto, el pilar es la anticoagulación para evitar la progresión y permitir la recanalización; la cirugía se reserva para infarto, perforación o peritonitis. B reseca intestino que aún es viable. C es para oclusión arterial, no venosa. C no es el tratamiento de primera línea en todos los casos y tiene riesgo hemorrágico.","topic":"Obstrucción intestinal y hemorragia digestiva baja"}]},{"id":"puem-r3-cc-r2-03-01","number":11,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 1","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Hombre de 32 años con fiebre de 39 °C, dolor en hipocondrio derecho de 10 días y antecedente de disentería hace un mes. Leucocitos 16,000/µL, fosfatasa alcalina elevada. Ultrasonido: lesión hipoecoica única de 8 cm en lóbulo derecho. Serología para Entamoeba histolytica positiva.","questions":[{"id":"puem-r3-cc-r2-03-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento inicial?","options":["Quiste hidatídico; cirugía urgente sin albendazol","Carcinoma hepatocelular; resección hepática inmediata","Absceso hepático amebiano; metronidazol más amebicida luminal, drenaje solo si no responde o hay riesgo de ruptura","Absceso piógeno; drenaje percutáneo inmediato más antibióticos sin metronidazol"],"answer_index":2,"correct_text":"Absceso hepático amebiano; metronidazol más amebicida luminal, drenaje solo si no responde o hay riesgo de ruptura","explanation":"Antecedente de disentería, lesión única en lóbulo derecho y serología amebiana positiva confirman absceso amebiano. El tratamiento es metronidazol más amebicida luminal; el drenaje no es de rutina y se reserva para falta de respuesta, gran tamaño con riesgo de ruptura o duda diagnóstica. El absceso piógeno (D) suele ser polimicrobiano, a menudo múltiple y asociado a patología biliar. El hidatídico (A) no da fiebre alta con leucocitosis de este tipo ni serología amebiana positiva. No hay datos de CHC (B).","topic":"Hígado"}]},{"id":"puem-r3-cc-r2-03-02","number":12,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 2","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Mujer de 45 años con dolor en hipocondrio derecho, fiebre e ictericia tras colangitis por coledocolitiasis. TC: lesión hipodensa de 5 cm en lóbulo derecho con realce periférico, multilocular. Hemocultivos: Escherichia coli y Klebsiella.","questions":[{"id":"puem-r3-cc-r2-03-02-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Resección hepática mayor inmediata","Observación sin antibióticos","Solo metronidazol sin drenaje","Antibióticos de amplio espectro más drenaje percutáneo guiado por imagen"],"answer_index":3,"correct_text":"Antibióticos de amplio espectro más drenaje percutáneo guiado por imagen","explanation":"Absceso piógeno secundario a colangitis, multilocular, con gérmenes entéricos: requiere antibióticos de amplio espectro más drenaje percutáneo, que es el estándar en la mayoría de los casos. Solo metronidazol (C) trata ameba, no bacterias piógenas. La resección mayor (A) no es primera línea en un absceso drenable. Observar sin antibióticos (B) dejaría una sepsis sin tratar.","topic":"Hígado"}]},{"id":"puem-r3-cc-r2-03-03","number":13,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 3","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Hombre de 55 años con cirrosis por alcohol, Child-Pugh A, sin hipertensión portal significativa. RM: lesión de 3 cm en segmento VI con realce arterial y lavado venoso, AFP 450 ng/mL. Sin metástasis.","questions":[{"id":"puem-r3-cc-r2-03-03-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento con intención curativa?","options":["Carcinoma hepatocelular; resección hepática (o ablación según localización) por BCLC temprano","Metástasis de colon; quimioterapia paliativa sola","Adenoma hepático; suspender anticonceptivos","Hemangioma; observación"],"answer_index":0,"correct_text":"Carcinoma hepatocelular; resección hepática (o ablación según localización) por BCLC temprano","explanation":"Realce arterial con lavado venoso en hígado cirrótico más AFP elevada es diagnóstico de CHC por imagen, sin necesidad de biopsia. Con Child-Pugh A y sin hipertensión portal, la resección es curativa en BCLC temprano; la ablación es alternativa en tumores pequeños según localización. El hemangioma (D) tiene realce nodular periférico progresivo, no lavado venoso. No hay antecedente de cáncer colorrectal (B). El adenoma (C) no es típico en hombre cirrótico de 55 años con este patrón de imagen.","topic":"Hígado"}]},{"id":"puem-r3-cc-r2-03-04","number":14,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 4","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Hombre de 28 años, accidente vial, hipotensión 80/50 mmHg, taquicardia 130 lpm, abdomen doloroso y distendido. FAST positivo con líquido libre. TC no posible por inestabilidad.","questions":[{"id":"puem-r3-cc-r2-03-04-q1","ordinal":1,"stem":"¿Cuál es la conducta más adecuada?","options":["TC con contraste para clasificar el grado AAST antes de decidir","Laparotomía urgente con cirugía de control de daños: packing perihepático y maniobra de Pringle si es necesario","Manejo conservador con reposo y vigilancia","Angioembolización como primer paso sin laparotomía"],"answer_index":1,"correct_text":"Laparotomía urgente con cirugía de control de daños: packing perihepático y maniobra de Pringle si es necesario","explanation":"Paciente inestable con hemoperitoneo no puede ir a TC ni manejarse conservadoramente; requiere laparotomía urgente con control de daños: compresión, packing perihepático y maniobra de Pringle para controlar el sangrado, difiriendo la cirugía definitiva. La TC (A) retrasa el control del sangrado en un paciente inestable. El manejo conservador (C) es solo para pacientes estables. La angioembolización (D) es coadyuvante tras el control inicial, no el primer paso en inestabilidad con hemoperitoneo masivo.","topic":"Hígado"}]},{"id":"puem-r3-cc-r2-03-05","number":15,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 5","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Mujer de 38 años con quiste hepático de 10 cm en lóbulo derecho, con vesículas hijas en su interior en TC y serología hidatídica positiva. Sin fiebre ni ictericia.","questions":[{"id":"puem-r3-cc-r2-03-05-q1","ordinal":1,"stem":"¿Cuál es el manejo correcto y qué debe evitarse?","options":["Drenaje percutáneo simple sin protección","Biopsia percutánea para confirmar el diagnóstico y luego observar","Cirugía conservadora con protección del campo con solución escolicida más albendazol perioperatorio; nunca biopsiar","Solo albendazol de por vida sin cirugía"],"answer_index":2,"correct_text":"Cirugía conservadora con protección del campo con solución escolicida más albendazol perioperatorio; nunca biopsiar","explanation":"Quiste con vesículas hijas y serología positiva es hidatídico. El tratamiento es quirúrgico con protección del campo para evitar siembra, más albendazol perioperatorio. La biopsia (B) está contraindicada por riesgo de anafilaxia y siembra peritoneal. Solo albendazol (D) no cura un quiste grande sintomático. El drenaje simple sin protección (A) arriesga diseminación; la técnica PAIR solo se hace en casos seleccionados con protección y albendazol.","topic":"Hígado"}]},{"id":"puem-r3-cc-r2-03-06","number":16,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 6","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Hombre de 60 años con cáncer de colon operado hace un año, ahora con tres metástasis hepáticas en lóbulo derecho, la mayor de 4 cm, resecables, sin enfermedad extrahepática. Función hepática normal, remanente hepático estimado suficiente.","questions":[{"id":"puem-r3-cc-r2-03-06-q1","ordinal":1,"stem":"¿Cuál es el manejo con intención curativa?","options":["Trasplante hepático","Solo ablación sin resección aunque sean resecables","Quimioterapia paliativa sola sin cirugía","Resección hepática de las metástasis con quimioterapia perioperatoria"],"answer_index":3,"correct_text":"Resección hepática de las metástasis con quimioterapia perioperatoria","explanation":"Metástasis hepáticas colorrectales resecables, sin enfermedad extrahepática y con remanente suficiente, se tratan con resección hepática más quimioterapia perioperatoria, la única opción potencialmente curativa. La quimioterapia sola (C) no es curativa. El trasplante (A) no es el tratamiento estándar para metástasis colorrectales. La ablación sola (B) es coadyuvante o alternativa en lesiones no resecables, no sustituto de la resección cuando esta es posible.","topic":"Hígado"}]},{"id":"puem-r3-cc-r2-03-07","number":17,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 7","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Mujer de 30 años con uso de anticonceptivos orales por 10 años, dolor en hipocondrio derecho y masa hepática de 6 cm en lóbulo izquierdo en TC, sin cirrosis. Biopsia: adenoma hepatocelular.","questions":[{"id":"puem-r3-cc-r2-03-07-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Suspender anticonceptivos y resección quirúrgica por tamaño mayor de 5 cm y riesgo de ruptura y malignización","Trasplante hepático","Quimioembolización como único tratamiento","Observación de por vida sin suspender anticonceptivos"],"answer_index":0,"correct_text":"Suspender anticonceptivos y resección quirúrgica por tamaño mayor de 5 cm y riesgo de ruptura y malignización","explanation":"Adenoma de 6 cm en mujer con anticonceptivos: debe suspenderse el anticonceptivo y resecarse por tamaño mayor de 5 cm, con riesgo de ruptura hemorrágica y de malignización a CHC. Observar (D) deja un adenoma grande con riesgo de sangrado. El trasplante (B) no está indicado. La TACE (C) no es el tratamiento del adenoma.","topic":"Hígado"}]},{"id":"puem-r3-cc-r2-03-08","number":18,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 8","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Hombre de 40 años, trauma contuso por caída, hemodinámicamente estable, sin peritonitis. TC: laceración hepática grado III de la AAST, sin sangrado activo, sin lesión de otro órgano. Hemoglobina estable en controles seriados.","questions":[{"id":"puem-r3-cc-r2-03-08-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Laparotomía inmediata con resección hepática","Manejo conservador con vigilancia estrecha, reposo, controles de hemoglobina y TC de control","Packing perihepático profiláctico","Alta inmediata sin seguimiento"],"answer_index":1,"correct_text":"Manejo conservador con vigilancia estrecha, reposo, controles de hemoglobina y TC de control","explanation":"Trauma hepático grado III en paciente estable, sin sangrado activo y con hemoglobina estable, se maneja conservadoramente con vigilancia, reposo y controles seriados; la mayoría de estas lesiones se resuelven sin cirugía. La laparotomía (A) y el packing (C) se reservan para inestabilidad o sangrado activo. El alta inmediata (D) es insegura sin vigilancia y sin TC de control.","topic":"Hígado"}]},{"id":"puem-r3-cc-r2-03-09","number":19,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 9","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Hombre de 50 años con lesión hepática de 8 cm en TC, con realce nodular periférico progresivo en fase arterial, portal y tardía, sin lavado venoso. Asintomático, pruebas hepáticas normales, sin cirrosis.","questions":[{"id":"puem-r3-cc-r2-03-09-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable?","options":["Quiste hidatídico","Carcinoma hepatocelular","Hemangioma hepático; observación sin cirugía","Absceso piógeno"],"answer_index":2,"correct_text":"Hemangioma hepático; observación sin cirugía","explanation":"Realce nodular periférico progresivo con llenado centrípeto y sin lavado es el patrón clásico del hemangioma, el tumor benigno más frecuente. Es asintomático y solo se vigila. El CHC (B) tiene realce arterial con lavado venoso. El absceso (D) cursa con fiebre, leucocitosis y realce periférico con centro hipodenso, no con este patrón vascular. El hidatídico (A) es quístico con vesículas hijas, no sólido vascular.","topic":"Hígado"}]},{"id":"puem-r3-cc-r2-03-10","number":20,"title":"Patología hepática quirúrgica: abscesos, quistes, tumores y trauma hepático · caso 10","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R2","context":"Hombre de 65 años con cirrosis por hepatitis C, Child-Pugh C, MELD 22, con CHC de 4 cm y ascitis refractaria. No es candidato a resección por función hepática.","questions":[{"id":"puem-r3-cc-r2-03-10-q1","ordinal":1,"stem":"¿Cuál es la opción con intención curativa más adecuada a valorar?","options":["Trasplante hepático si cumple criterios de Milán y no hay contraindicaciones","Quimioterapia sistémica paliativa como única opción curativa","Observación sin tratamiento","Resección hepática mayor a pesar de Child-Pugh C"],"answer_index":0,"correct_text":"Trasplante hepático si cumple criterios de Milán y no hay contraindicaciones","explanation":"En CHC con cirrosis descompensada (Child-Pugh C) la resección es insegura por riesgo de insuficiencia hepática posoperatoria; la opción curativa es el trasplante hepático, que trata el tumor y la cirrosis, si el tumor está dentro de los criterios de Milán y no hay contraindicaciones. La resección (D) en Child-Pugh C tiene mortalidad prohibitiva. La quimioterapia sistémica (B) es paliativa, no curativa, en enfermedad avanzada. Observar (C) deja sin tratar un tumor potencialmente curable con trasplante.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-01","number":21,"title":"Hígado, vía biliar y páncreas (HPB) · caso 1","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Mujer de 45 años con dolor en hipocondrio derecho de 12 h, fiebre 38.5 °C, Murphy positivo, leucocitos 14,000, ultrasonido: vesícula distendida, pared 5 mm, lito impactado en cuello.","questions":[{"id":"puem-r3-cc-r3-05-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo según TG18?","options":["Colecistitis: manejo conservador con antibióticos por 6 semanas y cirugía programada.","Colecistostomía percutánea como primera opción en todos los casos.","Cólico biliar: alta con analgésicos.","Colecistitis aguda: colecistectomía laparoscópica temprana durante el ingreso, con antibióticos."],"answer_index":3,"correct_text":"Colecistitis aguda: colecistectomía laparoscópica temprana durante el ingreso, con antibióticos.","explanation":"Es colecistitis aguda (clínica + imagen) y el estándar TG18/WSES es la colecistectomía temprana. **C es incorrecta:** el cólico biliar no tiene fiebre ni Murphy ni pared engrosada. **A es incorrecta:** el manejo conservador prolongado aumenta recurrencia y complicaciones. **B es incorrecta:** la colecistostomía es para alto riesgo quirúrgico, no primera opción general.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-02","number":22,"title":"Hígado, vía biliar y páncreas (HPB) · caso 2","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Hombre de 70 años con fiebre, ictericia, dolor en hipocondrio derecho, hipotensión y confusión. Laboratorio: bilirrubina 6 mg/dL, leucocitos 18,000.","questions":[{"id":"puem-r3-cc-r3-05-02-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y la conducta?","options":["Hepatitis viral: reposo.","Colecistitis leve: antibióticos orales.","Colangitis aguda grave (pentada de Reynolds): antibióticos intravenosos + drenaje biliar urgente por CPRE; no demorar el drenaje.","Pancreatitis leve: ayuno."],"answer_index":2,"correct_text":"Colangitis aguda grave (pentada de Reynolds): antibióticos intravenosos + drenaje biliar urgente por CPRE; no demorar el drenaje.","explanation":"La pentada de Reynolds (Charcot + hipotensión + alteración mental) es colangitis grave: el drenaje biliar urgente salva la vida; los antibióticos solos no bastan. **B es incorrecta:** no es colecistitis leve ni se trata por vía oral. **A y A son incorrectas:** el cuadro es de obstrucción biliar infectada, no de pancreatitis ni hepatitis.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-03","number":23,"title":"Hígado, vía biliar y páncreas (HPB) · caso 3","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Paciente con pancreatitis aguda biliar leve, dolor en resolución, sin necrosis en TC.","questions":[{"id":"puem-r3-cc-r3-05-03-q1","ordinal":1,"stem":"¿Cuándo se hace la colecistectomía?","options":["Nunca, la pancreatitis contraindica la cirugía.","En el mismo ingreso, una vez resuelto el dolor, porque previene recurrencia (que es frecuente y puede ser grave).","A los 6 meses obligatoriamente.","Solo si hay coledocolitiasis."],"answer_index":1,"correct_text":"En el mismo ingreso, una vez resuelto el dolor, porque previene recurrencia (que es frecuente y puede ser grave).","explanation":"En pancreatitis biliar leve la colecistectomía en el mismo ingreso es el estándar: la recurrencia sin cirugía es alta. **A es incorrecta:** la pancreatitis leve no contraindica la cirugía. **C es incorrecta:** esperar 6 meses expone a recurrencia. **D es incorrecta:** la indicación es la causa biliar, no solo la coledocolitiasis.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-04","number":24,"title":"Hígado, vía biliar y páncreas (HPB) · caso 4","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Hombre de 60 años con pancreatitis necrotizante, 3 semanas de evolución, fiebre, leucocitosis, TC: necrosis infectada con gas. Estable hemodinámicamente.","questions":[{"id":"puem-r3-cc-r3-05-04-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Manejo escalonado (step-up): antibióticos + drenaje percutáneo (o endoscópico) y necrosectomía mínimamente invasiva solo si no mejora; la cirugía abierta de inicio aumenta mortalidad.","Solo ayuno prolongado.","Colecistectomía de urgencia.","Necrosectomía abierta inmediata."],"answer_index":0,"correct_text":"Manejo escalonado (step-up): antibióticos + drenaje percutáneo (o endoscópico) y necrosectomía mínimamente invasiva solo si no mejora; la cirugía abierta de inicio aumenta mortalidad.","explanation":"El manejo step-up es el estándar actual en necrosis infectada: drenaje primero, necrosectomía solo si es necesario; la cirugía abierta temprana tiene alta mortalidad. **D es incorrecta:** es el manejo antiguo, con peores resultados. **B es incorrecta:** la necrosis infectada requiere antibióticos y drenaje. **C es incorrecta:** la colecistectomía no trata la necrosis infectada.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-05","number":25,"title":"Hígado, vía biliar y páncreas (HPB) · caso 5","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Paciente con ictericia indolora, pérdida de 12 kg, vesícula palpable no dolorosa, TC: masa en cabeza de páncreas de 3 cm, sin metástasis, sin invasión vascular.","questions":[{"id":"puem-r3-cc-r3-05-05-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico probable y el tratamiento?","options":["Colangitis: CPRE y antibióticos.","Pancreatitis crónica: manejo médico.","Colelitiasis: colecistectomía.","Cáncer de páncreas resecable (signo de Courvoisier): pancreatoduodenectomía (Whipple) + quimioterapia adyuvante, tras estadificación completa y CA 19-9."],"answer_index":3,"correct_text":"Cáncer de páncreas resecable (signo de Courvoisier): pancreatoduodenectomía (Whipple) + quimioterapia adyuvante, tras estadificación completa y CA 19-9.","explanation":"La ictericia indolora + pérdida de peso + Courvoisier es cáncer de cabeza de páncreas hasta demostrar lo contrario; si es resecable, Whipple + adyuvancia es el tratamiento curativo. **C es incorrecta:** la litiasis no da Courvoisier ni masa. **A es incorrecta:** no hay fiebre ni dolor de colangitis. **B es incorrecta:** la pancreatitis crónica no da masa ni ictericia de este tipo.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-06","number":26,"title":"Hígado, vía biliar y páncreas (HPB) · caso 6","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Durante una colecistectomía laparoscópica, el cirujano no logra identificar con claridad el conducto cístico y la arteria cística.","questions":[{"id":"puem-r3-cc-r3-05-06-q1","ordinal":1,"stem":"¿Cuál es la conducta segura?","options":["Hacer colangiografía y cortar de cualquier forma.","Continuar la disección y cortar lo que parezca el cístico.","Lograr la visión crítica de seguridad (disecar el triángulo hepatocístico, ver dos estructuras entrando a la vesícula); si no se logra, convertir, pedir ayuda o hacer colecistectomía subtotal: nunca cortar a ciegas.","Colocar un drenaje y cerrar."],"answer_index":2,"correct_text":"Lograr la visión crítica de seguridad (disecar el triángulo hepatocístico, ver dos estructuras entrando a la vesícula); si no se logra, convertir, pedir ayuda o hacer colecistectomía subtotal: nunca cortar a ciegas.","explanation":"La visión crítica de seguridad es la maniobra que previene la lesión de la vía biliar; si no se logra, la conducta segura es convertir o hacer subtotal, no cortar a ciegas. **B es incorrecta:** es la causa clásica de lesión biliar. **D es incorrecta:** no resuelve el problema. **A es incorrecta:** la colangiografía ayuda, pero no sustituye la identificación anatómica ni justifica cortar sin seguridad.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-07","number":27,"title":"Hígado, vía biliar y páncreas (HPB) · caso 7","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Paciente con hepatocarcinoma de 4 cm, cirrosis Child-Pugh A, sin hipertensión portal significativa, sin metástasis.","questions":[{"id":"puem-r3-cc-r3-05-07-q1","ordinal":1,"stem":"¿Cuál es la mejor opción?","options":["Quimioterapia sistémica como primera línea.","Resección hepática (o trasplante si cumple criterios de Milán y hay donante) según el estadio BCLC; la resección es curativa en hígado compensado con remanente suficiente.","No hacer nada porque la cirrosis lo impide.","TACE como única opción curativa."],"answer_index":1,"correct_text":"Resección hepática (o trasplante si cumple criterios de Milán y hay donante) según el estadio BCLC; la resección es curativa en hígado compensado con remanente suficiente.","explanation":"En BCLC A con Child A, la resección o el trasplante son curativos; la elección depende de función hepática, remanente y disponibilidad de donante. **A es incorrecta:** la quimio no es primera línea curativa en HCC temprano. **C es incorrecta:** la cirrosis compensada no impide la resección. **D es incorrecta:** TACE es paliativo/locorregional, no curativo en este escenario.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-08","number":28,"title":"Hígado, vía biliar y páncreas (HPB) · caso 8","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Mujer de 55 años, colecistectomía por litiasis; la patología reporta adenocarcinoma de vesícula T2 incidental, márgenes del cístico libres.","questions":[{"id":"puem-r3-cc-r3-05-08-q1","ordinal":1,"stem":"¿Qué se debe hacer?","options":["Re-resección: resección del lecho hepático (segmentos IVb/V) + linfadenectomía del hilio hepático, porque el T2 requiere tratamiento oncológico adicional; discutir en comité.","Radioterapia exclusiva.","Quimioterapia paliativa.","Nada, ya se quitó la vesícula."],"answer_index":0,"correct_text":"Re-resección: resección del lecho hepático (segmentos IVb/V) + linfadenectomía del hilio hepático, porque el T2 requiere tratamiento oncológico adicional; discutir en comité.","explanation":"El cáncer incidental de vesícula T2 exige re-resección oncológica (lecho + linfadenectomía); la colecistectomía simple es insuficiente. **D es incorrecta:** el T2 tiene riesgo de enfermedad residual. **A y C son incorrectas:** no son el tratamiento de un T2 resecable.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-09","number":29,"title":"Hígado, vía biliar y páncreas (HPB) · caso 9","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Hombre de 50 años con tumor quístico pancreático de 3 cm en cuerpo, sin síntomas, RM: quiste mucinoso con nódulo mural.","questions":[{"id":"puem-r3-cc-r3-05-09-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Aspiración del quiste como tratamiento.","Antibióticos.","Observación sin seguimiento.","Pancreatectomía distal, porque el nódulo mural es un estigma de alto riesgo de malignidad en neoplasia mucinosa quística; la vigilancia no basta con ese hallazgo."],"answer_index":3,"correct_text":"Pancreatectomía distal, porque el nódulo mural es un estigma de alto riesgo de malignidad en neoplasia mucinosa quística; la vigilancia no basta con ese hallazgo.","explanation":"El nódulo mural es un criterio de alto riesgo en lesiones quísticas mucinosas: indica resección. **C es incorrecta:** con nódulo mural la observación es insegura. **A es incorrecta:** la aspiración no es tratamiento. **D es irrelevante.","topic":"Hígado"}]},{"id":"puem-r3-cc-r3-05-10","number":30,"title":"Hígado, vía biliar y páncreas (HPB) · caso 10","topic":"Hígado","topicId":"ap-r3-higado","nivel":"R3","context":"Paciente pos-Whipple, día 5, con salida de líquido amilasa alta por el drenaje (3 veces el valor sérico), sin fiebre ni leucocitosis.","questions":[{"id":"puem-r3-cc-r3-05-10-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Fuga biliar: reintervención inmediata.","Fístula pancreática bioquímica (grado A ISGPS): si está asintomático, manejo conservador con drenaje, sin antibióticos ni reintervención; la clasificación ISGPS distingue la fístula bioquímica de la clínicamente relevante.","Dehiscencia de herida: curación.","Pancreatitis posoperatoria: ayuno absoluto prolongado."],"answer_index":1,"correct_text":"Fístula pancreática bioquímica (grado A ISGPS): si está asintomático, manejo conservador con drenaje, sin antibióticos ni reintervención; la clasificación ISGPS distingue la fístula bioquímica de la clínicamente relevante.","explanation":"Amilasa alta en drenaje sin repercusión clínica es fístula bioquímica (grado A): se mantiene el drenaje y se vigila; solo las fístulas clínicamente relevantes (B/C) exigen intervención. **A es incorrecta:** no es fuga biliar ni exige reoperar. **C y D son incorrectas:** no explican la amilasa en el drenaje.","topic":"Hígado"}]},{"id":"puem-r3-cc-r1-13-01","number":31,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 1","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Mujer de 45 años con dolor en hipocondrio derecho de 2 h, postprandial, sin fiebre, leucocitos normales, ecografía con cálculos sin engrosamiento de pared.","questions":[{"id":"puem-r3-cc-r1-13-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico?","options":["Cólico biliar por colelitiasis sintomática.","Colangitis.","Pancreatitis.","Colecistitis aguda."],"answer_index":0,"correct_text":"Cólico biliar por colelitiasis sintomática.","explanation":"dolor <6 h, sin fiebre ni leucocitosis y sin engrosamiento de pared es cólico biliar, no colecistitis. D es incorrecta: la colecistitis es dolor >6 h con fiebre, leucocitosis y pared engrosada. B es incorrecta: no hay ictericia ni fiebre. C es incorrecta: no hay dolor epigástrico irradiado ni amilasa elevada.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r1-13-02","number":32,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 2","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Mujer de 55 años con dolor en hipocondrio derecho de 24 h, fiebre 38.5 °C, leucocitos 16,000, Murphy positivo, ecografía con pared vesicular de 5 mm y líquido perivesicular.","questions":[{"id":"puem-r3-cc-r1-13-02-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el grado TG18?","options":["Cólico biliar; grado I.","Colecistitis aguda; por leucocitos y masa/inflamación local, al menos grado II (moderada) si cumple los criterios TG18.","Colangitis; grado III.","Pancreatitis; leve."],"answer_index":1,"correct_text":"Colecistitis aguda; por leucocitos y masa/inflamación local, al menos grado II (moderada) si cumple los criterios TG18.","explanation":"dolor >6 h + fiebre + leucocitosis + Murphy + imagen es colecistitis aguda TG18; leucocitos >18,000 o inflamación local marcada la hacen grado II, y hay que valorar los criterios completos. A es incorrecta: el cólico no da fiebre ni leucocitosis ni pared engrosada. C es incorrecta: no hay ictericia ni patrón colestásico. D es incorrecta: no es pancreatitis.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r1-13-03","number":33,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 3","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Hombre de 70 años con fiebre 39 °C, ictericia, dolor en hipocondrio derecho, PAS 85 mmHg, confusión, bilirrubina 8 mg/dL, leucocitos 20,000.","questions":[{"id":"puem-r3-cc-r1-13-03-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y la prioridad?","options":["Pancreatitis; ayuno.","Colecistitis leve; colecistectomía electiva.","Colangitis aguda grave (TG18 grado III, pentada de Reynolds); antibiótico + drenaje biliar urgente (CPRE).","Cólico biliar; analgésico."],"answer_index":2,"correct_text":"Colangitis aguda grave (TG18 grado III, pentada de Reynolds); antibiótico + drenaje biliar urgente (CPRE).","explanation":"Charcot (fiebre, ictericia, dolor) + choque y confusión (pentada de Reynolds) es colangitis grave; el antibiótico sin drenaje biliar no resuelve la obstrucción infectada. B es incorrecta: no es colecistitis leve. D es incorrecta: el cólico no da ictericia ni choque. A es incorrecta: no es pancreatitis.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r1-13-04","number":34,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 4","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Mujer de 50 años con ictericia, coluria, acolia, prurito, bilirrubina directa 5 mg/dL, FA y GGT elevadas, ecografía con colédoco de 10 mm y cálculo en colédoco.","questions":[{"id":"puem-r3-cc-r1-13-04-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Solo antibiótico.","Observación.","Colecistectomía sin estudiar la vía biliar.","CPRE terapéutica con extracción del cálculo y colecistectomía en el mismo ingreso."],"answer_index":3,"correct_text":"CPRE terapéutica con extracción del cálculo y colecistectomía en el mismo ingreso.","explanation":"la coledocolitiasis sintomática requiere extracción (CPRE) y colecistectomía en el mismo ingreso para evitar recurrencia (colangitis, pancreatitis). C es incorrecta: operar sin resolver el cálculo del colédoco deja la obstrucción. A es incorrecta: el antibiótico no extrae el cálculo. B es incorrecta: la obstrucción con ictericia requiere tratamiento.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r1-13-05","number":35,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 5","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Hombre de 60 años con colelitiasis asintomática hallada incidentalmente en ecografía por otro motivo, sin síntomas.","questions":[{"id":"puem-r3-cc-r1-13-05-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["No operar; vigilancia y educación sobre síntomas de alarma (salvo excepciones: vesícula en porcelana, pólipos grandes, riesgo especial).","Dar ácido ursodesoxicólico de por vida.","Dieta estricta sin grasa para siempre.","Colecistectomía de inmediato."],"answer_index":0,"correct_text":"No operar; vigilancia y educación sobre síntomas de alarma (salvo excepciones: vesícula en porcelana, pólipos grandes, riesgo especial).","explanation":"la colelitiasis asintomática en general no se opera; el riesgo anual de complicación es bajo y la cirugía tiene sus propios riesgos. D es incorrecta: operar sin síntomas no está indicado. B es incorrecta: el ácido ursodesoxicólico no es el tratamiento estándar. C es incorrecta: la dieta no sustituye la indicación quirúrgica cuando hay síntomas.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r1-13-06","number":36,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 6","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Mujer de 45 años con pancreatitis biliar leve (dolor epigástrico, lipasa 1,200, sin falla orgánica), con cálculos en la vesícula.","questions":[{"id":"puem-r3-cc-r1-13-06-q1","ordinal":1,"stem":"¿Cuándo se hace la colecistectomía?","options":["Solo si recurre la pancreatitis.","En el mismo ingreso, tras la mejoría clínica.","En 6 meses.","Nunca; la pancreatitis contraindica la cirugía."],"answer_index":1,"correct_text":"En el mismo ingreso, tras la mejoría clínica.","explanation":"en pancreatitis biliar leve, la colecistectomía en el mismo ingreso tras la mejoría previene la recurrencia (que es frecuente y puede ser grave). C es incorrecta: esperar 6 meses expone a recurrencia. D es incorrecta: la pancreatitis leve no contraindica la cirugía diferida en el mismo ingreso. A es incorrecta: esperar a la recurrencia es exponer al paciente a un segundo episodio que puede ser grave.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r1-13-07","number":37,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 7","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Paciente post-colecistectomía laparoscópica, día 2, con ictericia progresiva y salida biliar por el drenaje (300 mL/día).","questions":[{"id":"puem-r3-cc-r1-13-07-q1","ordinal":1,"stem":"¿Cuál es la sospecha?","options":["Hepatitis.","Síndrome post-colecistectomía funcional.","Lesión de la vía biliar; avisar al adscrito de inmediato y estudiar (colangio-RM, CPRE/estudio de vía biliar) sin retraso.","Colelitiasis residual sin importancia."],"answer_index":2,"correct_text":"Lesión de la vía biliar; avisar al adscrito de inmediato y estudiar (colangio-RM, CPRE/estudio de vía biliar) sin retraso.","explanation":"ictericia + fuga biliar post-colecistectomía es lesión de la vía biliar hasta demostrar lo contrario; es la complicación más temida y requiere diagnóstico y manejo especializado urgente. B es incorrecta: el síndrome post-colecistectomía no explica la fuga biliar. D es incorrecta: un cálculo residual no explica la fuga por el drenaje. A es incorrecta: la hepatitis no da fuga biliar por el drenaje.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r1-13-08","number":38,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 8","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Mujer de 65 años con colecistitis aguda, con leucocitos 20,000, masa palpable en hipocondrio derecho y síntomas de 4 días.","questions":[{"id":"puem-r3-cc-r1-13-08-q1","ordinal":1,"stem":"¿Qué grado TG18 es y qué implica?","options":["Grado III grave; UCI y drenaje en horas.","No es colecistitis.","Grado I leve; manejo conservador.","Grado II moderada (leucocitos >18,000, masa palpable, >72 h); requiere colecistectomía temprana o drenaje si no es candidata, con vigilancia estrecha."],"answer_index":3,"correct_text":"Grado II moderada (leucocitos >18,000, masa palpable, >72 h); requiere colecistectomía temprana o drenaje si no es candidata, con vigilancia estrecha.","explanation":"leucocitos >18,000, masa palpable y síntomas >72 h son criterios de grado II (moderada) en TG18; implica inflamación local marcada y mayor dificultad quirúrgica, pero no disfunción orgánica (grado III). C es incorrecta: no es leve. A es incorrecta: no hay disfunción orgánica descrita. B es incorrecta: el cuadro es de colecistitis.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r1-13-09","number":39,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 9","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Hombre de 55 años con coledocolitiasis, probabilidad intermedia por labs y ecografía (colédoco dilatado, bilirrubina moderadamente elevada, sin colangitis).","questions":[{"id":"puem-r3-cc-r1-13-09-q1","ordinal":1,"stem":"¿Cuál es el estudio para confirmar el cálculo?","options":["Colangio-RM (no invasiva) para confirmar; CPRE solo si es terapéutica.","TC simple.","Ningún estudio; operar a ciegas.","CPRE diagnóstica de inmediato."],"answer_index":0,"correct_text":"Colangio-RM (no invasiva) para confirmar; CPRE solo si es terapéutica.","explanation":"con probabilidad intermedia, la colangio-RM confirma el cálculo sin los riesgos de la CPRE; la CPRE es terapéutica, no diagnóstica de rutina. D es incorrecta: la CPRE diagnóstica tiene riesgos (pancreatitis, perforación) sin beneficio si no hay cálculo. B es incorrecta: la TC simple es menos sensible para cálculos de colédoco. C es incorrecta: operar sin confirmar es un error.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r1-13-10","number":40,"title":"Patología biliar: colelitiasis, colecistitis aguda y colangitis · caso 10","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R1","context":"Mujer de 70 años con colecistitis aguda, con insuficiencia cardiaca grave y alto riesgo quirúrgico, no candidata a colecistectomía.","questions":[{"id":"puem-r3-cc-r1-13-10-q1","ordinal":1,"stem":"¿Cuál es la alternativa?","options":["Dar analgésico solamente.","No hacer nada.","Colecistostomía percutánea como puente (drenaje de la vesícula) + antibiótico, con valoración posterior de colecistectomía si mejora.","CPRE."],"answer_index":2,"correct_text":"Colecistostomía percutánea como puente (drenaje de la vesícula) + antibiótico, con valoración posterior de colecistectomía si mejora.","explanation":"en el paciente no candidato a cirugía, la colecistostomía percutánea drena la vesícula infectada y es un puente hasta que el paciente pueda operarse o como tratamiento definitivo en casos seleccionados. B es incorrecta: no hacer nada en colecistitis con alto riesgo es peligroso. D es incorrecta: la CPRE drena la vía biliar, no la vesícula. A es incorrecta: el analgésico no trata la infección vesicular.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-01","number":41,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 1","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Mujer de 52 años, obesa, con antecedente de cólicos biliares en el último año. Acude con dolor en hipocondrio derecho de 10 horas de evolución, náusea, vómito y fiebre de 38.4 °C. Exploración: dolor a la palpación en hipocondrio derecho, Murphy positivo, sin ictericia ni peritonitis generalizada. Laboratorio: leucocitos 14,200/µL, PCR 96 mg/L, bilirrubina total 1.1 mg/dL, fosfatasa alcalina 110 U/L. Ultrasonido: vesícula distendida, pared de 5 mm, cálculo de 18 mm impactado en el cuello, líquido perivesicular, sin dilatación del colédoco.","questions":[{"id":"puem-r3-cc-r2-04-01-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Antibiótico intravenoso por 7 días y colecistectomía programada en 6 semanas.","Colecistectomía laparoscópica temprana en este ingreso, con antibiótico perioperatorio.","CPRE urgente con esfinterotomía.","Colecistostomía percutánea como tratamiento definitivo."],"answer_index":1,"correct_text":"Colecistectomía laparoscópica temprana en este ingreso, con antibiótico perioperatorio.","explanation":"Es una colecistitis aguda grado II por Tokio TG18 (leucocitosis, pared engrosada, líquido perivesicular, cálculo impactado, duración mayor de 6 horas) sin disfunción orgánica ni ictericia. El tratamiento de elección es la colecistectomía laparoscópica temprana, idealmente dentro de las 72 horas, que reduce estancia, complicaciones y conversión frente a la cirugía diferida. A es incorrecta porque diferir 6 semanas en colecistitis aguda aumenta el riesgo de recurrencia, gangrena y reingresos; el manejo conservador prolongado no es el estándar en una paciente operable. C es incorrecta porque no hay datos de coledocolitiasis ni colangitis: bilirrubina normal, colédoco no dilatado y sin ictericia, por lo que no hay indicación de CPRE. D es incorrecta porque la colecistostomía percutánea es un puente en pacientes inestables o no operables, no el tratamiento definitivo en una paciente de 52 años operable con colecistitis moderada.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-02","number":42,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 2","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Hombre de 78 años, diabético, con dolor en hipocondrio derecho de 4 días, fiebre de 39.2 °C, confusión, hipotensión de 88/55 mmHg y taquicardia de 118 lpm. Ictericia evidente. Laboratorio: leucocitos 19,500/µL, bilirrubina total 6.8 mg/dL (directa 5.2), fosfatasa alcalina 620 U/L, creatinina 1.9 mg/dL, plaquetas 98,000/µL, lactato 3.8 mmol/L. Tomografía: colédoco dilatado a 14 mm con cálculo de 12 mm en su porción distal, vesícula con cálculos, sin absceso hepático.","questions":[{"id":"puem-r3-cc-r2-04-02-q1","ordinal":1,"stem":"¿Cuál es la prioridad inmediata?","options":["Reanimación, antibióticos de amplio espectro y drenaje biliar urgente por CPRE en horas.","Colangiorresonancia para confirmar el cálculo antes de cualquier intervención.","Antibiótico oral y observación por 48 horas para valorar respuesta.","Colecistectomía laparoscópica de urgencia."],"answer_index":0,"correct_text":"Reanimación, antibióticos de amplio espectro y drenaje biliar urgente por CPRE en horas.","explanation":"Es una colangitis aguda grave grado III por TG18: pentada de Reynolds (fiebre, ictericia, dolor, hipotensión y alteración mental) más disfunción renal, hematológica y lactato elevado, con cálculo distal demostrado. La prioridad es reanimación con líquidos y vasopresores según se requiera, antibióticos de amplio espectro y drenaje biliar urgente en horas; el antibiótico solo no resuelve una vía obstruida infectada. D es incorrecta porque la colecistectomía no drena el colédoco obstruido y operar en choque séptico aumenta la mortalidad; la cirugía de la vesícula se difiere. B es incorrecta porque el diagnóstico ya está establecido por clínica, laboratorio y tomografía; pedir una colangiorresonancia retrasaría un drenaje que es urgente y no cambiaría la conducta. C es incorrecta porque el manejo conservador con antibiótico oral en colangitis grave con hipotensión es mortal; la observación no sustituye el drenaje.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-03","number":43,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 3","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Mujer de 45 años, 3 días después de colecistectomía laparoscópica por colecistitis aguda, con dolor abdominal difuso, ictericia progresiva y drenaje biliar por el drenaje quirúrgico de 400 mL/día. Laboratorio: bilirrubina total 4.5 mg/dL, fosfatasa alcalina 480 U/L. Colangiorresonancia: fuga de bilis en el lecho vesicular, colédoco íntegro sin cálculos, sin colección mayor.","questions":[{"id":"puem-r3-cc-r2-04-03-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable y el manejo inicial?","options":["Pancreatitis postoperatoria; ayuno y analgesia.","Cálculo retenido en el colédoco; CPRE con extracción.","Lesión de la vía biliar tipo E de Strasberg; reconstrucción quirúrgica inmediata con hepaticoyeyunostomía.","Fuga biliar menor del lecho vesicular (conducto de Luschka); manejo conservador con drenaje permeable y CPRE con prótesis si persiste."],"answer_index":3,"correct_text":"Fuga biliar menor del lecho vesicular (conducto de Luschka); manejo conservador con drenaje permeable y CPRE con prótesis si persiste.","explanation":"La fuga biliar de bajo gasto desde el lecho vesicular, habitualmente por un conducto de Luschka, es la causa más frecuente de fuga biliar postcolecistectomía; la colangiorresonancia muestra colédoco íntegro y sin cálculo retenido, lo que descarta lesión mayor y coledocolitiasis. El manejo inicial es conservador: mantener el drenaje permeable, vigilar el gasto y, si la fuga persiste o es de alto gasto, CPRE con esfinterotomía y prótesis para disminuir la presión y favorecer el cierre. B es incorrecta porque no hay cálculo en la imagen y la bilirrubina elevada se explica por la fuga y la reabsorción; una CPRE de entrada para extraer un cálculo inexistente no es el primer paso, aunque la CPRE sí tiene papel terapéutico si la fuga persiste. C es incorrecta porque una lesión tipo E implica sección o estenosis del hepático común, que aquí está íntegro; la reconstrucción inmediata no está indicada y en lesiones mayores el manejo suele diferirse hasta controlar la sepsis y definir la anatomía. A es incorrecta porque no hay dolor epigástrico irradiado a espalda ni elevación de amilasa/lipasa descrita, y el dato dominante es el drenaje biliar con ictericia.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-04","number":44,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 4","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Hombre de 63 años con ictericia indolora de 2 semanas, pérdida de peso de 6 kg, coluria y acolia. Sin fiebre ni dolor importante. Laboratorio: bilirrubina total 9.2 mg/dL, fosfatasa alcalina 890 U/L, GGT 640 U/L, transaminasas levemente elevadas, CA 19-9 de 320 U/mL. Ultrasonido: colédoco dilatado a 16 mm sin cálculo visible, vesícula distendida sin cálculos, páncreas no valorable.","questions":[{"id":"puem-r3-cc-r2-04-04-q1","ordinal":1,"stem":"¿Cuál es el siguiente paso más adecuado?","options":["CPRE urgente con esfinterotomía y extracción de cálculo.","Colecistectomía laparoscópica.","Tomografía contrastada de abdomen y colangiorresonancia para descartar tumor periampular o de colédoco.","Iniciar antibiótico por colangitis y egresar con seguimiento."],"answer_index":2,"correct_text":"Tomografía contrastada de abdomen y colangiorresonancia para descartar tumor periampular o de colédoco.","explanation":"La ictericia indolora, progresiva, con pérdida de peso, colédoco dilatado sin cálculo y vesícula distendida (signo de Courvoisier) apunta a obstrucción maligna periampular o del colédoco, no a litiasis. El CA 19-9 elevado apoya, sin confirmar, esa sospecha. El siguiente paso es estadificar con tomografía contrastada y colangiorresonancia para definir la lesión, su resecabilidad y la anatomía biliar antes de cualquier intervención. A es incorrecta porque no hay cálculo demostrado ni colangitis; una CPRE con esfinterotomía no trata un tumor y retrasaría el diagnóstico. B es incorrecta porque la vesícula no es la causa y la cirugía sin diagnóstico expondría al paciente a una operación innecesaria. D es incorrecta porque no hay fiebre, dolor ni leucocitosis que sustenten colangitis, y el antibiótico no resolvería una obstrucción maligna.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-05","number":45,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 5","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Mujer de 68 años, diabética, con dolor en hipocondrio derecho de 5 días, fiebre de 38.8 °C y vómito. Exploración: dolor intenso, masa palpable en hipocondrio derecho, defensa localizada. Laboratorio: leucocitos 21,000/µL, glucosa 320 mg/dL. Tomografía: vesícula distendida con gas en su pared y en su luz, cálculo impactado en el cuello, líquido perivesicular, sin perforación libre.","questions":[{"id":"puem-r3-cc-r2-04-05-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Colecistitis aguda leve; antibiótico oral y colecistectomía electiva.","Colecistitis enfisematosa; reanimación, antibióticos de amplio espectro y colecistectomía urgente.","Íleo biliar; sonda nasogástrica y cirugía intestinal.","Colangitis aguda; CPRE urgente."],"answer_index":1,"correct_text":"Colecistitis enfisematosa; reanimación, antibióticos de amplio espectro y colecistectomía urgente.","explanation":"El gas en la pared y la luz vesicular en una diabética con cuadro de 5 días es colecistitis enfisematosa, producida por bacterias formadoras de gas (Clostridium spp., E. coli), con alta mortalidad y riesgo de gangrena y perforación. El manejo es reanimación, antibióticos de amplio espectro con cobertura anaerobia y colecistectomía urgente (o colecistostomía si la paciente es inoperable en ese momento), no manejo conservador. A es incorrecta porque no es leve: la leucocitosis mayor de 18,000 ya la hace grado II y el gas la convierte en una forma grave con riesgo de perforación; el antibiótico oral y la cirugía electiva serían peligrosos. C es incorrecta porque el íleo biliar requiere un cálculo migrado que obstruya el intestino con distensión y niveles hidroaéreos, no gas en la pared vesicular. D es incorrecta porque no hay ictericia, colestasis ni dilatación del colédoco que sustenten colangitis; el problema es la vesícula, no la vía biliar principal.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-06","number":46,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 6","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Hombre de 58 años, programado para colecistectomía laparoscópica por cólico biliar recurrente. Laboratorio preoperatorio: bilirrubina total 3.2 mg/dL, fosfatasa alcalina 340 U/L, ALT 120 U/L, AST 95 U/L. Ultrasonido: vesícula con múltiples cálculos, colédoco de 9 mm sin cálculo visible. No tiene fiebre ni ictericia clínica.","questions":[{"id":"puem-r3-cc-r2-04-06-q1","ordinal":1,"stem":"¿Cuál es la conducta más adecuada respecto a la vía biliar?","options":["Estudio no invasivo de la vía biliar con colangiorresonancia o ultrasonido endoscópico antes de la colecistectomía.","Cancelar la cirugía y tratar solo con ácido ursodesoxicólico.","Colecistectomía directa sin estudio adicional de la vía biliar.","CPRE preoperatoria con esfinterotomía en todos los casos."],"answer_index":0,"correct_text":"Estudio no invasivo de la vía biliar con colangiorresonancia o ultrasonido endoscópico antes de la colecistectomía.","explanation":"El paciente tiene riesgo intermedio de coledocolitiasis según ASGE/TG18: pruebas hepáticas alteradas con patrón colestásico y colédoco dilatado (mayor de 6 mm), sin cálculo visible ni colangitis ni bilirrubina mayor de 4 mg/dL. En riesgo intermedio el paso correcto es un estudio no invasivo —colangiorresonancia o ultrasonido endoscópico— y solo si confirma el cálculo se hace CPRE terapéutica. C es incorrecta porque operar sin aclarar la vía en un paciente con colestasis y colédoco dilatado deja el riesgo de un cálculo retenido no diagnosticado, que puede manifestarse como colangitis o pancreatitis postoperatoria. D es incorrecta porque la CPRE es invasiva y tiene riesgo de pancreatitis post-CPRE y sangrado; no se indica de rutina sin confirmar el cálculo. B es incorrecta porque el ácido ursodesoxicólico no es tratamiento de la colelitiasis sintomática con riesgo de coledocolitiasis y no previene las complicaciones.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-07","number":47,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 7","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Mujer de 70 años con colecistitis aguda grado III: hipotensión que requiere vasopresor, creatinina 2.4 mg/dL, plaquetas 85,000/µL, leucocitos 22,000/µL. Tomografía: vesícula con pared engrosada, sin perforación. La paciente está inestable a pesar de reanimación y antibióticos.","questions":[{"id":"puem-r3-cc-r2-04-07-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado en este momento?","options":["CPRE urgente con colocación de prótesis biliar.","Suspender antibióticos y observar.","Colecistectomía laparoscópica inmediata.","Colecistostomía percutánea guiada por imagen como puente, con colecistectomía diferida tras la recuperación."],"answer_index":3,"correct_text":"Colecistostomía percutánea guiada por imagen como puente, con colecistectomía diferida tras la recuperación.","explanation":"En colecistitis aguda grado III con disfunción orgánica múltiple e inestabilidad hemodinámica, Tokio TG18 recomienda no operar de inicio: primero reanimación, antibióticos y drenaje de la vesícula mediante colecistostomía percutánea, que descomprime y controla la sepsis con menor agresión, y colecistectomía diferida semanas después cuando la paciente se recupere. C es incorrecta porque la cirugía mayor en choque séptico con disfunción multiorgánica tiene mortalidad muy alta; la colecistectomía inmediata no es el manejo en grado III inestable. A es incorrecta porque el problema es la vesícula obstruida, no el colédoco; la CPRE no drena la vesícula y no resolvería la colecistitis. B es incorrecta porque suspender el antibiótico en sepsis biliar sería abandonar el tratamiento de una infección grave.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-08","number":48,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 8","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Hombre de 55 años con antecedente de colecistectomía hace 2 años, que acude con dolor en hipocondrio derecho, fiebre de 38.6 °C e ictericia. Laboratorio: bilirrubina total 5.4 mg/dL, fosfatasa alcalina 520 U/L, leucocitos 15,800/µL. Colangiorresonancia: cálculo de 10 mm en el colédoco distal, sin estenosis.","questions":[{"id":"puem-r3-cc-r2-04-08-q1","ordinal":1,"stem":"¿Cuál es el manejo definitivo?","options":["Colangiorresonancia de control en 3 meses.","Antibiótico intravenoso por 10 días sin drenaje.","CPRE con esfinterotomía y extracción del cálculo.","Hepaticoyeyunostomía."],"answer_index":2,"correct_text":"CPRE con esfinterotomía y extracción del cálculo.","explanation":"Es una coledocolitiasis sintomática con colangitis secundaria en un paciente ya colecistectomizado; el tratamiento definitivo es la extracción endoscópica del cálculo mediante CPRE con esfinterotomía, balón o canastilla, que drena la vía y resuelve la infección. B es incorrecta porque el antibiótico sin drenaje no elimina el cálculo obstructivo y la colangitis recurrirá. D es incorrecta porque la hepaticoyeyunostomía es una derivación quirúrgica mayor reservada para estenosis, lesiones o anatomía no abordable por endoscopia, no para un cálculo distal extraíble. A es incorrecta porque observar un cálculo sintomático con colangitis deja al paciente en riesgo de sepsis recurrente y pancreatitis.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-09","number":49,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 9","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Mujer de 48 años con dolor en hipocondrio derecho de 8 horas, Murphy positivo, leucocitos 13,500/µL. Ultrasonido: vesícula con pared de 3 mm, sin cálculos visibles, sin líquido perivesicular, colédoco normal. Tomografía: sin hallazgos biliares. La paciente sigue con dolor y fiebre.","questions":[{"id":"puem-r3-cc-r2-04-09-q1","ordinal":1,"stem":"¿Cuál es el siguiente estudio más útil?","options":["Repetir ultrasonido en 48 horas sin hacer nada más.","Gammagrafía HIDA para confirmar o descartar obstrucción del conducto cístico.","CPRE diagnóstica.","Egresar con analgésicos porque el ultrasonido descarta colecistitis."],"answer_index":1,"correct_text":"Gammagrafía HIDA para confirmar o descartar obstrucción del conducto cístico.","explanation":"El cuadro clínico es compatible con colecistitis aguda, pero el ultrasonido es negativo: esto ocurre en colecistitis acalculosa o cuando el cálculo no se visualiza. La gammagrafía HIDA es el estudio funcional de elección en este escenario: la no visualización de la vesícula tras la inyección del radiofármaco confirma la obstrucción del cístico con alta sensibilidad. A es incorrecta porque esperar 48 horas sin estudio adicional retrasa el diagnóstico en una paciente con dolor persistente y fiebre. C es incorrecta porque la CPRE es terapéutica e invasiva, no es el estudio para confirmar colecistitis cuando la vía biliar es normal. D es incorrecta porque un ultrasonido normal no descarta colecistitis aguda, especialmente la acalculosa, y egresar a una paciente febril con Murphy positivo sería inseguro.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-04-10","number":50,"title":"Patología biliar: colecistitis aguda, coledocolitiasis y colangitis (Tokio TG18) · caso 10","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R2","context":"Hombre de 62 años con vómito, distensión abdominal y ausencia de evacuaciones de 3 días. Antecedente de cólicos biliares durante años sin tratamiento. Radiografía de abdomen: distensión de asas de intestino delgado, niveles hidroaéreos y gas en la vía biliar (neumobilia). Tomografía: cálculo de 28 mm impactado en íleon terminal, vesícula con fístula colecistoduodenal y aire en la vía biliar.","questions":[{"id":"puem-r3-cc-r2-04-10-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo quirúrgico habitual?","options":["Obstrucción por bridas; lisis de adherencias.","Colecistitis aguda; colecistectomía laparoscópica inmediata.","Pancreatitis aguda; ayuno y líquidos.","Íleo biliar; enterolitotomía para extraer el cálculo, difiriendo la reparación de la fístula y la colecistectomía."],"answer_index":3,"correct_text":"Íleo biliar; enterolitotomía para extraer el cálculo, difiriendo la reparación de la fístula y la colecistectomía.","explanation":"Es un íleo biliar: un cálculo grande migra por una fístula colecistoentérica, viaja por el intestino y se impacta habitualmente en el íleon terminal, produciendo obstrucción intestinal mecánica. La tríada radiológica es obstrucción de intestino delgado, neumobilia y cálculo ectópico visible. El manejo habitual en el paciente agudo es la enterolitotomía proximal al sitio de impactación para extraer el cálculo, difiriendo la colecistectomía y el cierre de la fístula para un segundo tiempo, porque el procedimiento en un solo tiempo prolonga la cirugía en un paciente obstruido y deshidratado. A es incorrecta porque las bridas no explican la neumobilia, la fístula ni el cálculo ectópico de 28 mm. B es incorrecta porque el problema dominante es la obstrucción intestinal, no la vesícula en sí, y la colecistectomía inmediata no resuelve el cálculo impactado en íleon. C es incorrecta porque no hay dolor epigástrico, amilasa elevada ni hallazgos pancreáticos; el cuadro es de obstrucción intestinal mecánica.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-01","number":51,"title":"Cirugía hepatobiliar avanzada · caso 1","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Mujer 68 años, ictericia progresiva, fiebre 38.8 °C, dolor en hipocondrio derecho, hipotensión 85/50 y confusión. Bilirrubina 8 mg/dL, leucocitos 18 000.","questions":[{"id":"puem-r3-cc-r4-01-01-q1","ordinal":1,"stem":"¿Conducta prioritaria?","options":["Esperar hemocultivos 48 h y luego decidir","Solo antipiréticos y revalorar en 72 h","Antibiótico y CPRE urgente con drenaje biliar en <24 h","Colecistectomía laparoscópica inmediata"],"answer_index":2,"correct_text":"Antibiótico y CPRE urgente con drenaje biliar en <24 h","explanation":"Colangitis grave (pentada de Reynolds). TG18: antibiótico + drenaje biliar urgente; esperar cultivos mata. Colecistectomía en colangitis séptica no drena la vía biliar; solo antipiréticos es insuficiente.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-02","number":52,"title":"Cirugía hepatobiliar avanzada · caso 2","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Hombre 55 años, colangiocarcinoma perihiliar Bismuth IIIa, FLR calculado 18% en hígado sano, sin metástasis.","questions":[{"id":"puem-r3-cc-r4-01-02-q1","ordinal":1,"stem":"¿Mejor plan?","options":["Quimioterapia paliativa sin más evaluación","Drenaje biliar definitivo como único tratamiento","Hepatectomía extendida inmediata","Embolización portal, revalorar volumetría y comité HPB"],"answer_index":3,"correct_text":"Embolización portal, revalorar volumetría y comité HPB","explanation":"FLR 18% es insuficiente (<20-25% en hígado sano). Embolización portal hipertrofia el remanente; la decisión es de comité HPB. Operar directo arriesga insuficiencia hepática; paliativo sin intentar optimizar es prematuro.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-03","number":53,"title":"Cirugía hepatobiliar avanzada · caso 3","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Paciente postcolecistectomía día 3, débito bilioso 400 mL/día por drenaje, sin peritonitis.","questions":[{"id":"puem-r3-cc-r4-01-03-q1","ordinal":1,"stem":"¿Clasificación y manejo inicial?","options":["Fuga biliar ISGLS probablemente B; manejo conservador, imagen y drenaje percutáneo/endoscópico si persiste","Reoperación inmediata siempre","Retirar el drenaje y alta","Solo antibiótico sin imagen"],"answer_index":0,"correct_text":"Fuga biliar ISGLS probablemente B; manejo conservador, imagen y drenaje percutáneo/endoscópico si persiste","explanation":"Fuga que requiere intervención no quirúrgica = grado B ISGLS; el manejo inicial es conservador + imagen y drenaje. Reoperar de inicio es excesivo sin peritonitis; retirar el drenaje sin evaluar esconde la fuga.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-04","number":54,"title":"Cirugía hepatobiliar avanzada · caso 4","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Mujer 62 años, vesícula con pólipo de 12 mm y cálculos, asintomática.","questions":[{"id":"puem-r3-cc-r4-01-04-q1","ordinal":1,"stem":"¿Conducta?","options":["Solo dieta","Colecistectomía laparoscópica electiva","Vigilancia anual con US","CPRE"],"answer_index":1,"correct_text":"Colecistectomía laparoscópica electiva","explanation":"Pólipo vesicular >10 mm es indicación de colecistectomía por riesgo de cáncer de vesícula. Vigilar un pólipo de 12 mm pierde la ventana; CPRE no trata la vesícula.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-05","number":55,"title":"Cirugía hepatobiliar avanzada · caso 5","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Hombre con colecistitis TG18 grado III, choque séptico y coagulopatía.","questions":[{"id":"puem-r3-cc-r4-01-05-q1","ordinal":1,"stem":"¿Manejo?","options":["Alta con antibiótico oral","Colecistectomía abierta inmediata","Drenaje percutáneo de vesícula + antibiótico + soporte en UCI","CPRE como único tratamiento"],"answer_index":2,"correct_text":"Drenaje percutáneo de vesícula + antibiótico + soporte en UCI","explanation":"TG18 grado III grave: drenaje (percutáneo) y soporte antes que cirugía mayor en paciente inestable. Operar en choque con coagulopatía aumenta mortalidad; CPRE no drena la vesícula.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-06","number":56,"title":"Cirugía hepatobiliar avanzada · caso 6","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Lesión de vía biliar Strasberg E2 reconocida en el postoperatorio, con fuga y colección.","questions":[{"id":"puem-r3-cc-r4-01-06-q1","ordinal":1,"stem":"¿Conducta del cirujano general?","options":["Esperar 6 meses sin drenaje","Repetir colecistectomía","Reparación biliodigestiva inmediata por el mismo equipo sin experiencia HPB","Drenaje percutáneo, control de sepsis y derivación a centro HPB"],"answer_index":3,"correct_text":"Drenaje percutáneo, control de sepsis y derivación a centro HPB","explanation":"La reparación inmediata sin experiencia ni tejido sano fracasa y empeora la estenosis. Lo correcto es drenar, controlar sepsis y derivar a HPB. Esperar sin drenaje perpetúa sepsis.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-07","number":57,"title":"Cirugía hepatobiliar avanzada · caso 7","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Paciente con metástasis hepáticas colorrectales, 3 lesiones en lóbulo derecho, FLR 35%, sin enfermedad extrahepática.","questions":[{"id":"puem-r3-cc-r4-01-07-q1","ordinal":1,"stem":"¿Plan?","options":["Valoración en comité: resección hepática R0 ± quimioterapia perioperatoria","Resección sin estadificación extrahepática","Solo ablación sin comité","Quimioterapia paliativa indefinida sin evaluación quirúrgica"],"answer_index":0,"correct_text":"Valoración en comité: resección hepática R0 ± quimioterapia perioperatoria","explanation":"Metástasis resecables con FLR adecuado van a comité multidisciplinario para resección R0 ± quimio perioperatoria. Negar evaluación quirúrgica pierde opción curativa; operar sin estadificar arriesga enfermedad oculta.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-08","number":58,"title":"Cirugía hepatobiliar avanzada · caso 8","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Ictericia obstructiva, CA 19-9 800 U/mL, sin masa en TC.","questions":[{"id":"puem-r3-cc-r4-01-08-q1","ordinal":1,"stem":"¿Interpretación correcta?","options":["CA 19-9 confirma cáncer pancreático","CA 19-9 se eleva con colestasis; no diagnostica solo: completar CPRM/EUS","No se necesita más estudio","Iniciar quimioterapia ya"],"answer_index":1,"correct_text":"CA 19-9 se eleva con colestasis; no diagnostica solo: completar CPRM/EUS","explanation":"CA 19-9 se eleva en colestasis benigna e inflamación; no es diagnóstico por sí solo. Falta imagen de vía biliar (CPRM/EUS). Tratar por un marcador es un error grave.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-09","number":59,"title":"Cirugía hepatobiliar avanzada · caso 9","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Hombre 70 años, coledocolitiasis y colangitis leve, estable.","questions":[{"id":"puem-r3-cc-r4-01-09-q1","ordinal":1,"stem":"¿Secuencia?","options":["Solo antibiótico 14 días","Litotricia extracorpórea","CPRE con extracción de lito y luego colecistectomía en el mismo ingreso","Colecistectomía sin CPRE"],"answer_index":2,"correct_text":"CPRE con extracción de lito y luego colecistectomía en el mismo ingreso","explanation":"En coledocolitiasis con colangitis: drenaje/extracción por CPRE y colecistectomía en el mismo ingreso (TG18/WSES) para evitar recurrencia. Operar sin limpiar la vía deja el lito; solo antibiótico no resuelve la obstrucción.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r4-01-10","number":60,"title":"Cirugía hepatobiliar avanzada · caso 10","topic":"Vías biliares","topicId":"ap-r3-vias-biliares","nivel":"R4","context":"Posthepatectomía mayor día 5: bilirrubina 7 mg/dL, INR 2.1, encefalopatía leve.","questions":[{"id":"puem-r3-cc-r4-01-10-q1","ordinal":1,"stem":"¿Qué es y qué sigue?","options":["Insuficiencia hepática posthepatectomía (criterios 50-50/ISGLS); soporte en UCI, corregir coagulopatía, comité HPB","Alta por evolución normal","Solo vitamina K y alta","Rehepatectomía inmediata"],"answer_index":0,"correct_text":"Insuficiencia hepática posthepatectomía (criterios 50-50/ISGLS); soporte en UCI, corregir coagulopatía, comité HPB","explanation":"Bilirrubina >50 µmol/L + INR >1.7 al día 5 = insuficiencia hepática posthepatectomía. Requiere UCI y soporte; no es evolución normal ni indicación automática de reoperación.","topic":"Vías biliares"}]},{"id":"puem-r3-cc-r2-05-01","number":61,"title":"Pancreatitis aguda y crónica · caso 1","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Mujer de 48 años, obesa, con dolor epigástrico intenso de 12 horas, irradiado a la espalda, náusea y vómito. Sin fiebre. Exploración: dolor epigástrico, defensa leve, ruidos intestinales disminuidos. Laboratorio: lipasa 1,850 U/L (normal hasta 60), amilasa 900 U/L, leucocitos 13,000/µL, bilirrubina total 2.8 mg/dL, fosfatasa alcalina 280 U/L, glucosa 180 mg/dL, calcio 8.4 mg/dL. Ultrasonido: vesícula con múltiples cálculos pequeños, colédoco de 7 mm, páncreas no valorable por gas.","questions":[{"id":"puem-r3-cc-r2-05-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo más adecuado?","options":["Pancreatitis aguda biliar leve; reanimación, analgesia, ayuno breve y colecistectomía laparoscópica en el mismo ingreso.","Colecistitis aguda; colecistectomía urgente inmediata sin reanimación previa.","Pancreatitis crónica; enzimas pancreáticas y analgesia crónica.","Úlcera péptica perforada; laparotomía urgente."],"answer_index":0,"correct_text":"Pancreatitis aguda biliar leve; reanimación, analgesia, ayuno breve y colecistectomía laparoscópica en el mismo ingreso.","explanation":"Cumple dos criterios de pancreatitis aguda: dolor típico y lipasa mayor de tres veces lo normal (1,850 frente a un límite de 60). La causa es biliar por los cálculos pequeños, la bilirrubina y la fosfatasa elevadas. Es leve porque no hay falla orgánica ni complicaciones. El manejo es soporte con líquidos, analgesia, reintroducción oral temprana y colecistectomía en el mismo ingreso para prevenir la recurrencia, que es alta si se difiere. B es incorrecta porque el cuadro es pancreatitis, no colecistitis: el dolor es epigástrico irradiado a espalda con lipasa muy elevada, y la colecistectomía urgente sin estabilizar la pancreatitis no es el manejo. C es incorrecta porque no hay datos de cronicidad: no hay calcificaciones, esteatorrea, diabetes crónica ni dolor prolongado; es un primer episodio agudo. D es incorrecta porque no hay abdomen en tabla, aire libre ni antecedente de úlcera; el dolor en banda con lipasa elevada define pancreatitis.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r2-05-02","number":62,"title":"Pancreatitis aguda y crónica · caso 2","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Hombre de 55 años, alcohólico crónico, con pancreatitis aguda grave. Al tercer día presenta fiebre de 39 °C, leucocitos 18,000/µL, hipotensión y deterioro respiratorio. Tomografía: necrosis pancreática de 50% con gas en su interior y colección peripancreática. Hemocultivos pendientes.","questions":[{"id":"puem-r3-cc-r2-05-02-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Necrosectomía abierta inmediata.","Antibióticos de amplio espectro y drenaje percutáneo o endoscópico de la necrosis infectada, con necrosectomía mínimamente invasiva solo si fracasa.","Suspender líquidos para evitar sobrecarga y observar.","CPRE urgente con esfinterotomía."],"answer_index":1,"correct_text":"Antibióticos de amplio espectro y drenaje percutáneo o endoscópico de la necrosis infectada, con necrosectomía mínimamente invasiva solo si fracasa.","explanation":"El gas en la necrosis con fiebre, leucocitosis y deterioro es necrosis infectada, la principal causa de muerte tardía. El manejo actual es el abordaje escalonado: antibióticos de amplio espectro con buena penetración pancreática y drenaje percutáneo o endoscópico, reservando la necrosectomía mínimamente invasiva para cuando el drenaje fracasa. A es incorrecta porque la necrosectomía abierta temprana tiene mortalidad muy alta y ya no es el estándar; el abordaje escalonado demostró menor mortalidad y menos complicaciones. C es incorrecta porque suspender líquidos en un paciente con SIRS, hipotensión y secuestro de líquidos empeoraría la hipoperfusión y la falla orgánica. D es incorrecta porque no hay datos de colangitis ni coledocolitiasis; la CPRE no trata la necrosis infectada.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r2-05-03","number":63,"title":"Pancreatitis aguda y crónica · caso 3","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Mujer de 60 años con pancreatitis aguda biliar. Al ingreso tiene dolor epigástrico, lipasa 1,200 U/L, bilirrubina total 5.5 mg/dL, fiebre de 39 °C, ictericia y dolor en hipocondrio derecho. Ultrasonido: colédoco dilatado a 12 mm con cálculo distal.","questions":[{"id":"puem-r3-cc-r2-05-03-q1","ordinal":1,"stem":"¿Cuál es la conducta más adecuada en las primeras 24 horas?","options":["Tomografía para valorar necrosis antes de cualquier intervención.","Antibiótico oral y colecistectomía en 6 semanas.","Reanimación y CPRE urgente con extracción del cálculo por colangitis asociada.","Colecistectomía laparoscópica inmediata."],"answer_index":2,"correct_text":"Reanimación y CPRE urgente con extracción del cálculo por colangitis asociada.","explanation":"La paciente tiene pancreatitis aguda biliar complicada con colangitis aguda (fiebre, ictericia, dolor, bilirrubina elevada y cálculo distal con colédoco dilatado). En este escenario la CPRE urgente dentro de las primeras 24 horas con drenaje y extracción del cálculo está indicada, junto con reanimación y antibióticos. D es incorrecta porque la colecistectomía no drena el colédoco obstruido e infectado; la prioridad es el drenaje biliar. A es incorrecta porque la tomografía para valorar necrosis no es urgente al ingreso y retrasaría el drenaje de una colangitis; además, la necrosis no se valora bien en las primeras 72 horas. B es incorrecta porque el manejo conservador con antibiótico oral en colangitis con pancreatitis es insuficiente y la cirugía diferida a 6 semanas dejaría la vía obstruida.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r2-05-04","number":64,"title":"Pancreatitis aguda y crónica · caso 4","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Hombre de 42 años, sin antecedente de alcohol ni litiasis, con tercer episodio de pancreatitis aguda en 18 meses. Laboratorio en este episodio: triglicéridos 2,400 mg/dL, colesterol total 380 mg/dL, glucosa 220 mg/dL, calcio normal. Ultrasonido: vesícula sin cálculos, páncreas edematoso.","questions":[{"id":"puem-r3-cc-r2-05-04-q1","ordinal":1,"stem":"¿Cuál es la causa más probable y el tratamiento preventivo clave?","options":["Pancreatitis biliar por microlitiasis; colecistectomía.","Cáncer de páncreas; pancreaticoduodenectomía.","Pancreatitis autoinmune; prednisona.","Hipertrigliceridemia grave; fibratos, dieta baja en grasas, control glucémico y abstinencia de alcohol."],"answer_index":3,"correct_text":"Hipertrigliceridemia grave; fibratos, dieta baja en grasas, control glucémico y abstinencia de alcohol.","explanation":"Los triglicéridos de 2,400 mg/dL, muy por encima del umbral de aproximadamente 1,000 mg/dL, explican la pancreatitis recurrente en un paciente sin litiasis ni alcohol. La hipertrigliceridemia produce lipólisis intrapancreática con ácidos grasos libres tóxicos. El tratamiento preventivo es reducir los triglicéridos con fibratos, dieta estricta baja en grasas, control de la diabetes y evitar alcohol y fármacos que los eleven; en el episodio agudo grave puede considerarse insulina o aféresis en casos seleccionados. C es incorrecta porque no hay datos de enfermedad por IgG4, masa pancreática ni enfermedad autoinmune asociada. A es incorrecta porque el ultrasonido muestra vesícula sin cálculos y la causa metabólica está demostrada por el laboratorio. B es incorrecta porque no hay masa, pérdida de peso marcada ni ictericia obstructiva que sugieran cáncer; la recurrencia se explica por la causa metabólica no tratada.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r2-05-05","number":65,"title":"Pancreatitis aguda y crónica · caso 5","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Mujer de 50 años con pancreatitis aguda grave hace 6 semanas. Ahora está afebril, tolera la vía oral, pero refiere saciedad temprana y dolor epigástrico leve. Tomografía: colección encapsulada de 9 cm en el cuerpo pancreático con contenido necrótico, pared bien definida, sin gas ni signos de infección. Laboratorio normal salvo lipasa 120 U/L.","questions":[{"id":"puem-r3-cc-r2-05-05-q1","ordinal":1,"stem":"¿Cuál es el manejo más adecuado?","options":["Observación y seguimiento con imagen, con drenaje solo si se vuelve sintomática, infectada o crece.","CPRE con prótesis pancreática.","Drenaje endoscópico inmediato por el tamaño mayor de 6 cm.","Necrosectomía abierta."],"answer_index":0,"correct_text":"Observación y seguimiento con imagen, con drenaje solo si se vuelve sintomática, infectada o crece.","explanation":"Es una necrosis encapsulada (walled-off necrosis) madura, asintomática salvo molestias leves, sin infección ni compresión significativa. Las colecciones pancreáticas asintomáticas no se drenan por tamaño: muchas se resuelven espontáneamente. La indicación de drenaje es que sea sintomática, infectada, crezca o comprima estructuras vecinas. C es incorrecta porque el tamaño por sí solo no es indicación de drenaje en una colección asintomática y estéril. D es incorrecta porque la necrosectomía abierta en una colección estéril y estable expondría a la paciente a una cirugía mayor innecesaria. B es incorrecta porque no hay obstrucción ductal demostrada ni fuga que justifique una prótesis pancreática.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r2-05-06","number":66,"title":"Pancreatitis aguda y crónica · caso 6","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Hombre de 58 años, alcohólico crónico y fumador, con dolor epigástrico crónico de 2 años, pérdida de peso de 12 kg, heces voluminosas, grasosas y malolientes, y diabetes de diagnóstico reciente sin obesidad. Tomografía: páncreas atrófico con calcificaciones difusas, conducto pancreático dilatado a 8 mm con irregularidad y un cálculo intraductal de 7 mm en la cabeza. Elastasa fecal 85 µg/g.","questions":[{"id":"puem-r3-cc-r2-05-06-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo inicial más adecuado?","options":["Pancreatitis aguda; reanimación y ayuno.","Pancreatitis crónica con insuficiencia exocrina y diabetes tipo 3c; abstinencia de alcohol y tabaco, enzimas pancreáticas con las comidas, insulina y valoración de drenaje ductal.","Cáncer de páncreas; quimioterapia neoadyuvante inmediata sin más estudios.","Úlcera duodenal; inhibidor de bomba de protones."],"answer_index":1,"correct_text":"Pancreatitis crónica con insuficiencia exocrina y diabetes tipo 3c; abstinencia de alcohol y tabaco, enzimas pancreáticas con las comidas, insulina y valoración de drenaje ductal.","explanation":"El cuadro es pancreatitis crónica alcohólica: dolor crónico, esteatorrea por insuficiencia exocrina (elastasa fecal menor de 200 µg/g), diabetes pancreatógena tipo 3c y tomografía con atrofia, calcificaciones y dilatación ductal con cálculo. El manejo inicial es abstinencia de alcohol y tabaco, reemplazo enzimático con las comidas, insulina para la diabetes, dieta baja en grasa y valoración de drenaje endoscópico o quirúrgico del conducto por el cálculo y la dilatación si el dolor no se controla. A es incorrecta porque no es un episodio agudo aislado: hay 2 años de dolor, calcificaciones y falla exocrina y endocrina. C es incorrecta porque, aunque el cáncer debe descartarse, la tomografía muestra el patrón clásico de pancreatitis crónica y no una masa; iniciar quimioterapia sin confirmar malignidad sería un error. D es incorrecta porque la úlcera no explica la esteatorrea, la diabetes, las calcificaciones ni la dilatación ductal.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r2-05-07","number":67,"title":"Pancreatitis aguda y crónica · caso 7","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Mujer de 35 años con dolor epigástrico, lipasa 900 U/L, sin litiasis ni alcohol, sin hipertrigliceridemia ni hipercalcemia. Tomografía: páncreas aumentado de tamaño en forma de salchicha, con realce homogéneo y halo peripancreático, sin necrosis ni calcificaciones. IgG4 sérica elevada. No hay ictericia.","questions":[{"id":"puem-r3-cc-r2-05-07-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable y el tratamiento?","options":["Adenocarcinoma de páncreas; cirugía de Whipple.","Pancreatitis aguda biliar; colecistectomía.","Pancreatitis autoinmune tipo 1; prednisona con buena respuesta esperada.","Pancreatitis crónica alcohólica; enzimas pancreáticas."],"answer_index":2,"correct_text":"Pancreatitis autoinmune tipo 1; prednisona con buena respuesta esperada.","explanation":"El páncreas en salchicha con realce homogéneo, halo peripancreático e IgG4 elevada en una mujer joven sin causa biliar ni alcohólica es pancreatitis autoinmune tipo 1, relacionada con IgG4. Es una entidad distinta que responde a esteroides y que simula cáncer, por lo que distinguirla evita una cirugía mayor innecesaria. B es incorrecta porque no hay litiasis y la morfología no es la de pancreatitis biliar. D es incorrecta porque no hay alcohol, calcificaciones ni atrofia crónica. A es incorrecta porque la imagen es difusa y homogénea, no una masa focal con dilatación ductal abrupta; operar como cáncer sin descartar enfermedad por IgG4 sería un error grave.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r2-05-08","number":68,"title":"Pancreatitis aguda y crónica · caso 8","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Hombre de 47 años con pancreatitis aguda grave, en el día 5 con oliguria, creatinina 2.8 mg/dL, PaO2/FiO2 de 180, hipotensión que requiere vasopresor y SIRS persistente. Tomografía: necrosis de 40% sin gas.","questions":[{"id":"puem-r3-cc-r2-05-08-q1","ordinal":1,"stem":"¿Cómo se clasifica según Atlanta revisada y cuál es el pronóstico?","options":["Crónica; enfermedad irreversible.","Leve; mortalidad menor de 1%.","Moderadamente grave; falla orgánica transitoria.","Grave; falla orgánica persistente mayor de 48 horas con mortalidad de 15-30%."],"answer_index":3,"correct_text":"Grave; falla orgánica persistente mayor de 48 horas con mortalidad de 15-30%.","explanation":"Según Atlanta revisada, la falla orgánica persistente mayor de 48 horas (renal, respiratoria y cardiovascular en este caso, al día 5) define pancreatitis aguda grave, con mortalidad aproximada de 15-30%, mayor si la necrosis se infecta. La necrosis sin gas es estéril por ahora, pero el paciente está grave por la falla orgánica. B es incorrecta porque hay falla multiorgánica y necrosis extensa, lo opuesto a leve. C es incorrecta porque la falla no es transitoria: persiste al día 5 y afecta tres sistemas. A es incorrecta porque es un episodio agudo grave, no una enfermedad crónica con fibrosis y calcificaciones.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r2-05-09","number":69,"title":"Pancreatitis aguda y crónica · caso 9","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Mujer de 44 años con pancreatitis aguda biliar leve, ya sin dolor, tolerando dieta blanda al tercer día, lipasa en descenso, sin falla orgánica. Ultrasonido: vesícula con cálculos, colédoco normal, pruebas hepáticas normalizándose. La paciente pregunta cuándo se opera de la vesícula.","questions":[{"id":"puem-r3-cc-r2-05-09-q1","ordinal":1,"stem":"¿Cuál es la recomendación correcta?","options":["Colecistectomía laparoscópica en el mismo ingreso antes del alta.","Esperar 6 semanas y operar de forma electiva.","No operar nunca; la pancreatitis no recurre.","CPRE antes de cualquier cirugía aunque el colédoco sea normal."],"answer_index":0,"correct_text":"Colecistectomía laparoscópica en el mismo ingreso antes del alta.","explanation":"En pancreatitis biliar leve resuelta, la colecistectomía laparoscópica en el mismo ingreso es el estándar porque previene la recurrencia, que es alta en las primeras semanas si la vesícula permanece. Diferirla 6 semanas deja a la paciente expuesta a un nuevo episodio, que puede ser grave. B es incorrecta por esa razón: la cirugía diferida se asocia a más reingresos y recurrencias. C es incorrecta porque la pancreatitis biliar recurre con frecuencia mientras persistan los cálculos. D es incorrecta porque el colédoco es normal y las pruebas se normalizan, por lo que no hay indicación de CPRE; la CPRE no sustituye a la colecistectomía.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r2-05-10","number":70,"title":"Pancreatitis aguda y crónica · caso 10","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R2","context":"Hombre de 60 años con pancreatitis crónica alcohólica, dolor epigástrico intratable a pesar de analgesia, abstinencia de alcohol y enzimas. Tomografía: conducto pancreático dilatado a 9 mm con múltiples cálculos intraductales en cabeza y cuerpo, sin masa sospechosa. Endoscopia: no es candidato a drenaje endoscópico por la carga litiásica.","questions":[{"id":"puem-r3-cc-r2-05-10-q1","ordinal":1,"stem":"¿Cuál es la opción quirúrgica más adecuada para el dolor?","options":["Esplenectomía.","Pancreaticoduodenectomía (Whipple).","Procedimiento de Frey (resección de la cabeza con pancreatoyeyunostomía longitudinal) o Puestow, según los hallazgos.","Colecistectomía laparoscópica."],"answer_index":2,"correct_text":"Procedimiento de Frey (resección de la cabeza con pancreatoyeyunostomía longitudinal) o Puestow, según los hallazgos.","explanation":"En pancreatitis crónica con conducto dilatado, cálculos intraductales y dolor intratable sin masa sospechosa, la cirugía de drenaje ductal —Puestow (pancreatoyeyunostomía longitudinal) o Frey (que añade resección de la cabeza pancreática con drenaje longitudinal)— es la opción para descomprimir el conducto y aliviar el dolor, preservando parénquima. B es incorrecta porque el Whipple es una resección mayor indicada ante sospecha de cáncer o enfermedad localizada en la cabeza no tratable con drenaje, no como primera opción para dolor por hipertensión ductal difusa sin masa. D es incorrecta porque la vesícula no es la causa del dolor crónico. A es incorrecta porque la esplenectomía no trata el dolor pancreático ni la hipertensión ductal.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-01","number":71,"title":"Cirugía pancreática avanzada · caso 1","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Hombre 48 años, pancreatitis aguda, lipasa 1 200, SIRS, TC: necrosis pancreática 40% sin gas, estable, día 5, sin infección documentada.","questions":[{"id":"puem-r3-cc-r4-02-01-q1","ordinal":1,"stem":"¿Conducta?","options":["Necrosectomía abierta inmediata","Soporte, nutrición enteral, antibiótico solo si hay infección; necrosectomía diferida si se infecta","Antibiótico profiláctico de amplio espectro 14 días","Ayuno absoluto 2 semanas"],"answer_index":1,"correct_text":"Soporte, nutrición enteral, antibiótico solo si hay infección; necrosectomía diferida si se infecta","explanation":"Necrosis estéril no se opera ni se da antibiótico profiláctico; el step-up diferido (≥4 semanas) es el estándar. Operar en fase temprana aumenta mortalidad; el ayuno prolongado empeora el pronóstico.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-02","number":72,"title":"Cirugía pancreática avanzada · caso 2","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Mujer 60 años, adenocarcinoma de cabeza de páncreas, contacto <180° con AMS, sin metástasis.","questions":[{"id":"puem-r3-cc-r4-02-02-q1","ordinal":1,"stem":"¿Clasificación y plan?","options":["Borderline resecable; neoadyuvancia y comité oncológico antes de cirugía","Irresecable; solo paliación","Solo radioterapia","Resecable; Whipple directo"],"answer_index":0,"correct_text":"Borderline resecable; neoadyuvancia y comité oncológico antes de cirugía","explanation":"Contacto <180° con AMS sin metástasis = borderline (NCCN). La neoadyuvancia mejora R0 y selecciona biología; ir directo a Whipple arriesga margen positivo.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-03","number":73,"title":"Cirugía pancreática avanzada · caso 3","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Post-Whipple día 7, débito por drenaje con amilasa 5x sérica, sin sepsis.","questions":[{"id":"puem-r3-cc-r4-02-03-q1","ordinal":1,"stem":"¿Diagnóstico y manejo?","options":["Reoperación inmediata","Retirar drenaje y alta","Fístula grado A sin relevancia","Fístula pancreática ISGPS grado B; drenaje conservado, soporte, imagen si deterioro"],"answer_index":3,"correct_text":"Fístula pancreática ISGPS grado B; drenaje conservado, soporte, imagen si deterioro","explanation":"Amilasa alta en drenaje >3 días con repercusión clínica = fístula grado B; manejo conservador con drenaje. Reoperar sin sepsis es excesivo; grado A es solo bioquímica sin cambio de manejo.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-04","number":74,"title":"Cirugía pancreática avanzada · caso 4","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Hombre 45 años, pseudoquiste pancreático 8 cm, 8 semanas postpancreatitis, dolor y saciedad precoz.","questions":[{"id":"puem-r3-cc-r4-02-04-q1","ordinal":1,"stem":"¿Tratamiento?","options":["Necrosectomía abierta urgente","Solo analgésicos","Drenaje endoscópico (cistogastrostomía) o quirúrgico según anatomía","Observación indefinida"],"answer_index":2,"correct_text":"Drenaje endoscópico (cistogastrostomía) o quirúrgico según anatomía","explanation":"Pseudoquiste sintomático y maduro (>4-6 semanas) se drena endoscópica o quirúrgicamente. Observar un quiste sintomático de 8 cm perpetúa síntomas; necrosectomía es para necrosis, no pseudoquiste.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-05","number":75,"title":"Cirugía pancreática avanzada · caso 5","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Mujer 52 años, IPMN de conducto principal de 12 mm con nódulo mural.","questions":[{"id":"puem-r3-cc-r4-02-05-q1","ordinal":1,"stem":"¿Conducta?","options":["Drenaje endoscópico","Resección pancreática (alto riesgo de malignidad)","Vigilancia anual","Solo RM cada 5 años"],"answer_index":1,"correct_text":"Resección pancreática (alto riesgo de malignidad)","explanation":"IPMN de conducto principal con nódulo mural tiene alto riesgo de malignidad (guía IAP/Fukuoka): resección. Vigilar pierde la ventana curativa; el drenaje no trata el tumor.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-06","number":76,"title":"Cirugía pancreática avanzada · caso 6","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Pancreatitis aguda grave, necrosis infectada confirmada (gas en TC), día 28, estable con antibiótico.","questions":[{"id":"puem-r3-cc-r4-02-06-q1","ordinal":1,"stem":"¿Paso siguiente?","options":["Drenaje percutáneo/endoscópico escalonado (step-up)","Necrosectomía abierta inmediata como primera opción","Suspender antibiótico y observar","Colecistectomía urgente"],"answer_index":0,"correct_text":"Drenaje percutáneo/endoscópico escalonado (step-up)","explanation":"El step-up (drenaje mínimamente invasivo primero) reduce mortalidad vs. necrosectomía abierta de inicio. A las 4 semanas el tejido está delimitado (WON). Suspender antibiótico con gas en TC es peligroso.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-07","number":77,"title":"Cirugía pancreática avanzada · caso 7","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Hombre 65 años, cáncer pancreático metastásico a hígado, ECOG 1.","questions":[{"id":"puem-r3-cc-r4-02-07-q1","ordinal":1,"stem":"¿Tratamiento?","options":["Solo cuidados paliativos sin quimio","Radioterapia pancreática curativa","Whipple paliativo","Quimioterapia sistémica (mFOLFIRINOX o gemcitabina/nab-paclitaxel) según NCCN y estado funcional"],"answer_index":3,"correct_text":"Quimioterapia sistémica (mFOLFIRINOX o gemcitabina/nab-paclitaxel) según NCCN y estado funcional","explanation":"Enfermedad metastásica no es quirúrgica; la quimioterapia sistémica es el estándar en ECOG 0-1. Whipple no cura metástasis; negar quimio sin valorar estado funcional es prematuro.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-08","number":78,"title":"Cirugía pancreática avanzada · caso 8","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Mujer con pancreatitis biliar leve, cálculos en vesícula.","questions":[{"id":"puem-r3-cc-r4-02-08-q1","ordinal":1,"stem":"¿Cuándo colecistectomía?","options":["Nunca, solo dieta","Solo si recurre","En el mismo ingreso, tras resolver la pancreatitis","A los 6 meses"],"answer_index":2,"correct_text":"En el mismo ingreso, tras resolver la pancreatitis","explanation":"Colecistectomía en el mismo ingreso tras pancreatitis biliar leve previene recurrencia (guías WSES/IAP). Esperar 6 meses expone a nueva pancreatitis, que puede ser grave.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-09","number":79,"title":"Cirugía pancreática avanzada · caso 9","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Postpancreatectomía distal, glucemia 280 mg/dL persistente.","questions":[{"id":"puem-r3-cc-r4-02-09-q1","ordinal":1,"stem":"¿Explicación y manejo?","options":["Insulina solo si hay cetoacidosis","Diabetes postpancreatectomía por pérdida de masa de islotes; control glucémico y enzimas pancreáticas si hay insuficiencia exocrina","Error de laboratorio, ignorar","Solo dieta sin fármacos"],"answer_index":1,"correct_text":"Diabetes postpancreatectomía por pérdida de masa de islotes; control glucémico y enzimas pancreáticas si hay insuficiencia exocrina","explanation":"La pancreatectomía distal reduce masa insular: diabetes secundaria real que requiere tratamiento. Ignorarla descompensa cicatrización e infección.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r4-02-10","number":80,"title":"Cirugía pancreática avanzada · caso 10","topic":"Páncreas","topicId":"ap-r3-pancreas","nivel":"R4","context":"Tumor neuroendocrino pancreático 1.5 cm, no funcionante, en cuerpo, asintomático.","questions":[{"id":"puem-r3-cc-r4-02-10-q1","ordinal":1,"stem":"¿Conducta?","options":["Enucleación urgente siempre","Quimioterapia neoadyuvante","Solo analgesia","Valoración en comité: resección vs. vigilancia estrecha según grado y crecimiento"],"answer_index":3,"correct_text":"Valoración en comité: resección vs. vigilancia estrecha según grado y crecimiento","explanation":"Los NET pequeños no funcionantes se individualizan: resección o vigilancia según Ki67/grado, localización y comorbilidad, en comité. Operar siempre sin valorar grado es excesivo; la quimio neoadyuvante no es estándar aquí.","topic":"Páncreas"}]},{"id":"puem-r3-cc-r3-12-01","number":81,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 1","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Hombre de 65 años con peritonitis por perforación de colon, hipotenso, lactato 4.5, SOFA 8.","questions":[{"id":"puem-r3-cc-r3-12-01-q1","ordinal":1,"stem":"¿Cuál es la prioridad en la primera hora?","options":["Dar solo líquidos y observar.","Dar vasopresor sin líquidos ni antibióticos.","Pedir TC y esperar el resultado antes de dar antibióticos.","Bundle de sepsis: hemocultivos, antibióticos de amplio espectro en la primera hora, líquidos y control de la fuente quirúrgico urgente; la demora en antibióticos y en control de la fuente aumenta la mortalidad."],"answer_index":3,"correct_text":"Bundle de sepsis: hemocultivos, antibióticos de amplio espectro en la primera hora, líquidos y control de la fuente quirúrgico urgente; la demora en antibióticos y en control de la fuente aumenta la mortalidad.","explanation":"En choque séptico por peritonitis, la primera hora define el pronóstico: antibióticos inmediatos + reanimación + control quirúrgico de la fuente. **C es incorrecta:** esperar la TC antes de los antibióticos es un error. **A es incorrecta:** los líquidos solos no tratan la infección. **B es incorrecta:** el vasopresor no sustituye líquidos ni antibióticos.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-12-02","number":82,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 2","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Paciente con absceso intraabdominal localizado de 6 cm tras apendicectomía, estable, sin peritonitis difusa.","questions":[{"id":"puem-r3-cc-r3-12-02-q1","ordinal":1,"stem":"¿Cuál es el manejo?","options":["Alta con analgésicos.","Laparotomía inmediata.","Drenaje percutáneo guiado por imagen + antibióticos, con vigilancia; la cirugía se reserva para falla del drenaje o peritonitis difusa.","Solo antibióticos sin drenaje."],"answer_index":2,"correct_text":"Drenaje percutáneo guiado por imagen + antibióticos, con vigilancia; la cirugía se reserva para falla del drenaje o peritonitis difusa.","explanation":"El absceso localizado y bien definido se drena por vía percutánea; la laparotomía es para peritonitis difusa o falla del drenaje. **B es incorrecta:** es sobretratamiento en un absceso localizado estable. **D es incorrecta:** un absceso de 6 cm no se resuelve solo con antibióticos. **A es incorrecta:** requiere hospitalización y drenaje.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-12-03","number":83,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 3","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Mujer de 70 años con fuga anastomótica tras colectomía, con peritonitis difusa y choque séptico.","questions":[{"id":"puem-r3-cc-r3-12-03-q1","ordinal":1,"stem":"¿Cuál es la conducta quirúrgica?","options":["Conservar la anastomosis y dar antibióticos.","Reintervención: deshacer la anastomosis, resección y estoma (Hartmann o derivación), lavado y drenaje; en sepsis grave con inestabilidad, control de daños con abdomen abierto si es necesario.","Colocar stent en la anastomosis.","Esperar a que la fuga cierre sola."],"answer_index":1,"correct_text":"Reintervención: deshacer la anastomosis, resección y estoma (Hartmann o derivación), lavado y drenaje; en sepsis grave con inestabilidad, control de daños con abdomen abierto si es necesario.","explanation":"La fuga con peritonitis difusa y choque exige reoperar y deshacer la anastomosis; conservarla en sepsis grave es un error. **A es incorrecta:** la anastomosis fallida no se conserva en peritonitis difusa. **C es incorrecta:** el stent no trata la peritonitis difusa. **D es incorrecta:** la fuga con choque no cierra sola.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-12-04","number":84,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 4","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Paciente con sepsis abdominal, 4 días posoperatorio, con control adecuado de la fuente, afebril y con leucocitos en descenso.","questions":[{"id":"puem-r3-cc-r3-12-04-q1","ordinal":1,"stem":"¿Cuánto tiempo de antibióticos se recomienda?","options":["Duración corta (aprox. 4 días tras control adecuado de la fuente) según las guías WSES, con desescalada según cultivos; prolongar sin evidencia aumenta resistencia y efectos adversos.","Antibióticos de por vida.","Suspender al día siguiente de la cirugía siempre.","14 días obligatorios."],"answer_index":0,"correct_text":"Duración corta (aprox. 4 días tras control adecuado de la fuente) según las guías WSES, con desescalada según cultivos; prolongar sin evidencia aumenta resistencia y efectos adversos.","explanation":"Tras un control adecuado de la fuente, 4 días son suficientes en peritonitis complicada; la duración prolongada no mejora resultados. **D es incorrecta:** 14 días es sobretratamiento sin evidencia. **B es incorrecta:** no hay antibióticos de por vida. **C es incorrecta:** suspender al día siguiente es demasiado pronto sin evaluar la respuesta.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-12-05","number":85,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 5","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Hombre de 50 años con abdomen abierto por control de daños, con salida de contenido intestinal por la herida abierta al día 7.","questions":[{"id":"puem-r3-cc-r3-12-05-q1","ordinal":1,"stem":"¿Cuál es la complicación?","options":["Es normal en abdomen abierto.","Infección de herida superficial.","Dehiscencia simple de herida.","Fístula enteroatmosférica: la complicación más temida del abdomen abierto; requiere manejo especializado (aislamiento, control del efluente, nutrición, cierre diferido) y tiene alta mortalidad."],"answer_index":3,"correct_text":"Fístula enteroatmosférica: la complicación más temida del abdomen abierto; requiere manejo especializado (aislamiento, control del efluente, nutrición, cierre diferido) y tiene alta mortalidad.","explanation":"La salida de contenido intestinal por el abdomen abierto es fístula enteroatmosférica, no una dehiscencia simple; su manejo es complejo y especializado. **C es incorrecta:** no es solo dehiscencia. **A es incorrecta:** nunca es normal. **B es incorrecta:** no es superficial.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-12-06","number":86,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 6","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Paciente en choque séptico que persiste hipotenso pese a 30 mL/kg de cristaloides.","questions":[{"id":"puem-r3-cc-r3-12-06-q1","ordinal":1,"stem":"¿Cuál es el vasopresor de primera línea?","options":["No dar vasopresor, dar más líquidos indefinidamente.","Dopamina.","Norepinefrina: vasopresor de primera línea en choque séptico según Surviving Sepsis; la dopamina tiene más arritmias y la fenilefrina no es de primera línea.","Vasopresina como primera línea."],"answer_index":2,"correct_text":"Norepinefrina: vasopresor de primera línea en choque séptico según Surviving Sepsis; la dopamina tiene más arritmias y la fenilefrina no es de primera línea.","explanation":"La norepinefrina es el vasopresor de primera línea; la vasopresina es adyuvante. **B es incorrecta:** la dopamina aumenta arritmias y mortalidad. **D es incorrecta:** la vasopresina no es de primera línea. **A es incorrecta:** la sobrecarga de líquidos empeora el edema y la función orgánica.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-12-07","number":87,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 7","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Paciente con peritonitis terciaria (infección persistente pese a control de la fuente y antibióticos adecuados).","questions":[{"id":"puem-r3-cc-r3-12-07-q1","ordinal":1,"stem":"¿Qué se debe sospechar?","options":["Que los antibióticos son suficientes.","Infección por microorganismos resistentes, hongos (Candida) o foco no controlado (absceso residual, fuga oculta); requiere revaloración con TC, cultivos y ajuste del tratamiento, además de evaluar inmunosupresión y nutrición.","Que ya no hay infección.","Que el paciente no necesita más estudios."],"answer_index":1,"correct_text":"Infección por microorganismos resistentes, hongos (Candida) o foco no controlado (absceso residual, fuga oculta); requiere revaloración con TC, cultivos y ajuste del tratamiento, además de evaluar inmunosupresión y nutrición.","explanation":"La peritonitis terciaria implica falla del control o microorganismos no cubiertos; exige buscar el foco y ampliar el espectro. **A es incorrecta:** si persiste, el tratamiento no es suficiente. **C y D son incorrectas:** la persistencia exige estudiar, no asumir resolución.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-12-08","number":88,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 8","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Hombre de 60 años con pancreatitis necrotizante infectada y choque séptico.","questions":[{"id":"puem-r3-cc-r3-12-08-q1","ordinal":1,"stem":"¿Cuál es el principio de manejo?","options":["Antibióticos + drenaje percutáneo/endoscópico escalonado (step-up) y control de la fuente; la cirugía abierta temprana en pancreatitis infectada tiene alta mortalidad (ver tema 5).","Solo ayuno.","Colecistectomía de urgencia.","Necrosectomía abierta inmediata."],"answer_index":0,"correct_text":"Antibióticos + drenaje percutáneo/endoscópico escalonado (step-up) y control de la fuente; la cirugía abierta temprana en pancreatitis infectada tiene alta mortalidad (ver tema 5).","explanation":"El manejo escalonado es el estándar en necrosis infectada; la cirugía abierta de inicio es el error clásico. **D es incorrecta:** la necrosectomía abierta temprana aumenta mortalidad. **B es incorrecta:** el ayuno no controla la infección. **C es incorrecta:** la colecistectomía no trata la necrosis infectada.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-12-09","number":89,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 9","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Paciente crítico posoperatorio con presión intraabdominal de 22 mmHg, oliguria, dificultad ventilatoria y acidosis.","questions":[{"id":"puem-r3-cc-r3-12-09-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Dar diuréticos.","Es un hallazgo normal en el posoperatorio.","Dar más líquidos para mejorar la perfusión renal.","Reconocer el síndrome compartimental abdominal: medir la presión intraabdominal, optimizar (evitar sobrecarga, descompresión nasogástrica/rectal) y descomprimir quirúrgicamente (abdomen abierto) si hay disfunción orgánica persistente."],"answer_index":3,"correct_text":"Reconocer el síndrome compartimental abdominal: medir la presión intraabdominal, optimizar (evitar sobrecarga, descompresión nasogástrica/rectal) y descomprimir quirúrgicamente (abdomen abierto) si hay disfunción orgánica persistente.","explanation":"La tríada (presión alta + oliguria + dificultad ventilatoria) es síndrome compartimental; más líquidos lo empeoran. **C es incorrecta:** la sobrecarga aumenta la presión intraabdominal. **A es incorrecta:** los diuréticos no descomprimen el abdomen. **B es incorrecta:** nunca es normal.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-12-10","number":90,"title":"Sepsis abdominal, abdomen abierto y paciente quirúrgico crítico · caso 10","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R3","context":"Mujer de 75 años con sepsis abdominal, desnutrida, en terapia intensiva, día 5, hemodinámicamente estable, intestino funcionante.","questions":[{"id":"puem-r3-cc-r3-12-10-q1","ordinal":1,"stem":"¿Cuál es la conducta nutricional correcta?","options":["Ayuno prolongado hasta el alta.","Nutrición enteral temprana (cuando el intestino lo tolera) en el paciente crítico estable, porque preserva la barrera intestinal y mejora resultados; la nutrición parenteral se reserva para cuando la enteral no es posible.","Solo suero glucosado.","Nutrición parenteral total de inicio en todos los casos."],"answer_index":1,"correct_text":"Nutrición enteral temprana (cuando el intestino lo tolera) en el paciente crítico estable, porque preserva la barrera intestinal y mejora resultados; la nutrición parenteral se reserva para cuando la enteral no es posible.","explanation":"La nutrición enteral temprana es el estándar en el crítico estable con intestino funcionante; el ayuno prolongado empeora la desnutrición y la barrera intestinal. **A es incorrecta:** el ayuno prolongado es dañino. **C es incorrecta:** el suero glucosado no es nutrición. **D es incorrecta:** la parenteral es segunda línea por sus complicaciones.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-01","number":91,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 1","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"Mujer 58 años, cáncer de ovario con carcinomatosis, PCI 12 en laparoscopia, sin enfermedad extraperitoneal, ECOG 0.","questions":[{"id":"puem-r3-cc-r4-03-01-q1","ordinal":1,"stem":"¿Plan?","options":["Citorreducción completa + HIPEC/quimio según comité, en centro experto","Laparotomía paliativa sin intención citorreductora","Solo quimioterapia sin valorar cirugía","Derivar a cuidados paliativos exclusivos"],"answer_index":0,"correct_text":"Citorreducción completa + HIPEC/quimio según comité, en centro experto","explanation":"PCI 12 resecable en paciente apta: citorreducción completa (CC-0) es el objetivo, ± HIPEC/quimio en centro experto. Negar evaluación quirúrgica sin comité pierde opción de control prolongado.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-02","number":92,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 2","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"Hombre 62 años, carcinomatosis colorrectal, PCI 28, ECOG 2, desnutrición.","questions":[{"id":"puem-r3-cc-r4-03-02-q1","ordinal":1,"stem":"¿Decisión?","options":["Citorreducción + HIPEC a toda costa","Quimioterapia sistémica y soporte; citorreducción no es adecuada por PCI alto y estado funcional","Laparotomía exploradora sin plan","Solo cirugía paliativa mayor"],"answer_index":1,"correct_text":"Quimioterapia sistémica y soporte; citorreducción no es adecuada por PCI alto y estado funcional","explanation":"PCI alto + ECOG 2 + desnutrición: la citorreducción completa es improbable y mórbida; la quimio sistémica y el soporte son lo proporcional. Forzar HIPEC aquí aumenta mortalidad sin beneficio.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-03","number":93,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 3","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"Paciente con pseudomixoma peritoneal por apéndice, PCI 20, buen estado.","questions":[{"id":"puem-r3-cc-r4-03-03-q1","ordinal":1,"stem":"¿Tratamiento de referencia?","options":["Quimioterapia sistémica exclusiva","Observación","Citorreducción completa + HIPEC en centro experto","Solo apendicectomía"],"answer_index":2,"correct_text":"Citorreducción completa + HIPEC en centro experto","explanation":"El pseudomixoma es la indicación clásica de citorreducción + HIPEC con intención curativa. Solo apendicectomía deja enfermedad peritoneal extensa.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-04","number":94,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 4","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"GIST gástrico 8 cm, mutación KIT exón 11.","questions":[{"id":"puem-r3-cc-r4-03-04-q1","ordinal":1,"stem":"¿Plan?","options":["Solo imatinib de por vida sin cirugía","Quimioterapia convencional (FOLFOX)","Radioterapia curativa","Resección quirúrgica; valorar imatinib neoadyuvante/adyuvante por riesgo y comité"],"answer_index":3,"correct_text":"Resección quirúrgica; valorar imatinib neoadyuvante/adyuvante por riesgo y comité","explanation":"GIST grande de alto riesgo: cirugía + imatinib perioperatorio según mutación y riesgo (NCCN). La quimio convencional no funciona en GIST; imatinib solo no reseca el tumor.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-05","number":95,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 5","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"Hombre con obstrucción intestinal por carcinomatosis, vómitos, sin isquemia, cáncer avanzado conocido.","questions":[{"id":"puem-r3-cc-r4-03-05-q1","ordinal":1,"stem":"¿Primera conducta?","options":["Valorar descompresión (sonda/gastrostomía), soporte, imagen y comité: cirugía paliativa solo con objetivo claro","Solo opioides sin evaluación","Alta domiciliaria","Laparotomía urgente inmediata"],"answer_index":0,"correct_text":"Valorar descompresión (sonda/gastrostomía), soporte, imagen y comité: cirugía paliativa solo con objetivo claro","explanation":"La obstrucción maligna sin isquemia se evalúa primero: descompresión, soporte y decisión en comité; operar sin objetivo claro en enfermedad avanzada suele empeorar calidad de vida. Negar evaluación también es error.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-06","number":96,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 6","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"Sarcoma retroperitoneal 15 cm, sin metástasis.","questions":[{"id":"puem-r3-cc-r4-03-06-q1","ordinal":1,"stem":"¿Principio quirúrgico?","options":["Radioterapia preoperatoria siempre sin cirugía","Resección en bloque con márgenes, con órganos adyacentes si están comprometidos, en centro experto","Enucleación simple del tumor","Biopsia y quimioterapia exclusiva"],"answer_index":1,"correct_text":"Resección en bloque con márgenes, con órganos adyacentes si están comprometidos, en centro experto","explanation":"El sarcoma retroperitoneal se cura con resección en bloque R0; enuclear deja enfermedad y recurre. La decisión de neoadyuvancia es de comité, no automática.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-07","number":97,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 7","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"Mujer 70 años, cáncer de colon metastásico, obstrucción, sangrado activo, inestable.","questions":[{"id":"puem-r3-cc-r4-03-07-q1","ordinal":1,"stem":"¿Cirugía paliativa?","options":["Solo transfusión indefinida","No operar nunca en cáncer avanzado","Cirugía de control de daño paliativa con objetivo claro (hemorragia/obstrucción) y consentimiento real","Resección oncológica curativa extensa"],"answer_index":2,"correct_text":"Cirugía de control de daño paliativa con objetivo claro (hemorragia/obstrucción) y consentimiento real","explanation":"La paliación quirúrgica es legítima con objetivo claro y consentimiento: controlar hemorragia/obstrucción en paciente inestable. Ni el nihilismo ni la resección curativa extensa son correctos aquí.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-08","number":98,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 8","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"TC sugiere PCI 8, pero en laparoscopia el PCI real es 22 con intestino delgado comprometido.","questions":[{"id":"puem-r3-cc-r4-03-08-q1","ordinal":1,"stem":"¿Qué explica esto?","options":["Error de la laparoscopia, la TC siempre es exacta","El PCI no cambia con el método","No importa el PCI para decidir","La TC subestima la carcinomatosis peritoneal, sobre todo en intestino delgado"],"answer_index":3,"correct_text":"La TC subestima la carcinomatosis peritoneal, sobre todo en intestino delgado","explanation":"La TC subestima sistemáticamente el PCI, especialmente en intestino delgado y lesiones <5 mm; la laparoscopia estadificadora es más fiable. Decidir solo por TC lleva a laparotomías fútiles.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-09","number":99,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 9","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"Paciente con mesotelioma peritoneal maligno, buen estado, sin enfermedad extraperitoneal.","questions":[{"id":"puem-r3-cc-r4-03-09-q1","ordinal":1,"stem":"¿Opción?","options":["Citorreducción + HIPEC en centro experto como opción de referencia","Solo quimioterapia paliativa sin valorar cirugía","Pleurodesis","Observación"],"answer_index":0,"correct_text":"Citorreducción + HIPEC en centro experto como opción de referencia","explanation":"El mesotelioma peritoneal seleccionado es indicación de citorreducción + HIPEC en centro experto. Negarlo sin comité pierde la mejor opción de control.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r4-03-10","number":100,"title":"Cirugía oncológica avanzada y carcinomatosis peritoneal · caso 10","topic":"Peritoneo y retroperitoneo","topicId":"ap-r3-peritoneo","nivel":"R4","context":"Hombre con cáncer gástrico y citología peritoneal positiva en laparoscopia, sin carcinomatosis visible.","questions":[{"id":"puem-r3-cc-r4-03-10-q1","ordinal":1,"stem":"¿Estadio y plan?","options":["Solo radioterapia","Alta","M1 (enfermedad peritoneal); quimioterapia sistémica, no gastrectomía curativa de inicio","Resecable; gastrectomía inmediata"],"answer_index":2,"correct_text":"M1 (enfermedad peritoneal); quimioterapia sistémica, no gastrectomía curativa de inicio","explanation":"Citología peritoneal positiva = M1 (AJCC): enfermedad sistémica; la gastrectomía curativa de inicio no beneficia. La laparoscopia estadificadora evitó una laparotomía fútil.","topic":"Peritoneo y retroperitoneo"}]},{"id":"puem-r3-cc-r3-06-01","number":101,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 1","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Mujer de 40 años con nódulo tiroideo de 2.5 cm, TSH normal, ultrasonido: nódulo sólido hipoecoico con microcalcificaciones, BAAF Bethesda V (sospechoso de malignidad).","questions":[{"id":"puem-r3-cc-r3-06-01-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Tiroidectomía (lobectomía o total según el caso y la preferencia) con estudio de ganglios, porque Bethesda V tiene alta probabilidad de malignidad y la cirugía es diagnóstica y terapéutica.","Dar levotiroxina para achicar el nódulo.","Solo vigilancia con ultrasonido anual.","Repetir BAAF en 6 meses."],"answer_index":0,"correct_text":"Tiroidectomía (lobectomía o total según el caso y la preferencia) con estudio de ganglios, porque Bethesda V tiene alta probabilidad de malignidad y la cirugía es diagnóstica y terapéutica.","explanation":"Bethesda V (sospechoso de malignidad) tiene probabilidad de malignidad alta (aprox. 60-75%) y la indicación es quirúrgica. **D es incorrecta:** repetir la BAAF no cambia el manejo de un Bethesda V. **B es incorrecta:** la levotiroxina no trata un nódulo sospechoso. **C es incorrecta:** la vigilancia es para Bethesda II (benigno).","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-06-02","number":102,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 2","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Paciente con calcio 11.8 mg/dL, PTH elevada, vitamina D normal, ultrasonido y sestamibi concordantes en adenoma paratiroideo inferior derecho.","questions":[{"id":"puem-r3-cc-r3-06-02-q1","ordinal":1,"stem":"¿Cuál es el tratamiento?","options":["Bifosfonatos de por vida.","Paratiroidectomía mínimamente invasiva del adenoma localizado, con PTH intraoperatoria para confirmar curación.","Tiroidectomía total.","Dieta baja en calcio."],"answer_index":1,"correct_text":"Paratiroidectomía mínimamente invasiva del adenoma localizado, con PTH intraoperatoria para confirmar curación.","explanation":"El hiperparatiroidismo primario sintomático (o con criterios) se cura con cirugía; la localización concordante permite el abordaje mínimamente invasivo con PTH intraoperatoria. **A es incorrecta:** los bifosfonatos no curan el adenoma. **C es incorrecta:** no es cirugía de tiroides. **D es incorrecta:** la dieta no corrige la hipercalcemia del adenoma.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-06-03","number":103,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 3","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Hombre de 50 años con masa suprarrenal de 5 cm encontrada en TC. No se ha hecho estudio bioquímico. El cirujano propone adrenalectomía directa.","questions":[{"id":"puem-r3-cc-r3-06-03-q1","ordinal":1,"stem":"¿Cuál es el error?","options":["El error es operar por laparoscopia.","Ninguno, el tamaño indica cirugía inmediata.","No hacer estudio bioquímico antes: toda masa suprarrenal debe estudiarse (metanefrinas, aldosterona/renina, cortisol) porque un feocromocitoma no diagnosticado puede causar crisis hipertensiva mortal en quirófano.","El error es no pedir biopsia de la masa."],"answer_index":2,"correct_text":"No hacer estudio bioquímico antes: toda masa suprarrenal debe estudiarse (metanefrinas, aldosterona/renina, cortisol) porque un feocromocitoma no diagnosticado puede causar crisis hipertensiva mortal en quirófano.","explanation":"El estudio bioquímico preoperatorio es obligatorio: operar un feocromocitoma sin bloqueo alfa puede ser mortal. **B es incorrecta:** el tamaño no sustituye el estudio hormonal. **D es incorrecta:** la biopsia suprarrenal está contraindicada sin descartar feocromocitoma y rara vez cambia el manejo. **A es incorrecta:** la laparoscopia es el abordaje estándar en tumores benignos.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-06-04","number":104,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 4","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Paciente con feocromocitoma confirmado.","questions":[{"id":"puem-r3-cc-r3-06-04-q1","ordinal":1,"stem":"¿Cuál es la preparación preoperatoria correcta?","options":["No requiere preparación, se opera directo.","Dar calcioantagonista como único tratamiento.","Betabloqueo inmediato con propranolol.","Bloqueo alfa (fenoxibenzamina) 7-14 días antes, hidratación y dieta alta en sodio, y solo después betabloqueo si hay taquicardia; nunca betabloqueo sin alfa previo."],"answer_index":3,"correct_text":"Bloqueo alfa (fenoxibenzamina) 7-14 días antes, hidratación y dieta alta en sodio, y solo después betabloqueo si hay taquicardia; nunca betabloqueo sin alfa previo.","explanation":"El bloqueo alfa previo previene la crisis hipertensiva por liberación de catecolaminas; el betabloqueo sin alfa deja el alfa sin oposición y empeora la vasoconstricción. **C es incorrecta:** es el error clásico y peligroso. **A es incorrecta:** operar sin preparación es inseguro. **B es incorrecta:** no es la preparación estándar.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-06-05","number":105,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 5","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Mujer de 32 años, 6 h pos-tiroidectomía total, con estridor, disnea y aumento del volumen cervical.","questions":[{"id":"puem-r3-cc-r3-06-05-q1","ordinal":1,"stem":"¿Cuál es la conducta inmediata?","options":["Abrir la herida en la cama (quitar puntos/grapas) para descomprimir el hematoma y asegurar la vía aérea; es una emergencia quirúrgica.","Esperar a que se reabsorba el hematoma.","Dar oxígeno y pedir radiografía de tórax.","Dar calcio intravenoso."],"answer_index":0,"correct_text":"Abrir la herida en la cama (quitar puntos/grapas) para descomprimir el hematoma y asegurar la vía aérea; es una emergencia quirúrgica.","explanation":"El hematoma cervical pos-tiroidectomía comprime la vía aérea: abrir la herida en la cama es la maniobra que salva la vida mientras se asegura la vía aérea. **D es incorrecta:** el calcio trata hipocalcemia, no el hematoma. **B es incorrecta:** esperar puede ser mortal. **C es incorrecta:** el oxígeno no resuelve la compresión.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-06-06","number":106,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 6","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Paciente pos-tiroidectomía total con parestesias peribucales, Chvostek positivo y calcio 7.2 mg/dL.","questions":[{"id":"puem-r3-cc-r3-06-06-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Lesión del nervio recurrente: foniatría.","Hipocalcemia por hipoparatiroidismo posoperatorio: calcio intravenoso si es sintomática/grave, luego calcio oral + calcitriol y vigilancia; es la complicación más frecuente.","Déficit de magnesio: solo reponer magnesio.","Es normal y no requiere tratamiento."],"answer_index":1,"correct_text":"Hipocalcemia por hipoparatiroidismo posoperatorio: calcio intravenoso si es sintomática/grave, luego calcio oral + calcitriol y vigilancia; es la complicación más frecuente.","explanation":"Las parestesias + Chvostek + calcio bajo son hipocalcemia por hipoparatiroidismo; el manejo es calcio IV si hay síntomas graves y luego oral + calcitriol. **A es incorrecta:** el recurrente da ronquera, no parestesias. **C es incorrecta:** el magnesio se corrige como cofactor, pero el problema es el calcio/PTH. **D es incorrecta:** la hipocalcemia sintomática exige tratamiento.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-06-07","number":107,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 7","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Hombre de 60 años con cáncer papilar de tiroides de 1.2 cm, sin metástasis ganglionares, sin extensión extratiroidea.","questions":[{"id":"puem-r3-cc-r3-06-07-q1","ordinal":1,"stem":"¿Qué cirugía es razonable?","options":["Disección radical de cuello bilateral siempre.","Tiroidectomía total obligatoria en todos los casos.","Lobectomía (hemitiroidectomía) es una opción válida en cáncer papilar pequeño de bajo riesgo, con vigilancia del lóbulo restante; la total se reserva para alto riesgo, bilateralidad o preferencia informada.","No operar, el papilar no necesita cirugía."],"answer_index":2,"correct_text":"Lobectomía (hemitiroidectomía) es una opción válida en cáncer papilar pequeño de bajo riesgo, con vigilancia del lóbulo restante; la total se reserva para alto riesgo, bilateralidad o preferencia informada.","explanation":"La ATA permite lobectomía en papilar pequeño de bajo riesgo; la tiroidectomía total no es obligatoria universal. **B es incorrecta:** es sobretratamiento en bajo riesgo. **D es incorrecta:** el cáncer requiere resección (salvo microcarcinomas en vigilancia activa en protocolos). **A es incorrecta:** la disección radical no es rutinaria sin ganglios afectados.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-06-08","number":108,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 8","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Mujer de 45 años con hipertensión de difícil control e hipopotasemia persistente, aldosterona alta y renina suprimida, TC: adenoma suprarrenal izquierdo de 1.8 cm.","questions":[{"id":"puem-r3-cc-r3-06-08-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el tratamiento?","options":["Síndrome de Cushing: hipofisectomía.","Hipertensión esencial: antihipertensivos de por vida.","Feocromocitoma: bloqueo alfa.","Aldosteronoma (síndrome de Conn): adrenalectomía laparoscópica izquierda, curativa en una proporción importante; confirmar lateralización según el caso."],"answer_index":3,"correct_text":"Aldosteronoma (síndrome de Conn): adrenalectomía laparoscópica izquierda, curativa en una proporción importante; confirmar lateralización según el caso.","explanation":"Hipertensión + hipopotasemia + aldosterona alta/renina baja = hiperaldosteronismo primario; el adenoma unilateral se cura con adrenalectomía. **C es incorrecta:** el feocromocitoma da crisis paroxísticas, no este perfil. **A es incorrecta:** no hay datos de Cushing. **B es incorrecta:** es hipertensión secundaria curable, no esencial.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-06-09","number":109,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 9","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Paciente con carcinoma medular de tiroides, calcitonina elevada, antecedente familiar de MEN 2.","questions":[{"id":"puem-r3-cc-r3-06-09-q1","ordinal":1,"stem":"¿Qué estudio genético y qué conducta se asocian?","options":["Estudio del protooncogén RET (MEN 2) y tiroidectomía total con disección central; además descartar feocromocitoma antes de operar y tamizar a familiares.","No requiere estudio genético.","Solo yodo radiactivo.","Estudio de BRAF y quimioterapia."],"answer_index":0,"correct_text":"Estudio del protooncogén RET (MEN 2) y tiroidectomía total con disección central; además descartar feocromocitoma antes de operar y tamizar a familiares.","explanation":"El medular se asocia a RET/MEN 2; antes de la tiroidectomía debe descartarse feocromocitoma (que puede coexistir y matar en quirófano) y la familia debe tamizarse. **D es incorrecta:** BRAF es de papilar, no de medular. **B es incorrecta:** el estudio genético es central. **C es incorrecta:** el medular no capta yodo (células C, no foliculares).","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-06-10","number":110,"title":"Cirugía endocrina: tiroides, paratiroides y suprarrenal · caso 10","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R3","context":"Paciente con hiperparatiroidismo primario operado: PTH intraoperatoria cae de 180 a 70 pg/mL (caída >50%) a los 10 minutos.","questions":[{"id":"puem-r3-cc-r3-06-10-q1","ordinal":1,"stem":"¿Qué significa?","options":["Que la PTH no sirve para nada.","Que la cirugía fracasó.","Que se cumple el criterio de Miami y es probable que se haya resecado el adenoma hiperfuncionante; se confirma con calcio posoperatorio.","Que debe explorarse el otro lado obligatoriamente."],"answer_index":2,"correct_text":"Que se cumple el criterio de Miami y es probable que se haya resecado el adenoma hiperfuncionante; se confirma con calcio posoperatorio.","explanation":"La caída >50% de la PTH intraoperatoria (criterio de Miami) predice curación bioquímica y permite terminar la cirugía mínimamente invasiva. **B es incorrecta:** la caída es éxito, no fracaso. **D es incorrecta:** el criterio evita la exploración bilateral innecesaria. **A es incorrecta:** la PTH intraoperatoria es la herramienta clave del procedimiento.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-01","number":111,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 1","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Mujer 45 años, nódulo tiroideo 2 cm, PAAF Bethesda V.","questions":[{"id":"puem-r3-cc-r4-07-01-q1","ordinal":1,"stem":"¿Conducta?","options":["Tiroidectomía (lobectomía vs. total según riesgo) con estudio de extensión","Solo levotiroxina","Yodo radiactivo sin cirugía","Vigilancia"],"answer_index":0,"correct_text":"Tiroidectomía (lobectomía vs. total según riesgo) con estudio de extensión","explanation":"Bethesda V (sospechoso de malignidad) exige cirugía; la extensión define lobectomía vs. total. Vigilar un Bethesda V pierde tratamiento curativo.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-02","number":112,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 2","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Postiroidectomía total, calcio 7.0 mg/dL, parestesias, Chvostek positivo.","questions":[{"id":"puem-r3-cc-r4-07-02-q1","ordinal":1,"stem":"¿Diagnóstico y manejo?","options":["Normal postoperatorio","Hipoparatiroidismo postoperatorio; calcio IV/oral + calcitriol y vigilancia","Hipertiroidismo","Lesión de recurrente"],"answer_index":1,"correct_text":"Hipoparatiroidismo postoperatorio; calcio IV/oral + calcitriol y vigilancia","explanation":"Hipocalcemia sintomática postirodectomía = hipoparatiroidismo (temporal o permanente). Requiere reposición y vigilancia; no es normal ni lesión de recurrente (esa da disfonía).","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-03","number":113,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 3","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Mujer 50 años, cáncer de mama triple negativo, tumor 3 cm, ganglios clínicamente negativos.","questions":[{"id":"puem-r3-cc-r4-07-03-q1","ordinal":1,"stem":"¿Plan?","options":["Solo hormonoterapia","Mastectomía inmediata sin sistémico","Quimioterapia neoadyuvante y luego cirugía conservadora/mastectomía + ganglio centinela, según respuesta","Solo radioterapia"],"answer_index":2,"correct_text":"Quimioterapia neoadyuvante y luego cirugía conservadora/mastectomía + ganglio centinela, según respuesta","explanation":"Triple negativo localmente avanzado: neoadyuvancia primero (mejora respuesta y permite conservar). La hormonoterapia no funciona sin receptores; operar directo pierde la ventaja de la neoadyuvancia.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-04","number":114,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 4","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Hombre 60 años, feocromocitoma, crisis hipertensivas, se programa adrenalectomía.","questions":[{"id":"puem-r3-cc-r4-07-04-q1","ordinal":1,"stem":"¿Preparación?","options":["Sin preparación, a quirófano","Solo dieta baja en sal","Beta-bloqueo primero","Alfa-bloqueo 7-14 días, hidratación y luego beta si hace falta"],"answer_index":3,"correct_text":"Alfa-bloqueo 7-14 días, hidratación y luego beta si hace falta","explanation":"El alfa-bloqueo previo previene crisis intraoperatoria; el beta-bloqueo sin alfa previo puede precipitar crisis por vasoconstricción alfa sin oposición.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-05","number":115,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 5","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Mujer con cáncer de mama, ganglio centinela positivo con 1 ganglio y cirugía conservadora + radioterapia.","questions":[{"id":"puem-r3-cc-r4-07-05-q1","ordinal":1,"stem":"¿Siempre disección axilar?","options":["No necesariamente: en casos seleccionados (Z0011) se puede omitir disección con radioterapia y sistémico","Nunca se opera la axila","Solo quimioterapia","Sí, siempre"],"answer_index":0,"correct_text":"No necesariamente: en casos seleccionados (Z0011) se puede omitir disección con radioterapia y sistémico","explanation":"Z0011: en conservadora + radioterapia con 1-2 centinelas positivos, omitir disección axilar es aceptable en seleccionados. 'Siempre' es dogma superado.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-06","number":116,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 6","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Postiroidectomía, estridor y hematoma cervical expansivo.","questions":[{"id":"puem-r3-cc-r4-07-06-q1","ordinal":1,"stem":"¿Acción inmediata?","options":["Esperar TC de cuello","Abrir la herida en la cama / quirófano inmediato para descomprimir la vía aérea","Solo oxígeno","Intubar sin abrir la herida"],"answer_index":1,"correct_text":"Abrir la herida en la cama / quirófano inmediato para descomprimir la vía aérea","explanation":"El hematoma cervical postirodectomía es urgencia de vía aérea: abrir la herida descomprime y permite intubar. Esperar la TC puede ser letal.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-07","number":117,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 7","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Mujer 38 años, BRCA1 positivo, cáncer de mama.","questions":[{"id":"puem-r3-cc-r4-07-07-q1","ordinal":1,"stem":"¿Implicación quirúrgica?","options":["Radioterapia exclusiva","Ninguna","Valorar mastectomía con reducción de riesgo / conservación con vigilancia intensiva y consejo genético familiar","Solo quimioterapia"],"answer_index":2,"correct_text":"Valorar mastectomía con reducción de riesgo / conservación con vigilancia intensiva y consejo genético familiar","explanation":"BRCA1 cambia la decisión: mastectomía terapéutica ± contralateral profiláctica y vigilancia familiar. Ignorar la mutación deja riesgo contralateral y familiar.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-08","number":118,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 8","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Hombre con hiperparatiroidismo primario, calcio 11.5, adenoma en sestamibi.","questions":[{"id":"puem-r3-cc-r4-07-08-q1","ordinal":1,"stem":"¿Cirugía y confirmación?","options":["Tiroidectomía total","Solo cinacalcet de por vida","Exploración bilateral siempre sin PTH","Paratiroidectomía mínimamente invasiva con PTH intraoperatoria (caída >50%)"],"answer_index":3,"correct_text":"Paratiroidectomía mínimamente invasiva con PTH intraoperatoria (caída >50%)","explanation":"La paratiroidectomía dirigida con PTH intraoperatoria confirma curación. El cinacalcet no cura el adenoma; la exploración bilateral sin PTH es innecesaria si hay localización concordante.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-09","number":119,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 9","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Mujer 62 años, cáncer de mama luminal A, 1.2 cm, ganglios negativos.","questions":[{"id":"puem-r3-cc-r4-07-09-q1","ordinal":1,"stem":"¿Tratamiento sistémico principal?","options":["Terapia endocrina adyuvante (± radioterapia tras conservadora)","Solo cirugía sin más","Inmunoterapia","Quimioterapia intensa"],"answer_index":0,"correct_text":"Terapia endocrina adyuvante (± radioterapia tras conservadora)","explanation":"Luminal A pequeño: la terapia endocrina es el pilar; la quimio intensa no aporta en bajo riesgo. Omitir sistémico ignora el riesgo de recurrencia.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r4-07-10","number":120,"title":"Cirugía endocrina, de cabeza y cuello y de mama · caso 10","topic":"Tiroides y paratiroides","topicId":"ap-r3-tiroides","nivel":"R4","context":"Nódulo mamario, biopsia: carcinoma ductal in situ (DCIS) extenso.","questions":[{"id":"puem-r3-cc-r4-07-10-q1","ordinal":1,"stem":"¿Principio?","options":["Quimioterapia neoadyuvante","Siempre mastectomía","Cirugía conservadora con márgenes libres + radioterapia o mastectomía según extensión/deseo; el DCIS no invade, pero exige márgenes","Solo vigilancia"],"answer_index":2,"correct_text":"Cirugía conservadora con márgenes libres + radioterapia o mastectomía según extensión/deseo; el DCIS no invade, pero exige márgenes","explanation":"El DCIS se trata con escisión con márgenes ± radioterapia o mastectomía según extensión; no requiere quimio neoadyuvante. 'Siempre mastectomía' es excesivo.","topic":"Tiroides y paratiroides"}]},{"id":"puem-r3-cc-r3-02-01","number":121,"title":"Cáncer de mama · caso 1","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Mujer de 52 años con masa de 2 cm en cuadrante superior externo, biopsia: carcinoma ductal infiltrante RE+/RP+/HER2-, Ki67 10%, axila clínicamente negativa, sin metástasis. Desea conservar la mama.","questions":[{"id":"puem-r3-cc-r3-02-01-q1","ordinal":1,"stem":"¿Cuál es el plan correcto?","options":["Tumorectomía con márgenes libres + biopsia de ganglio centinela + radioterapia adyuvante, con hormonoterapia posterior.","Tumorectomía sin radioterapia, porque el tumor es pequeño.","Solo hormonoterapia sin cirugía, porque el tumor es receptor positivo.","Mastectomía radical modificada, porque la conservadora no es segura en este tamaño."],"answer_index":0,"correct_text":"Tumorectomía con márgenes libres + biopsia de ganglio centinela + radioterapia adyuvante, con hormonoterapia posterior.","explanation":"Enfermedad temprana luminal: la conservadora con margen libre + centinela + radioterapia es equivalente en supervivencia a la mastectomía, y la hormonoterapia adyuvante es el tratamiento sistémico base. **D es incorrecta:** 2 cm no obliga a mastectomía. **B es incorrecta:** omitir radioterapia tras conservadora aumenta recurrencia local. **C es incorrecta:** la hormonoterapia no sustituye la resección.","topic":"Mama"}]},{"id":"puem-r3-cc-r3-02-02","number":122,"title":"Cáncer de mama · caso 2","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Mujer de 38 años con cáncer de mama HER2 positivo, 3 cm, un ganglio axilar palpable sospechoso.","questions":[{"id":"puem-r3-cc-r3-02-02-q1","ordinal":1,"stem":"¿Cuál es la conducta inicial más adecuada?","options":["Cirugía inmediata (mastectomía + disección axilar) y luego decidir sistémico.","Quimioterapia neoadyuvante + anti-HER2 (trastuzumab ± pertuzumab) para reducir tumor y axila, evaluar respuesta y luego cirugía.","Solo radioterapia neoadyuvante.","Hormonoterapia neoadyuvante como único tratamiento."],"answer_index":1,"correct_text":"Quimioterapia neoadyuvante + anti-HER2 (trastuzumab ± pertuzumab) para reducir tumor y axila, evaluar respuesta y luego cirugía.","explanation":"HER2+ con axila positiva es indicación de neoadyuvancia con doble bloqueo anti-HER2 + quimio: reduce tumor y axila, permite cirugía menos extensa y la respuesta patológica completa predice pronóstico. **A es incorrecta:** operar directo pierde la oportunidad de respuesta y de desescalar axila. **C y D son incorrectas:** la radioterapia sola y la hormonoterapia no son el tratamiento de un HER2+ (RE no es el driver).","topic":"Mama"}]},{"id":"puem-r3-cc-r3-02-03","number":123,"title":"Cáncer de mama · caso 3","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Paciente con tumor de 1.8 cm, centinela con 1 ganglio positivo de 3 mm (macrometástasis), mastectomía planeada.","questions":[{"id":"puem-r3-cc-r3-02-03-q1","ordinal":1,"stem":"¿Qué manejo axilar es correcto según criterios actuales?","options":["Radioterapia axilar en lugar de cirugía en todos los casos.","Disección axilar completa siempre que haya un centinela positivo.","En mastectomía con centinela positivo, la disección axilar sigue siendo el estándar en la mayoría de los casos (a diferencia de la conservadora con criterios Z0011); valorar radioterapia y decisión en comité.","No hacer nada más en axila porque el centinela ya estadificó."],"answer_index":2,"correct_text":"En mastectomía con centinela positivo, la disección axilar sigue siendo el estándar en la mayoría de los casos (a diferencia de la conservadora con criterios Z0011); valorar radioterapia y decisión en comité.","explanation":"El punto fino: los criterios Z0011 (omitir disección con 1-2 centinelas positivos) aplican a cirugía conservadora con radioterapia de mama completa; en mastectomía la disección axilar sigue siendo el estándar habitual, con radioterapia como alternativa en casos seleccionados y decisión en comité. **B es incorrecta** por absoluta: hay escenarios de radioterapia axilar. **D es incorrecta:** un centinela positivo exige tratamiento axilar adicional. **A es incorrecta:** no es universal.","topic":"Mama"}]},{"id":"puem-r3-cc-r3-02-04","number":124,"title":"Cáncer de mama · caso 4","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Mujer de 60 años posmenopáusica, RE+/HER2-, tumor 1.2 cm, centinela negativo, sin metástasis. El reporte genómico (Oncotype DX) muestra puntaje de recurrencia bajo.","questions":[{"id":"puem-r3-cc-r3-02-04-q1","ordinal":1,"stem":"¿Qué implica?","options":["Necesita mastectomía bilateral profiláctica.","El puntaje bajo significa que no necesita ningún tratamiento.","Necesita quimioterapia de cualquier forma por el tamaño.","Puede omitir quimioterapia y recibir solo hormonoterapia, porque el puntaje bajo predice poco beneficio de quimio en este perfil."],"answer_index":3,"correct_text":"Puede omitir quimioterapia y recibir solo hormonoterapia, porque el puntaje bajo predice poco beneficio de quimio en este perfil.","explanation":"En RE+/HER2- ganglio negativo con puntaje genómico bajo, la hormonoterapia sola es suficiente y la quimio aporta poco beneficio; es el uso clásico de la prueba genómica. **C es incorrecta:** el tamaño solo no obliga a quimio. **A es incorrecta:** no hay indicación de profilaxis contralateral. **B es incorrecta:** la hormonoterapia adyuvante sigue siendo necesaria.","topic":"Mama"}]},{"id":"puem-r3-cc-r3-02-05","number":125,"title":"Cáncer de mama · caso 5","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Mujer de 44 años con mama derecha con eritema, edema y piel de naranja que abarca más de un tercio, masa de 4 cm, biopsia: carcinoma ductal infiltrante triple negativo.","questions":[{"id":"puem-r3-cc-r3-02-05-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y la conducta?","options":["Cáncer inflamatorio, localmente avanzado: quimioterapia neoadyuvante (con inmunoterapia según el caso) y luego cirugía + radioterapia; no operar de inicio.","Cáncer temprano: tumorectomía inmediata.","Fibroadenoma inflamado: observación.","Mastitis: antibióticos y drenaje."],"answer_index":0,"correct_text":"Cáncer inflamatorio, localmente avanzado: quimioterapia neoadyuvante (con inmunoterapia según el caso) y luego cirugía + radioterapia; no operar de inicio.","explanation":"El cuadro clínico es cáncer inflamatorio (T4d): es localmente avanzado por definición y se trata con sistémico neoadyuvante primero; operar de inicio es un error clásico. **D es incorrecta:** la mastitis no explica la masa ni el cuadro, y la biopsia ya es maligna. **A y C son incorrectas:** no es temprano ni benigno.","topic":"Mama"}]},{"id":"puem-r3-cc-r3-02-06","number":126,"title":"Cáncer de mama · caso 6","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Paciente con cáncer de mama triple negativo, 2.5 cm, ganglio centinela negativo. Recibió quimioterapia neoadyuvante y la patología muestra respuesta patológica completa (sin tumor residual).","questions":[{"id":"puem-r3-cc-r3-02-06-q1","ordinal":1,"stem":"¿Qué significa?","options":["Que el cáncer ya no existe y no necesita más tratamiento.","Excelente factor pronóstico: la respuesta patológica completa en triple negativo se asocia a mejor supervivencia; aun así requiere cirugía ya realizada, radioterapia según el caso y vigilancia estrecha.","Que la quimioterapia falló porque no quedó tumor para analizar.","Que debe recibir radioterapia de todo el cuerpo."],"answer_index":1,"correct_text":"Excelente factor pronóstico: la respuesta patológica completa en triple negativo se asocia a mejor supervivencia; aun así requiere cirugía ya realizada, radioterapia según el caso y vigilancia estrecha.","explanation":"La pCR es el mejor marcador pronóstico en triple negativo y HER2+; no significa 'curada sin más': el plan quirúrgico y la adyuvancia/radioterapia se completan según el estadio inicial. **A es incorrecta:** la pCR no elimina el seguimiento ni el tratamiento local. **C es incorrecta:** la ausencia de tumor es éxito, no falla. **D es incorrecta:** no existe radioterapia corporal total en este contexto.","topic":"Mama"}]},{"id":"puem-r3-cc-r3-02-07","number":127,"title":"Cáncer de mama · caso 7","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Mujer de 55 años con DCIS de 1 cm, grado intermedio, RE+, tratado con tumorectomía. El margen es de 1 mm.","questions":[{"id":"puem-r3-cc-r3-02-07-q1","ordinal":1,"stem":"¿Qué se debe hacer?","options":["Quimioterapia adyuvante.","Nada, el margen es suficiente.","Ampliar el margen a aprox. 2 mm (re-excisión) y radioterapia adyuvante + hormonoterapia, porque en DCIS el margen estrecho aumenta recurrencia.","Mastectomía inmediata obligatoria."],"answer_index":2,"correct_text":"Ampliar el margen a aprox. 2 mm (re-excisión) y radioterapia adyuvante + hormonoterapia, porque en DCIS el margen estrecho aumenta recurrencia.","explanation":"En DCIS el estándar es margen de aprox. 2 mm; 1 mm es estrecho y justifica re-excisión, más radioterapia y hormonoterapia en RE+. **B es incorrecta:** 1 mm es insuficiente para DCIS. **D es incorrecta:** la mastectomía no es obligatoria por un margen estrecho. **A es incorrecta:** el DCIS no recibe quimioterapia.","topic":"Mama"}]},{"id":"puem-r3-cc-r3-02-08","number":128,"title":"Cáncer de mama · caso 8","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Paciente posmastectomía con disección axilar desarrolla edema del brazo a los 6 meses, sin eritema ni fiebre.","questions":[{"id":"puem-r3-cc-r3-02-08-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable y el manejo?","options":["Trombosis venosa profunda: anticoagulación inmediata sin más estudios.","Recurrencia tumoral segura: biopsia urgente del brazo.","Celulitis: antibióticos intravenosos inmediatos.","Linfedema posquirúrgico: fisioterapia, drenaje linfático, compresión y educación; descartar recurrencia/trombosis si hay datos de alarma."],"answer_index":3,"correct_text":"Linfedema posquirúrgico: fisioterapia, drenaje linfático, compresión y educación; descartar recurrencia/trombosis si hay datos de alarma.","explanation":"El linfedema es la complicación axilar clásica, de inicio insidioso sin signos infecciosos; el manejo es conservador y temprano, con vigilancia de alarma. **C es incorrecta:** no hay datos de infección. **A es incorrecta:** la TVP no se diagnostica ni se trata sin confirmar. **B es incorrecta:** la recurrencia no se asume por un edema.","topic":"Mama"}]},{"id":"puem-r3-cc-r3-02-09","number":129,"title":"Cáncer de mama · caso 9","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Mujer de 48 años, HER2+ en tratamiento con trastuzumab, FEVI cae de 62% a 46% asintomática.","questions":[{"id":"puem-r3-cc-r3-02-09-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Suspender temporalmente trastuzumab, valoración cardiológica, repetir ecocardiograma y revalorar; la cardiotoxicidad por anti-HER2 suele ser reversible al suspender.","Cambiar a quimioterapia oral inmediatamente.","Dar diuréticos y continuar el anti-HER2.","Continuar trastuzumab sin cambios, la caída es irrelevante."],"answer_index":0,"correct_text":"Suspender temporalmente trastuzumab, valoración cardiológica, repetir ecocardiograma y revalorar; la cardiotoxicidad por anti-HER2 suele ser reversible al suspender.","explanation":"La cardiotoxicidad por trastuzumab es un efecto conocido, a menudo reversible: se suspende, se valora con cardiología y se decide reintroducción según recuperación de la FEVI. **D es incorrecta:** una caída de 16 puntos es significativa. **B es incorrecta:** no es el manejo de la cardiotoxicidad. **C es incorrecta:** los diuréticos no resuelven la causa.","topic":"Mama"}]},{"id":"puem-r3-cc-r3-02-10","number":130,"title":"Cáncer de mama · caso 10","topic":"Mama","topicId":"ap-r3-mama","nivel":"R3","context":"Mujer de 35 años con cáncer de mama, BRCA2 positivo, tumor RE+ de 2 cm. Pregunta por el riesgo de la mama contralateral.","questions":[{"id":"puem-r3-cc-r3-02-10-q1","ordinal":1,"stem":"¿Qué se le debe explicar?","options":["El riesgo solo existe si su madre tuvo cáncer.","No hay riesgo contralateral, el cáncer ya está en una mama.","El riesgo contralateral está aumentado por BRCA2; se discuten vigilancia intensiva (RM anual) y mastectomía contralateral reductora de riesgo como opción, con asesoría genética y decisión informada.","Debe hacerse mastectomía bilateral de inmediato sin discutirlo."],"answer_index":2,"correct_text":"El riesgo contralateral está aumentado por BRCA2; se discuten vigilancia intensiva (RM anual) y mastectomía contralateral reductora de riesgo como opción, con asesoría genética y decisión informada.","explanation":"BRCA2 eleva el riesgo de cáncer contralateral y de ovario; la decisión entre vigilancia intensiva y cirugía reductora es informada y personal. **B es incorrecta:** el riesgo existe y es relevante. **D es incorrecta:** es una opción a discutir, no una imposición. **A es incorrecta:** el riesgo es genético, no depende de la historia materna aislada.","topic":"Mama"}]},{"id":"puem-r4-cc-r3-08-01","number":1,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 1","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Hombre de 72 años fumador con dolor abdominal súbito, hipotensión 80/50, masa abdominal pulsátil y palidez.","questions":[{"id":"puem-r4-cc-r3-08-01-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y la conducta?","options":["Pancreatitis: ayuno y TC.","Infarto: trombólisis.","Cólico renal: analgésicos y esperar.","Aneurisma de aorta abdominal roto: reanimación con control permisivo de hipotensión, transfusión y cirugía inmediata (abierta o EVAR); no demorar con estudios largos."],"answer_index":3,"correct_text":"Aneurisma de aorta abdominal roto: reanimación con control permisivo de hipotensión, transfusión y cirugía inmediata (abierta o EVAR); no demorar con estudios largos.","explanation":"La tríada (dolor, hipotensión, masa pulsátil) es AAA roto: es una emergencia quirúrgica y el tiempo es vida. **C es incorrecta:** el cólico renal no da hipotensión ni masa pulsátil. **A es incorrecta:** la pancreatitis no explica la masa pulsátil. **B es incorrecta:** la trombólisis no trata un aneurisma roto y empeoraría el sangrado.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-08-02","number":2,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 2","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Hombre de 68 años con AAA de 4.5 cm asintomático, sin crecimiento en 1 año.","questions":[{"id":"puem-r4-cc-r3-08-02-q1","ordinal":1,"stem":"¿Cuál es la conducta correcta?","options":["Dar anticoagulación.","Reparación inmediata por EVAR.","Vigilancia con ultrasonido/TC periódica y control de factores de riesgo, porque el umbral de reparación es aprox. 5.5 cm en hombres; operar un aneurisma pequeño aumenta el riesgo sin beneficio.","No hacer nada nunca."],"answer_index":2,"correct_text":"Vigilancia con ultrasonido/TC periódica y control de factores de riesgo, porque el umbral de reparación es aprox. 5.5 cm en hombres; operar un aneurisma pequeño aumenta el riesgo sin beneficio.","explanation":"El AAA pequeño asintomático se vigila: el riesgo de ruptura es bajo y la cirugía tiene morbilidad; el umbral es aprox. 5.5 cm (hombres) o crecimiento rápido. **B es incorrecta:** operar antes del umbral no beneficia. **D es incorrecta:** la vigilancia es activa, no abandono. **A es incorrecta:** la anticoagulación no trata el aneurisma.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-08-03","number":3,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 3","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Mujer de 70 años con amaurosis fugaz derecha y AIT hace 5 días; dúplex: estenosis carotídea derecha del 80% sintomática.","questions":[{"id":"puem-r4-cc-r3-08-03-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Solo antiagregación, la cirugía es muy riesgosa.","Endarterectomía carotídea en las primeras 2 semanas tras el evento (idealmente pronto, una vez estable), porque el riesgo de ictus es máximo en ese periodo.","Esperar 3 meses para operar.","Stent carotídeo en todos los casos."],"answer_index":1,"correct_text":"Endarterectomía carotídea en las primeras 2 semanas tras el evento (idealmente pronto, una vez estable), porque el riesgo de ictus es máximo en ese periodo.","explanation":"La carótida sintomática con estenosis grave se opera pronto (dentro de 2 semanas): el riesgo de ictus recurrente es mayor en los primeros días. **A es incorrecta:** la antiagregación sola no previene el ictus en estenosis grave sintomática. **C es incorrecta:** esperar 3 meses deja el periodo de mayor riesgo sin protección. **D es incorrecta:** el stent es alternativa en casos seleccionados, no universal.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-08-04","number":4,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 4","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Hombre de 65 años diabético con dolor en reposo en el pie, úlcera en el talón que no cicatriza, ITB 0.35, pulsos ausentes.","questions":[{"id":"puem-r4-cc-r3-08-04-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Isquemia crítica de la extremidad: revascularización (endovascular o bypass) + cuidado de la herida y control de factores de riesgo; la amputación es el último recurso.","Amputación inmediata sin intentar revascularizar.","Solo antibióticos.","Claudicación leve: ejercicio."],"answer_index":0,"correct_text":"Isquemia crítica de la extremidad: revascularización (endovascular o bypass) + cuidado de la herida y control de factores de riesgo; la amputación es el último recurso.","explanation":"Dolor en reposo + úlcera + ITB 0.35 es isquemia crítica: la extremidad está amenazada y la revascularización es el tratamiento. **D es incorrecta:** no es claudicación leve. **B es incorrecta:** la amputación sin intentar revascularizar es un error en isquemia crítica. **C es incorrecta:** los antibióticos no restauran el flujo.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-08-05","number":5,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 5","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Paciente con fibrilación auricular que llega con dolor súbito en la pierna derecha, pálida, fría, sin pulsos, con parestesias pero con movimiento conservado.","questions":[{"id":"puem-r4-cc-r3-08-05-q1","ordinal":1,"stem":"¿Cuál es la conducta inmediata?","options":["Amputación inmediata.","Dar trombólisis oral en casa.","Dar analgésicos y observar 24 h.","Heparina intravenosa inmediata + revascularización urgente (embolectomía/trombólisis/bypass según el caso); es isquemia aguda amenazada (Rutherford II) y el tiempo es extremidad."],"answer_index":3,"correct_text":"Heparina intravenosa inmediata + revascularización urgente (embolectomía/trombólisis/bypass según el caso); es isquemia aguda amenazada (Rutherford II) y el tiempo es extremidad.","explanation":"La isquemia aguda embólica exige anticoagulación inmediata y revascularización urgente; las parestesias indican amenaza, no irreversibilidad. **C es incorrecta:** observar condena la extremidad. **A es incorrecta:** hay movimiento conservado: la extremidad es salvable. **B es incorrecta:** no existe trombólisis oral domiciliaria.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-08-06","number":6,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 6","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Hombre de 55 años con dolor torácico desgarrante que irradia a la espalda, presión 200/110 en brazo derecho y 140/90 en izquierdo, déficit de pulsos.","questions":[{"id":"puem-r4-cc-r3-08-06-q1","ordinal":1,"stem":"¿Cuál es la sospecha y el manejo?","options":["Reflujo: antiácidos.","Infarto: trombólisis.","Disección aórtica: TC/angio-TC urgente, control de presión arterial (betabloqueo, meta de sistólica aprox. 100-120) y cirugía urgente si es Stanford A; la trombólisis está contraindicada.","Neumonía: antibióticos."],"answer_index":2,"correct_text":"Disección aórtica: TC/angio-TC urgente, control de presión arterial (betabloqueo, meta de sistólica aprox. 100-120) y cirugía urgente si es Stanford A; la trombólisis está contraindicada.","explanation":"El dolor desgarrante + diferencia de presión entre brazos es disección aórtica; la trombólisis sería catastrófica. **B es incorrecta:** la trombólisis en disección causa ruptura y muerte. **A y A son incorrectas:** no explican el cuadro.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-08-07","number":7,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 7","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Paciente con claudicación intermitente a 200 m, ITB 0.7, sin dolor en reposo ni úlceras.","questions":[{"id":"puem-r4-cc-r3-08-07-q1","ordinal":1,"stem":"¿Cuál es el tratamiento de primera línea?","options":["Bypass femoropoplíteo inmediato.","Ejercicio supervisado, abandono del tabaco, estatina, antiagregación y control de diabetes/hipertensión; la revascularización se reserva para claudicación limitante que no mejora o isquemia crítica.","Amputación.","Solo analgésicos."],"answer_index":1,"correct_text":"Ejercicio supervisado, abandono del tabaco, estatina, antiagregación y control de diabetes/hipertensión; la revascularización se reserva para claudicación limitante que no mejora o isquemia crítica.","explanation":"La claudicación sin isquemia crítica se trata médicamente y con ejercicio; operar de entrada no mejora el pronóstico y expone a riesgos. **A es incorrecta:** el bypass no es primera línea en claudicación. **C es incorrecta:** no hay indicación de amputación. **D es incorrecta:** los analgésicos no tratan la enfermedad arterial.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-08-08","number":8,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 8","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Hombre de 75 años con AAA reparado con EVAR hace 1 año, TC de control con endofuga tipo II (llenado del saco por lumbares).","questions":[{"id":"puem-r4-cc-r3-08-08-q1","ordinal":1,"stem":"¿Qué significa?","options":["Endofuga tipo II: flujo retrógrado por colaterales; si el saco no crece, se vigila; si crece, se interviene (embolización). Es la endofuga más frecuente y la menos grave.","Que el aneurisma se curó.","Que debe retirarse la endoprótesis.","Que la endoprótesis falló y hay que operarlo de urgencia siempre."],"answer_index":0,"correct_text":"Endofuga tipo II: flujo retrógrado por colaterales; si el saco no crece, se vigila; si crece, se interviene (embolización). Es la endofuga más frecuente y la menos grave.","explanation":"La tipo II es la más frecuente y se vigila si el saco es estable; la intervención se indica si el saco crece. **D es incorrecta:** no toda endofuga es urgencia. **B es incorrecta:** el saco persiste y debe vigilarse. **C es incorrecta:** retirar la endoprótesis no es el manejo de una tipo II.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-08-09","number":9,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 9","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Paciente con isquemia aguda revascularizada con éxito, 6 h después desarrolla dolor intenso en la pantorrilla, tensión a la palpación y parestesias.","questions":[{"id":"puem-r4-cc-r3-08-09-q1","ordinal":1,"stem":"¿Cuál es la complicación y la conducta?","options":["Infección: antibióticos.","Es normal tras la revascularización.","Trombosis del injerto: trombólisis.","Síndrome compartimental por reperfusión: fasciotomía de urgencia; el dolor desproporcionado y la tensión son los signos clave."],"answer_index":3,"correct_text":"Síndrome compartimental por reperfusión: fasciotomía de urgencia; el dolor desproporcionado y la tensión son los signos clave.","explanation":"Tras la reperfusión, el edema muscular en un compartimento rígido causa síndrome compartimental: la fasciotomía es urgente para salvar la extremidad. **C es incorrecta:** la trombosis daría isquemia, no tensión compartimental. **A es incorrecta:** no hay datos de infección. **B es incorrecta:** el dolor desproporcionado nunca es normal.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-08-10","number":10,"title":"Cirugía vascular: aorta, carótida y enfermedad arterial periférica · caso 10","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R3","context":"Mujer de 62 años con estenosis carotídea del 70% asintomática, sin AIT ni ictus.","questions":[{"id":"puem-r4-cc-r3-08-10-q1","ordinal":1,"stem":"¿Cuál es la conducta más adecuada?","options":["Endarterectomía inmediata en todos los casos.","Tratamiento médico óptimo (antiagregación, estatina, control de presión y tabaco) y vigilancia; la cirugía en asintomática se individualiza según el riesgo (edad, esperanza de vida, características de la placa) y no es automática.","No hacer nada.","Stent carotídeo urgente."],"answer_index":1,"correct_text":"Tratamiento médico óptimo (antiagregación, estatina, control de presión y tabaco) y vigilancia; la cirugía en asintomática se individualiza según el riesgo (edad, esperanza de vida, características de la placa) y no es automática.","explanation":"En carótida asintomática el beneficio quirúrgico es mucho menor que en sintomática; el manejo médico óptimo es la base y la cirugía se individualiza. **A y D son incorrectas:** no hay indicación automática. **C es incorrecta:** el tratamiento médico es activo, no abandono.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-01","number":11,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 1","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Hombre 72 años, dolor abdominal súbito desproporcionado a la exploración, fibrilación auricular, lactato 5, leucocitosis.","questions":[{"id":"puem-r4-cc-r4-09-01-q1","ordinal":1,"stem":"¿Estudio y conducta?","options":["Solo analgésicos","Colonoscopia","US abdominal y observación","Angio-TC inmediata; revascularización urgente + evaluación de viabilidad intestinal"],"answer_index":3,"correct_text":"Angio-TC inmediata; revascularización urgente + evaluación de viabilidad intestinal","explanation":"Dolor desproporcionado + FA + lactato = isquemia mesentérica embólica. La angio-TC es el estudio clave y el tiempo es intestino; el US no descarta isquemia.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-02","number":12,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 2","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Mujer 68 años, dolor lumbar, hipotensión 70/40, masa abdominal pulsátil.","questions":[{"id":"puem-r4-cc-r4-09-02-q1","ordinal":1,"stem":"¿Diagnóstico y conducta?","options":["Alta","Cólico renal; analgésicos","AAA roto; control aórtico, reanimación y EVAR/abierto según anatomía y recursos; derivar sin demora si no hay recurso","Solo TC en 24 h"],"answer_index":2,"correct_text":"AAA roto; control aórtico, reanimación y EVAR/abierto según anatomía y recursos; derivar sin demora si no hay recurso","explanation":"La tríada de AAA roto exige control inmediato. Esperar o tratar como cólico es letal; en hospital sin recurso vascular, estabilizar y derivar es lo correcto.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-03","number":13,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 3","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Hombre post-AMI, dolor abdominal, TC: isquemia mesentérica no oclusiva.","questions":[{"id":"puem-r4-cc-r4-09-03-q1","ordinal":1,"stem":"¿Manejo?","options":["Resección intestinal amplia inmediata","Corregir bajo gasto/vasoespasmo, anticoagulación según caso, soporte en UCI y second look si hay necrosis","Solo antibiótico","Alta"],"answer_index":1,"correct_text":"Corregir bajo gasto/vasoespasmo, anticoagulación según caso, soporte en UCI y second look si hay necrosis","explanation":"La isquemia no oclusiva es por bajo gasto/vasoespasmo: se corrige la causa y se vigila viabilidad; resecar amplio de inicio sin necrosis demostrada es excesivo.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-04","number":14,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 4","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Paciente con trauma torácico, ausencia de murmullo derecho, hipotensión, desviación traqueal.","questions":[{"id":"puem-r4-cc-r4-09-04-q1","ordinal":1,"stem":"¿Acción?","options":["Descompresión con aguja/toracostomía inmediata (neumotórax a tensión)","Solo oxígeno","Intubación sin descompresión","Radiografía de tórax primero"],"answer_index":0,"correct_text":"Descompresión con aguja/toracostomía inmediata (neumotórax a tensión)","explanation":"Neumotórax a tensión: la descompresión es inmediata y clínica; esperar la placa mata. Intubar sin descomprimir empeora la tensión.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-05","number":15,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 5","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Hombre con isquemia mesentérica, resección de 60 cm de yeyuno necrótico, intestino dudoso restante.","questions":[{"id":"puem-r4-cc-r4-09-05-q1","ordinal":1,"stem":"¿Plan?","options":["Cerrar sin second look","Solo antibiótico","Resecar todo lo dudoso en la primera cirugía","Dejar intestino dudoso, second look 24-48 h y revalorar viabilidad"],"answer_index":3,"correct_text":"Dejar intestino dudoso, second look 24-48 h y revalorar viabilidad","explanation":"En isquemia, el second look evita resecar intestino viable y evita dejar necrosis. Resecar de más genera intestino corto innecesario.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-06","number":16,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 6","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Paciente con empiema pleural fase fibrinopurulenta.","questions":[{"id":"puem-r4-cc-r4-09-06-q1","ordinal":1,"stem":"¿Tratamiento?","options":["Observación","Solo antibiótico","Drenaje torácico + fibrinolíticos o VATS/decorticación según fase y respuesta","Toracotomía siempre de inicio"],"answer_index":2,"correct_text":"Drenaje torácico + fibrinolíticos o VATS/decorticación según fase y respuesta","explanation":"El empiema organizado requiere drenaje y desbridamiento (VATS/decorticación); solo antibiótico no drena el espacio pleural infectado.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-07","number":17,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 7","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Hombre con trauma vascular femoral, sangrado activo, inestable, en damage control.","questions":[{"id":"puem-r4-cc-r4-09-07-q1","ordinal":1,"stem":"¿Conducta?","options":["Reparación vascular definitiva prolongada","Control proximal/distal y shunt temporal; reparación definitiva diferida","Ligadura definitiva siempre","Solo compresión"],"answer_index":1,"correct_text":"Control proximal/distal y shunt temporal; reparación definitiva diferida","explanation":"En damage control, el shunt temporal salva la extremidad y la vida; la reparación definitiva prolongada en paciente inestable aumenta mortalidad.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-08","number":18,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 8","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Mujer con AAA 6 cm asintomático, estable.","questions":[{"id":"puem-r4-cc-r4-09-08-q1","ordinal":1,"stem":"¿Conducta del cirujano general?","options":["Valoración vascular urgente/electiva para reparación (EVAR/abierto) por tamaño y riesgo de ruptura; no es urgencia inmediata si está estable","Solo analgésicos","Cirugía en urgencias sin valoración","Observación sin más"],"answer_index":0,"correct_text":"Valoración vascular urgente/electiva para reparación (EVAR/abierto) por tamaño y riesgo de ruptura; no es urgencia inmediata si está estable","explanation":"AAA ≥5.5 cm (aprox.) en hombre / menor umbral en mujer con riesgo: indicación de reparación electiva valorada por vascular. No es ruptura, pero tampoco observación pasiva.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-09","number":19,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 9","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Paciente con trombosis venosa mesentérica, dolor subagudo, sin peritonitis.","questions":[{"id":"puem-r4-cc-r4-09-09-q1","ordinal":1,"stem":"¿Tratamiento inicial?","options":["Solo analgésicos","Alta","Laparotomía inmediata","Anticoagulación, soporte y vigilancia; cirugía solo si hay peritonitis/necrosis"],"answer_index":3,"correct_text":"Anticoagulación, soporte y vigilancia; cirugía solo si hay peritonitis/necrosis","explanation":"La trombosis venosa mesentérica sin peritonitis se trata con anticoagulación y vigilancia. Operar sin necrosis es innecesario; negar anticoagulación perpetúa la trombosis.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r4-09-10","number":20,"title":"Cirugía vascular, torácica y emergencias toracoabdominales · caso 10","topic":"Enfermedades vasculares","topicId":"ap-r4-vascular","nivel":"R4","context":"Hombre con hemotórax, tubo drena 250 mL/h por 3 h.","questions":[{"id":"puem-r4-cc-r4-09-10-q1","ordinal":1,"stem":"¿Conducta?","options":["Mantener tubo y observar","Toracotomía: sangrado persistente >200 mL/h","Retirar tubo","Solo transfusión"],"answer_index":1,"correct_text":"Toracotomía: sangrado persistente >200 mL/h","explanation":"Sangrado persistente >200 mL/h (aprox.) por tubo torácico es indicación quirúrgica. Observar perpetúa el choque y el hemotórax retenido.","topic":"Enfermedades vasculares"}]},{"id":"puem-r4-cc-r3-07-01","number":21,"title":"Cirugía de tórax, pleura y mediastino · caso 1","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Hombre de 25 años, alto y delgado, con disnea súbita y dolor torácico, hipotensión, ingurgitación yugular, tráquea desviada a la izquierda, ausencia de murmullo en hemitórax derecho.","questions":[{"id":"puem-r4-cc-r3-07-01-q1","ordinal":1,"stem":"¿Cuál es la conducta inmediata?","options":["Descompresión con aguja en segundo espacio intercostal derecho, línea medioclavicular, seguida de sonda pleural: neumotórax a tensión.","Dar oxígeno y observar.","Toracocentesis diagnóstica.","Pedir radiografía de tórax urgente y esperar el resultado."],"answer_index":0,"correct_text":"Descompresión con aguja en segundo espacio intercostal derecho, línea medioclavicular, seguida de sonda pleural: neumotórax a tensión.","explanation":"El neumotórax a tensión es un diagnóstico clínico que se descomprime sin esperar imagen; esperar la radiografía puede ser mortal. **D es incorrecta:** la radiografía demora la descompresión. **B es incorrecta:** el oxígeno no resuelve la tensión. **C es incorrecta:** la toracocentesis no descomprime un neumotórax a tensión.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-07-02","number":22,"title":"Cirugía de tórax, pleura y mediastino · caso 2","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Paciente con trauma torácico, sonda pleural con drenaje inicial de 1,600 mL de sangre y luego 250 mL/h por 3 h, hipotenso pese a transfusión.","questions":[{"id":"puem-r4-cc-r3-07-02-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Seguir con la sonda y transfundir más.","Toracotomía de urgencia: el hemotórax masivo con sangrado sostenido e inestabilidad es indicación quirúrgica.","Retirar la sonda pleural.","Dar antifibrinolíticos y esperar."],"answer_index":1,"correct_text":"Toracotomía de urgencia: el hemotórax masivo con sangrado sostenido e inestabilidad es indicación quirúrgica.","explanation":"Los criterios clásicos de toracotomía en hemotórax (drenaje inicial aprox. >1,500 mL o >200 mL/h sostenido con inestabilidad) están presentes. **A es incorrecta:** seguir transfundiendo sin controlar la fuente es fútil. **C es incorrecta:** retirar la sonda empeora el cuadro. **D es incorrecta:** los antifibrinolíticos no sustituyen el control quirúrgico del sangrado.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-07-03","number":23,"title":"Cirugía de tórax, pleura y mediastino · caso 3","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Mujer de 60 años con neumonía, derrame pleural que no resuelve, fiebre persistente, líquido pleural con pH 6.9, glucosa 30 mg/dL, LDH muy alta, Gram con bacterias.","questions":[{"id":"puem-r4-cc-r3-07-03-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Toracocentesis diagnóstica y alta.","Derrame paraneumónico simple: solo antibióticos.","Empiema / derrame paraneumónico complicado: antibióticos + drenaje pleural (sonda) y valorar fibrinolíticos o VATS, porque el pH bajo y la glucosa baja indican infección del espacio pleural.","Derrame por insuficiencia cardiaca: diuréticos."],"answer_index":2,"correct_text":"Empiema / derrame paraneumónico complicado: antibióticos + drenaje pleural (sonda) y valorar fibrinolíticos o VATS, porque el pH bajo y la glucosa baja indican infección del espacio pleural.","explanation":"pH <7.2, glucosa baja y Gram positivo definen derrame complicado/empiema que exige drenaje, no solo antibióticos. **B es incorrecta:** los antibióticos solos no drenan un espacio infectado. **D es incorrecta:** no es trasudado cardiaco. **A es incorrecta:** el alta sería negligente.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-07-04","number":24,"title":"Cirugía de tórax, pleura y mediastino · caso 4","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Hombre de 65 años fumador con masa pulmonar de 3 cm, biopsia: adenocarcinoma, PET sin metástasis, mediastino negativo, FEV1 adecuada.","questions":[{"id":"puem-r4-cc-r3-07-04-q1","ordinal":1,"stem":"¿Cuál es el tratamiento?","options":["Radioterapia exclusiva en todos los casos.","Neumectomía obligatoria.","Quimioterapia exclusiva.","Lobectomía anatómica con linfadenectomía mediastínica (VATS o abierta) como tratamiento curativo de enfermedad temprana resecable."],"answer_index":3,"correct_text":"Lobectomía anatómica con linfadenectomía mediastínica (VATS o abierta) como tratamiento curativo de enfermedad temprana resecable.","explanation":"El cáncer pulmonar de células no pequeñas temprano resecable se cura con lobectomía anatómica + linfadenectomía. **C es incorrecta:** la quimio sola no cura un tumor resecable. **A es incorrecta:** la radioterapia es alternativa en no operables, no el estándar en operables. **B es incorrecta:** la neumectomía no es obligatoria si la lobectomía logra R0.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-07-05","number":25,"title":"Cirugía de tórax, pleura y mediastino · caso 5","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Paciente con cáncer pulmonar de células pequeñas, enfermedad limitada al tórax.","questions":[{"id":"puem-r4-cc-r3-07-05-q1","ordinal":1,"stem":"¿Cuál es el manejo correcto?","options":["Quimioterapia + radioterapia torácica (manejo sistémico): el células pequeñas es una enfermedad sistémica desde el inicio y la cirugía no es el tratamiento estándar.","Solo observación.","Pleurodesis.","Lobectomía como primera línea."],"answer_index":0,"correct_text":"Quimioterapia + radioterapia torácica (manejo sistémico): el células pequeñas es una enfermedad sistémica desde el inicio y la cirugía no es el tratamiento estándar.","explanation":"El células pequeñas se disemina temprano y se trata con quimio ± radioterapia; la cirugía solo se considera en nódulos muy seleccionados sin ganglios. **D es incorrecta:** la cirugía no es el estándar. **A y C son incorrectas:** no son tratamiento oncológico.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-07-06","number":26,"title":"Cirugía de tórax, pleura y mediastino · caso 6","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Mujer de 40 años con masa en mediastino anterior, debilidad muscular fluctuante, ptosis y disfagia.","questions":[{"id":"puem-r4-cc-r3-07-06-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico más probable y el manejo?","options":["Linfoma: quimioterapia.","Timoma asociado a miastenia gravis: timectomía (mejora la miastenia y trata el tumor) tras optimizar la miastenia con neurología y anestesia.","Quiste pericárdico: observación.","Tumor neurogénico: resección."],"answer_index":1,"correct_text":"Timoma asociado a miastenia gravis: timectomía (mejora la miastenia y trata el tumor) tras optimizar la miastenia con neurología y anestesia.","explanation":"Masa mediastínica anterior + miastenia = timoma hasta demostrar lo contrario; la timectomía es terapéutica para ambos, con preparación especial por el riesgo de crisis miasténica. **A es incorrecta:** el linfoma no explica la miastenia. **C es incorrecta:** el quiste no da miastenia. **D es incorrecta:** los neurogénicos son del mediastino posterior.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-07-07","number":27,"title":"Cirugía de tórax, pleura y mediastino · caso 7","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Paciente con fractura de 5 costillas contiguas en dos puntos, con movimiento paradójico del segmento, dolor grave e insuficiencia respiratoria.","questions":[{"id":"puem-r4-cc-r3-07-07-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["Solo vendaje compresivo del tórax.","Contusión pulmonar leve: alta.","Tórax inestable (flail chest): analgesia adecuada (incluso peridural), soporte ventilatorio y fijación quirúrgica de costillas en casos seleccionados; la causa de la insuficiencia es más la contusión pulmonar que el movimiento paradójico en sí.","Toracotomía inmediata en todos los casos."],"answer_index":2,"correct_text":"Tórax inestable (flail chest): analgesia adecuada (incluso peridural), soporte ventilatorio y fijación quirúrgica de costillas en casos seleccionados; la causa de la insuficiencia es más la contusión pulmonar que el movimiento paradójico en sí.","explanation":"El tórax inestable se maneja con analgesia y soporte; la fijación quirúrgica se reserva para casos seleccionados (inestabilidad grave, destete difícil). **B es incorrecta:** es un cuadro grave. **D es incorrecta:** no toda flail exige toracotomía. **A es incorrecta:** el vendaje compresivo empeora la ventilación.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-07-08","number":28,"title":"Cirugía de tórax, pleura y mediastino · caso 8","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Hombre de 55 años con derrame pleural, líquido con proteínas altas, LDH alta, citología con células malignas.","questions":[{"id":"puem-r4-cc-r3-07-08-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo del síntoma?","options":["Empiema: drenaje quirúrgico.","Neumotórax: sonda pleural.","Trasudado por cirrosis: diuréticos.","Derrame pleural maligno (exudado): pleurodesis o catéter pleural tunelizado para controlar la disnea, más tratamiento oncológico de la neoplasia de base."],"answer_index":3,"correct_text":"Derrame pleural maligno (exudado): pleurodesis o catéter pleural tunelizado para controlar la disnea, más tratamiento oncológico de la neoplasia de base.","explanation":"Exudado con citología maligna = derrame maligno; el manejo es paliativo del síntoma (pleurodesis o catéter tunelizado) más oncología. **C es incorrecta:** no es trasudado. **A es incorrecta:** no hay datos de infección. **B es incorrecta:** no hay aire en pleura.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-07-09","number":29,"title":"Cirugía de tórax, pleura y mediastino · caso 9","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Paciente pos-esofagectomía con salida de líquido lechoso por el drenaje torácico, triglicéridos altos en el líquido.","questions":[{"id":"puem-r4-cc-r3-07-09-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo inicial?","options":["Quilotórax por lesión del conducto torácico: manejo conservador inicial (ayuno, nutrición parenteral o dieta baja en grasa con triglicéridos de cadena media, octreótido) y ligadura quirúrgica si el drenaje persiste o es alto.","Empiema: antibióticos.","Hemotórax: transfusión.","Fuga anastomótica: reintervención."],"answer_index":0,"correct_text":"Quilotórax por lesión del conducto torácico: manejo conservador inicial (ayuno, nutrición parenteral o dieta baja en grasa con triglicéridos de cadena media, octreótido) y ligadura quirúrgica si el drenaje persiste o es alto.","explanation":"Líquido lechoso con triglicéridos altos = quilotórax; el manejo inicial es conservador y la cirugía se reserva para drenaje persistente/alto. **D es incorrecta:** la fuga anastomótica no da líquido lechoso con triglicéridos altos. **A y C son incorrectas:** no hay datos de infección ni sangre.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-07-10","number":30,"title":"Cirugía de tórax, pleura y mediastino · caso 10","topic":"Tórax","topicId":"ap-r4-torax","nivel":"R3","context":"Hombre de 70 años con neumotórax espontáneo secundario a EPOC, disnea moderada, neumotórax del 40% en radiografía.","questions":[{"id":"puem-r4-cc-r3-07-10-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Toracotomía.","Observación sin sonda, porque es espontáneo.","Sonda pleural (drenaje) porque es un neumotórax grande y sintomático en paciente con enfermedad pulmonar de base; la observación es para neumotórax pequeños en pacientes estables sin enfermedad pulmonar.","Aguja de descompresión."],"answer_index":2,"correct_text":"Sonda pleural (drenaje) porque es un neumotórax grande y sintomático en paciente con enfermedad pulmonar de base; la observación es para neumotórax pequeños en pacientes estables sin enfermedad pulmonar.","explanation":"En neumotórax secundario grande y sintomático se drena; la observación es para neumotórax primarios pequeños y estables. **B es incorrecta:** el tamaño y la EPOC contraindican observar. **D es incorrecta:** la aguja es para tensión, no para drenaje definitivo. **A es incorrecta:** no hay indicación de toracotomía.","topic":"Tórax"}]},{"id":"puem-r4-cc-r3-11-01","number":31,"title":"Trasplante de órganos sólidos · caso 1","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Paciente con enfermedad renal crónica en diálisis, donante vivo hermano, crossmatch positivo con anticuerpos donante-específicos.","questions":[{"id":"puem-r4-cc-r3-11-01-q1","ordinal":1,"stem":"¿Cuál es la conducta?","options":["Trasplantar de cualquier forma, el crossmatch no importa.","No trasplantar con ese donante (riesgo de rechazo hiperagudo); buscar otro donante o protocolos de desensibilización en centro especializado.","Dar más inmunosupresión y trasplantar.","Trasplantar y hacer plasmaféresis después si hay rechazo."],"answer_index":1,"correct_text":"No trasplantar con ese donante (riesgo de rechazo hiperagudo); buscar otro donante o protocolos de desensibilización en centro especializado.","explanation":"El crossmatch positivo con anticuerpos donante-específicos predice rechazo hiperagudo (pérdida inmediata del injerto); no se trasplanta con ese donante salvo desensibilización en protocolos especializados. **A es incorrecta:** el crossmatch es la prueba clave de compatibilidad. **C es incorrecta:** más inmunosupresión no previene el rechazo hiperagudo. **D es incorrecta:** el rechazo hiperagudo destruye el injerto en horas.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r3-11-02","number":32,"title":"Trasplante de órganos sólidos · caso 2","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Hombre de 55 años con cirrosis descompensada, MELD 28, ascitis refractaria y encefalopatía.","questions":[{"id":"puem-r4-cc-r3-11-02-q1","ordinal":1,"stem":"¿Cuál es el tratamiento definitivo?","options":["Trasplante hepático: es el único tratamiento curativo de la cirrosis descompensada; el MELD alto lo prioriza en la lista.","TIPS como tratamiento definitivo.","Dar lactulosa indefinidamente.","Diuréticos de por vida."],"answer_index":0,"correct_text":"Trasplante hepático: es el único tratamiento curativo de la cirrosis descompensada; el MELD alto lo prioriza en la lista.","explanation":"La cirrosis descompensada solo se cura con trasplante; el MELD 28 indica prioridad alta. **D es incorrecta:** los diuréticos no curan la cirrosis. **B es incorrecta:** el TIPS es un puente o paliación, no curativo. **C es incorrecta:** la lactulosa trata la encefalopatía, no la cirrosis.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r3-11-03","number":33,"title":"Trasplante de órganos sólidos · caso 3","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Paciente 10 días postrasplante renal con aumento de creatinina, fiebre y dolor en el injerto.","questions":[{"id":"puem-r4-cc-r3-11-03-q1","ordinal":1,"stem":"¿Cuál es el primer paso diagnóstico?","options":["Dar antibióticos y esperar.","Retirar la inmunosupresión.","Aumentar el tacrolimus sin estudios.","Descartar causas quirúrgicas (ultrasonido Doppler del injerto: perfusión, obstrucción) y toxicidad, y hacer biopsia del injerto para diagnosticar rechazo agudo; el rechazo es diagnóstico histológico."],"answer_index":3,"correct_text":"Descartar causas quirúrgicas (ultrasonido Doppler del injerto: perfusión, obstrucción) y toxicidad, y hacer biopsia del injerto para diagnosticar rechazo agudo; el rechazo es diagnóstico histológico.","explanation":"El deterioro del injerto exige descartar complicación vascular/obstructiva y confirmar el rechazo con biopsia antes de tratarlo; aumentar inmunosupresión a ciegas puede empeorar una infección. **C es incorrecta:** sin diagnóstico se puede tratar mal una infección o una trombosis. **A es incorrecta:** los antibióticos solos no diagnostican rechazo. **B es incorrecta:** retirar inmunosupresión precipita el rechazo.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r3-11-04","number":34,"title":"Trasplante de órganos sólidos · caso 4","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Mujer de 40 años, 3 meses postrasplante hepático, con fiebre, leucopenia y carga viral de CMV positiva.","questions":[{"id":"puem-r4-cc-r3-11-04-q1","ordinal":1,"stem":"¿Cuál es el diagnóstico y el manejo?","options":["No requiere tratamiento.","Rechazo agudo: pulsos de esteroides.","Infección por citomegalovirus (CMV): antiviral (valganciclovir/ganciclovir) y ajuste de inmunosupresión; el CMV es la infección viral más frecuente postrasplante.","Infección bacteriana: antibióticos de amplio espectro solamente."],"answer_index":2,"correct_text":"Infección por citomegalovirus (CMV): antiviral (valganciclovir/ganciclovir) y ajuste de inmunosupresión; el CMV es la infección viral más frecuente postrasplante.","explanation":"CMV positivo con síndrome viral postrasplante es infección por CMV, no rechazo; se trata con antiviral. **B es incorrecta:** los esteroides empeorarían la infección. **D es incorrecta:** no es bacteriana. **A es incorrecta:** el CMV sin tratar puede ser grave.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r3-11-05","number":35,"title":"Trasplante de órganos sólidos · caso 5","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Paciente trasplantado renal en tratamiento con tacrolimus con creatinina en aumento progresivo, sin rechazo en biopsia, con arteriolopatía.","questions":[{"id":"puem-r4-cc-r3-11-05-q1","ordinal":1,"stem":"¿Cuál es la causa probable?","options":["Rechazo crónico solamente.","Nefrotoxicidad por tacrolimus (inhibidor de calcineurina): ajustar dosis/niveles y considerar cambio de esquema; es una causa frecuente de deterioro crónico del injerto.","El tacrolimus nunca es nefrotóxico.","Deshidratación solamente."],"answer_index":1,"correct_text":"Nefrotoxicidad por tacrolimus (inhibidor de calcineurina): ajustar dosis/niveles y considerar cambio de esquema; es una causa frecuente de deterioro crónico del injerto.","explanation":"La nefrotoxicidad por inhibidor de calcineurina es una causa clásica de disfunción crónica del injerto; el manejo es optimizar niveles y ajustar el esquema. **A es incorrecta:** la biopsia no mostró rechazo. **C es incorrecta:** el tacrolimus es nefrotóxico. **D es incorrecta:** la deshidratación no explica la arteriolopatía.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r3-11-06","number":36,"title":"Trasplante de órganos sólidos · caso 6","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Donante vivo de riñón, 35 años, sano, con dos arterias renales en el riñón izquierdo y una en el derecho.","questions":[{"id":"puem-r4-cc-r3-11-06-q1","ordinal":1,"stem":"¿Qué riñón se dona habitualmente y por qué?","options":["El izquierdo habitualmente (vena renal más larga, facilita el implante), pero con dos arterias la decisión se individualiza: se dona el riñón que deje al donante con el mejor riñón remanente y que sea técnicamente factible.","El derecho siempre.","No se puede donar con arterias múltiples.","El izquierdo, porque tiene más arterias y es mejor."],"answer_index":0,"correct_text":"El izquierdo habitualmente (vena renal más larga, facilita el implante), pero con dos arterias la decisión se individualiza: se dona el riñón que deje al donante con el mejor riñón remanente y que sea técnicamente factible.","explanation":"Se prefiere el riñón izquierdo por la vena más larga, pero la anatomía vascular múltiple obliga a individualizar y a priorizar la seguridad del donante. **D es incorrecta:** más arterias complican, no mejoran. **B es incorrecta:** no siempre es el derecho. **C es incorrecta:** las arterias múltiples no contraindican la donación.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r3-11-07","number":37,"title":"Trasplante de órganos sólidos · caso 7","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Paciente 2 semanas postrasplante hepático con elevación súbita de transaminasas, bilirrubina y fiebre; Doppler: flujo arterial hepático ausente.","questions":[{"id":"puem-r4-cc-r3-11-07-q1","ordinal":1,"stem":"¿Cuál es la complicación y la conducta?","options":["Colangitis: antibióticos.","Es normal en el posoperatorio.","Rechazo agudo: esteroides.","Trombosis de la arteria hepática: emergencia quirúrgica (revascularización urgente o retrasplante); es la complicación vascular más temida y puede causar pérdida del injerto."],"answer_index":3,"correct_text":"Trombosis de la arteria hepática: emergencia quirúrgica (revascularización urgente o retrasplante); es la complicación vascular más temida y puede causar pérdida del injerto.","explanation":"La ausencia de flujo arterial con disfunción del injerto es trombosis de la arteria hepática: urgencia que amenaza el injerto y la vida. **C es incorrecta:** los esteroides no restauran el flujo. **A es incorrecta:** no es colangitis. **B es incorrecta:** nunca es normal.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r3-11-08","number":38,"title":"Trasplante de órganos sólidos · caso 8","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Hombre de 60 años trasplantado renal hace 5 años, con lesión cutánea escamosa en la cara que crece.","questions":[{"id":"puem-r4-cc-r3-11-08-q1","ordinal":1,"stem":"¿Qué se debe sospechar?","options":["Infección por hongos solamente.","Verruga benigna sin importancia.","Cáncer de piel postrasplante (carcinoma escamocelular, el más frecuente en trasplantados por inmunosupresión crónica): biopsia y manejo dermatológico, además de revisar la inmunosupresión.","Alergia al tacrolimus."],"answer_index":2,"correct_text":"Cáncer de piel postrasplante (carcinoma escamocelular, el más frecuente en trasplantados por inmunosupresión crónica): biopsia y manejo dermatológico, además de revisar la inmunosupresión.","explanation":"La inmunosupresión crónica multiplica el riesgo de cáncer de piel; toda lesión sospechosa se biopsia. **B es incorrecta:** en un trasplantado ninguna lesión cutánea se minimiza. **D es incorrecta:** no es alergia. **A es incorrecta:** no se asume infección sin biopsia.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r3-11-09","number":39,"title":"Trasplante de órganos sólidos · caso 9","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Paciente en lista de espera para trasplante renal con diabetes descontrolada, obesidad mórbida y tabaquismo activo.","questions":[{"id":"puem-r4-cc-r3-11-09-q1","ordinal":1,"stem":"¿Qué se le debe explicar?","options":["Que el trasplante se hace de inmediato sin condiciones.","Que debe optimizarse (control glucémico, peso, abandono del tabaco) antes del trasplante, porque la comorbilidad no controlada aumenta el riesgo quirúrgico y del injerto; la evaluación pretrasplante es exhaustiva y puede condicionar la lista.","Que la diabetes contraindica el trasplante para siempre.","Que el tabaquismo no importa."],"answer_index":1,"correct_text":"Que debe optimizarse (control glucémico, peso, abandono del tabaco) antes del trasplante, porque la comorbilidad no controlada aumenta el riesgo quirúrgico y del injerto; la evaluación pretrasplante es exhaustiva y puede condicionar la lista.","explanation":"La evaluación pretrasplante exige optimizar comorbilidades; no es una contraindicación absoluta, pero sí una condición para trasplantar con seguridad. **A es incorrecta:** no se trasplanta sin optimización. **C es incorrecta:** la diabetes no contraindica el trasplante (es la primera causa de ERC). **D es incorrecta:** el tabaco aumenta complicaciones.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r3-11-10","number":40,"title":"Trasplante de órganos sólidos · caso 10","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R3","context":"Mujer de 45 años donante viva de riñón, 1 año después, con creatinina normal y proteinuria leve.","questions":[{"id":"puem-r4-cc-r3-11-10-q1","ordinal":1,"stem":"¿Qué seguimiento requiere?","options":["Solo una consulta al año sin laboratorios.","Diálisis preventiva.","Ninguno, el donante ya no necesita nada.","Seguimiento de por vida: función renal, presión arterial, proteinuria y control de factores de riesgo; el donante tiene un riñón y su función debe vigilarse siempre."],"answer_index":3,"correct_text":"Seguimiento de por vida: función renal, presión arterial, proteinuria y control de factores de riesgo; el donante tiene un riñón y su función debe vigilarse siempre.","explanation":"El donante vivo requiere seguimiento de por vida: su riesgo renal a largo plazo es bajo pero real y debe vigilarse. **C es incorrecta:** el donante nunca se da de alta definitiva. **A es incorrecta:** el seguimiento incluye laboratorios y presión arterial. **B es incorrecta:** no hay diálisis preventiva.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-01","number":41,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 1","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Hombre trasplantado renal hace 2 años, dolor abdominal leve, febrícula, leucocitos 9 000, inmunosuprimido.","questions":[{"id":"puem-r4-cc-r4-10-01-q1","ordinal":1,"stem":"¿Conducta?","options":["Alta por leucocitos normales","TC abdominal con umbral bajo y valoración con equipo de trasplante; no descartar abdomen agudo por signos atenuados","Solo analgésicos","Esperar 72 h"],"answer_index":1,"correct_text":"TC abdominal con umbral bajo y valoración con equipo de trasplante; no descartar abdomen agudo por signos atenuados","explanation":"La inmunosupresión atenúa signos y leucocitosis; el abdomen agudo en trasplantado exige TC temprana. Dar de alta por 'leucocitos normales' es el error clásico.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-02","number":42,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 2","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Mujer con púrpura trombocitopénica inmune refractaria, se propone esplenectomía electiva.","questions":[{"id":"puem-r4-cc-r4-10-02-q1","ordinal":1,"stem":"¿Vía y preparación?","options":["Laparoscópica electiva con vacunación preoperatoria y profilaxis","Sin vacunación","Solo esteroides de por vida","Esplenectomía abierta siempre"],"answer_index":0,"correct_text":"Laparoscópica electiva con vacunación preoperatoria y profilaxis","explanation":"La esplenectomía electiva hematológica es laparoscópica y exige vacunación previa (neumococo, meningococo, Haemophilus). Operar sin vacunar deja OPSI sin prevención.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-03","number":43,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 3","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Hombre postrasplante hepático, fiebre, bilirrubina en aumento, día 10.","questions":[{"id":"puem-r4-cc-r4-10-03-q1","ordinal":1,"stem":"¿Diferencial prioritario?","options":["Alta","Solo antipiréticos","Solo infección urinaria","Rechazo agudo, complicación biliar/vascular e infección (CMV); Doppler, biopsia y cultivos con equipo de trasplante"],"answer_index":3,"correct_text":"Rechazo agudo, complicación biliar/vascular e infección (CMV); Doppler, biopsia y cultivos con equipo de trasplante","explanation":"La fiebre + disfunción del injerto postrasplante exige descartar rechazo, trombosis/fístula e infección oportunista en equipo. Atribuirlo a una sola causa retrasa el diagnóstico.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-04","number":44,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 4","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Paciente postesplenectomía hace 3 años, fiebre alta, hipotensión, púrpura.","questions":[{"id":"puem-r4-cc-r4-10-04-q1","ordinal":1,"stem":"¿Sospecha?","options":["Alta","Gripe común","Sepsis postesplenectomía fulminante (OPSI); antibiótico inmediato, cultivos y UCI","Solo paracetamol"],"answer_index":2,"correct_text":"Sepsis postesplenectomía fulminante (OPSI); antibiótico inmediato, cultivos y UCI","explanation":"OPSI es fulminante en asplénicos: fiebre + choque exige antibiótico inmediato. Tratarlo como gripe es letal.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-05","number":45,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 5","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Donador vivo de riñón, se valora donación.","questions":[{"id":"puem-r4-cc-r4-10-05-q1","ordinal":1,"stem":"¿Principio ético central?","options":["El receptor decide por el donador","Consentimiento informado libre, evaluación independiente del donador y no maleficencia","Donar es obligatorio si es familiar","No se evalúa al donador"],"answer_index":1,"correct_text":"Consentimiento informado libre, evaluación independiente del donador y no maleficencia","explanation":"La donación viva exige consentimiento libre, evaluación independiente y protección del donador. Obligar a donar viola la autonomía y la no maleficencia.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-06","number":46,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 6","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Hombre con trauma esplénico AAST V, hipotenso, sin respuesta a reanimación.","questions":[{"id":"puem-r4-cc-r4-10-06-q1","ordinal":1,"stem":"¿Conducta?","options":["Esplenectomía urgente (control de hemorragia)","Embolización electiva","Solo transfusión","Manejo no operatorio"],"answer_index":0,"correct_text":"Esplenectomía urgente (control de hemorragia)","explanation":"Bazo AAST V inestable sin respuesta: esplenectomía para controlar hemorragia. El manejo no operatorio es para estables.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-07","number":47,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 7","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Mujer trasplantada renal, embarazo planeado.","questions":[{"id":"puem-r4-cc-r4-10-07-q1","ordinal":1,"stem":"¿Conducta?","options":["Embarazo contraindicado siempre sin excepción","Solo ácido fólico","Suspender inmunosupresión","Planificación con equipo de trasplante/obstetricia: ajustar fármacos teratógenos, vigilar función y rechazo"],"answer_index":3,"correct_text":"Planificación con equipo de trasplante/obstetricia: ajustar fármacos teratógenos, vigilar función y rechazo","explanation":"El embarazo postrasplante es posible con planificación y ajuste de inmunosupresores en equipo. Suspender inmunosupresión causa rechazo; prohibirlo siempre sin valorar es incorrecto.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-08","number":48,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 8","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Paciente en lista de trasplante, muerte encefálica del donador.","questions":[{"id":"puem-r4-cc-r4-10-08-q1","ordinal":1,"stem":"¿Qué sigue?","options":["Desechar órganos","Solo un órgano","Procuración multiorgánica con técnica, tiempos de isquemia fría y coordinación CENATRA/centro","Trasplante sin compatibilidad"],"answer_index":2,"correct_text":"Procuración multiorgánica con técnica, tiempos de isquemia fría y coordinación CENATRA/centro","explanation":"La procuración exige diagnóstico de muerte encefálica, compatibilidad, técnica y tiempos de isquemia fría coordinados. Trasplantar sin compatibilidad es inviable.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-09","number":49,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 9","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Hombre inmunosuprimido con apendicitis, dolor leve, sin fiebre.","questions":[{"id":"puem-r4-cc-r4-10-09-q1","ordinal":1,"stem":"¿Riesgo?","options":["La apendicitis no ocurre en inmunosuprimidos","Presentación atenuada con riesgo de perforación tardía; umbral bajo para imagen y cirugía","Solo antibiótico siempre","Alta"],"answer_index":1,"correct_text":"Presentación atenuada con riesgo de perforación tardía; umbral bajo para imagen y cirugía","explanation":"La inmunosupresión atenúa la presentación y retrasa el diagnóstico; la perforación es más probable si se espera. El umbral para TC/cirugía debe ser bajo.","topic":"Trasplante"}]},{"id":"puem-r4-cc-r4-10-10","number":50,"title":"Cirugía de trasplantes, bazo e inmunocomprometido · caso 10","topic":"Trasplante","topicId":"ap-r4-trasplante","nivel":"R4","context":"Postrasplante, niveles subterapéuticos de tacrolimus y creatinina en aumento.","questions":[{"id":"puem-r4-cc-r4-10-10-q1","ordinal":1,"stem":"¿Interpretación?","options":["Nefrotoxicidad segura sin más","Normal","Suspender tacrolimus","Rechazo agudo probable por inmunosupresión insuficiente; ajustar con equipo y biopsia si procede"],"answer_index":3,"correct_text":"Rechazo agudo probable por inmunosupresión insuficiente; ajustar con equipo y biopsia si procede","explanation":"Niveles bajos + disfunción del injerto sugieren rechazo por infradosificación; requiere ajuste en equipo y biopsia. Suspender el fármaco empeora el rechazo.","topic":"Trasplante"}]}];
